def _load_cover_image(path, target=180):
    """Load a PS5 icon0.png cover image and fit to a `target × target`
    square. Returns a PIL.Image or None on failure.

    Step 33 (v2.2.14): smart middle-ground trim. v2.2.11 was too timid
    (5% threshold), v2.2.12 was too aggressive (no upper bound — trimmed
    every blue pixel from ASTRO BOT's logo background), v2.2.13 was
    pure rollback (no solid trim at all).

    The middle ground: border trim is allowed ONLY if the trimmed
    border on each side stays under 25% of the dimension. If the
    "padding" exceeds 25%, that's solid-background artwork (Astro Bot's
    blue, Last of Us's dark), not padding. Bail out.

    Also trims transparent borders (alpha bbox) without any threshold —
    transparent pixels are unambiguously not artwork.
    """
    try:
        from PIL import Image
    except Exception:
        return None
    try:
        img = Image.open(path)
        img.load()
    except Exception:
        return None

    # ── 1. Trim transparent borders (alpha) — unambiguous ──
    if img.mode in ('RGBA', 'LA') or (
            img.mode == 'P' and 'transparency' in img.info):
        try:
            alpha = img.convert('RGBA').getchannel('A')
            bbox = alpha.getbbox()
            if bbox and bbox != (0, 0, img.width, img.height):
                img = img.crop(bbox)
        except Exception:
            pass

    # ── 2. Trim solid borders WITH STRICT UPPER BOUND ──
    # Only trim if the would-be trim leaves the artwork at >= 75% of
    # the original dimension on every side. This catches genuine
    # logo-with-padding icons (typically 5-20% padding) without
    # mistaking solid-background artwork (50%+ uniform corners) for
    # padding.
    try:
        rgb = img.convert('RGB')
        w, h = rgb.size
        if w >= 32 and h >= 32:
            # Sample all 4 corners
            corners = [
                rgb.getpixel((0, 0)),
                rgb.getpixel((w - 1, 0)),
                rgb.getpixel((0, h - 1)),
                rgb.getpixel((w - 1, h - 1)),
            ]
            # Only proceed if ALL FOUR corners are similar — strict
            # match required. If corners differ, the image has
            # full-bleed art and there's no padding to trim.
            tol = 12  # tighter than before (was 24)
            def _close(a, b):
                return (abs(a[0] - b[0]) <= tol and
                        abs(a[1] - b[1]) <= tol and
                        abs(a[2] - b[2]) <= tol)
            ref = corners[0]
            if all(_close(c, ref) for c in corners):
                # Walk inward from each edge with tighter tolerance
                def _matches(px):
                    return _close(px, ref)
                # Top
                top = 0
                step_x = max(1, w // 32)
                step_y = max(1, h // 32)
                for y in range(h):
                    row = [rgb.getpixel((x, y)) for x in range(0, w, step_x)]
                    if not all(_matches(p) for p in row):
                        top = y
                        break
                # Bottom
                bot = h
                for y in range(h - 1, -1, -1):
                    row = [rgb.getpixel((x, y)) for x in range(0, w, step_x)]
                    if not all(_matches(p) for p in row):
                        bot = y + 1
                        break
                # Left
                left = 0
                for x in range(w):
                    col = [rgb.getpixel((x, y)) for y in range(0, h, step_y)]
                    if not all(_matches(p) for p in col):
                        left = x
                        break
                # Right
                right = w
                for x in range(w - 1, -1, -1):
                    col = [rgb.getpixel((x, y)) for y in range(0, h, step_y)]
                    if not all(_matches(p) for p in col):
                        right = x + 1
                        break
                # STRICT: only trim if every border is < 25% of the
                # dimension. This is the line that prevents trimming
                # solid-background artwork.
                max_top    = h * 0.25
                max_bot    = h * 0.25
                max_left   = w * 0.25
                max_right  = w * 0.25
                trim_top   = top
                trim_bot   = h - bot
                trim_left  = left
                trim_right = w - right
                if (trim_top    < max_top  and
                        trim_bot   < max_bot  and
                        trim_left  < max_left and
                        trim_right < max_right and
                        right > left + 16 and bot > top + 16 and
                        (top > 0 or bot < h or
                         left > 0 or right < w)):
                    img = img.crop((left, top, right, bot))
    except Exception:
        pass

    # ── 3. Convert + plain resize. PS5 icon0 is square; trimmed
    # results are typically still close to square. ──
    try:
        if img.mode != 'RGB':
            img = img.convert('RGB')
        img = img.resize((target, target), Image.LANCZOS)
    except Exception:
        return None
    return img


_UFS2TOOL_DIR = None

def extract_backport(custom_temp=None):
    """Extract Backport.py and all src/ modules to a temp directory."""
    import base64 as _b64
    tmp = custom_temp or tempfile.mkdtemp(prefix='exfat_builder_bp_')
    bp_path = os.path.join(tmp, 'Backport.py')
    if not os.path.isfile(bp_path):
        with open(bp_path, 'wb') as f:
            f.write(_b64.b64decode(_BACKPORT_B64))

    src_dir = os.path.join(tmp, 'src')
    os.makedirs(src_dir, exist_ok=True)

    src_files = {
        '__init__.py':                 b'',
        'Archive.py':                  _b64.b64decode(_SRC_ARCHIVE_B64),
        'decrypt_fself.py':            _b64.b64decode(_SRC_DECRYPT_B64),
        'make_fself.py':               _b64.b64decode(_SRC_FSELF_B64),
        'ps5_sdk_version_patcher.py':  _b64.b64decode(_SRC_PATCHER_B64),
    }
    for fname, content in src_files.items():
        fpath = os.path.join(src_dir, fname)
        # Always write — ensures files are complete even after partial extractions
        with open(fpath, 'wb') as f:
            f.write(content)

    return bp_path, tmp

def extract_ufs2tool(custom_temp=None):
    """Extract UFS2Tool.exe, UFS2Tool.dll and DokanNet.dll to a temp folder."""
    global _UFS2TOOL_DIR
    base = custom_temp if (custom_temp and os.path.isdir(custom_temp)) else None
    _UFS2TOOL_DIR = tempfile.mkdtemp(prefix='exfat_builder_ufs2_', dir=base)
    files = [
        ('UFS2Tool.exe',             _UFS2TOOL_EXE_B64),
        ('UFS2Tool.dll',             _UFS2TOOL_DLL_B64),
        ('DokanNet.dll',             _DOKAN_B64),
    ]
    # runtimeconfig.json — .NET 8 framework-dependent
    rc_json = (b'{"runtimeOptions":{"tfm":"net8.0","framework":{'
               b'"name":"Microsoft.NETCore.App","version":"8.0.0"},'
               b'"configProperties":{"System.Reflection.Metadata.'
               b'MetadataUpdater.IsSupported":false}}}')
    rc_path = os.path.join(_UFS2TOOL_DIR, 'UFS2Tool.runtimeconfig.json')
    with open(rc_path, 'wb') as f:
        f.write(rc_json)
    for name, b64 in files:
        path = os.path.join(_UFS2TOOL_DIR, name)
        with open(path, 'wb') as f:
            f.write(base64.b64decode(b64))
    return os.path.join(_UFS2TOOL_DIR, 'UFS2Tool.exe')

def cleanup_ufs2tool():
    global _UFS2TOOL_DIR
    if _UFS2TOOL_DIR and os.path.isdir(_UFS2TOOL_DIR):
        shutil.rmtree(_UFS2TOOL_DIR, ignore_errors=True)

def clear_temp_folder(base_dir):
    removed, failed, size = 0, 0, 0
    try:
        for entry in os.scandir(base_dir):
            if entry.name.startswith('exfat_builder_'):
                try:
                    if entry.is_dir():
                        # sum size
                        for root, dirs, files in os.walk(entry.path):
                            for fn in files:
                                try:
                                    size += os.path.getsize(os.path.join(root, fn))
                                except Exception:
                                    pass
                        shutil.rmtree(entry.path, ignore_errors=True)
                        removed += 1
                except Exception:
                    failed += 1
    except Exception as e:
        return False, str(e), 0
    return True, removed, size

def is_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except Exception:
        return False

def relaunch_as_admin():
    script = os.path.abspath(sys.argv[0])
    params = ' '.join('"' + a + '"' for a in sys.argv[1:])
    try:
        ret = ctypes.windll.shell32.ShellExecuteW(
            None, 'runas', sys.executable,
            '"' + script + '" ' + params, None, 1)
        if ret <= 32:
            messagebox.showerror('Admin required',
                'This app needs Administrator rights.\n'
                'Right-click the .exe and choose Run as administrator.')
    except Exception as e:
        messagebox.showerror('Elevation failed', str(e))
    sys.exit(0)

if not is_admin():
    relaunch_as_admin()

# ── Theme ────────────────────────────────────────────────────────────────────
# Step 2 (v2.0.4): the design-system theme module is now the source of truth.
# These module-level constants are kept as aliases so the ~1300 widget
# definitions throughout the codebase don't need to change immediately —
# they all reference these names, and now those names point at the theme.
#
# Step 3+ will migrate widgets to either ttk styles or direct COLORS[...] /
# FONTS[...] lookups; for now the indirection lets us flip the entire palette
# in one place.
from tkinter_theme import apply_theme, COLORS, FONTS

BG           = COLORS['bg_1']        # was '#000000' — design system uses #0a0a0a (near-black, never pure)
SURFACE2     = COLORS['bg_4']        # was '#1c1c1c' — closest design token is #1a1a1a
FIELD_BG     = COLORS['field_bg']    # '#f0f0f0' — exact match
