class QueueItem:
    def __init__(self, game_folder, output_dir, output_name,
                 game_title=None, title_id=None, version=None):
        self.game_folder = game_folder
        self.output_dir  = output_dir
        self.output_name = output_name
        self.game_title  = game_title
        self.title_id    = title_id
        self.version     = version
        self.status      = 'waiting'

class Tooltip:
    """Lightweight tooltip that appears below a widget on hover."""
    _active = None  # singleton — only one tooltip visible at a time

    def __init__(self, widget, text, delay=600, wraplength=320):
        self.widget = widget
        self.text   = text
        self.delay  = delay
        self.wraplength = wraplength
        self._after_id = None
        self._tip      = None
        widget.bind('<Enter>',    self._schedule, add='+')
        widget.bind('<Leave>',    self._hide,     add='+')
        widget.bind('<Button-1>', self._hide,     add='+')

    def _schedule(self, _=None):
        self._cancel()
        self._after_id = self.widget.after(self.delay, self._show)

    def _cancel(self):
        if self._after_id:
            try: self.widget.after_cancel(self._after_id)
            except Exception: pass
            self._after_id = None

    def _show(self):
        if self._tip or not self.text:
            return
        # Hide any other active tooltip
        if Tooltip._active is not None and Tooltip._active is not self:
            Tooltip._active._hide()
        Tooltip._active = self
        try:
            x = self.widget.winfo_rootx() + 12
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 4
        except Exception:
            return
        tip = tk.Toplevel(self.widget)
        tip.wm_overrideredirect(True)
        tip.wm_geometry('+%d+%d' % (x, y))
        tip.configure(bg='#1e1e1e', highlightbackground='#3a3a3a',
                       highlightthickness=1)
        try:
            tip.attributes('-topmost', True)
        except Exception:
            pass
        lbl = tk.Label(tip, text=self.text, bg='#1e1e1e', fg='#dddddd',
                       font=('Segoe UI', 8), padx=8, pady=4,
                       justify='left', wraplength=self.wraplength)
        lbl.pack()
        self._tip = tip

    def _hide(self, _=None):
        self._cancel()
        if self._tip is not None:
            try: self._tip.destroy()
            except Exception: pass
            self._tip = None
        if Tooltip._active is self:
            Tooltip._active = None

class SubTabBar:
    """Lightweight horizontal sub-tab bar — used inside main tabs that have
    multiple sub-views (Y2JB, Settings, Advanced). Owns the bar widget and the
    container in which sub-frames will be packed; only one sub-frame is shown
    at a time.

    Step 14 (v2.1.6): redesigned with design-system tokens — bg_0 bar bg,
    accent text + 2px accent underline on active tab, hover lifts inactive
    tabs to fg_2.

    Usage:
        bar = SubTabBar(parent_frame)
        conn  = bar.add_tab('connection', '🔌 Connection')
        inst  = bar.add_tab('install',    '📤 Install')
        # ... build widgets inside `conn` and `inst` ...
        bar.show('connection')   # or bar.show_first()
    """
    def __init__(self, parent, font_size=10, pad=(14, 7)):
        self.parent = parent
        self.font_size = font_size
        self.pad = pad
        self._tabs   = []   # list of (key, btn, frame)
        self._active = None

        # Design tokens via the theme module (defensive fallback below)
        try:
            from tkinter_theme import COLORS as _C
            self._bar_bg   = _C['bg_0']
            self._fg_inact = _C['fg_4']
            self._fg_hover = _C['fg_2']
            self._fg_act   = _C['accent']
            self._border   = _C['border_2']
            self._body_bg  = _C['bg_1']
        except Exception:
            self._bar_bg   = '#0a0a0a'
            self._fg_inact = '#888888'
            self._fg_hover = '#c0c0c0'
            self._fg_act   = '#4a9eff'
            self._border   = '#222222'
            self._body_bg  = BG

        self.bar = tk.Frame(parent, bg=self._bar_bg)
        self.bar.pack(fill='x')
        # 1px hairline divider under the bar
        tk.Frame(parent, bg=self._border, height=1).pack(fill='x')

        # Inner padding so tabs align to the page padding
        self._bar_inner = tk.Frame(self.bar, bg=self._bar_bg)
        self._bar_inner.pack(fill='x', padx=16)

        # Container for the sub-frames
        self.body = tk.Frame(parent, bg=self._body_bg)
        self.body.pack(fill='both', expand=True)

    def add_tab(self, key, text):
        # Each tab is a vertical wrapper: the Label sits on top, a thin
        # bottom Frame becomes a 2px accent underline when active.
        wrap = tk.Frame(self._bar_inner, bg=self._bar_bg)
        wrap.pack(side='left')
        btn = tk.Label(wrap, text=text,
                       font=('Segoe UI', self.font_size, 'bold'),
                       bg=self._bar_bg, fg=self._fg_inact,
                       padx=self.pad[0], pady=self.pad[1],
                       cursor='hand2')
        btn.pack()
        underline = tk.Frame(wrap, bg=self._bar_bg, height=2)
        underline.pack(fill='x')
        btn._underline = underline
        btn._wrap = wrap

        btn.bind('<Button-1>', lambda e, k=key: self.show(k))
        wrap.bind('<Button-1>', lambda e, k=key: self.show(k))
        # Hover effect — only when the tab isn't already active
        def _enter(e, b=btn, k=key):
            if self._active != k:
                b.configure(fg=self._fg_hover)
        def _leave(e, b=btn, k=key):
            if self._active != k:
                b.configure(fg=self._fg_inact)
        btn.bind('<Enter>', _enter)
        btn.bind('<Leave>', _leave)

        frame = tk.Frame(self.body, bg=self._body_bg)
        self._tabs.append((key, btn, frame))
        return frame

    def show(self, key):
        for k, btn, frame in self._tabs:
            if k == key:
                frame.pack(fill='both', expand=True)
                btn.configure(fg=self._fg_act)
                if hasattr(btn, '_underline'):
                    btn._underline.configure(bg=self._fg_act)
            else:
                frame.pack_forget()
                btn.configure(fg=self._fg_inact)
                if hasattr(btn, '_underline'):
                    btn._underline.configure(bg=self._bar_bg)
        self._active = key

    def show_first(self):
        if self._tabs:
            self.show(self._tabs[0][0])


class LeftRail:
    """Sidebar-style category picker: vertical list of labels on the left,
    content panel on the right. Used for the Settings tab and Help tab where
    a 'list of categories → focused content' layout reads better than a
    horizontal sub-tab bar.

    Step 8 (v2.1.0): redesigned with design-system tokens — bg_0 rail
    background, accent-blue left border on the active item, hover state on
    bg_1, optional section label header.

    Usage:
        rail = LeftRail(parent_frame, rail_width=210)
        rail.add_section_label('SETTINGS')
        general_pane  = rail.add_section('general',  '\u2699 General')
        ftp_pane      = rail.add_section('ftp',      '\U0001f4e1 FTP / PS5')
        rail.add_divider()
        reset_pane    = rail.add_section('reset',    '\u21bb Reset to defaults')
        # ... build widgets inside `general_pane`, `ftp_pane` ...
        rail.show('general')
    """
    def __init__(self, parent, rail_width=210, font_size=10):
        self.parent = parent
        self.rail_width = rail_width
        self.font_size = font_size
        self._sections = []   # list of (key, btn, frame)
        self._active = None

        # Pull design tokens here so the legacy callers that import this
        # class don't need to do it themselves.
        try:
            from tkinter_theme import COLORS as _C
            self._rail_bg     = _C['bg_0']
            self._rail_hover  = _C['bg_1']
            self._rail_active = _C['accent_08']
            self._rail_accent = _C['accent']
            self._fg_muted    = _C['fg_4']
            self._fg_active   = _C['fg_0']
            self._border      = _C['border_2']
            self._fg_dim      = _C['fg_5']
        except Exception:
            # Fallback to legacy colors if theme isn't available
            self._rail_bg = '#0a0a0a'
            self._rail_hover = '#151515'
            self._rail_active = '#1a2232'
            self._rail_accent = '#4a9eff'
            self._fg_muted = '#888888'
            self._fg_active = '#ffffff'
            self._border = '#222222'
            self._fg_dim = '#555555'

        # Outer container
        outer = tk.Frame(parent, bg=BG)
        outer.pack(fill='both', expand=True)

        # Left rail (vertical button strip) + 1px right separator
        self.rail = tk.Frame(outer, bg=self._rail_bg, width=rail_width)
        self.rail.pack(side='left', fill='y')
        self.rail.pack_propagate(False)
        # Top inner padding
        tk.Frame(self.rail, bg=self._rail_bg, height=12).pack(fill='x')

        tk.Frame(outer, bg=self._border, width=1).pack(side='left', fill='y')

        # Body container — holds the active section's frame
        self.body = tk.Frame(outer, bg=BG)
        self.body.pack(side='left', fill='both', expand=True)

    def add_section_label(self, text):
        """Add a small uppercase section header in the rail (e.g. 'SETTINGS').
        Decorative — not selectable."""
        tk.Label(self.rail, text=text,
                 font=('Segoe UI', 8, 'bold'),
                 bg=self._rail_bg, fg=self._fg_dim,
                 padx=20, pady=4, anchor='w'
                 ).pack(fill='x')

    def add_divider(self):
        """Insert a 1px horizontal divider in the rail."""
        wrap = tk.Frame(self.rail, bg=self._rail_bg)
        wrap.pack(fill='x', pady=(8, 8))
        tk.Frame(wrap, bg=self._border, height=1
                 ).pack(fill='x', padx=16)

    def add_section(self, key, text):
        # Each rail item is a wrapper Frame so we can paint a 2px accent
        # left border when the item is active. The Frame holds an inner
        # Label for the actual click target.
        wrap = tk.Frame(self.rail, bg=self._rail_bg)
        wrap.pack(fill='x')
        # Left accent strip — width 2px, color toggles on/off
        accent = tk.Frame(wrap, bg=self._rail_bg, width=2)
        accent.pack(side='left', fill='y')
        accent.pack_propagate(False)

        btn = tk.Label(wrap, text=text,
                       font=('Segoe UI', self.font_size),
                       bg=self._rail_bg, fg=self._fg_muted,
                       padx=18, pady=9,
                       anchor='w', cursor='hand2')
        btn.pack(side='left', fill='x', expand=True)

        # Stash the accent strip on the button so .show() can recolor it
        btn._wrap = wrap
        btn._accent_strip = accent

        btn.bind('<Button-1>', lambda e, k=key: self.show(k))
        # Hover effect
        def _enter(e, b=btn, w=wrap, k=key):
            if self._active != k:
                w.configure(bg=self._rail_hover)
                b.configure(bg=self._rail_hover, fg=self._fg_active)
        def _leave(e, b=btn, w=wrap, k=key):
            if self._active != k:
                w.configure(bg=self._rail_bg)
                b.configure(bg=self._rail_bg, fg=self._fg_muted)
        btn.bind('<Enter>', _enter)
        btn.bind('<Leave>', _leave)
        wrap.bind('<Enter>', _enter)
        wrap.bind('<Leave>', _leave)
        accent.bind('<Button-1>', lambda e, k=key: self.show(k))

        frame = tk.Frame(self.body, bg=BG)
        self._sections.append((key, btn, frame))
        return frame

    def show(self, key):
        for k, btn, frame in self._sections:
            if k == key:
                frame.pack(fill='both', expand=True)
                btn.configure(fg=self._fg_active, bg=self._rail_active)
                btn._wrap.configure(bg=self._rail_active)
                btn._accent_strip.configure(bg=self._rail_accent)
            else:
                frame.pack_forget()
                btn.configure(fg=self._fg_muted, bg=self._rail_bg)
                btn._wrap.configure(bg=self._rail_bg)
                btn._accent_strip.configure(bg=self._rail_bg)
        self._active = key

    def show_first(self):
        if self._sections:
            self.show(self._sections[0][0])


class ExFATBuilder(_TK_BASE):
    def _on_close(self):
        # Save window position and size before closing
        try:
            self._settings['window_geometry'] = self.geometry()
            # Step 21 (v2.2.2): also persist current language so it
            # survives next launch even if user previewed a language
            # without explicitly clicking the Apply button. If
            # _lang_var holds the active language code, copy it into
            # settings here.
            try:
                if hasattr(self, '_lang_var') and self._lang_var.get():
                    self._settings['language'] = self._lang_var.get()
            except Exception:
                pass
            save_settings(self._settings)
        except Exception:
            pass
        cleanup_scripts()
        cleanup_ufs2tool()
        self.destroy()

    # ── Keyboard shortcuts ──
    def _kbd_build(self, event=None):
        """Ctrl+B: build current tab's queue."""
        try:
            tab = self._active_tab.get() if hasattr(self, '_active_tab') else 'build'
            if tab == 'build' and hasattr(self, '_run_queue'):
                self._run_queue()
            elif tab == 'ffpkg' and hasattr(self, '_ffpkg_run_queue'):
                self._ffpkg_run_queue()
        except Exception:
            pass

    def _kbd_cancel(self, event=None):
        """Esc: cancel running build/queue."""
        try:
            # Don't fire if focus is in an entry/text widget — let Esc do its
            # native job there (close popups, deselect, etc.)
            focus = self.focus_get()
            if focus is not None:
                wclass = focus.winfo_class()
                if wclass in ('Entry', 'Text', 'TCombobox', 'Spinbox'):
                    return
            # Active tab determines which cancel to call
            tab = self._active_tab.get() if hasattr(self, '_active_tab') else 'build'
            if tab == 'build' and hasattr(self, '_cancel_build'):
                self._cancel_build()
            elif tab == 'ffpkg' and hasattr(self, '_ffpkg_cancel'):
                self._ffpkg_cancel()
        except Exception:
            pass

    def _kbd_test_ftp(self, event=None):
        """Ctrl+Shift+T: test FTP connection."""
        try:
            if hasattr(self, '_test_ftp_conn'):
                self._test_ftp_conn()
        except Exception:
            pass

    def _kbd_refresh(self, event=None):
        """F5: refresh current tab's content."""
        try:
            tab = self._active_tab.get() if hasattr(self, '_active_tab') else ''
            if tab == 'ps5' and hasattr(self, '_ps5_refresh'):
                self._ps5_refresh()
            elif tab == 'images' and hasattr(self, '_imgs_refresh'):
                self._imgs_refresh()
            elif tab == 'library' and hasattr(self, '_lib_refresh'):
                self._lib_refresh()
        except Exception:
            pass

    def _show_keyboard_shortcuts(self):
        """Show a modal listing all keyboard shortcuts."""
        dlg = tk.Toplevel(self)
        dlg.title('Keyboard shortcuts')
        dlg.configure(bg=BG)
        dlg.geometry('420x340')
        dlg.transient(self)
        try:
            dlg.iconbitmap(self.winfo_toplevel().iconbitmap())
        except Exception:
            pass

        tk.Label(dlg, text='\u2328  Keyboard shortcuts',
                 font=('Segoe UI', 13, 'bold'), bg=BG, fg=TEXT,
                 padx=20, pady=14).pack(anchor='w')

        body = tk.Frame(dlg, bg=BG)
        body.pack(fill='both', expand=True, padx=20, pady=(0, 12))

        SHORTCUTS = [
            ('Ctrl + B',          'Build queue (current tab)'),
            ('Esc',               'Cancel running build'),
            ('F5',                'Refresh current tab'),
            ('Ctrl + Shift + T',  'Test FTP connection'),
            ('Ctrl + Q',          'Quit application'),
            ('Double-click row',  'Open build folder (in History tab)'),
            ('Drop folder',       'Add to build queue (drag & drop)'),
        ]
        for keys, desc in SHORTCUTS:
            row = tk.Frame(body, bg=BG)
            row.pack(fill='x', pady=2)
            tk.Label(row, text=keys, font=('Consolas', 10, 'bold'),
                     bg=SURFACE2, fg=ACCENT, width=18, anchor='w',
                     padx=8, pady=3).pack(side='left')
            tk.Label(row, text=desc, font=('Segoe UI', 9),
                     bg=BG, fg=TEXT, anchor='w',
                     padx=10).pack(side='left', fill='x', expand=True)

        tk.Button(dlg, text='Close',
                  font=('Segoe UI', 9), bg=ACCENT, fg=TEXT,
                  activebackground='#3a8eef', relief='flat', bd=0,
                  padx=20, pady=6, cursor='hand2',
                  command=dlg.destroy).pack(pady=(0, 16))

    def __init__(self):
        super().__init__()
        # Step 2 (v2.0.4): apply the design-system theme to all ttk widgets.
        # This sets up Primary/Secondary/Ghost/Warn/Danger button styles,
        # Card.TFrame, theme-aware Treeview, themed scrollbars, and option_add
        # defaults for non-ttk widgets like Listbox / Text / Menu / Canvas.
        # Existing tk.* widgets with explicit bg/fg kwargs continue to work;
        # they'll be migrated to ttk styles tab-by-tab in Step 3+.
        apply_theme(self)
        self.title('exFAT Image Builder  [Administrator]')

        self._settings = load_settings()

        # Restore window geometry from settings, with sanity check
        saved_geom = self._settings.get('window_geometry', '')
        if saved_geom and re.match(r'^\d+x\d+([+\-]\d+[+\-]\d+)?$', saved_geom):
            # Make sure window is on-screen — if monitor was unplugged, fall back
            try:
                m = re.match(r'^(\d+)x(\d+)\+(-?\d+)\+(-?\d+)$', saved_geom)
                if m:
                    w, h, x, y = (int(g) for g in m.groups())
                    sw = self.winfo_screenwidth()
                    sh = self.winfo_screenheight()
                    if x >= -50 and y >= -50 and x < sw - 100 and y < sh - 100:
                        self.geometry(saved_geom)
                    else:
                        self.geometry('780x760')
                else:
                    self.geometry(saved_geom)
            except Exception:
                self.geometry('780x760')
        else:
            self.geometry('780x760')

        self.resizable(True, True)
        self.minsize(680, 640)
        self.configure(bg=BG)
        self.protocol('WM_DELETE_WINDOW', self._on_close)

        # Keyboard shortcuts
        self.bind_all('<Control-b>',     self._kbd_build)
        self.bind_all('<Control-B>',     self._kbd_build)
        self.bind_all('<Escape>',        self._kbd_cancel)
        self.bind_all('<Control-q>',     lambda e: self._on_close())
        self.bind_all('<Control-Q>',     lambda e: self._on_close())
        self.bind_all('<Control-Shift-T>', self._kbd_test_ftp)
        self.bind_all('<F5>',            self._kbd_refresh)

        self._bat_path, ico_path = extract_scripts(
            self._settings.get('temp_dir'))
        try:
            self.iconbitmap(ico_path)
        except Exception:
            pass

        self.game_folder = tk.StringVar()
        self.output_dir  = tk.StringVar(
            value=self._settings.get('output_dir', ''))
        self.output_name = tk.StringVar(value='game.exfat')
        self.status_text = tk.StringVar(value='Running as Administrator  ✓')
        self._temp_dir_var = tk.StringVar(
            value=self._settings.get('temp_dir', ''))
        self._osfmount_path_var = tk.StringVar(
            value=self._settings.get('osfmount_path', ''))
        self._ftp_ip_var   = tk.StringVar(
            value=self._settings.get('ftp_ip', ''))
        self._ftp_port_var = tk.StringVar(
            value=str(self._settings.get('ftp_port', 2121)))
        self._ftp_path_var = tk.StringVar(
            value=self._settings.get('ftp_path', '/data/etaHEN/games/'))
        self._ftp_auto_var = tk.BooleanVar(
            value=self._settings.get('ftp_auto', False))
        self._discord_var  = tk.StringVar(
            value=self._settings.get('discord_webhook', ''))
        self._sound_var    = tk.BooleanVar(
            value=self._settings.get('notify_sound', True))
        self._retry_var    = tk.IntVar(
            value=self._settings.get('retry_count', 3))
        self._auto_ip_var  = tk.BooleanVar(
            value=self._settings.get('auto_ip', False))
        self._logs_dir_var = tk.StringVar(
            value=self._settings.get('logs_dir',
                  os.path.join(os.path.expanduser('~'), 'exfat_builder_logs')))
        # Advanced build parameters
        self._adv_cluster_var = tk.StringVar(value=self._settings.get('adv_cluster', 'Auto'))
        self._adv_sector_var  = tk.StringVar(value=self._settings.get('adv_sector', '512'))
        self._adv_threads_var = tk.StringVar(value=self._settings.get('adv_threads', '1'))
        self._adv_retries_var      = tk.StringVar(value=str(self._settings.get('adv_retries', '3')))
        self._adv_retry_wait_var   = tk.StringVar(value=str(self._settings.get('adv_retry_wait', '3')))
        self._adv_skip_verify_var  = tk.BooleanVar(value=self._settings.get('adv_skip_verify', False))
        self._lowercase_names_var  = tk.BooleanVar(value=self._settings.get('lowercase_names', False))
        self._adv_excl_hidden_var  = tk.BooleanVar(value=self._settings.get('adv_excl_hidden', False))
        self._adv_delete_source_var      = tk.BooleanVar(
            value=self._settings.get('adv_delete_source', False))
        self._adv_delete_source_ffpkg_var = tk.BooleanVar(
            value=self._settings.get('adv_delete_source_ffpkg', False))
        # New advanced features
        self._adv_auto_upload_var    = tk.BooleanVar(
            value=self._settings.get('adv_auto_upload', False))
        self._adv_robo_log_var       = tk.BooleanVar(
            value=self._settings.get('adv_robo_log', False))
        self._adv_robo_log_dir_var   = tk.StringVar(
            value=self._settings.get('adv_robo_log_dir', ''))
        self._adv_checksum_var       = tk.BooleanVar(
            value=self._settings.get('adv_checksum_verify', False))
        self._adv_img_size_var       = tk.StringVar(
            value=self._settings.get('adv_img_size_override', ''))
        self._adv_show_var    = tk.BooleanVar(value=False)
        # ffpkg advanced parameters
        self._adv_ffpkg_block_var  = tk.StringVar(value=self._settings.get('adv_ffpkg_block', '65536'))
        self._adv_ffpkg_frag_var   = tk.StringVar(value=self._settings.get('adv_ffpkg_frag',  '65536'))
        self._adv_ffpkg_minfree_var= tk.StringVar(value=self._settings.get('adv_ffpkg_minfree','0'))
        self._adv_ffpkg_inode_var  = tk.StringVar(value=self._settings.get('adv_ffpkg_inode', '262144'))
        # Pre-initialise vars used by _refresh_* methods called in __init__
        # before the settings tab is fully built
        self._temp_size_var  = tk.StringVar(value='')
        self._logs_count_var = tk.StringVar(value='')
        self._ftp_status_var = tk.StringVar(value='Not connected')
        self._osf_found_var  = tk.StringVar(value='')
        self._building       = False
        self._paused         = False
        self._pause_after_current = False   # pause after current game finishes
        self._game_start_times = {}         # idx → start time for per-game ETA
        self._start_time     = None
        self._current_pct    = 0
        self._robocopy_file_count = 0
        self._bar_width      = 720
        self._step_label_var = tk.StringVar(value='')
        self._pct_var        = tk.StringVar(value='')
        self._eta_var        = tk.StringVar(value='')
        self._queue_eta_var  = tk.StringVar(value='')
        self._queue          = []
        self._detected_title    = None
        self._detected_title_id = None
        self._detected_version  = None
        # Drive polling
        self._mounted_drive   = None
        self._image_total_gb  = None
        self._copy_start_free = None
        self._copy_start_time = None
        self._drive_poll_id   = None
        self._source_file_count  = 0
        self._dest_file_count    = 0
        self._dest_walk_last_ts  = 0.0
        self._dest_walk_running  = False
        self._current_build_idx  = 0
        # FTP upload cancel
        self._ftp_cancel      = False
        self._ftp_uploading   = False
        # Library
        self._lib_folders     = self._settings.get('lib_folders', [])
        self._lib_games       = []   # list of dicts
        self._lib_cards       = []   # tk widgets
        self._lib_filter      = ''
        # Recently used game folders (last 10)
        self._recent_folders  = self._settings.get('recent_folders', [])
        # Theme
        self._theme_var = tk.StringVar(value=self._settings.get('theme', 'dark'))
        # Language
        saved_lang = self._settings.get('language', 'en')
        set_language(saved_lang)
        self._lang_var = tk.StringVar(value=saved_lang)
        # ffpkg builder state
        self._ffpkg_queue        = []
        self._ffpkg_building     = False
        self._ffpkg_start_time   = None
        self._ffpkg_current_pct  = 0
        self._ffpkg_ufs2_exe     = None
        self._ffpkg_stage        = 'init'
        self._ffpkg_total_files  = 0
        self._ffpkg_out_path     = None
        self._ffpkg_expected_size       = 0
        self._ffpkg_current_queue_idx   = 0
        self._ffpkg_folder_sizes        = {}  # folder path → size bytes cache
        self._ffpkg_folder_file_counts  = {}  # folder path → file count cache
        # Y2JB state
        self._y2jb_ps5_ip   = tk.StringVar(value=self._settings.get('ftp_ip', ''))
        self._y2jb_ftp_port = tk.StringVar(value=self._settings.get('y2jb_ftp_port', '2121'))
        self._y2jb_dpi_port = tk.StringVar(value=self._settings.get('y2jb_dpi_port', '12800'))
        self._y2jb_pkg_paths = {
            'USA': tk.StringVar(value=self._settings.get('y2jb_pkg_usa', '')),
            'EU':  tk.StringVar(value=self._settings.get('y2jb_pkg_eu',  '')),
            'JP':  tk.StringVar(value=self._settings.get('y2jb_pkg_jp',  '')),
        }
        self._ffpkg_poll_drive_free_start = None
        self._ffpkg_copy_start_t = None
        self._ffpkg_copy_start_size = 0
        self._ffpkg_final_size   = 0
        self._ffpkg_poll_id      = None
        self._ffpkg_size_window  = []

        self._build_ui()
        self._render_queue()
        self._refresh_temp_size()
        # Check for updates in background after 3 seconds
        self.after(3000, self._check_for_updates)
        if self._settings.get('lib_auto_scan', True) and self._lib_folders:
            self.after(1500, self._lib_scan)
        # Check OSFMount after UI is ready
        self.after(500, self._check_osfmount_banner)
        # Ko-fi donation popup — shown once per version
        self.after(1200, self._show_kofi_popup)

        # Restore saved window position and size
        geo = self._settings.get('window_geometry')
        if geo:
            try:
                self.geometry(geo)
                # Make sure it's on screen (handles monitor changes)
                self.update_idletasks()
                x = self.winfo_x()
                y = self.winfo_y()
                w = self.winfo_width()
                h = self.winfo_height()
                sw = self.winfo_screenwidth()
                sh = self.winfo_screenheight()
                # Clamp to screen bounds
                x = max(0, min(x, sw - 200))
                y = max(0, min(y, sh - 200))
                self.geometry('%dx%d+%d+%d' % (w, h, x, y))
            except Exception:
                pass

    def _show_kofi_popup(self):
        """Show a Ko-fi donation popup on every launch."""
        import webbrowser as _wb
        KOFI_URL = 'https://ko-fi.com/deckerr9746220'

        win = tk.Toplevel(self)
        win.title('exFAT Image Builder')
        win.configure(bg=BG)
        win.resizable(False, False)
        win.grab_set()

        # Centre over main window
        self.update_idletasks()
        mx = self.winfo_x() + self.winfo_width() // 2
        my = self.winfo_y() + self.winfo_height() // 2
        win.geometry(f'500x360+{mx - 250}+{my - 180}')

        # ── Ko-fi orange accent bar at top ──
        tk.Frame(win, bg='#ff5e16', height=4).pack(fill='x')

        body = tk.Frame(win, bg=BG)
        body.pack(fill='both', expand=True, padx=32, pady=22)

        # Icon + title row
        top = tk.Frame(body, bg=BG)
        top.pack(fill='x', pady=(0, 12))
        tk.Label(top, text='☕', font=('Segoe UI Emoji', 28),
                 bg=BG, fg='#ff5e16').pack(side='left', padx=(0, 10))
        title_col = tk.Frame(top, bg=BG)
        title_col.pack(side='left', anchor='w')
        tk.Label(title_col, text='exFAT Image Builder  v' + APP_VERSION,
                 font=('Segoe UI', 12, 'bold'), bg=BG, fg=TEXT,
                 anchor='w').pack(anchor='w')
        tk.Label(title_col, text='by DecKerr97',
                 font=('Segoe UI', 9), bg=BG, fg=MUTED,
                 anchor='w').pack(anchor='w')

        tk.Frame(body, bg=BORDER, height=1).pack(fill='x', pady=(0, 14))

        # Message — wraplength keeps text inside the window
        msg = (
            "Hey — thanks for using the tool! I've been putting a lot of time "
            "into building and maintaining this, and every small donation really "
            "does help keep the project going.\n\n"
            "If this has saved you time or made your life easier, consider "
            "buying me a coffee — it genuinely means a lot. 🙏"
        )
        tk.Label(body, text=msg, font=('Segoe UI', 9),
                 bg=BG, fg='#cccccc', justify='left',
                 wraplength=436, anchor='w').pack(anchor='w', pady=(0, 18))

        # Buttons row
        btns = tk.Frame(body, bg=BG)
        btns.pack(anchor='e')

        def _open_kofi():
            _wb.open(KOFI_URL)
            win.destroy()

        tk.Button(btns, text='  Maybe later  ',
                  font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                  activebackground=BORDER, activeforeground=TEXT,
                  relief='flat', bd=0, padx=10, pady=6, cursor='hand2',
                  command=win.destroy).pack(side='left', padx=(0, 8))

        tk.Button(btns, text='☕  Buy me a coffee',
                  font=('Segoe UI', 9, 'bold'), bg='#ff5e16', fg='#ffffff',
                  activebackground='#e04d0a', activeforeground='#ffffff',
                  relief='flat', bd=0, padx=14, pady=6, cursor='hand2',
                  command=_open_kofi).pack(side='left')

        win.bind('<Return>', lambda e: _open_kofi())
        win.bind('<Escape>', lambda e: win.destroy())
        win.focus_set()

