        hdr = tk.Frame(self, bg=BG)
        hdr.pack(fill='x', padx=24, pady=(10, 6))
        title_row = tk.Frame(hdr, bg=BG)
        title_row.pack(fill='x')
        tk.Label(title_row, text='exFAT Image Builder',
                 font=('Segoe UI', 16, 'bold'), bg=BG, fg=TEXT).pack(side='left', anchor='w')
        tk.Label(title_row, text='v' + APP_VERSION,
                 font=('Segoe UI', 8), bg=BG, fg='#3a3a3a').pack(side='left', anchor='s', padx=(8,0), pady=(0,4))
        tk.Label(title_row, text='by DecKerr97',
                 font=('Segoe UI', 9), bg=BG, fg='#555555').pack(side='right', anchor='s', pady=(6, 0))
        tk.Label(hdr, text='Build PS5 exFAT game images  \u2014  scripts bundled, game name auto-detected',
                 font=('Segoe UI', 10), bg=BG, fg=MUTED).pack(anchor='w')
        tk.Label(hdr, text='Inspired by NookieAI \u2022 stonemodder (Porkfolio)',
                 font=('Segoe UI', 8), bg=BG, fg='#3a3a3a').pack(anchor='w')
        tk.Frame(self, bg=BORDER, height=1).pack(fill='x')

        # ── Tab bar ──
        # Outer container holds tabs + accent indicator bar below them
        tab_outer = tk.Frame(self, bg='#0a0a0a')
        tab_outer.pack(fill='x')
        tab_bar = tk.Frame(tab_outer, bg='#0a0a0a')
        tab_bar.pack(fill='x')
        # Accent indicator bar — follows the active tab
        tab_accent = tk.Frame(tab_outer, bg='#0a0a0a', height=2)
        tab_accent.pack(fill='x')
        self._tab_accent_bar = tab_accent

        self._active_tab = tk.StringVar(value='build')
        self._tab_build_frame  = None
        self._tab_extract_frame = None

        def _make_tab(parent, text, key):
            btn = tk.Label(parent, text=text,
                           font=('Segoe UI', 9), bg='#0a0a0a', fg=MUTED,
                           padx=11, pady=8, cursor='hand2')
            btn.pack(side='left')
            def _click(e, k=key):
                self._switch_tab(k)
            btn.bind('<Button-1>', _click)
            # Subtle hover effect
            def _enter(e, b=btn):
                if self._active_tab.get() != key:
                    b.config(fg=TEXT)
            def _leave(e, b=btn):
                if self._active_tab.get() != key:
                    b.config(fg=MUTED)
            btn.bind('<Enter>', _enter)
            btn.bind('<Leave>', _leave)
            return btn

        def _make_divider(parent):
            # Vertical divider between tab groups
            tk.Frame(parent, bg=BORDER, width=1).pack(
                side='left', fill='y', padx=6, pady=4)

        # ── Group 1: Build & manage ──
        self._tab_build_btn   = _make_tab(tab_bar, '\U0001f528 exFAT',     'build')
        self._tab_ffpkg_btn   = _make_tab(tab_bar, '\U0001f4e6 ffpkg',     'ffpkg')
        self._tab_library_btn = _make_tab(tab_bar, '\U0001f4da Library',   'library')
        # Step 40 (v2.5.4): Images is now a sub-tab of Library.
        self._tab_images_btn  = _make_tab(tab_bar, '\U0001f4be Images',    'images')
        self._tab_images_btn.pack_forget()

        _make_divider(tab_bar)

        # ── Group 2: PS5 communication ──
        self._tab_ps5_btn     = _make_tab(tab_bar, '\U0001f3ae PS5',       'ps5')
        # Step 40 (v2.5.4): FTP, Klog, Payloads, Y2JB are now sub-tabs
        # of PS5. Top-bar buttons preserved (so any legacy state-toggle
        # code keeps working) but never packed.
        self._tab_ftp_btn     = _make_tab(tab_bar, '\U0001f4e1 FTP',       'ftp')
        self._tab_ftp_btn.pack_forget()
        self._tab_klog_btn    = _make_tab(tab_bar, '\U0001f4dd Klog',      'klog')
