        self._tab_y2jb_btn.pack_forget()

        _make_divider(tab_bar)

        # ── Group 3: Tools ──
        self._tab_bp_btn      = _make_tab(tab_bar, '\U0001f9e9 Backports', 'backports')
        # Step 42 (v2.5.6): Convert tab — exFAT \u2194 ffpkg conversions.
        self._tab_convert_btn = _make_tab(tab_bar, '\U0001f504 Convert',   'convert')
        # Step 38 (v2.5.2): Extract is now a sub-tab of the exFAT tab,
        # so we no longer pack a top-level Extract button. The button
        # widget is still constructed (so legacy code that toggles
