        self._tab_files_btn.pack_forget()
        self._tab_adv_btn     = _make_tab(tab_bar, '\u2699 Advanced',      'advanced')
        self._tab_hist_btn    = _make_tab(tab_bar, '\U0001f4cb History',   'hist')

        _make_divider(tab_bar)

        # ── Group 4: App ──
        self._tab_cfg_btn     = _make_tab(tab_bar, '\U0001f527 Settings',  'settings')
