    def _build_files_tab(self, parent):
        # Carved out in Step 1 — see ui/tab_files.py
        from ui.tab_files import build_files_tab
        build_files_tab(parent, self)

    # ── File Manager helpers ──────────────────────────────────────────────────
    def _build_ftp_tab(self, parent):
        # Carved out in Step 1 — see ui/tab_ftp.py
        from ui.tab_ftp import build_ftp_tab
        build_ftp_tab(parent, self)

    def _build_extract_tab(self, parent):
        # Carved out in Step 1 — see ui/tab_extract.py
        from ui.tab_extract import build_extract_tab
        build_extract_tab(parent, self)

    def _build_ffpkg_tab(self, parent):
        # v2.9.0: ffpkg tab now has Build + Edit + Extract sub-tabs.
        # Build delegates to ui/tab_ffpkg.py as before; Edit and Extract
        # are built locally (Edit calls ui/tab_ffpkg_edit.py).
        parent.configure(bg=BG)
        self._ffpkg_subtabs = SubTabBar(parent, font_size=10, pad=(16, 9))
        build_pane   = self._ffpkg_subtabs.add_tab('build',
                                '\U0001f6e0  ' + _('Build'))
        edit_pane    = self._ffpkg_subtabs.add_tab('edit',
                                '\u270f  ' + _('Edit'))
        extract_pane = self._ffpkg_subtabs.add_tab('extract',
                                '\U0001f4e4  ' + _('Extract'))

        # Build pane = existing module
        try:
            from ui.tab_ffpkg import build_ffpkg_tab
            build_ffpkg_tab(build_pane, self)
        except Exception as _e:
            tk.Label(build_pane,
                     text='Could not load Build sub-tab:\n' + repr(_e),
                     bg=BG, fg=DANGER, font=('Consolas', 10),
                     justify='left'
                     ).pack(padx=24, pady=24, anchor='nw')

        # Edit pane = new in v2.9.0
        try:
            from ui.tab_ffpkg_edit import build_ffpkg_edit_tab
            build_ffpkg_edit_tab(edit_pane, self)
        except Exception as _e:
            tk.Label(edit_pane,
                     text='Could not build Edit sub-tab:\n' + repr(_e),
                     bg=BG, fg=DANGER, font=('Consolas', 10),
                     justify='left'
                     ).pack(padx=24, pady=24, anchor='nw')

        # Extract pane = new in v2.9.0
        try:
            self._build_ffpkg_extract_pane(extract_pane)
        except Exception as _e:
            tk.Label(extract_pane,
                     text='Could not build Extract sub-tab:\n' + repr(_e),
                     bg=BG, fg=DANGER, font=('Consolas', 10),
                     justify='left'
                     ).pack(padx=24, pady=24, anchor='nw')

        # Restore last sub-tab; persist on switch
        last = self._settings.get('ffpkg_active_subtab', 'build')
        try:
            self._ffpkg_subtabs.show(last)
        except Exception:
            self._ffpkg_subtabs.show_first()
        def _remember(k):
            self._settings['ffpkg_active_subtab'] = k
            try: save_settings(self._settings)
            except Exception: pass
        for key, btn, _frame in self._ffpkg_subtabs._tabs:
            btn.bind('<Button-1>',
                lambda e, k=key: (self._ffpkg_subtabs.show(k), _remember(k)),
                add='+')

    def _ffpkg_subtab_error(self, parent, name, err):
        """Stub kept for backward compatibility after the Extract / Edit /
        Convert sub-tabs were removed. No longer wired to anything, but
        retained so any external caller does not crash."""
        import tkinter as tk
        try:
            for w in parent.winfo_children():
                w.destroy()
        except Exception:
            pass
        msg = ('Could not load the ' + name + ' sub-tab:\n\n' +
               type(err).__name__ + ': ' + str(err))
        try:
            tk.Label(parent, text=msg, justify='left',
                     wraplength=600, padx=24, pady=24,
                     fg='#ff8a8a', bg='#1a0e10',
                     font=('Consolas', 10)).pack(anchor='nw',
                                                  padx=20, pady=20)
        except Exception:
            try: self._log('[FFPKG] ' + msg + '\n')
            except Exception: pass

