    def _ffpkg_extract_browse_image(self):
        from tkinter import filedialog
        p = filedialog.askopenfilename(
            title=_('Select .ffpkg image'),
            filetypes=[('ffpkg images', '*.ffpkg'),
                       ('All files',    '*.*')])
        if not p:
            return
        self._ffpkg_extract_file_var.set(p.replace('/', '\\'))
        # Auto-fill name from filename
        base = os.path.splitext(os.path.basename(p))[0]
        if not self._ffpkg_extract_name_var.get().strip():
            self._ffpkg_extract_name_var.set(base)
        # If no output dir set yet, default to the source file's folder
        if not self._ffpkg_extract_outdir_var.get().strip():
            self._ffpkg_extract_outdir_var.set(
                os.path.dirname(p).replace('/', '\\'))

    def _ffpkg_extract_browse_outdir(self):
        from tkinter import filedialog
        p = filedialog.askdirectory(title=_('Select output folder'))
        if not p:
            return
        self._ffpkg_extract_outdir_var.set(p.replace('/', '\\'))
        self._settings['ffpkg_extract_outdir'] = p.replace('/', '\\')
        try: save_settings(self._settings)
        except Exception: pass

    def _ffpkg_extract_log_line(self, line):
        try:
            self._ffpkg_extract_log.config(state='normal')
            self._ffpkg_extract_log.insert('end', line)
            self._ffpkg_extract_log.see('end')
            self._ffpkg_extract_log.config(state='disabled')
        except Exception:
            pass

    def _ffpkg_extract_set_progress(self, pct):
        try:
            w = self._ffpkg_extract_bar.winfo_width()
            self._ffpkg_extract_bar.coords(self._ffpkg_extract_bar_rect,
                0, 0, int(w * pct / 100), 8)
        except Exception:
            pass

    def _run_ffpkg_extract(self):
        """Worker entry — validates inputs, kicks off UFS2Tool.exe extract."""
        img_path = self._ffpkg_extract_file_var.get().strip()
        out_dir  = self._ffpkg_extract_outdir_var.get().strip()
        out_name = self._ffpkg_extract_name_var.get().strip()

        if not img_path or not os.path.isfile(img_path):
            messagebox.showwarning(_('Missing'),
                _('Please select a valid .ffpkg image.'))
            return
        if not out_dir:
            messagebox.showwarning(_('Missing'),
                _('Please select an output directory.'))
            return
        if not out_name:
            out_name = os.path.splitext(os.path.basename(img_path))[0]
            self._ffpkg_extract_name_var.set(out_name)
        dest = os.path.join(out_dir, out_name)
        if os.path.exists(dest):
            if not messagebox.askyesno(_('Folder exists'),
                    _('Output folder already exists:\n') + dest +
                    _('\n\nFiles will be merged/overwritten. Continue?')):
                return

        # Ensure UFS2Tool is extracted to temp
        try:
            if not self._ffpkg_ufs2_exe or not os.path.isfile(self._ffpkg_ufs2_exe):
                self._ffpkg_ufs2_exe = extract_ufs2tool(
                    self._settings.get('temp_dir') or None)
        except Exception as e:
            messagebox.showerror(_('UFS2Tool extraction failed'), str(e))
            return

        # UI state
        self._ffpkg_extract_btn.config(state='disabled',
            text=_('Extracting...'))
        self._ffpkg_extract_status_var.set(_('Running UFS2Tool extract...'))
        self._ffpkg_extract_eta_var.set('')
        self._ffpkg_extract_set_progress(0)
        # Clear log
        try:
            self._ffpkg_extract_log.config(state='normal')
            self._ffpkg_extract_log.delete('1.0', 'end')
            self._ffpkg_extract_log.config(state='disabled')
        except Exception:
            pass

        self._ffpkg_extract_log_line('[EXTRACT] Image: ' + img_path + '\n')
        self._ffpkg_extract_log_line('[EXTRACT] Destination: ' + dest + '\n\n')

        import threading
        start_time = [time.time()]

        def worker():
            rc = -1
            try:
                os.makedirs(dest, exist_ok=True)
                exe = self._ffpkg_ufs2_exe
                # UFS2Tool v2.5+ extract syntax:
                #   UFS2Tool.exe extract <image-path> <output-directory>
                cmd = [exe, 'extract', img_path, dest]
                self.after(0, self._ffpkg_extract_log_line,
                    '[EXTRACT] Command: ' + ' '.join('"%s"' % a for a in cmd) + '\n\n')
                _enc = 'mbcs' if sys.platform.startswith('win') else 'utf-8'
                proc = subprocess.Popen(cmd,
                    stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                    text=True, encoding=_enc, errors='replace',
                    creationflags=_NO_WIN_FLAGS)
                last_pct = [0]
                for line in proc.stdout:
                    self.after(0, self._ffpkg_extract_log_line, line)
                    # Heuristic progress sniff — UFS2Tool prints lines
                    # mentioning files extracted. We don't get a real
                    # percentage from the CLI, so we just bump the bar
                    # smoothly based on log activity.
                    if 'Extracted' in line or 'Writing' in line or 'extracting' in line.lower():
                        last_pct[0] = min(95, last_pct[0] + 1)
                        self.after(0, self._ffpkg_extract_set_progress, last_pct[0])
                proc.wait()
                rc = proc.returncode
            except Exception as e:
                self.after(0, self._ffpkg_extract_log_line,
                    '[ERROR] ' + str(e) + '\n')
                rc = -2

            elapsed = time.time() - start_time[0]
            m, s = int(elapsed // 60), int(elapsed % 60)
            ok = (rc == 0) and os.path.isdir(dest) and len(os.listdir(dest)) > 0
            self.after(0, self._ffpkg_extract_done, ok, rc, m, s, dest)

        threading.Thread(target=worker, daemon=True).start()

    def _ffpkg_extract_done(self, ok, rc, m, s, dest):
        self._ffpkg_extract_set_progress(100 if ok else 0)
        if ok:
            self._ffpkg_extract_status_var.set(
                _('Complete') + (' (%dm %02ds)' % (m, s)))
            self._ffpkg_extract_log_line(
                '\n[OK] Extraction complete in %dm %02ds\n' % (m, s))
            self._ffpkg_extract_log_line(
                '[OK] Files at: ' + dest + '\n')
        else:
            self._ffpkg_extract_status_var.set(
                _('Failed') + ' (exit ' + str(rc) + ')')
            self._ffpkg_extract_log_line(
                '\n[FAIL] Extraction failed (exit code %s)\n' % rc)
        self._ffpkg_extract_btn.config(state='normal',
            text='\U0001f4e4  ' + _('Extract Image'))

    # ── ffpkg helpers ─────────────────────────────────────────────────────────
    def _build_build_tab(self, parent):
        # Step 38 → 40 (v2.5.4): exFAT tab hosts Build / Extract / Edit
        # exFAT sub-tabs. Refactored to use the shared `build_subtabs`
        # helper so all sub-tab strips across the app look identical.
        from ui.tab_exfat   import build_exfat_tab
        from ui.tab_extract import build_extract_tab
        from ui.tab_files   import build_files_tab
        from ui.shared.cards import build_subtabs

        self._exfat_subtab_activate = build_subtabs(parent, [
            ('build',   '\U0001f528 Build',
                lambda f: build_exfat_tab(f, self)),
            ('extract', '\U0001f4e4 Extract',
                lambda f: build_extract_tab(f, self)),
            ('files',   '\U0001f5c2 Edit exFAT',
                lambda f: build_files_tab(f, self)),
        ])

    # ── Settings strip ──────────────────────────────────────────────────────
    def _activate_dot(self, index):
        # Step 3 (v2.0.5): forward to the new StagedProgressBar widget
        # built in ui/tab_exfat.py. The legacy `_stage_dots` iteration
        # below is now a no-op (the list is empty) but is preserved so
        # any future tab that uses the old idiom still works.
        if hasattr(self, '_build_stages') and self._build_stages is not None:
            try:
                self._build_stages.set_active(index)
            except Exception:
                pass

        for i, (dot, lbl) in enumerate(self._stage_dots):
            if i < index:
                dot.itemconfig('dot', fill=SUCCESS)
                lbl.config(fg=SUCCESS)
            elif i == index:
                dot.itemconfig('dot', fill=ACCENT)
                lbl.config(fg=ACCENT)
            else:
                dot.itemconfig('dot', fill=BORDER)
                lbl.config(fg=MUTED)

    def _add_to_queue(self):
        game = self.game_folder.get().strip()
        odir = self.output_dir.get().strip()
        name = self.output_name.get().strip() or 'game.exfat'
        if not name.lower().endswith('.exfat'):
            name += '.exfat'
        if not game:
            messagebox.showwarning('Missing', 'Please select a game folder.')
            return
        # Step 42 (v2.5.8): final safety net. If the game folder field
        # was set by some path that bypassed the resolver (legacy queue
        # restore, scripting, etc), resolve once more before queueing.
        # No-op if eboot.bin is already at the root.
        resolved = self._resolve_game_root(game)
        if os.path.normpath(resolved) != os.path.normpath(game):
            try:
                self._log('[INFO] Queue add: descended from "%s" to "%s"\n'
                          % (game, resolved))
            except Exception:
                pass
            game = resolved
            self.game_folder.set(game)
        if not odir:
            messagebox.showwarning('Missing', 'Please select an output directory.')
            return
        # ── Duplicate detection ──
        for existing in self._queue:
            if os.path.normpath(existing.game_folder) == os.path.normpath(game):
                if not messagebox.askyesno('Duplicate detected',
                        'This game folder is already in the queue:\n' + game +
                        '\n\nAdd it again anyway?'):
                    return
                break
        out_path = os.path.join(odir, name)
        if os.path.isfile(out_path):
            if not messagebox.askyesno('File exists',
                    'Output file already exists:\n' + out_path +
                    '\n\nIt will be overwritten. Continue?'):
                return
        # ── Disk space check ──
        try:
            free = shutil.disk_usage(odir).free
            game_size = self._get_folder_size(game)
            if game_size > 0 and free < game_size * 1.05:
                free_gb = free / (1024**3)
                need_gb = game_size / (1024**3)
                if not messagebox.askyesno('Low disk space',
                        'Output drive may not have enough space.\n\n'
                        'Estimated needed: %.1f GB\nFree: %.1f GB\n\nContinue anyway?' % (need_gb, free_gb)):
                    return
        except Exception:
            pass
        item = QueueItem(game, odir, name,
                         self._detected_title,
                         self._detected_title_id,
                         self._detected_version)
        self._queue.append(item)
        self._render_queue()
        # Track recently used
        game = self.game_folder.get().strip()
        if game:
            self._add_to_recent(game)
        self.game_folder.set('')
        # Keep output_dir so user doesn't have to re-select it each time
        self.output_name.set('game.exfat')
        self._info_frame.pack_forget()
        self._auto_label.pack_forget()
        self._no_sfo_label.pack_forget()
        self._filename_preview.config(fg='#555555')
        self._detected_title = self._detected_title_id = self._detected_version = None
        self._set_status(str(len(self._queue)) + ' item(s) in queue', ACCENT)

    def _br_connect(self):
        self._br_status.set('Connecting...')
        def worker():
            try:
                ftp = self._ftp_connect()
                self._br_ftp[0] = ftp
                self.after(0, self._br_status.set, 'Connected \u2713')
                self.after(0, self._br_load, self._br_path.get())
            except Exception as e:
                self.after(0, self._br_status.set, 'Failed: ' + str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _br_ctx(self, event):
        sel_idx = self._br_listbox.nearest(event.y)
        self._br_listbox.selection_clear(0, 'end')
        self._br_listbox.selection_set(sel_idx)
        if sel_idx >= len(self._br_entries): return
        name, is_dir, sz = self._br_entries[sel_idx]
        if name == '..': return
        remote = self._br_cur() + '/' + name
        menu = tk.Menu(self, tearoff=0, bg=SURFACE2, fg=TEXT,
                       activebackground=ACCENT, activeforeground=TEXT,
                       font=('Segoe UI', 9))
        menu.add_command(label=name, state='disabled',
                         font=('Segoe UI', 9, 'bold'))
        menu.add_separator()
        if is_dir:
            menu.add_command(label='\U0001f4c2  Open folder',
                             command=lambda: self._br_load(remote))
        else:
            menu.add_command(label='\u2935  Download',
                             command=self._br_download)
        menu.add_command(label='\u2702  Rename',       command=self._br_rename)
        menu.add_command(label='\u2702\ufe0f  Cut',    command=self._br_cut)
        menu.add_command(label='\u27a1  Move to...',   command=self._br_move_to)
        menu.add_separator()
        menu.add_command(label='\U0001f5d1  Delete',   command=self._br_delete)
        menu.tk_popup(event.x_root, event.y_root)

    def _br_cur(self):
        return self._br_path.get().rstrip('/')

    def _br_cut(self):
        sel = self._br_selected()
        if not sel:
            messagebox.showwarning('No selection', 'Select items to move.')
            return
        paths = [(self._br_cur() + '/' + name, is_dir) for name, is_dir, _ in sel]
        self._br_clipboard[0] = ('move', paths)
        self._br_status.set(
            str(len(paths)) + ' item(s) cut — navigate to destination and Paste')

    def _br_delete(self):
        sel = self._br_selected()
        if not sel:
            messagebox.showwarning('No selection', 'Select files or folders to delete.')
            return
        names = [name for name, _, _ in sel]
        if not messagebox.askyesno('Delete from PS5',
                'Permanently delete %d item(s) from PS5?\n\n%s%s' % (
                    len(names), '\n'.join(names[:8]),
                    '\n...' if len(names) > 8 else '')):
            return
        def _rmd(ftp, path):
            lines = []
            try: ftp.retrlines('LIST ' + path, lines.append)
            except Exception: pass
            for line in lines:
                parts = line.split()
                if len(parts) < 9: continue
                n = ' '.join(parts[8:])
                if n in ('.', '..'): continue
                child = path + '/' + n
                if line.startswith('d'): _rmd(ftp, child)
                else:
                    try: ftp.delete(child)
                    except Exception: pass
            try: ftp.rmd(path)
            except Exception: pass
        def worker():
            errors = []
            ftp = self._br_ensure()
            for name, is_dir, _ in sel:
                remote = self._br_cur() + '/' + name
                try:
                    if is_dir: _rmd(ftp, remote)
                    else:      ftp.delete(remote)
                except Exception as e:
                    errors.append(name + ': ' + str(e))
            self.after(0, self._br_load, self._br_path.get())
            if errors:
                self.after(0, messagebox.showerror,
                           'Some deletions failed', '\n'.join(errors))
            else:
                self.after(0, self._br_status.set,
                           'Deleted ' + str(len(sel)) + ' item(s)')
        threading.Thread(target=worker, daemon=True).start()

    def _br_disconnect(self):
        try:
            if self._br_ftp[0]:
                self._br_ftp[0].quit()
        except Exception:
            pass
        self._br_ftp[0] = None
        self._br_listbox.delete(0, 'end')
        self._br_entries = []
        self._br_status.set('Disconnected')
        self._br_free.set('')

    def _br_download(self):
        sel = self._br_selected()
        files_only = [(n, sz) for n, is_dir, sz in sel if not is_dir]
        if not files_only:
            messagebox.showwarning('Files only', 'Select files (not folders) to download.')
            return
        save_dir = filedialog.askdirectory(title='Save downloaded files to...')
        if not save_dir: return
        self._br_status.set('Downloading %d file(s)...' % len(files_only))
        def worker():
            errors = []
            ftp = self._br_ensure()
            for name, sz in files_only:
                remote = self._br_cur() + '/' + name
                local  = os.path.join(save_dir, name)
                try:
                    with open(local, 'wb') as f:
                        ftp.retrbinary('RETR ' + remote, f.write)
                except Exception as e:
                    errors.append(name + ': ' + str(e))
            if errors:
                self.after(0, messagebox.showerror, 'Download errors', '\n'.join(errors))
                self.after(0, self._br_status.set, 'Download finished with errors')
            else:
                self.after(0, self._br_status.set,
                           '%d file(s) downloaded to %s' % (len(files_only), save_dir))
        threading.Thread(target=worker, daemon=True).start()

    def _br_ensure(self):
        try:
            if self._br_ftp[0]:
                self._br_ftp[0].voidcmd('NOOP')
                return self._br_ftp[0]
        except Exception:
            pass
        ftp = self._ftp_connect()
        self._br_ftp[0] = ftp
        return ftp

    def _br_fmt(self, sz, is_dir):
        if is_dir: return '<DIR>'
        if sz >= 1024**3: return '%.2f GB' % (sz/1024**3)
        if sz >= 1024**2: return '%.1f MB' % (sz/1024**2)
        if sz >= 1024:    return '%d KB'   % (sz//1024)
        return '%d B' % sz

    def _br_go_up(self):
        cur = self._br_cur()
        if not cur: return
        parent = '/'.join(cur.split('/')[:-1]) or '/'
        self._br_load(parent)

    def _br_load(self, p):
        p = p or '/'
        self._br_status.set('Loading...')
        self._br_listbox.delete(0, 'end')
        self._br_entries = []
        def worker():
            try:
                ftp   = self._br_ensure()
                lines = []
                ftp.retrlines('LIST ' + p, lines.append)
                # Try to get free space
                free_str = ''
                try:
                    resp = ftp.sendcmd('SITE AVAIL')
                    free_str = 'Free: ' + resp
                except Exception:
                    pass
                self.after(0, self._br_show, lines, p, free_str)
            except Exception as e:
                self.after(0, self._br_status.set, 'Error: ' + str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _br_move_to(self):
        """Move selected items to a typed destination path."""
        sel = self._br_selected()
        if not sel:
            messagebox.showwarning('No selection', 'Select items to move.')
            return
        dest = simpledialog.askstring(
            'Move to', 'Destination path on PS5:',
            initialvalue=self._br_cur(), parent=self)
        if not dest: return
        dest = dest.rstrip('/')
        def worker():
            errors = []
            ftp = self._br_ensure()
            # Ensure destination exists
            parts = dest.strip('/').split('/')
            cur = ''
            for part in parts:
                cur += '/' + part
                try: ftp.mkd(cur)
                except Exception: pass
            for name, is_dir, _ in sel:
                src_path = self._br_cur() + '/' + name
                dst_path = dest + '/' + name
                try:
                    ftp.rename(src_path, dst_path)
                except Exception as e:
                    errors.append(name + ': ' + str(e))
            self.after(0, self._br_load, self._br_path.get())
            if errors:
                self.after(0, messagebox.showerror, 'Move failed', '\n'.join(errors))
            else:
                self.after(0, self._br_status.set,
                           str(len(sel)) + ' item(s) moved to ' + dest)
        threading.Thread(target=worker, daemon=True).start()

    def _br_nav(self):
        sel = self._br_listbox.curselection()
        if not sel or sel[0] >= len(self._br_entries): return
        name, is_dir, _ = self._br_entries[sel[0]]
        if not is_dir: return
        if name == '..':
            self._br_go_up()
        else:
            self._br_load(self._br_cur() + '/' + name)

    def _br_new_folder(self):
        name = simpledialog.askstring('New folder', 'Folder name:', parent=self)
        if not name: return
        remote = self._br_cur() + '/' + name
        def worker():
            try:
                ftp = self._br_ensure()
                ftp.mkd(remote)
                self.after(0, self._br_load, self._br_path.get())
            except Exception as e:
                self.after(0, messagebox.showerror, 'Error', str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _br_paste(self):
        if not self._br_clipboard[0]:
            messagebox.showwarning('Nothing to paste', 'Cut some files first.')
            return
        action, items = self._br_clipboard[0]
        dest = self._br_cur()
        def worker():
            errors = []
            ftp = self._br_ensure()
            for src_path, _ in items:
                name     = src_path.split('/')[-1]
                dst_path = dest + '/' + name
                try:
                    ftp.rename(src_path, dst_path)
                except Exception as e:
                    errors.append(name + ': ' + str(e))
            self._br_clipboard[0] = None
            self.after(0, self._br_load, self._br_path.get())
            if errors:
                self.after(0, messagebox.showerror, 'Move failed', '\n'.join(errors))
            else:
                self.after(0, self._br_status.set,
                           str(len(items)) + ' item(s) moved to ' + dest)
        threading.Thread(target=worker, daemon=True).start()

    def _br_rename(self):
        sel = self._br_selected()
        if not sel:
            messagebox.showwarning('No selection', 'Select a file or folder to rename.')
            return
        if len(sel) > 1:
            messagebox.showwarning('Too many', 'Select only one item to rename.')
            return
        name, _, _ = sel[0]
        new_name = simpledialog.askstring('Rename', 'New name:',
                                           initialvalue=name, parent=self)
        if not new_name or new_name == name: return
        old_p = self._br_cur() + '/' + name
        new_p = self._br_cur() + '/' + new_name
        def worker():
            try:
                ftp = self._br_ensure()
                ftp.rename(old_p, new_p)
                self.after(0, self._br_load, self._br_path.get())
                self.after(0, self._br_status.set, 'Renamed: ' + name + ' \u2192 ' + new_name)
            except Exception as e:
                self.after(0, messagebox.showerror, 'Rename failed', str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _br_selected(self):
        result = []
        for i in self._br_listbox.curselection():
            if i < len(self._br_entries):
                name, is_dir, sz = self._br_entries[i]
                if name != '..':
                    result.append((name, is_dir, sz))
        return result

    def _br_show(self, lines, p, free_str):
        self._br_listbox.delete(0, 'end')
        self._br_entries = []
        self._br_path.set(p)
        if free_str:
            self._br_free.set(free_str)
        parsed = []
        for line in lines:
            parts = line.split()
            if len(parts) < 9: continue
            name   = ' '.join(parts[8:])
            is_dir = line.startswith('d')
            try: sz = int(parts[4])
            except: sz = 0
            if name not in ('.', '..'):
                parsed.append((name, is_dir, sz))
        parsed.sort(key=lambda x: (not x[1], x[0].lower()))
        if p != '/':
            self._br_entries.append(('..', True, 0))
            self._br_listbox.insert('end', '\U0001f4c2  ..')
        for name, is_dir, sz in parsed:
            self._br_entries.append((name, is_dir, sz))
            icon = '\U0001f4c1  ' if is_dir else '\U0001f4be  '
            sz_str = self._br_fmt(sz, is_dir)
            self._br_listbox.insert('end',
                '%-3s%-42s %12s' % (icon, name, sz_str))
        self._br_status.set('%d items in %s' % (len(parsed), p))
        self._br_sel_info.set('')

    def _br_update_sel(self):
        sel = self._br_selected()
        if not sel:
            self._br_sel_info.set('')
            return
        total = sum(sz for _, is_dir, sz in sel if not is_dir)
        self._br_sel_info.set(
            '%d selected' % len(sel) +
            ('  —  ' + self._br_fmt(total, False) if total else ''))

    def _br_upload_here(self):
        """Upload a file or folder to the current directory."""
        choice = messagebox.askyesnocancel(
            'Upload', 'What do you want to upload?\n\nYes = File\nNo = Folder\nCancel = Abort')
        if choice is None: return
        if choice:
            local = filedialog.askopenfilename(title='Select file to upload')
        else:
            local = filedialog.askdirectory(title='Select folder to upload')
        if not local: return
        # Reuse the FTP upload tab logic with current remote path
        self._ftptab_local_var.set(local.replace('/', '\\'))
        self._ftptab_remote_var.set(self._br_path.get())
        self._ftptab_is_folder.set(not choice)
        self._switch_tab('ftp')
        self._ftp_switch_sub('upload')
        self._ftptab_start_upload()

    def _browse_extract_file(self):
        p = filedialog.askopenfilename(
            title='Select exFAT image',
            filetypes=[('exFAT images', '*.exfat'), ('All files', '*.*')])
        if not p:
            return
        p = p.replace('/', '\\')
        self._extract_file_var.set(p)
        # Auto-fill folder name from filename (strip .exfat)
        base = os.path.splitext(os.path.basename(p))[0]
        self._extract_name_var.set(base)

    def _browse_extract_outdir(self):
        p = filedialog.askdirectory(title='Select output directory')
        if p:
            self._extract_outdir_var.set(p.replace('/', '\\'))

    def _resolve_game_root(self, folder):
        """If `folder` doesn't directly contain eboot.bin, walk up to 3
        levels deep to find the real game root. Returns the path to the
        folder that contains eboot.bin, or the original folder if none
        is found within the search depth.

        Step 42 (v2.5.8): users routinely drag the OUTER named folder
        like "PPSA19639 Minecraft Preview (01.024.000)" which contains
        one or two subfolders — the actual game lives in
        "PPSA19639 Minecraft Preview (01.024.000)\\PPSA19639\\". Without
        this resolver, the build would fail with "eboot.bin not found"
        even though the file is clearly there, one folder deeper.
        The library scanner already auto-descends this way; drag/drop
        and Browse now match that behaviour.
        """
        try:
            if not folder or not os.path.isdir(folder):
                return folder
            folder = os.path.normpath(folder)
            # Level 0: eboot.bin sitting directly inside?
            if os.path.isfile(os.path.join(folder, 'eboot.bin')):
                return folder
            # Level 1: any immediate subfolder contains eboot.bin?
            try:
                for sub in os.scandir(folder):
                    if sub.is_dir() and os.path.isfile(
                            os.path.join(sub.path, 'eboot.bin')):
                        return os.path.normpath(sub.path)
            except Exception:
                pass
            # Level 2: any sub-sub-folder contains eboot.bin?
            try:
                for sub in os.scandir(folder):
                    if not sub.is_dir():
                        continue
                    try:
                        for subsub in os.scandir(sub.path):
                            if subsub.is_dir() and os.path.isfile(
                                    os.path.join(subsub.path,
                                                  'eboot.bin')):
                                return os.path.normpath(subsub.path)
                    except Exception:
                        continue
            except Exception:
                pass
        except Exception:
            pass
        # Couldn't descend — return the original folder so the
        # downstream error path can complain about missing eboot.bin.
        return folder

    def _browse_game(self):
        p = filedialog.askdirectory(
            title='Select game root folder (containing eboot.bin)')
        if not p:
            return
        # Step 42 (v2.5.8): if the user picked an outer wrapper folder,
        # descend into it to find the real game root with eboot.bin.
        resolved = self._resolve_game_root(p)
        if os.path.normpath(resolved) != os.path.normpath(p):
            self._log('[INFO] Picked folder had no eboot.bin; '
                      'descended to: %s\n' % resolved)
            p = resolved
        p_display = p.replace('/', '\\')
        self.game_folder.set(p_display)
        self._detect_game_info_async(p)

    def _browse_multi_games(self):
        """Select a parent folder and add all valid game subfolders to queue."""
        parent = filedialog.askdirectory(
            title='Select folder containing multiple PS5 game dumps')
        if not parent:
            return

        odir = self.output_dir.get().strip()
        if not odir:
            odir = filedialog.askdirectory(title='Select output directory for all games')
            if not odir:
                return
            odir = odir.replace('/', '\\')
            self.output_dir.set(odir)
            self._settings['output_dir'] = odir
            save_settings(self._settings)

        self._set_status('Scanning for game folders...', ACCENT)

        def worker():
            found   = []
            skipped = []
            try:
                for entry in os.scandir(parent):
                    if not entry.is_dir():
                        continue
                    folder = entry.path
                    # Step 42 (v2.5.8): when we find eboot.bin one level
                    # down, store the INNER path so the build doesn't
                    # later fail looking for eboot.bin in the outer
                    # wrapper folder.
                    eboot_root = folder
                    has_eboot = os.path.isfile(os.path.join(folder, 'eboot.bin'))
                    if not has_eboot:
                        try:
                            for sub in os.scandir(folder):
                                if sub.is_dir() and os.path.isfile(
                                        os.path.join(sub.path, 'eboot.bin')):
                                    has_eboot = True
                                    eboot_root = sub.path
                                    break
                        except Exception:
                            pass
                    # Also accept PPSA/CUSA named folders
                    if not has_eboot:
                        if re.search(r'(?:PPSA|CUSA|PPLH)\d{5}',
                                     entry.name, re.IGNORECASE):
                            has_eboot = True
                    if not has_eboot:
                        skipped.append(entry.name)
                        continue
                    # Already in queue? (compare against the resolved
                    # eboot root, not the wrapper)
                    already = any(
                        os.path.normpath(q.game_folder) == os.path.normpath(eboot_root)
                        for q in self._queue)
                    if already:
                        skipped.append(entry.name + ' (already in queue)')
                        continue
                    found.append(eboot_root)
            except Exception as e:
                self.after(0, messagebox.showerror, 'Scan error', str(e))
                return

            self.after(0, self._multi_add_confirm, found, skipped, odir)

        threading.Thread(target=worker, daemon=True).start()

    def _browse_output(self):
        p = filedialog.askdirectory(title='Select output directory')
        if p:
            p = p.replace('/', '\\')
            self.output_dir.set(p)
            self._settings['output_dir'] = p
            save_settings(self._settings)

    # ── Queue ─────────────────────────────────────────────────────────────────
    def _browse_temp(self):
        p = filedialog.askdirectory(title='Select temp folder for image building')
        if not p:
            return
        p = p.replace('/', '\\')
        self._temp_dir_var.set(p)
        self._settings['temp_dir'] = p
        save_settings(self._settings)
        self._refresh_temp_size()
        messagebox.showinfo('Temp folder set',
            'Temp folder set to:\n' + p +
            '\n\nThis will take effect on next launch.')

    def _build_ftp_upload_section(self, parent):
        # Step 12 (v2.1.4): the upload section moved inside the dual-pane
        # rewrite of build_ftp_tab. This shim is preserved as a no-op for
        # any external/legacy caller; it is no longer invoked internally.
        pass

    # ── FTP tab helpers ───────────────────────────────────────────────────────
    def _build_ftpbr_tab(self, parent):
        # Step 12 (v2.1.4): the PS5 browser became the right pane of the
        # dual-pane layout in build_ftp_tab. Shim preserved as no-op.
        pass

    # ── PS5 Browser methods ───────────────────────────────────────────────────

    def _build_single(self, index):
        if self._building:
            messagebox.showwarning('Busy', 'A build is already in progress.')
            return
        if 0 <= index < len(self._queue):
            self._queue[index].status = 'waiting'
            self._building = True
            self.build_btn.config(state='disabled', text='Building...')
            self._process_next([index], 0)

    def _check_osfmount_banner(self):
        if self._find_osfmount():
            return  # All good, no banner needed
        # Show warning banner under header
        banner = tk.Frame(self, bg='#3a1500',
                          highlightbackground='#ff6600', highlightthickness=1)
        banner.pack(fill='x', padx=24, pady=(4, 0))
        inner = tk.Frame(banner, bg='#3a1500')
        inner.pack(fill='x', padx=12, pady=8)
        tk.Label(inner, text='\u26a0  OSFMount not detected',
                 font=('Segoe UI', 9, 'bold'),
                 bg='#3a1500', fg='#ff9944').pack(side='left')
        tk.Label(inner,
                 text='  \u2014  Required for building images.',
                 font=('Segoe UI', 9), bg='#3a1500', fg='#ffbb88').pack(side='left')
        def _open_download():
            import webbrowser
            webbrowser.open('https://www.osforensics.com/tools/mount-disk-images.html')
        tk.Button(inner, text='Download OSFMount \u2197',
                  font=('Segoe UI', 9, 'bold'),
                  bg='#ff6600', fg='#ffffff',
                  activebackground='#cc5500', activeforeground='#ffffff',
                  relief='flat', bd=0, padx=10, pady=3,
                  cursor='hand2',
                  command=_open_download).pack(side='right')

    # ── Verify image ───────────────────────────────────────────────────────────
    def _check_pause_then_next(self, indices, pos):
        """Check if paused, if so wait for resume, otherwise start next item."""
        if self._pause_after_current:
            self._pause_after_current = False
            self._building = False
            self._pause_btn.config(text='▶ Resume', bg=SUCCESS, fg=TEXT)
            self._set_status('⏸ Paused — click Resume to continue', WARNING)
            # Store where we left off
            self._paused_indices = indices
            self._paused_pos     = pos
            self._pause_btn.config(state='normal',
                                   command=self._resume_queue)
        else:
            self._process_next(indices, pos)

    def _clear_queue(self):
        if self._building:
            messagebox.showwarning('Building', 'Cannot clear queue while building.')
            return
        self._queue.clear()
        self._render_queue()

    def _clear_temp(self):
        base = self._settings.get('temp_dir') or tempfile.gettempdir()
        if not messagebox.askyesno('Clear temp files',
                'This will delete all exfat_builder_* folders in:\n' + base +
                '\n\nAny active build will be interrupted. Continue?'):
            return
        # Don\'t delete the currently active temp dir if building
        if self._building:
            messagebox.showwarning('Building',
                'Cannot clear temp while a build is in progress.')
            return
        ok, result, size = clear_temp_folder(base)
        if ok:
            freed = size / (1024 * 1024)
            msg = ('Removed %d folder(s), freed %.1f MB' % (result, freed)
                   if result > 0 else 'No temp folders found to remove')
            self._set_status(msg, SUCCESS)
            messagebox.showinfo('Temp cleared', msg)
        else:
            messagebox.showerror('Error', 'Failed to clear temp:\n' + str(result))
        self._refresh_temp_size()

    def _detect_game_info(self, folder):
        folder = os.path.normpath(folder)
        title, title_id, version = get_game_info(folder)

        # Fallback: extract PPSA/CUSA from folder name
        if not title_id:
            m = re.search(r'((?:PPSA|CUSA|PPLH)\d{5})', os.path.basename(folder), re.IGNORECASE)
            if m:
                title_id = m.group(1).upper()

        self._detected_title    = title
        self._detected_title_id = title_id
        self._detected_version  = version

        # ── Cover art ──
        cover_path = self._load_cover_art(folder)
        if cover_path:
            try:
                from PIL import Image, ImageTk
                # 96x96 thumbnail — bigger than the previous 56x56 so
                # cover art is genuinely readable. LANCZOS gives clean
                # downscale even for high-res icon0.png sources.
                img = Image.open(cover_path).resize((96, 96), Image.LANCZOS)
                self._cover_image = ImageTk.PhotoImage(img)
                self._cover_label.config(image=self._cover_image, text='',
                                          width=96, height=96)
            except Exception:
                self._cover_label.config(image='', text='\U0001f3ae',
                                          font=('Segoe UI', 32), fg=INFO_FG)
        else:
            self._cover_label.config(image='', text='\U0001f3ae',
                                      font=('Segoe UI', 32), fg='#333333')

        # ── Folder size ──
        def calc_size():
            size_bytes = self._get_folder_size(folder)
            size_gb = size_bytes / (1024 ** 3)
            size_str = ('%.2f GB' % size_gb) if size_gb >= 1 else ('%.0f MB' % (size_bytes / (1024**2)))
            # Check output drive has enough space
            space_warn = ''
            out_dir = self.output_dir.get().strip()
            if out_dir:
                try:
                    free = shutil.disk_usage(out_dir).free
                    if free < size_bytes * 1.1:
                        space_warn = '  \u26a0 Low space on output drive!'
                except Exception:
                    pass
            self.after(0, self._info_size_var.set,
                       '\U0001f4be ' + size_str + ' estimated image size' + space_warn)
        threading.Thread(target=calc_size, daemon=True).start()

        if title or title_id:
            self._info_title_var.set(title or title_id)
            self._info_id_var.set(title_id or '')
            self._info_ver_var.set(('Version ' + version) if version else '')
            self._info_frame.pack(fill='x', pady=(0, 8))
            auto_name = build_exfat_name(title, title_id, version)
            self.output_name.set(auto_name)
            self._auto_label.pack(side='left')
            self._no_sfo_label.pack_forget()
            self._filename_preview.config(fg='#ffffff')
            src = 'param.sfo' if title else 'folder name'
            pfs_path = find_meta_file(os.path.normpath(folder), ['pfs-version.dat'])
            if pfs_path and os.path.isfile(pfs_path):
                src = 'param.sfo + pfs-version.dat' if title else 'folder name'
            self._set_status('Detected: ' + (title or title_id) + '  (from ' + src + ')', SUCCESS)
        else:
            self._info_frame.pack_forget()
            self._auto_label.pack_forget()
            self.output_name.set('game.exfat')
            self._no_sfo_label.pack(side='left')
            self._filename_preview.config(fg='#555555')
            self._info_size_var.set('')
            has_eboot = os.path.isfile(os.path.join(folder, 'eboot.bin'))
            self._set_status(
                'eboot.bin found  \u2013  no metadata detected' if has_eboot
                else 'Warning: eboot.bin not found', WARNING)

    def _detect_game_info_async(self, folder):
        """Run detect on a background thread so USB/slow drives don't freeze the UI."""
        self._info_title_var.set('Reading game info...')
        self._info_frame.pack(fill='x', pady=(0, 8))
        self._auto_label.pack_forget()
        self._no_sfo_label.pack_forget()
        threading.Thread(
            target=lambda: self._detect_game_info(folder),
            daemon=True).start()

    def _elog(self, text):
        self._extract_log.config(state='normal')
        self._extract_log.insert('end', text)
        self._extract_log.see('end')
        self._extract_log.config(state='disabled')

    def _elog_clear(self):
        self._extract_log.config(state='normal')
        self._extract_log.delete('1.0', 'end')
        self._extract_log.config(state='disabled')

    def _extract_done(self, ok, info, m, s):
        self._extract_btn.config(state='normal', text='\U0001f4e4  Extract Image')
        if ok:
            self._update_extract_bar(100)
            self._extract_status_var.set('Complete! Extracted to: ' + info)
            self._extract_eta_var.set('Finished in %dm %02ds' % (m, s))
            self._elog('\n[OK] Extraction complete: ' + info + '\n')
            if messagebox.askyesno('Extraction complete',
                    'Image extracted successfully!\n\n' + info +
                    '\n\nOpen output folder?'):
                try: os.startfile(info)
                except Exception: pass
        else:
            self._extract_status_var.set('Extraction failed')
            self._elog('\n[ERROR] ' + info + '\n')
            messagebox.showerror('Extraction failed', info)

    def _ffpkg_activate_dot(self, index):
        # Step 9 (v2.1.1): forward to the new StagedProgressBar widget
        # built in ui/tab_ffpkg.py. The legacy `_ffpkg_stage_dots` iteration
        # below is now a no-op (the list is empty in the new layout) but
        # is preserved so any future tab that uses the old idiom still works.
        if hasattr(self, '_ffpkg_build_stages') and self._ffpkg_build_stages is not None:
            try:
                self._ffpkg_build_stages.set_active(index)
            except Exception:
                pass

        if not hasattr(self, '_ffpkg_stage_dots'):
            return
        for i, (dot, lbl) in enumerate(self._ffpkg_stage_dots):
            if i < index:
                dot.itemconfig('dot', fill=SUCCESS)
                lbl.config(fg=SUCCESS)
            elif i == index:
                dot.itemconfig('dot', fill=ACCENT)
                lbl.config(fg=ACCENT)
            else:
                dot.itemconfig('dot', fill=BORDER)
                lbl.config(fg=MUTED)

    def _ffpkg_add_to_queue(self):
        game  = self._ffpkg_game_folder.get().strip()
        odir  = self._ffpkg_output_dir.get().strip()
        name  = self._ffpkg_output_name.get().strip() or 'game.ffpkg'
        if not name.lower().endswith('.ffpkg'):
            name += '.ffpkg'
        if not game:
            messagebox.showwarning('Missing', 'Please select a game folder.')
            return
        if not odir:
            messagebox.showwarning('Missing', 'Please select an output directory.')
            return
        # Duplicate check
        for existing in self._ffpkg_queue:
            if os.path.normpath(existing['folder']) == os.path.normpath(game):
                if not messagebox.askyesno('Duplicate',
                        'This folder is already in the queue. Add again?'):
                    return
                break
        self._ffpkg_queue.append({
            'folder': game,
            'odir':   odir,
            'name':   name,
            'status': 'waiting',
        })
        self._ffpkg_render_queue()

    def _ffpkg_browse_game(self):
        p = filedialog.askdirectory(
            title='Select game root folder (containing eboot.bin)')
        if not p:
            return
        p = p.replace('/', '\\')
        self._ffpkg_game_folder.set(p)
        self._ffpkg_detect_game_async(p)

    def _ffpkg_browse_output(self):
        p = filedialog.askdirectory(title='Select output directory')
        if not p:
            return
        p = p.replace('/', '\\')
        self._ffpkg_output_dir.set(p)
        self._settings['ffpkg_output_dir'] = p
        save_settings(self._settings)

    def _ffpkg_check_dotnet(self):
        """Check if .NET 8 runtime is available and show result."""
        import subprocess as _sp
        btn_label = '\u2139 ' + _('Check .NET 8') + '  ...'
        # Visual feedback
        def worker():
            found   = False
            version = ''
            try:
                r = _sp.run(['dotnet', '--list-runtimes'],
                            capture_output=True, text=True, timeout=15,
                            creationflags=0x08000000 if os.name == 'nt' else 0)
                output = r.stdout + r.stderr
                for line in output.splitlines():
                    if 'Microsoft.NETCore.App 8.' in line:
                        found   = True
                        version = line.strip()
                        break
                if not found:
                    # Also check --version as fallback
                    r2 = _sp.run(['dotnet', '--version'],
                                 capture_output=True, text=True, timeout=10,
                                 creationflags=0x08000000 if os.name == 'nt' else 0)
                    v = (r2.stdout + r2.stderr).strip()
                    if v.startswith('8.'):
                        found   = True
                        version = '.NET ' + v
            except FileNotFoundError:
                pass
            except Exception as e:
                self.after(0, messagebox.showerror,
                           '.NET Check Error', 'Could not run dotnet:\n' + str(e))
                return

            if found:
                self.after(0, messagebox.showinfo,
                           '\u2713 .NET 8 Found',
                           '.NET 8 Runtime is installed and ready.\n\n'
                           + version +
                           '\n\nUFS2Tool (ffpkg builder) will work correctly.')
            else:
                def _open_dl():
                    import webbrowser
                    webbrowser.open('https://dotnet.microsoft.com/en-us/download/dotnet/8.0')
                dlg = tk.Toplevel(self)
                dlg.title('.NET 8 Not Found')
                dlg.configure(bg=BG)
                dlg.resizable(False, False)
                dlg.grab_set()
                tk.Label(dlg,
                         text='\u26a0  .NET 8 Runtime not found',
                         font=('Segoe UI', 12, 'bold'), bg=BG, fg='#ffaa44'
                         ).pack(padx=24, pady=(18, 4))
                tk.Label(dlg,
                         text='UFS2Tool requires the .NET 8 Runtime (not SDK) to build .ffpkg images.\n'
                              'Download and install the Windows x64 Desktop Runtime.',
                         font=('Segoe UI', 9), bg=BG, fg=MUTED,
                         wraplength=340, justify='left'
                         ).pack(padx=24, pady=(0, 12))
                btn_row = tk.Frame(dlg, bg=BG)
                btn_row.pack(pady=(0, 18))
                tk.Button(btn_row, text='\U0001f30d  Open Download Page',
                          font=('Segoe UI', 10, 'bold'),
                          bg=ACCENT, fg=TEXT, relief='flat', bd=0,
                          padx=14, pady=6, cursor='hand2',
                          command=lambda: (_open_dl(), dlg.destroy())
                          ).pack(side='left', padx=(0, 8))
                tk.Button(btn_row, text='Close',
                          font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                          relief='flat', bd=0, padx=14, pady=6, cursor='hand2',
                          command=dlg.destroy).pack(side='left')

        threading.Thread(target=worker, daemon=True).start()

    def _ffpkg_clear_queue(self):
        if self._ffpkg_building:
            messagebox.showwarning('Building', 'Cannot clear queue while building.')
            return
        self._ffpkg_queue.clear()
        self._ffpkg_render_queue()

    def _ffpkg_detect_game(self, folder):
        folder = os.path.normpath(folder)
        title, title_id, version = get_game_info(folder)
        if not title_id:
            m = re.search(r'((?:PPSA|CUSA|PPLH)\d{5})',
                          os.path.basename(folder), re.IGNORECASE)
            if m:
                title_id = m.group(1).upper()

        # Cover art
        cover_path = self._load_cover_art(folder)
        if cover_path:
            try:
                from PIL import Image, ImageTk
                img = Image.open(cover_path).resize((96, 96), Image.LANCZOS)
                self._ffpkg_cover_image = ImageTk.PhotoImage(img)
                self._ffpkg_cover_label.config(
                    image=self._ffpkg_cover_image, text='', width=96, height=96)
            except Exception:
                self._ffpkg_cover_label.config(
                    image='', text='\U0001f3ae', font=('Segoe UI', 32), fg=INFO_FG)
        else:
            self._ffpkg_cover_label.config(
                image='', text='\U0001f3ae', font=('Segoe UI', 32), fg='#333333')

        # Size + file count — calculate and cache for ETA/progress use during build
        def calc_size():
            size_bytes = self._get_folder_size(folder)
            file_count = sum(len(files) for _, _, files in os.walk(folder))
            norm = os.path.normpath(folder)
            self._ffpkg_folder_sizes[norm] = size_bytes
            self._ffpkg_folder_file_counts[norm] = file_count
            size_str = ('%.2f GB' % (size_bytes/1024**3)
                        if size_bytes >= 1024**3
                        else '%.0f MB' % (size_bytes/1024**2))
            self.after(0, self._ffpkg_info_size_var.set,
                       '\U0001f4be ' + size_str + ' estimated image size')
        threading.Thread(target=calc_size, daemon=True).start()

        display = title or title_id or os.path.basename(folder)
        self.after(0, self._ffpkg_info_title_var.set, display)
        # Step 9 (v2.1.1): also feed the new id/ver StringVars on the
        # DetectedGameStrip widget. The legacy code only set title+size;
        # the new strip has 4 fields.
        if hasattr(self, '_ffpkg_info_id_var'):
            self.after(0, self._ffpkg_info_id_var.set, title_id or '')
        if hasattr(self, '_ffpkg_info_ver_var'):
            self.after(0, self._ffpkg_info_ver_var.set,
                       ('v' + version) if version else '')
        self.after(0, lambda: self._ffpkg_info_frame.pack(
            fill='x', pady=(0, 6),
            before=self._ffpkg_output_dir_frame))

        # Auto filename: TITLEID (version).ffpkg  or  Title (version).ffpkg
        name = build_exfat_name(title, title_id, version)
        name = name.replace('.exfat', '.ffpkg')
        self.after(0, self._ffpkg_output_name.set, name)
        self.after(0, self._ffpkg_auto_label.pack, )
        self.after(0, self._ffpkg_filename_preview.config,
                   {'fg': '#ffffff'})

    def _ffpkg_detect_game_async(self, folder):
        self._ffpkg_info_title_var.set('Reading game info...')
        self._ffpkg_info_frame.pack(fill='x', pady=(0, 8))
        threading.Thread(
            target=lambda: self._ffpkg_detect_game(folder),
            daemon=True).start()

    def _ffpkg_handle_line(self, line, pos, total):
        self._ffpkg_log(line)
        elapsed = time.time() - self._ffpkg_start_time if self._ffpkg_start_time else 0
        el_str  = 'Elapsed: %dm %02ds' % (int(elapsed//60), int(elapsed%60))
        stripped = line.strip()

        # ── Stage detection ──────────────────────────────────────────────────
        if 'Writing cylinder groups' in stripped:
            self._ffpkg_stage = 'cylgroups'
            self._ffpkg_activate_dot(0)

        elif 'Adding files to image' in stripped:
            self._ffpkg_stage = 'copying'
            self._ffpkg_activate_dot(1)
            self._ffpkg_copy_start_t = time.time()
            self._ffpkg_start_poll()   # starts expected_size background calc

        elif 'Populated image with' in stripped:
            self._ffpkg_stage = 'done'
            self._ffpkg_activate_dot(2)
            self._ffpkg_stop_poll()
            m2 = re.search(r'(\d+)\s+files?', stripped)
            files_done = int(m2.group(1)) if m2 else self._ffpkg_total_files
            total_files = self._ffpkg_total_files or files_done
            self._ffpkg_set_progress(
                97,
                'Finalising... (%d/%d files)' % (files_done, total_files),
                el_str)
            return

        elif 'Image created successfully' in stripped:
            self._ffpkg_stage = 'done'
            self._ffpkg_stop_poll()
            return

        # ── Percentage parsing ───────────────────────────────────────────────
        m = re.search(r'(\d{1,3})\s*%', stripped)
        if not m:
            return
        raw_pct = min(int(m.group(1)), 100)

        if self._ffpkg_stage == 'cylgroups':
            mapped = int(raw_pct * 0.30)
            self._ffpkg_set_progress(
                mapped,
                '[1/2] Writing filesystem structure... %d%%' % raw_pct,
                el_str)

        elif self._ffpkg_stage == 'copying':
            mapped = 30 + int(raw_pct * 0.65)

            # Parse UFS2Tool's rich output line:
            # "Adding files to image... 34% (83/148 files, 6.20 GiB/18.23 GiB)"
            files_done = files_total = 0
            written_gib = total_gib = 0.0

            mf = re.search(r'\((\d+)/(\d+)\s+files?', stripped)
            if mf:
                files_done  = int(mf.group(1))
                files_total = int(mf.group(2))
                if files_total > 0:
                    self._ffpkg_total_files = files_total

            mg = re.search(r'([\d.]+)\s*GiB\s*/\s*([\d.]+)\s*GiB', stripped)
            if mg:
                written_gib = float(mg.group(1))
                total_gib   = float(mg.group(2))

            # Step label
            if files_done > 0 and files_total > 0:
                label = '[2/2] Copying files... %d/%d  (%d%%)' % (
                    files_done, files_total, raw_pct)
            else:
                label = '[2/2] Copying files... %d%%' % raw_pct

            # ETA line — built from parsed values
            copy_elapsed = (time.time() - self._ffpkg_copy_start_t
                            if self._ffpkg_copy_start_t else elapsed)
            eta_parts = ['Elapsed: %dm %02ds' % (int(elapsed//60), int(elapsed%60))]

            if written_gib > 0:
                eta_parts.append('%.2f GB written' % written_gib)
            if total_gib > 0 and written_gib > 0:
                rem = total_gib - written_gib
                if rem > 0:
                    eta_parts.append('%.2f GB remaining' % rem)

            if written_gib > 0 and copy_elapsed > 1:
                speed_mbs = (written_gib * 1024) / copy_elapsed
                eta_parts.append('%.1f MB/s' % speed_mbs)
                if total_gib > 0 and rem > 0 and speed_mbs > 0:
                    eta_s = (rem * 1024) / speed_mbs
                    if eta_s < 5:
                        eta_parts.append('Almost done')
                    elif eta_s < 60:
                        eta_parts.append('ETA: %ds' % int(eta_s))
                    else:
                        eta_parts.append('ETA: %dm %02ds' % (
                            int(eta_s // 60), int(eta_s % 60)))

            self._ffpkg_set_progress(mapped, label, '  \u2022  '.join(eta_parts))

    def _ffpkg_item_done(self, returncode, idx, indices, pos, out_path):
        elapsed = time.time() - self._ffpkg_start_time if self._ffpkg_start_time else 0
        m, s = int(elapsed//60), int(elapsed%60)
        if returncode == 0:
            self._ffpkg_queue[idx]['status'] = 'done'
            self._ffpkg_activate_dot(len(self._ffpkg_stage_dots) if hasattr(self, '_ffpkg_stage_dots') else 3)
            self._ffpkg_set_progress(100, 'Complete!',
                'Finished in %dm %02ds' % (m, s))
            self._ffpkg_log('\n[OK] Done: ' + out_path + '\n')
            self._set_status('ffpkg built: ' + os.path.basename(out_path), SUCCESS)
            # ── Delete source folder if enabled ──
            if self._adv_delete_source_ffpkg_var.get():
                src = self._ffpkg_queue[idx].get('folder', '')
                if src and os.path.isdir(src):
                    try:
                        import shutil as _sh
                        self._ffpkg_log('[POST] Deleting source: %s\n' % src)
                        _sh.rmtree(src)
                        self._ffpkg_log('[POST] Source deleted ✓\n')
                    except Exception as de:
                        self._ffpkg_log('[POST] Delete failed: %s\n' % str(de))
            # Auto-upload if enabled
            if self._ftp_auto_var.get() and self._ftp_ip_var.get().strip():
                if messagebox.askyesno('FTP Upload',
                        'ffpkg built!\n\nUpload to PS5 now?\n' + out_path):
                    self._ftp_upload_file(out_path,
                        on_done=lambda: self._ffpkg_process_next(indices, pos+1))
                    self._ffpkg_render_queue()
                    return
            self._ffpkg_render_queue()
            self._ffpkg_process_next(indices, pos + 1)
        else:
            self._ffpkg_queue[idx]['status'] = 'failed'
            self._ffpkg_set_progress(self._ffpkg_current_pct, 'Failed', '')
            self._set_status('ffpkg build failed (exit %d)' % returncode, DANGER)
            self._ffpkg_log('\n[ERROR] Exit code: %d\n' % returncode)
            self._ffpkg_render_queue()
            if messagebox.askyesno('Build failed',
                    'ffpkg build failed for:\n' + out_path +
                    '\n\nContinue with remaining items?'):
                self._ffpkg_process_next(indices, pos + 1)
            else:
                self._ffpkg_building = False
                self._ffpkg_build_btn.config(state='normal', text='Build All')

    def _ffpkg_item_error(self, msg, idx, indices, pos):
        self._ffpkg_queue[idx]['status'] = 'failed'
        self._set_status('ffpkg error: ' + msg, DANGER)
        self._ffpkg_log('\n[ERROR] ' + msg + '\n')
        self._ffpkg_render_queue()
        if messagebox.askyesno('Error', 'UFS2Tool error:\n' + msg +
                '\n\nContinue with remaining items?'):
            self._ffpkg_process_next(indices, pos + 1)
        else:
            self._ffpkg_building = False
            self._ffpkg_build_btn.config(state='normal', text='Build All')

    def _ffpkg_log(self, text):
        # v3.0.0: no longer auto-opens the drawer; user controls it.
        self._ffpkg_log_box.config(state='normal')
        self._ffpkg_log_box.insert('end', text)
        self._ffpkg_log_box.see('end')
        self._ffpkg_log_box.config(state='disabled')

    def _ffpkg_log_clear(self):
        self._ffpkg_log_box.config(state='normal')
        self._ffpkg_log_box.delete('1.0', 'end')
        self._ffpkg_log_box.config(state='disabled')

    def _ffpkg_process_next(self, indices, pos):
        if pos >= len(indices):
            self._ffpkg_building = False
            self._ffpkg_build_btn.config(state='normal', text='Build All')
            self._ffpkg_set_progress(100, 'All done!', '')
            self._set_status('ffpkg: %d image(s) built \u2713' % len(indices), SUCCESS)
            self._ffpkg_render_queue()
            self._trigger_shutdown('ffpkg')  # before messagebox blocks
            messagebox.showinfo('ffpkg Complete',
                '%d ffpkg image(s) built successfully!' % len(indices))
            return
        idx  = indices[pos]
        item = self._ffpkg_queue[idx]
        item['status'] = 'building'
        self._ffpkg_render_queue()

        out_path    = os.path.join(item['odir'], item['name'])
        game_folder = item['folder']
        exe         = self._ffpkg_ufs2_exe

        # Build command — use advanced parameters from the Advanced tab
        block  = self._adv_ffpkg_block_var.get()  or '65536'
        frag   = self._adv_ffpkg_frag_var.get()   or '65536'
        minfr  = self._adv_ffpkg_minfree_var.get() or '0'
        inode  = self._adv_ffpkg_inode_var.get()  or '262144'
        try:
            if int(frag) > int(block):
                frag = block
        except Exception:
            frag = block
        cmd = [exe, 'newfs',
               '-O', '2',
               '-b', block,
               '-f', frag,
               '-m', minfr,
               '-S', '512',
               '-i', inode,
               '-D', game_folder,
               out_path]

        label = 'Building %d/%d: %s' % (pos + 1, len(indices), item['name'])
        self._ffpkg_set_progress(0, label, '')
        self._ffpkg_start_time   = time.time()
        self._ffpkg_stage        = 'init'
        self._ffpkg_total_files  = 0
        self._ffpkg_out_path     = out_path
        self._ffpkg_expected_size       = 0
        self._ffpkg_current_queue_idx   = idx
        # Load size from cache immediately — may have been pre-calculated on folder select
        try:
            _norm = os.path.normpath(item['folder'])
            _cached = self._ffpkg_folder_sizes.get(_norm, 0)
            if _cached > 0:
                self._ffpkg_expected_size = _cached
            _fc = self._ffpkg_folder_file_counts.get(_norm, 0)
            if _fc > 0:
                self._ffpkg_total_files = _fc
        except Exception:
            pass
        self._ffpkg_poll_drive_free_start = None
        self._ffpkg_copy_start_t = None
        self._ffpkg_copy_start_size = 0
        self._ffpkg_final_size   = 0
        self._ffpkg_poll_id      = None
        self._set_status(label, ACCENT)
        self._ffpkg_log_clear()
        self._ffpkg_log('[ffpkg] ' + ' '.join(
            ('"' + a + '"' if ' ' in a else a) for a in cmd) + '\n\n')
        os.makedirs(item['odir'], exist_ok=True)

        # Pre-count source files for progress context
        def count_files():
            try:
                n = sum(len(files) for _, _, files in os.walk(game_folder))
                self._ffpkg_total_files = n
            except Exception:
                pass
        threading.Thread(target=count_files, daemon=True).start()

        def worker():
            try:
                proc = subprocess.Popen(
                    cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                    text=True, encoding='utf-8', errors='replace',
                    cwd=os.path.dirname(exe),
                    creationflags=subprocess.CREATE_NO_WINDOW)
                for line in proc.stdout:
                    self.after(0, self._ffpkg_handle_line, line, pos, len(indices))
                proc.wait()
                self.after(0, self._ffpkg_stop_poll)
                self.after(0, self._ffpkg_item_done,
                           proc.returncode, idx, indices, pos, out_path)
            except Exception as ex:
                self.after(0, self._ffpkg_stop_poll)
                self.after(0, self._ffpkg_item_error, str(ex), idx, indices, pos)

        threading.Thread(target=worker, daemon=True).start()

    # Stages mapped to bar ranges:
    #   0–30%  : init / writing cylinder groups  (UFS2Tool reports 0–100% here)
    #   30–95% : adding files to image           (UFS2Tool reports 0–100% here)
    #   95–100%: finalising / done

    def _ffpkg_remove_item(self, idx):
        if 0 <= idx < len(self._ffpkg_queue):
            self._ffpkg_queue.pop(idx)
            self._ffpkg_render_queue()

    def _ffpkg_render_queue(self):
        for w in self._ffpkg_queue_frame.winfo_children():
            w.destroy()
        if not self._ffpkg_queue:
            tk.Label(self._ffpkg_queue_frame,
                     text='Queue is empty — add a game folder above',
                     font=('Segoe UI', 9), bg=SURFACE2, fg='#333333',
                     pady=14).pack()
            return
        for i, item in enumerate(self._ffpkg_queue):
            bg = QUEUE_ODD if i % 2 == 0 else QUEUE_EVEN
            row = tk.Frame(self._ffpkg_queue_frame, bg=bg)
            row.pack(fill='x')
            # Status dot
            dot = tk.Canvas(row, width=12, height=12, bg=bg, highlightthickness=0)
            dot.pack(side='left', padx=(10, 6), pady=8)
            colour = {
                'waiting':  BORDER,
                'building': ACCENT,
                'done':     SUCCESS,
                'failed':   DANGER,
            }.get(item['status'], BORDER)
            dot.create_oval(1, 1, 11, 11, fill=colour, outline='')
            # Name
            tk.Label(row, text=item['name'],
                     font=('Segoe UI', 9), bg=bg, fg=TEXT,
                     anchor='w').pack(side='left', fill='x', expand=True, padx=(0, 8))
            # Remove button (only when not building)
            if not self._ffpkg_building:
                idx = i
                tk.Button(row, text='\u2715',
                          font=('Segoe UI', 8), bg=bg, fg=DANGER,
                          activebackground=bg, activeforeground=DANGER,
                          relief='flat', bd=0, padx=8, cursor='hand2',
                          command=lambda ix=idx: self._ffpkg_remove_item(ix)
                          ).pack(side='right', padx=(0, 6))
            # Upload button if done
            if item['status'] == 'done':
                out_path = os.path.join(item['odir'], item['name'])
                tk.Button(row, text='\u2191 PS5',
                          font=('Segoe UI', 8), bg=SURFACE2, fg=ACCENT,
                          activebackground=BORDER, activeforeground=ACCENT,
                          relief='flat', bd=0, padx=8, pady=2, cursor='hand2',
                          command=lambda p=out_path: self._ftp_upload_file(p)
                          ).pack(side='right', padx=(0, 4))

    def _ffpkg_run_queue(self):
        if self._ffpkg_building:
            return
        waiting = [i for i, it in enumerate(self._ffpkg_queue)
                   if it['status'] == 'waiting']
        if not waiting:
            messagebox.showwarning('Nothing to build',
                'No waiting items in the ffpkg queue.')
            return
        # Ensure UFS2Tool is extracted
        if not self._ffpkg_ufs2_exe or not os.path.isfile(self._ffpkg_ufs2_exe):
            try:
                temp_dir = self._settings.get('temp_dir') or None
                self._ffpkg_ufs2_exe = extract_ufs2tool(temp_dir)
            except Exception as e:
                messagebox.showerror('UFS2Tool extraction failed', str(e))
                return
        self._ffpkg_building = True
        self._ffpkg_build_btn.config(state='disabled', text='Building...')
        self._ffpkg_render_queue()
        self._ffpkg_process_next(waiting, 0)

    def _ffpkg_set_progress(self, pct, step_text=None, eta_text=None):
        self._ffpkg_current_pct = pct
        self._ffpkg_update_bar(pct)
        self._ffpkg_pct_var.set(str(int(pct)) + '%')
        if step_text is not None:
            self._ffpkg_step_var.set(step_text)
        if eta_text is not None:
            self._ffpkg_eta_var.set(eta_text)

    def _ffpkg_start_poll(self):
        """Set expected size and file count from cache, or recalculate in background."""
        try:
            folder = self._ffpkg_queue[self._ffpkg_current_queue_idx]['folder']
            norm   = os.path.normpath(folder)
            cached_size  = self._ffpkg_folder_sizes.get(norm, 0)
            cached_count = self._ffpkg_folder_file_counts.get(norm, 0)
            if cached_size > 0:
                self._ffpkg_expected_size = cached_size
            if cached_count > 0:
                self._ffpkg_total_files = cached_count
            if cached_size == 0 or cached_count == 0:
                # Calculate anything not yet cached
                def _calc():
                    try:
                        if cached_size == 0:
                            sz = self._get_folder_size(folder)
                            self._ffpkg_expected_size = sz
                            self._ffpkg_folder_sizes[norm] = sz
                        if cached_count == 0:
                            n = sum(len(files) for _, _, files in os.walk(folder))
                            self._ffpkg_total_files = n
                            self._ffpkg_folder_file_counts[norm] = n
                    except Exception:
                        pass
                threading.Thread(target=_calc, daemon=True).start()
        except Exception:
            pass

    def _ffpkg_stop_poll(self):
        if self._ffpkg_poll_id is not None:
            try:
                self.after_cancel(self._ffpkg_poll_id)
            except Exception:
                pass
            self._ffpkg_poll_id = None

    def _ffpkg_toggle_log(self, force_open=False):
        # v3.0.0: same policy as the global OUTPUT LOG — never
        # auto-open. The drawer only opens via the user clicking
        # the toggle label. See `_toggle_log` for the full rationale.
        if force_open:
            return
        self._ffpkg_log_visible.set(not self._ffpkg_log_visible.get())
        if self._ffpkg_log_visible.get():
            self._ffpkg_log_body.pack(fill='x', padx=24, pady=(2, 6))
            self._ffpkg_log_toggle.config(
                text='\u25bc  OUTPUT LOG', fg=TEXT)
        else:
            self._ffpkg_log_body.pack_forget()
            self._ffpkg_log_toggle.config(
                text='\u25b6  OUTPUT LOG', fg=MUTED)

    def _ffpkg_update_bar(self, pct):
        try:
            w = self._ffpkg_bar_canvas.winfo_width()
            fill_w = int(w * pct / 100)
            self._ffpkg_bar_canvas.coords(self._ffpkg_bar_rect, 0, 0, fill_w, 20)
            self._ffpkg_bar_canvas.itemconfig(
                self._ffpkg_bar_rect, fill=SUCCESS if pct >= 100 else ACCENT)
        except Exception:
            pass

