    def _find_osfmount(self):
        """Locate OSFMount on disk. Returns the absolute path to a usable
        binary, or None.

        Search order:
          1. User-specified path in settings (validated — falls through
             if the file no longer exists or is a folder).
          2. Windows Registry (canonical install location, set by the
             official installer at HKLM\\SOFTWARE\\PassMark\\OSFMount).
          3. Common install directories under Program Files / x86 /
             PassMark, looking for both osfmount.com (CLI wrapper) AND
             OSFMount.exe (newer versions ship only the .exe).
          4. PATH lookup for osfmount.com / OSFMount.exe.

        Why this used to false-negative: older code only checked
        `osfmount.com`, but OSFMount v3+ installers ship only
        `OSFMount.exe`. Settings displays the saved string regardless of
        whether the file exists, while the build path validates via
        os.path.isfile() — hence the "Settings says installed, build
        says missing" inconsistency.
        """
        import os
        import shutil as _sh

        # Helper: return path only if it's a real, usable file
        def _ok(p):
            try:
                return p if (p and os.path.isfile(p)) else None
            except Exception:
                return None

        # Step 50 (v2.6.1): for the same folder, prefer the .com CLI
        # wrapper over the .exe GUI binary. OSFMount.exe pops its GUI
        # window in some scenarios even when invoked with CLI args
        # (CREATE_NO_WINDOW suppresses only the console, not a GUI).
        # osfmount.com is the pure CLI wrapper — silent always.
        def _prefer_com(p):
            try:
                if not p or not os.path.isfile(p):
                    return p
                base = os.path.basename(p).lower()
                if base.endswith('.exe'):
                    com_sibling = os.path.join(
                        os.path.dirname(p), 'osfmount.com')
                    if os.path.isfile(com_sibling):
                        return com_sibling
            except Exception:
                pass
            return p

        # Helper: given a folder, return the first OSFMount binary
        # inside it (either name). Returns None if neither exists.
        # Step 50: .com names come FIRST in the search order so we
        # avoid the GUI binary whenever the CLI wrapper exists.
        def _from_dir(d):
            if not d:
                return None
            for fname in ('osfmount.com', 'OSFMount.com',
                          'OSFMount.exe', 'osfmount.exe'):
                p = os.path.join(d, fname)
                if _ok(p):
                    return p
            return None

        # ── 1. User-specified path ──
        custom = (self._settings.get('osfmount_path') or '').strip()
        if custom:
            # If a file was given and it exists, use it — but if it's
            # the .exe and a .com sits beside it, use the .com instead.
            ok = _ok(custom)
            if ok:
                return _prefer_com(ok)
            # If a folder was given (or the saved file no longer exists
            # but its parent directory still has OSFMount), try the
            # directory containing it.
            try:
                if os.path.isdir(custom):
                    found = _from_dir(custom)
                    if found:
                        return found
                else:
                    parent = os.path.dirname(custom)
                    found = _from_dir(parent)
                    if found:
                        return found
            except Exception:
                pass
            # Saved path is stale — fall through to fresh detection
            # rather than returning None outright.

        # ── 2. Registry lookup (Windows only) ──
        # OSFMount's installer writes its install location to the
        # registry. This is the most reliable source.
        try:
            import winreg  # only available on Windows
            for hive, subkey in [
                (winreg.HKEY_LOCAL_MACHINE,
                    r'SOFTWARE\PassMark\OSFMount'),
                (winreg.HKEY_LOCAL_MACHINE,
                    r'SOFTWARE\WOW6432Node\PassMark\OSFMount'),
                (winreg.HKEY_CURRENT_USER,
                    r'SOFTWARE\PassMark\OSFMount'),
                # Uninstall keys sometimes have InstallLocation too
                (winreg.HKEY_LOCAL_MACHINE,
                    r'SOFTWARE\Microsoft\Windows\CurrentVersion'
                    r'\Uninstall\OSFMount_is1'),
                (winreg.HKEY_LOCAL_MACHINE,
                    r'SOFTWARE\WOW6432Node\Microsoft\Windows'
                    r'\CurrentVersion\Uninstall\OSFMount_is1'),
            ]:
                try:
                    with winreg.OpenKey(hive, subkey) as k:
                        for value_name in ('InstallLocation', 'Path',
                                           'InstallDir'):
                            try:
                                val, _vt = winreg.QueryValueEx(
                                    k, value_name)
                                found = _from_dir(val)
                                if found:
                                    return found
                            except FileNotFoundError:
                                continue
                except (FileNotFoundError, OSError):
                    continue
        except ImportError:
            # Not on Windows or winreg unavailable — skip
            pass

        # ── 3. Common install directories ──
        # Expand env-var driven paths to be drive-letter-agnostic.
        pf      = os.environ.get('ProgramFiles', r'C:\Program Files')
        pf_x86  = os.environ.get('ProgramFiles(x86)',
                                  r'C:\Program Files (x86)')
        pf_w64  = os.environ.get('ProgramW6432', pf)
        candidates = []
        for base in (pf, pf_x86, pf_w64):
            for sub in ('OSFMount', os.path.join('PassMark', 'OSFMount')):
                candidates.append(os.path.join(base, sub))
        # De-dupe while preserving order
        seen = set()
        ordered = []
        for c in candidates:
            n = os.path.normcase(c)
            if n not in seen:
                seen.add(n)
                ordered.append(c)
        for d in ordered:
            found = _from_dir(d)
            if found:
                return found

        # ── 4. PATH lookup, both names ──
        # Step 50: .com first so the CLI wrapper wins over the GUI .exe.
        for name in ('osfmount.com', 'OSFMount.com',
                     'OSFMount.exe', 'osfmount.exe'):
            p = _sh.which(name)
            if p:
                return p

        return None

    def _fm_add_file(self):
        if not self._fm_drive:
            messagebox.showwarning('Not mounted', 'Mount an image first.')
            return
        files = filedialog.askopenfilenames(title='Select file(s) to add')
        if not files:
            return
        added = 0
        skipped = 0
        overwrite_all = [False]
        skip_all      = [False]
        for src in files:
            dst = os.path.join(self._fm_current_dir, os.path.basename(src))
            if os.path.exists(dst) and not overwrite_all[0]:
                if skip_all[0]:
                    skipped += 1
                    continue
                choice = self._fm_overwrite_dialog(os.path.basename(src),
                                                    len(files) > 1)
                if choice == 'skip':
                    skipped += 1
                    continue
                elif choice == 'skip_all':
                    skip_all[0] = True
                    skipped += 1
                    continue
                elif choice == 'overwrite_all':
                    overwrite_all[0] = True
                # 'overwrite' or 'overwrite_all' — fall through to copy
            try:
                shutil.copy2(src, dst)
                added += 1
            except Exception as e:
                messagebox.showerror('Copy failed',
                    'Failed to copy ' + os.path.basename(src) + ':\n' + str(e))
        self._fm_refresh()
        parts = []
        if added:   parts.append(str(added) + ' file(s) added')
        if skipped: parts.append(str(skipped) + ' skipped')
        self._fm_status_var.set('  •  '.join(parts) if parts else 'Done')

    def _fm_add_folder(self):
        if not self._fm_drive:
            messagebox.showwarning('Not mounted', 'Mount an image first.')
            return
        src_folder = filedialog.askdirectory(title='Select folder to copy into image')
        if not src_folder:
            return
        folder_name = os.path.basename(src_folder.rstrip('/\\'))
        dst_root = os.path.join(self._fm_current_dir, folder_name)

        # Collect all files to copy
        all_files = []
        for root, dirs, files in os.walk(src_folder):
            for fn in files:
                src_path = os.path.join(root, fn)
                rel      = os.path.relpath(src_path, src_folder)
                dst_path = os.path.join(dst_root, rel)
                all_files.append((src_path, dst_path, fn))

        if not all_files:
            messagebox.showinfo('Empty folder', 'The selected folder contains no files.')
            return

        # Check for any conflicts upfront
        conflicts = [(s, d, n) for s, d, n in all_files if os.path.exists(d)]
        overwrite_all = False
        if conflicts:
            msg = (str(len(conflicts)) + ' file(s) already exist in the image.\n\n' +
                   '\n'.join(os.path.basename(d) for _, d, _ in conflicts[:8]) +
                   ('\n...' if len(conflicts) > 8 else '') +
                   '\n\nOverwrite all existing files?')
            ans = messagebox.askyesnocancel('Files exist', msg)
            if ans is None:
                return   # Cancel
            overwrite_all = ans

        added = 0
        skipped = 0
        errors = []
        for src_path, dst_path, fn in all_files:
            if os.path.exists(dst_path) and not overwrite_all:
                skipped += 1
                continue
            try:
                os.makedirs(os.path.dirname(dst_path), exist_ok=True)
                shutil.copy2(src_path, dst_path)
                added += 1
            except Exception as e:
                errors.append(fn + ': ' + str(e))

        self._fm_refresh()
        parts = []
        if added:   parts.append(str(added) + ' file(s) copied')
        if skipped: parts.append(str(skipped) + ' skipped')
        self._fm_status_var.set('  •  '.join(parts) if parts else 'Done')
        if errors:
            messagebox.showerror('Some files failed',
                str(len(errors)) + ' file(s) could not be copied:\n\n' +
                '\n'.join(errors[:10]))

    def _fm_browse(self):
        p = filedialog.askopenfilename(
            title='Select exFAT image',
            filetypes=[('exFAT images', '*.exfat'), ('All files', '*.*')])
        if p:
            self._fm_image_var.set(p.replace('/', '\\'))

    def _fm_context_menu(self, event):
        if not self._fm_drive:
            return
        sel = self._fm_listbox.nearest(event.y)
        self._fm_listbox.selection_clear(0, 'end')
        self._fm_listbox.selection_set(sel)
        path, is_dir = self._fm_selected_path()
        if not path:
            return
        menu = tk.Menu(self, tearoff=0, bg=SURFACE2, fg=TEXT,
                       activebackground=ACCENT, activeforeground=TEXT,
                       font=('Segoe UI', 9))
        if not is_dir:
            menu.add_command(label='\U0001f504  Replace file',
                             command=self._fm_replace_file)
        menu.add_command(label='\u2795  Add files here',
                         command=self._fm_add_file)
        menu.add_command(label='\U0001f4c1  Add folder here',
                         command=self._fm_add_folder)
        if is_dir:
            menu.add_command(label='\U0001f4c2  Open folder',
                             command=self._fm_enter)
        menu.add_separator()
        menu.add_command(label='\U0001f5d1  Delete',
                         command=self._fm_delete)
        menu.tk_popup(event.x_root, event.y_root)

    def _fm_delete(self):
        sels = self._fm_listbox.curselection()
        if not sels:
            messagebox.showwarning('No selection', 'Select file(s) or folder(s) to delete.')
            return
        names = [self._fm_entries[i][0] for i in sels if self._fm_entries[i][0] != '..']
        if not names:
            return
        if not messagebox.askyesno('Delete',
                'Delete ' + str(len(names)) + ' item(s)?\n\n' +
                '\n'.join(names[:10]) +
                ('\n...' if len(names) > 10 else '') +
                '\n\nThis cannot be undone.'):
            return
        errors = []
        for name in names:
            p = os.path.join(self._fm_current_dir, name)
            try:
                if os.path.isdir(p):
                    shutil.rmtree(p)
                else:
                    os.remove(p)
            except Exception as e:
                errors.append(name + ': ' + str(e))
        self._fm_refresh()
        if errors:
            messagebox.showerror('Some deletions failed', '\n'.join(errors))
        else:
            self._fm_status_var.set('Deleted ' + str(len(names)) + ' item(s)')

    def _fm_dismount(self):
        if not self._fm_drive or not self._fm_osf:
            return
        if not messagebox.askyesno('Dismount',
                'Dismount the image?\n\nMake sure all file operations are complete.'):
            return
        self._fm_dismount_btn.config(state='disabled', text='Dismounting...')
        drive = self._fm_drive
        osf   = self._fm_osf

        def worker():
            ok = self._dismount_with_retry(osf, drive)
            self.after(0, self._fm_dismount_done, ok, drive)

        threading.Thread(target=worker, daemon=True).start()

    def _dismount_with_retry(self, osf, mount_point, max_attempts=6):
        import subprocess as _sp
        import time as _t
        targets = [mount_point, mount_point.rstrip('\\') + '\\']
        for _ in range(max_attempts):
            for target in targets:
                try:
                    r = _sp.run([osf, '-d', '-m', target],
                                capture_output=True,
                                creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())
                    if r.returncode == 0:
                        return True
                except Exception:
                    pass
            _t.sleep(0.5)
        return False

    def _fm_dismount_done(self, ok, drive):
        self._fm_drive = None
        self._fm_current_dir = None
        self._fm_osf = None
        self._fm_listbox.delete(0, 'end')
        self._fm_entries = []
        self._fm_path_var.set('—')
        self._fm_dismount_btn.config(text='\U0001f513 Dismount')
        self._fm_mount_btn.config(state='normal')
        self._fm_dismount_btn.config(state='disabled')
        if ok:
            self._fm_status_var.set('Dismounted successfully \u2713')
        else:
            self._fm_status_var.set(
                '\u26a0 Dismount may not have fully completed — '
                'check Explorer and eject manually if needed')

    def _fm_enter(self):
        sel = self._fm_listbox.curselection()
        if not sel:
            return
        name, is_dir, _ = self._fm_entries[sel[0]]
        if not is_dir:
            return
        if name == '..':
            self._fm_go_up()
        else:
            self._fm_current_dir = os.path.join(self._fm_current_dir, name) + '\\'
            self._fm_refresh()

    def _fm_find_osf(self):
        # Step 48 (v2.6.1): defer to the canonical _find_osfmount() so
        # this tab honours the OSFMount path set in Settings, the
        # PassMark registry entries, and OSFMount v3+ which ships only
        # OSFMount.exe (no osfmount.com). The hardcoded three-path
        # scan that lived here previously caused "OSFMount not found"
        # popups even when Settings clearly showed a detected binary.
        return self._find_osfmount()

    def _fm_go_up(self):
        if not self._fm_current_dir:
            return
        cur = self._fm_current_dir.rstrip('\\')
        if cur == self._fm_drive:
            return
        parent = os.path.dirname(cur) + '\\'
        self._fm_current_dir = parent
        self._fm_refresh()

    def _fm_mount(self):
        img = self._fm_image_var.get().strip()
        if not img:
            messagebox.showwarning('No image', 'Please select an exFAT image first.')
            return
        if not os.path.isfile(img):
            messagebox.showerror('Not found', 'Image file not found:\n' + img)
            return
        osf = self._fm_find_osf()
        if not osf:
            messagebox.showerror('OSFMount not found',
                'Please install OSFMount from:\n'
                'https://www.osforensics.com/tools/mount-disk-images.html')
            return
        self._fm_osf = osf

        # Find free drive letter
        try:
            import ctypes as _ct
            bitmask = _ct.windll.kernel32.GetLogicalDrives()
            free = None
            for i in range(25, 3, -1):
                if not (bitmask & (1 << i)):
                    free = chr(65 + i) + ':'
                    break
            if not free:
                raise Exception('No free drive letters')
        except Exception as e:
            messagebox.showerror('Error', str(e))
            return

        self._fm_status_var.set('Mounting...')
        self.update()

        result = subprocess.run(
            [osf, '-a', '-t', 'file', '-f', img,
             '-m', free, '-o', 'rw,rem'],
            capture_output=True, text=True,
            creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())

        if result.returncode != 0:
            self._fm_status_var.set('Mount failed')
            messagebox.showerror('Mount failed',
                result.stderr or result.stdout or 'Unknown error')
            return

        # Wait for drive
        import time as _t
        for _ in range(20):
            if os.path.exists(free + '\\'):
                break
            _t.sleep(0.3)
        else:
            self._fm_status_var.set('Drive did not appear')
            return

        self._fm_drive = free
        self._fm_current_dir = free + '\\'
        self._fm_status_var.set('Mounted: ' + free + '  (read-write)')
        self._fm_mount_btn.config(state='disabled')
        self._fm_dismount_btn.config(state='normal')
        self._fm_refresh()

    def _fm_new_folder(self):
        if not self._fm_drive:
            messagebox.showwarning('Not mounted', 'Mount an image first.')
            return
        name = tk.simpledialog.askstring('New folder', 'Folder name:',
                                          parent=self)
        if not name:
            return
        try:
            os.makedirs(os.path.join(self._fm_current_dir, name), exist_ok=True)
            self._fm_refresh()
        except Exception as e:
            messagebox.showerror('Error', str(e))

    def _fm_overwrite_dialog(self, filename, show_all_options):
        """Ask user what to do when a file already exists. Returns:
        'overwrite', 'overwrite_all', 'skip', 'skip_all'"""
        win = tk.Toplevel(self)
        win.title('File exists')
        win.configure(bg=BG)
        win.resizable(False, False)
        win.transient(self)
        win.grab_set()

        tk.Label(win, text='\u26a0  File already exists',
                 font=('Segoe UI', 11, 'bold'), bg=BG, fg=WARNING).pack(padx=24, pady=(16, 4))
        tk.Label(win, text=filename,
                 font=('Consolas', 9), bg=BG, fg=MUTED).pack(padx=24, pady=(0, 16))

        result = [None]

        btn_frame = tk.Frame(win, bg=BG)
        btn_frame.pack(padx=24, pady=(0, 16))

        def make_btn(text, val, fg=TEXT, bg=SURFACE2):
            tk.Button(btn_frame, text=text, font=('Segoe UI', 9),
                      bg=bg, fg=fg, activebackground=BORDER,
                      activeforeground=TEXT, relief='flat', bd=0,
                      padx=12, pady=6, cursor='hand2',
                      command=lambda v=val: (result.__setitem__(0, v), win.destroy())
                      ).pack(side='left', padx=4)

        make_btn('Overwrite', 'overwrite', bg=WARNING, fg='#000000')
        if show_all_options:
            make_btn('Overwrite All', 'overwrite_all', bg=DANGER)
        make_btn('Skip', 'skip')
        if show_all_options:
            make_btn('Skip All', 'skip_all')

        win.update_idletasks()
        # Centre over parent
        x = self.winfo_x() + (self.winfo_width()  - win.winfo_width())  // 2
        y = self.winfo_y() + (self.winfo_height() - win.winfo_height()) // 2
        win.geometry('+%d+%d' % (x, y))
        win.wait_window()
        return result[0] or 'skip'

    def _fm_refresh(self):
        if not self._fm_drive or not self._fm_current_dir:
            return
        self._fm_listbox.delete(0, 'end')
        self._fm_entries = []
        self._fm_path_var.set(self._fm_current_dir)
        try:
            entries = []
            with os.scandir(self._fm_current_dir) as it:
                for e in it:
                    try:
                        is_dir = e.is_dir()
                        size   = 0 if is_dir else e.stat().st_size
                        entries.append((e.name, is_dir, size))
                    except Exception:
                        pass
            # Dirs first, then files, both alphabetical
            entries.sort(key=lambda x: (not x[1], x[0].lower()))
            # Add parent dir if not at root
            if self._fm_current_dir.rstrip('\\') != self._fm_drive:
                self._fm_entries.append(('..', True, 0))
                self._fm_listbox.insert('end', '\U0001f4c2  ..')
            for name, is_dir, size in entries:
                self._fm_entries.append((name, is_dir, size))
                if is_dir:
                    self._fm_listbox.insert('end', '\U0001f4c1  ' + name)
                else:
                    if size >= 1024**3:
                        sz = '%.2f GB' % (size / 1024**3)
                    elif size >= 1024**2:
                        sz = '%.1f MB' % (size / 1024**2)
                    else:
                        sz = '%d KB' % (size // 1024)
                    self._fm_listbox.insert('end',
                        '\U0001f4be  %-60s %10s' % (name, sz))

            # v2.9.0: Populate the MODIFIED column on each Treeview row.
            # The old Listbox-based UI couldn't show a separate column;
            # the new Treeview backing has one but the ListboxProxy.insert
            # didn't know about mtime. Post-pass fills it in.
            tree = getattr(self, '_fm_tree', None)
            if tree is not None:
                import time as _time
                rows = tree.get_children('')
                for i, entry in enumerate(self._fm_entries):
                    if i >= len(rows):
                        break
                    name, _is_dir, _size = entry
                    if name == '..':
                        continue
                    try:
                        mtime = os.path.getmtime(
                            os.path.join(self._fm_current_dir, name))
                        ts = _time.strftime('%d %b %Y %H:%M',
                                             _time.localtime(mtime))
                    except Exception:
                        ts = ''
                    try:
                        vals = list(tree.item(rows[i], 'values'))
                        if len(vals) >= 4:
                            vals[3] = ts
                            tree.item(rows[i], values=vals)
                    except Exception:
                        pass
        except Exception as e:
            messagebox.showerror('Error reading directory', str(e))

    def _fm_replace_file(self):
        path, is_dir = self._fm_selected_path()
        if not path:
            messagebox.showwarning('No selection', 'Select a file to replace.')
            return
        if is_dir:
            messagebox.showwarning('Is a folder', 'Select a file, not a folder.')
            return
        src = filedialog.askopenfilename(
            title='Select replacement file',
            initialfile=os.path.basename(path))
        if not src:
            return
        try:
            shutil.copy2(src, path)
            self._fm_refresh()
            self._fm_status_var.set('Replaced: ' + os.path.basename(path))
        except Exception as e:
            messagebox.showerror('Replace failed', str(e))

    def _fm_selected_path(self):
        sel = self._fm_listbox.curselection()
        if not sel:
            return None, None
        name, is_dir, _ = self._fm_entries[sel[0]]
        if name == '..':
            return None, None
        return os.path.join(self._fm_current_dir, name), is_dir

    def _force_dismount_all(self):
        """Show a picker of mounted virtual drives and let user choose
        which to dismount.

        SAFETY:
          - The system drive (%SystemDrive%, usually C:) is NEVER shown.
          - Any drive containing \\Windows\\System32 is NEVER shown.
          - Physical fixed drives are hidden by default behind an
            "Advanced — show physical drives" checkbox with a warning.
          - On final submission, a second check refuses to dismount
            anything that looks like a system drive.

        Auto-detection of OSFMount virtual drives: the active build's
        target drive is always considered virtual. Other drives are
        classified virtual if their volume label matches one of the
        common OSFMount labels (OSFIMG, PS5DATA, PS5IMG). Anything
        else is treated as a physical drive and hidden.
        """
        import ctypes as _ct
        import os as _os

        # ── Identify the system drive ──
        try:
            sys_drive = _os.environ.get('SystemDrive', 'C:')
            sys_letter = sys_drive.rstrip(':\\').upper()[:1]
        except Exception:
            sys_letter = 'C'

        bitmask = _ct.windll.kernel32.GetLogicalDrives()
        drives  = []

        for i in range(2, 26):  # skip A, B
            if not (bitmask & (1 << i)):
                continue
            letter = chr(65 + i)
            drive  = letter + ':\\'

            # ── HARD EXCLUSIONS ──
            if letter == sys_letter:
                continue
            try:
                if _os.path.isdir(drive + 'Windows\\System32'):
                    continue
            except Exception:
                pass
            try:
                dtype = _ct.windll.kernel32.GetDriveTypeW(drive)
                if dtype not in (2, 3):  # removable or fixed only
                    continue
            except Exception:
                continue

            # Gather info
            try:
                vol_buf = _ct.create_unicode_buffer(256)
                _ct.windll.kernel32.GetVolumeInformationW(
                    drive, vol_buf, 256, None, None, None, None, 0)
                label = vol_buf.value or 'No Label'
            except Exception:
                label = 'No Label'

            try:
                usage = shutil.disk_usage(drive)
                size_gb = usage.total / 1024**3
                size_str = '%.1f GB' % size_gb
            except Exception:
                size_str = '?'

            is_current = bool(self._mounted_drive and
                              letter in self._mounted_drive.upper())

            # Heuristic: is this an OSFMount virtual drive?
            # Sure-things: current build target, or label is one of
            # the well-known OSFMount labels.
            up_label = (label or '').upper()
            is_virtual = bool(
                is_current
                or up_label in ('OSFIMG', 'PS5DATA', 'PS5IMG')
            )

            drives.append({
                'letter':     letter,
                'label':      label,
                'size':       size_str,
                'current':    is_current,
                'is_virtual': is_virtual,
            })

        if not drives:
            messagebox.showinfo(
                'No drives',
                'No virtual drives found to dismount.\n\n'
                '(System drives and physical disks are intentionally '
                'hidden — they can\'t be dismounted while Windows is '
                'running.)')
            return

        # Sort: virtual first, then alphabetical
        drives.sort(key=lambda d: (not d['is_virtual'], d['letter']))
        n_virtual  = sum(1 for d in drives if d['is_virtual'])
        n_physical = len(drives) - n_virtual

        # ── Build dialog ──
        dlg = tk.Toplevel(self)
        dlg.title('Force Dismount — Select Drive')
        dlg.configure(bg=BG)
        dlg.resizable(False, False)
        dlg.attributes('-topmost', True)

        tk.Label(dlg, text='Select drive(s) to force dismount:',
                 font=('Segoe UI', 10, 'bold'), bg=BG, fg=TEXT,
                 padx=20, pady=12).pack(anchor='w')

        tk.Label(dlg,
                 text='Your system drive is hidden for safety.',
                 font=('Segoe UI', 8),
                 bg=BG, fg='#888888',
                 padx=20, pady=(0, 6)).pack(anchor='w')

        check_vars = {}
        physical_rows = []  # list of (Frame, drive_letter)

        def _row(d, hidden=False):
            var = tk.BooleanVar(value=d['current'])
            check_vars[d['letter']] = var
            row = tk.Frame(dlg, bg=BG)
            if not hidden:
                row.pack(fill='x', padx=20, pady=2)
            tag = ''
            if d['current']:
                tag = '  \u2190 current build drive'
            elif not d['is_virtual']:
                tag = '  \u2014 physical drive!'
            tk.Checkbutton(row, variable=var,
                           bg=BG, activebackground=BG,
                           selectcolor=ACCENT,
                           cursor='hand2').pack(side='left')
            color = ACCENT if d['current'] else (
                '#c08040' if not d['is_virtual'] else TEXT)
            tk.Label(row,
                     text='%s:  %s  (%s)%s' % (
                         d['letter'], d['label'], d['size'], tag),
                     font=('Segoe UI', 9),
                     bg=BG, fg=color,
                     anchor='w').pack(side='left')
            return row

        # Virtual drives
        for d in drives:
            if d['is_virtual']:
                _row(d, hidden=False)

        if not n_virtual:
            tk.Label(dlg,
                     text='(No virtual drives detected. Use the '
                          'Advanced toggle below to show physical '
                          'drives — but be very careful.)',
                     font=('Segoe UI', 8),
                     bg=BG, fg='#888888',
                     padx=20, pady=(6, 0), wraplength=380,
                     justify='left'
                     ).pack(anchor='w')

        # Physical drives — hidden behind an expander
        if n_physical:
            adv = tk.Frame(dlg, bg=BG)
            adv.pack(fill='x', padx=20, pady=(8, 0))
            show_phys = tk.BooleanVar(value=False)

            def _toggle_physical():
                if show_phys.get():
                    for row in physical_rows:
                        row.pack(fill='x', padx=20, pady=2,
                                 before=adv)
                else:
                    for row in physical_rows:
                        row.pack_forget()
                    # Uncheck physical drives when hiding so user
                    # can't smuggle a selection past the expander
                    for d in drives:
                        if not d['is_virtual']:
                            if d['letter'] in check_vars:
                                check_vars[d['letter']].set(False)

            tk.Checkbutton(adv, variable=show_phys,
                           text=('\u26a0  Show physical drives '
                                 '(%d hidden) \u2014 advanced'
                                 % n_physical),
                           font=('Segoe UI', 9),
                           bg=BG, fg='#c08040',
                           activebackground=BG,
                           selectcolor=BG,
                           cursor='hand2',
                           command=_toggle_physical
                           ).pack(anchor='w')

            for d in drives:
                if not d['is_virtual']:
                    physical_rows.append(_row(d, hidden=True))

        btn_row = tk.Frame(dlg, bg=BG)
        btn_row.pack(fill='x', padx=20, pady=(12, 16))

        selected = [None]

        def _go():
            picks = [l for l, v in check_vars.items() if v.get()]
            # Final safety: refuse if any picked drive is the system
            # drive or has a Windows folder.
            for letter in picks:
                if letter == sys_letter:
                    messagebox.showerror(
                        'Cannot dismount',
                        'Refusing to dismount %s: — it\'s your system '
                        'drive.' % letter)
                    return
                try:
                    if _os.path.isdir(letter + ':\\Windows\\System32'):
                        messagebox.showerror(
                            'Cannot dismount',
                            ('Refusing to dismount %s: — looks like '
                             'a Windows install (contains '
                             '\\Windows\\System32).') % letter)
                        return
                except Exception:
                    pass
            selected[0] = picks
            dlg.destroy()

        tk.Button(btn_row, text='\u23cf Dismount Selected',
                  font=('Segoe UI', 10, 'bold'),
                  bg=DANGER, fg=TEXT, activebackground='#c0392b',
                  relief='flat', bd=0, padx=16, pady=8,
                  cursor='hand2', command=_go).pack(side='right')
        tk.Button(btn_row, text='Cancel',
                  font=('Segoe UI', 9),
                  bg=SURFACE2, fg=MUTED, activebackground=BORDER,
                  relief='flat', bd=0, padx=12, pady=8,
                  cursor='hand2', command=dlg.destroy
                  ).pack(side='right', padx=(0, 8))

        dlg.grab_set()
        self.wait_window(dlg)

        letters = selected[0]
        if not letters:
            return

        dismounted = []
        failed     = []
        for letter in letters:
            ok = self._dismount_drive_robust(letter)
            if ok:
                dismounted.append(letter)
                if self._mounted_drive and \
                        letter in self._mounted_drive.upper():
                    self._mounted_drive = None
                self._log('[DISMOUNT] %s: dismounted \u2713\n' % letter)
            else:
                failed.append(letter)
                self._log('[DISMOUNT] %s: failed\n' % letter)

        msg = ''
        if dismounted:
            msg += 'Dismounted: %s\n' % ', '.join(l + ':'
                                                   for l in dismounted)
        if failed:
            msg += 'Failed: %s' % ', '.join(l + ':' for l in failed)
        if msg:
            messagebox.showinfo('Force Dismount', msg.strip())

    def _dismount_drive_robust(self, letter, max_wait_seconds=30):
        """Robustly dismount a drive letter. Tries, in order:
          1. osfmount.com / OSFMount.exe -D (force) -m <letter>:
          2. osfmount.com / OSFMount.exe -d (normal) -m <letter>:
          2.5 Step 49 (v2.6.1): osfmount.com -l → find the device
              number whose mount is <letter>: → osfmount.com -D -m #:
              This works when letter-based dismount is wedged because
              the kernel-mode driver disagrees about the letter table.
          3. mountvol <letter>: /D
          4. Win32 FSCTL_LOCK_VOLUME + FSCTL_DISMOUNT_VOLUME

        Each step gives Windows ~2s to release handles. Defender
        and Search Indexer typically release within 5-30s after
        the file is closed; if we're called right after a build,
        we may need to wait a bit. The total wait is capped at
        max_wait_seconds.

        Returns True if the drive is no longer present after the
        attempt, False otherwise.
        """
        import time as _t
        import subprocess as _sp
        import ctypes as _ct
        import os as _os
        import re as _re

        drive_path = letter + ':\\'
        deadline = _t.time() + max_wait_seconds

        def _still_mounted():
            try:
                return _os.path.exists(drive_path)
            except Exception:
                return True  # assume yes if we can't tell

        if not _still_mounted():
            return True  # already gone

        osf = self._find_osfmount()
        creation_flags = getattr(_sp, 'CREATE_NO_WINDOW', 0)

        # ── Step 1: osfmount -D (force) ──
        # The -D (uppercase) flag is OSFMount's "force dismount" which
        # bypasses the busy check. Not all versions support it; if it
        # doesn't, we fall through to -d.
        if osf:
            for attempt in range(3):
                if _t.time() >= deadline:
                    break
                try:
                    _sp.run([osf, '-D', '-m', letter + ':'],
                            capture_output=True, timeout=8,
                            creationflags=creation_flags,
                            startupinfo=_silent_startupinfo())
                except Exception:
                    pass
                _t.sleep(1.0)
                if not _still_mounted():
                    return True

        # ── Step 2: osfmount -d (normal) ──
        if osf:
            for attempt in range(3):
                if _t.time() >= deadline:
                    break
                try:
                    _sp.run([osf, '-d', '-m', letter + ':'],
                            capture_output=True, timeout=8,
                            creationflags=creation_flags,
                            startupinfo=_silent_startupinfo())
                except Exception:
                    pass
                _t.sleep(1.0)
                if not _still_mounted():
                    return True

        # ── Step 2.5: dismount-by-device-number ──
        # When letter-based dismount is wedged (the kernel driver and
        # CLI disagree about the letter table — happens when a previous
        # `-a` was killed mid-mount by TimeoutExpired), the device
        # often survives `-l` listing and can be killed by its index.
        # Each line of `osfmount.com -l` looks roughly like:
        #   Device 0: D:\path\to\image.exfat -> Y:
        # We parse that, match our letter, and re-issue dismount as
        # `osfmount.com -D -m N:` where N is the device number.
        if osf and _t.time() < deadline and _still_mounted():
            try:
                lst = _sp.run([osf, '-l'],
                              capture_output=True, text=True, timeout=8,
                              creationflags=creation_flags,
                              startupinfo=_silent_startupinfo())
                out = (lst.stdout or '') + '\n' + (lst.stderr or '')
                want = letter.upper() + ':'
                # Match "Device N:" followed by something containing ` -> X:`
                # Be permissive about the device-number pattern across
                # OSFMount versions.
                dev_num = None
                cur_dev = None
                for line in out.splitlines():
                    m = _re.match(r'\s*[Dd]evice\s+(\d+)\b', line)
                    if m:
                        cur_dev = int(m.group(1))
                    if cur_dev is not None and want.upper() in line.upper():
                        dev_num = cur_dev
                        break
                if dev_num is not None:
                    try:
                        _sp.run([osf, '-D', '-m', '%d:' % dev_num],
                                capture_output=True, timeout=8,
                                creationflags=creation_flags,
                                startupinfo=_silent_startupinfo())
                    except Exception:
                        pass
                    _t.sleep(1.0)
                    if not _still_mounted():
                        return True
            except Exception:
                pass

        # ── Step 3: mountvol /D ──
        # This removes the mount point (drive letter) but leaves the
        # underlying volume. Works even when OSFMount is unhappy.
        if _t.time() < deadline:
            try:
                _sp.run(['mountvol', letter + ':', '/D'],
                        capture_output=True, timeout=8,
                        creationflags=creation_flags)
            except Exception:
                pass
            _t.sleep(1.0)
            if not _still_mounted():
                return True

        # ── Step 4: FSCTL_LOCK_VOLUME + FSCTL_DISMOUNT_VOLUME ──
        # This is the lowest level and works regardless of OSFMount's
        # state. We LOCK first (which closes other handles via Windows
        # broadcast), then DISMOUNT. Without the lock, dismount fails
        # when any handle is still open.
        try:
            GENERIC_READ      = 0x80000000
            GENERIC_WRITE     = 0x40000000
            FILE_SHARE_READ   = 0x1
            FILE_SHARE_WRITE  = 0x2
            OPEN_EXISTING     = 3
            FSCTL_LOCK_VOLUME     = 0x00090018
            FSCTL_DISMOUNT_VOLUME = 0x00090020
            INVALID_HANDLE_VALUE  = _ct.c_void_p(-1).value

            CreateFileW = _ct.windll.kernel32.CreateFileW
            CreateFileW.argtypes = [
                _ct.c_wchar_p, _ct.c_uint32, _ct.c_uint32,
                _ct.c_void_p, _ct.c_uint32, _ct.c_uint32, _ct.c_void_p]
            CreateFileW.restype = _ct.c_void_p
            DeviceIoControl = _ct.windll.kernel32.DeviceIoControl
            CloseHandle = _ct.windll.kernel32.CloseHandle

            h = CreateFileW(
                '\\\\.\\' + letter + ':',
                GENERIC_READ | GENERIC_WRITE,
                FILE_SHARE_READ | FILE_SHARE_WRITE,
                None, OPEN_EXISTING, 0, None)
            if h and h != INVALID_HANDLE_VALUE:
                try:
                    dw = _ct.c_ulong(0)
                    # Try LOCK then DISMOUNT, with a couple of retries
                    # while we wait for handles to close.
                    for _ in range(5):
                        if _t.time() >= deadline:
                            break
                        rl = DeviceIoControl(
                            h, FSCTL_LOCK_VOLUME,
                            None, 0, None, 0,
                            _ct.byref(dw), None)
                        if rl:
                            DeviceIoControl(
                                h, FSCTL_DISMOUNT_VOLUME,
                                None, 0, None, 0,
                                _ct.byref(dw), None)
                            break
                        _t.sleep(1.0)
                finally:
                    CloseHandle(h)
        except Exception:
            pass

        # ── Final wait for the letter to disappear ──
        while _t.time() < deadline:
            if not _still_mounted():
                return True
            _t.sleep(0.5)

        return not _still_mounted()

    def _sweep_stale_osf_mounts(self, exclude_letter=None, log_prefix='[SWEEP]'):
        """Step 49 (v2.6.1): scan for OSFMount-labeled drives and
        dismount them. Called before verify so a previous build's
        leaked mount can't snipe the new verify slot or wedge the
        OSFMount driver. Returns the list of letters dismounted.

        We identify OSFMount drives by their volume label (OSFIMG,
        PS5DATA, PS5IMG). The active build's mount point is excluded
        via `exclude_letter` so we don't kill the build mid-copy.
        """
        import ctypes as _ct
        import os as _os
        try:
            bitmask = _ct.windll.kernel32.GetLogicalDrives()
        except Exception:
            return []
        try:
            sys_letter = _os.environ.get('SystemDrive', 'C:').rstrip(':\\').upper()[:1]
        except Exception:
            sys_letter = 'C'
        excl = (exclude_letter or '').rstrip(':\\').upper()[:1]
        killed = []
        for i in range(3, 26):  # skip A, B, C
            if not (bitmask & (1 << i)):
                continue
            letter = chr(65 + i)
            if letter == sys_letter or letter == excl:
                continue
            try:
                # Hard exclusion: anything that looks like a Windows
                # install. Cheap check, runs first.
                if _os.path.isdir(letter + ':\\Windows\\System32'):
                    continue
            except Exception:
                pass
            # GetVolumeInformationW — null label tolerated; we only
            # care about a match against the OSFMount labels.
            try:
                vol_buf = _ct.create_unicode_buffer(256)
                ok = _ct.windll.kernel32.GetVolumeInformationW(
                    letter + ':\\', vol_buf, 256, None, None, None, None, 0)
                label = (vol_buf.value or '').upper() if ok else ''
            except Exception:
                label = ''
            if label not in ('OSFIMG', 'PS5DATA', 'PS5IMG'):
                continue
            try:
                self._log('%s Dismounting stale OSFMount drive %s: '
                          '(label=%s)\n' % (log_prefix, letter, label))
            except Exception:
                pass
            try:
                if self._dismount_drive_robust(letter, max_wait_seconds=15):
                    killed.append(letter)
                    try:
                        self._log('%s   %s: dismounted\n' % (log_prefix, letter))
                    except Exception:
                        pass
                else:
                    try:
                        self._log('%s   %s: still mounted after sweep\n'
                                  % (log_prefix, letter))
                    except Exception:
                        pass
            except Exception:
                pass
        return killed

    def _format_eta(self, elapsed, pct):
        es = 'Elapsed: %dm %02ds' % (int(elapsed // 60), int(elapsed % 60))
        if pct <= 1:
            return es
        remaining = max(0, (elapsed / (pct / 100.0)) - elapsed)
        if remaining < 5:
            return es + '  —  Almost done'
        m, s = int(remaining // 60), int(remaining % 60)
        return es + '  —  ETA: %dm %02ds' % (m, s)

    def _ftp_ping(self, callback):
        ip = self._ftp_ip_var.get().strip()
        if not ip:
            callback(False, 'No IP set')
            return
        def worker():
            try:
                import socket
                port = int(self._ftp_port_var.get().strip() or '2121')
                s = socket.create_connection((ip, port), timeout=3)
                s.close()
                self.after(0, callback, True, 'PS5 reachable at ' + ip)
            except Exception as e:
                self.after(0, callback, False, str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _ftp_switch_sub(self, key):
        # Step 12 (v2.1.4): underline-style sub-tabs matching the design
        # system. Active button: accent text + 2px accent underline.
        self._ftp_subtab_var.set(key)
        active_fg     = '#4a9eff'  # COLORS['accent']
        inactive_fg   = '#888888'  # COLORS['fg_4']
        underline_off = '#050505'  # COLORS['bg_0']

        def _paint(btn, active):
            try:
                btn.config(fg=active_fg if active else inactive_fg)
            except Exception:
                pass
            ul = getattr(btn, '_underline', None)
            if ul is not None:
                try:
                    ul.configure(bg=active_fg if active else underline_off)
                except Exception:
                    pass

        if key == 'upload':
            self._ftp_sub_upload_frame.pack(fill='both', expand=True)
            self._ftp_sub_browser_frame.pack_forget()
            _paint(self._ftp_sub_upload_btn, True)
            _paint(self._ftp_sub_browser_btn, False)
        else:
            self._ftp_sub_browser_frame.pack(fill='both', expand=True)
            self._ftp_sub_upload_frame.pack_forget()
            _paint(self._ftp_sub_browser_btn, True)
            _paint(self._ftp_sub_upload_btn, False)

    def _ftptab_browse(self):
        if self._ftptab_is_folder.get():
            p = filedialog.askdirectory(title='Select folder to upload')
        else:
            p = filedialog.askopenfilename(title='Select file to upload')
        if p:
            self._ftptab_local_var.set(p.replace('/', '\\'))

    def _ftptab_cancel(self):
        self._ftptab_cancel_flag = True
        self._ftptab_status_var.set('Cancelling...')

    def _ftptab_done(self, ok, info):
        self._ftptab_upload_btn.config(state='normal', text='\U0001f4e1  Upload to PS5')
        self._ftptab_cancel_btn.pack_forget()
        if ok:
            self._ftptab_set_bar(100)
            self._ftptab_status_var.set('Upload complete \u2713')
            self._ftptab_log_write('\n[OK] Upload complete: ' + info + '\n')
            self._notify('FTP Upload complete', info)
        else:
            if 'Cancelled' in info:
                self._ftptab_status_var.set('Upload cancelled')
                self._ftptab_log_write('\n[CANCELLED] Upload cancelled by user\n')
            else:
                self._ftptab_status_var.set('Upload failed')
                self._ftptab_log_write('\n[ERROR] ' + info + '\n')
                messagebox.showerror('Upload failed', info)

    def _ftptab_log_write(self, text):
        self._ftptab_log.config(state='normal')
        self._ftptab_log.insert('end', text)
        self._ftptab_log.see('end')
        self._ftptab_log.config(state='disabled')

    def _ftptab_set_bar(self, pct):
        self._ftptab_pct = pct
        try:
            w = self._ftptab_canvas.winfo_width()
            fill_w = int(w * pct / 100)
            self._ftptab_canvas.coords(self._ftptab_bar, 0, 0, fill_w, 18)
            self._ftptab_canvas.itemconfig(
                self._ftptab_bar, fill=SUCCESS if pct >= 100 else ACCENT)
        except Exception:
            pass

    def _ftptab_start_upload(self):
        local = self._ftptab_local_var.get().strip()
        remote_dir = self._ftptab_remote_var.get().strip() or '/data/etaHEN/games/'
        is_folder  = self._ftptab_is_folder.get()

        if not local:
            messagebox.showwarning('Missing', 'Please select a file or folder to upload.')
            return
        if not os.path.exists(local):
            messagebox.showerror('Not found', 'Path not found:\n' + local)
            return
        ip = self._ftp_ip_var.get().strip()
        if not ip:
            messagebox.showwarning('No IP',
                'Enter your PS5 IP in the Build tab Settings → PS5 FTP UPLOAD.')
            return

        self._ftptab_cancel_flag = False
        self._ftptab_upload_btn.config(state='disabled', text='Uploading...')
        self._ftptab_cancel_btn.pack(side='left', padx=(8, 0))
        self._ftptab_status_var.set('Connecting...')
        self._ftptab_set_bar(0)
        self._ftptab_eta_var.set('')
        self._ftptab_log.config(state='normal')
        self._ftptab_log.delete('1.0', 'end')
        self._ftptab_log.config(state='disabled')
        self._ftptab_log_write('[FTP] ' + ('Folder' if is_folder else 'File') +
                                ': ' + local + '\n')
        self._ftptab_log_write('[FTP] Remote: ' + remote_dir + '\n\n')

        def worker():
            try:
                import ftplib
                ftp = self._ftp_connect()
                self.after(0, self._ftptab_status_var.set, 'Connected')

                def ensure_dir(ftp, path):
                    parts = path.strip('/').split('/')
                    cur = ''
                    for part in parts:
                        cur += '/' + part
                        try:
                            ftp.mkd(cur)
                        except Exception:
                            pass

                if is_folder:
                    # Count total files first
                    all_files = []
                    for root, dirs, files in os.walk(local):
                        for fn in files:
                            all_files.append(os.path.join(root, fn))
                    total_files = len(all_files)
                    total_bytes = sum(os.path.getsize(f) for f in all_files)
                    sent_bytes  = [0]
                    sent_files  = [0]
                    start_t     = time.time()
                    folder_name = os.path.basename(local.rstrip('\\/'))

                    self.after(0, self._ftptab_log_write,
                        '[FTP] %d files, %.2f GB total\n\n' % (
                            total_files, total_bytes / 1024**3))

                    for local_path in all_files:
                        if self._ftptab_cancel_flag:
                            raise Exception('Cancelled by user')
                        rel = os.path.relpath(local_path, os.path.dirname(local))
                        remote_path = (remote_dir.rstrip('/') + '/' +
                                       folder_name + '/' +
                                       rel.replace('\\', '/'))
                        remote_parent = '/'.join(remote_path.split('/')[:-1])
                        ensure_dir(ftp, remote_parent)
                        sz = os.path.getsize(local_path)
                        self.after(0, self._ftptab_log_write,
                            'Uploading: ' + os.path.basename(local_path) + '\n')

                        window = []
                        def prog(block, _sz=sz, _lp=local_path):
                            if self._ftptab_cancel_flag:
                                raise Exception('Cancelled')
                            sent_bytes[0] += len(block)
                            now = time.time()
                            window.append((now, sent_bytes[0]))
                            cutoff = now - 5.0
                            while len(window) > 1 and window[0][0] < cutoff:
                                window.pop(0)
                            dt = window[-1][0] - window[0][0]
                            db = window[-1][1] - window[0][1]
                            speed = (db / 1024 / 1024) / dt if dt > 0 else 0
                            pct = min(100, int(sent_bytes[0] / total_bytes * 100)) if total_bytes else 0
                            elapsed = now - start_t
                            rem_gb  = max(0, (total_bytes - sent_bytes[0]) / 1024**3)
                            eta_s   = (rem_gb * 1024 / speed) if speed > 0 else 0
                            eta_str = ('Almost done' if eta_s < 5 else
                                       'ETA: %dm %02ds' % (int(eta_s//60), int(eta_s%60)))
                            el_str  = 'Elapsed: %dm %02ds' % (int(elapsed//60), int(elapsed%60))
                            status  = ('%d/%d files  \u2022  %.2f GB sent  \u2022  '
                                       '%.1f MB/s  \u2022  %s' % (
                                           sent_files[0]+1, total_files,
                                           sent_bytes[0]/1024**3, speed, eta_str))
                            self.after(0, self._ftptab_status_var.set, status)
                            self.after(0, self._ftptab_eta_var.set, el_str)
                            self.after(0, self._ftptab_set_bar, pct)

                        with open(local_path, 'rb') as f:
                            ftp.storbinary('STOR ' + remote_path, f,
                                           blocksize=65536, callback=prog)
                        sent_files[0] += 1

                else:
                    # Single file upload
                    filename = os.path.basename(local)
                    remote_path = remote_dir.rstrip('/') + '/' + filename
                    ensure_dir(ftp, remote_dir)
                    file_size = os.path.getsize(local)
                    file_size_gb = file_size / 1024**3
                    self.after(0, self._ftptab_log_write,
                        '[FTP] Size: %.2f GB\n\n' % file_size_gb)
                    uploaded = [0]
                    start_t  = [time.time()]
                    window   = []
                    def prog(block):
                        if self._ftptab_cancel_flag:
                            raise Exception('Cancelled')
                        uploaded[0] += len(block)
                        now = time.time()
                        window.append((now, uploaded[0]))
                        cutoff = now - 5.0
                        while len(window) > 1 and window[0][0] < cutoff:
                            window.pop(0)
                        dt = window[-1][0] - window[0][0]
                        db = window[-1][1] - window[0][1]
                        speed = (db / 1024 / 1024) / dt if dt > 0 else 0
                        pct   = min(100, int(uploaded[0] / file_size * 100)) if file_size else 0
                        elapsed = now - start_t[0]
                        rem_gb  = max(0, (file_size - uploaded[0]) / 1024**3)
                        eta_s   = (rem_gb * 1024 / speed) if speed > 0 else 0
                        eta_str = ('Almost done' if eta_s < 5 else
                                   'ETA: %dm %02ds' % (int(eta_s//60), int(eta_s%60)))
                        el_str  = 'Elapsed: %dm %02ds' % (int(elapsed//60), int(elapsed%60))
                        status  = ('%.2f / %.2f GB  \u2022  %.1f MB/s  \u2022  %s' % (
                            uploaded[0]/1024**3, file_size_gb, speed, eta_str))
                        self.after(0, self._ftptab_status_var.set, status)
                        self.after(0, self._ftptab_eta_var.set, el_str)
                        self.after(0, self._ftptab_set_bar, pct)

                    with open(local, 'rb') as f:
                        ftp.storbinary('STOR ' + remote_path, f,
                                       blocksize=65536, callback=prog)

                ftp.quit()
                self.after(0, self._ftptab_done, True, remote_dir)

            except Exception as e:
                self.after(0, self._ftptab_done, False, str(e))

        threading.Thread(target=worker, daemon=True).start()

    def _ftptab_update_browse(self):
        if self._ftptab_is_folder.get():
            self._ftptab_local_lbl.config(text='Local folder')
        else:
            self._ftptab_local_lbl.config(text='Local file')

    def _get_cluster_size_arg(self):
        """Return cluster size in bytes, or '' for auto."""
        val = self._adv_cluster_var.get().strip()
        if val == 'Auto' or not val.isdigit():
            return ''
        return val

    def _get_folder_size(self, folder):
        total = 0
        try:
            stack = [folder]
            while stack:
                current = stack.pop()
                try:
                    with os.scandir(current) as it:
                        for entry in it:
                            try:
                                if entry.is_file(follow_symlinks=False):
                                    total += entry.stat(follow_symlinks=False).st_size
                                elif entry.is_dir(follow_symlinks=False):
                                    stack.append(entry.path)
                            except Exception:
                                pass
                except Exception:
                    pass
        except Exception:
            pass
        return total

    def _get_sector_size_arg(self):
        """Return sector size in bytes (512 or 4096)."""
        val = self._adv_sector_var.get().strip()
        return val if val in ('512', '4096') else '512'

    def _get_threads_arg(self):
        """Return robocopy thread count (1-128). Defaults to 8 on parse failure."""
        raw = self._adv_threads_var.get().strip()
        try:
            n = int(raw)
            return str(max(1, min(128, n)))
        except Exception:
            # Couldn't parse the value — fall back to a safe default and log it
            # so users can see why their copy speed differs from expectations.
            try:
                self._log('[WARN] Could not parse copy threads value '
                          + repr(raw) + ' — using default of 8.\n')
            except Exception:
                pass
            return '8'

    def _handle_line(self, line):
        # Clean carriage returns — robocopy uses \r for progress overwrites
        line = line.replace('\r', '\n').rstrip('\n') + '\n'
        # Skip lines that are just a bare percentage (robocopy progress noise)
        stripped = line.strip()
        if re.match(r'^\d{1,3}%$', stripped):
            return
        self._log(line)
        # Capture into the per-build ring buffer for failure diagnostics.
        # Trim very long lines so a runaway PowerShell error doesn't
        # blow out the buffer.
        try:
            tail = self._build_log_tail
            tail.append(line.rstrip('\n')[:500])
            if len(tail) > 80:
                del tail[:len(tail) - 80]
        except AttributeError:
            self._build_log_tail = [line.rstrip('\n')[:500]]
        # ── Parse robocopy file copy count from its output ──
        # Robocopy prints "   71\tFilename.ext" for each file copied
        # We can count these to get live file progress without os.walk
        robo_file_m = re.match(r'^\s*(\d+)\t', line.strip())
        if robo_file_m:
            self._robocopy_file_count = int(robo_file_m.group(1))
        # Also catch "Files :   71      ..." from summary
        robo_sum_m = re.search(r'Files\s*:\s*(\d+)\s+\d+', line)
        if robo_sum_m:
            self._robocopy_file_count = int(robo_sum_m.group(1))
        pct, extra, kind = self._parse_line(line)
        elapsed = time.time() - self._start_time if self._start_time else 0

        # ── Detect mounted drive letter from PS5 output ──
        if not self._mounted_drive:
            m = re.search(r'logical volume on ([A-Z]:)', line)
            if m:
                self._mounted_drive = m.group(1)

        # ── When copy phase starts, snapshot free space and begin polling ──
        if '[3/4]' in line and self._mounted_drive and self._drive_poll_id is None:
            try:
                usage = shutil.disk_usage(self._mounted_drive + '\\')
                self._image_total_gb  = usage.total / (1024 ** 3)
                self._copy_start_free = usage.free
                self._copy_start_time = time.time()
            except Exception:
                pass
            # Count source files in background so we know the target
            self._source_file_count = 0
            src = self._queue[self._current_build_idx].game_folder \
                if hasattr(self, '_current_build_idx') else None
            if src:
                def _count_src(folder=src):
                    n = sum(len(files) for _, _, files in os.walk(folder))
                    self._source_file_count = n
                threading.Thread(target=_count_src, daemon=True).start()
            self._start_drive_poll()

        if pct is not None:
            if kind == 'step':
                self._set_progress(pct, extra,
                    self._format_eta(elapsed, pct) if pct > 0 else '')
            elif kind == 'robo_eta':
                es = 'Elapsed: %dm %02ds' % (int(elapsed // 60), int(elapsed % 60))
                self._set_progress(pct, None,
                    es + '  \u2014  ' + extra if extra
                    else self._format_eta(elapsed, pct))
            else:
                self._set_progress(pct, None, self._format_eta(elapsed, pct))
        elif self._current_pct > 0 and self._start_time:
            self._eta_var.set(self._format_eta(elapsed, self._current_pct))
    def _history_path(self):
        return os.path.join(os.path.expanduser('~'), '.exfat_builder_history.json')

    def _item_done(self, returncode, idx, indices, pos, out_path):
        elapsed = time.time() - self._start_time if self._start_time else 0
        m, s = int(elapsed // 60), int(elapsed % 60)

        # Per-game elapsed time
        game_elapsed = time.time() - self._game_start_times.get(idx, time.time())
        gm, gs = int(game_elapsed // 60), int(game_elapsed % 60)

        if returncode == 0:
            self._update_queue_dot(idx, 'done')
            self._set_progress(100, 'Complete!',
                               'Game: %dm %02ds  •  Total: %dm %02ds' % (gm, gs, m, s))
            self._activate_dot(4)
            self._log('\n[OK] Done: ' + out_path +
                      ' (%dm %02ds)\n' % (gm, gs))
            self._save_history(self._queue[idx], out_path, True)
            # Write a per-build summary.json next to the .exfat. Records
            # provenance + settings so later you can verify a known-good
            # build matches a config or diagnose drift between similar
            # builds. Best-effort — failure here doesn't fail the build.
            try:
                self._write_build_summary(out_path, idx, game_elapsed)
            except Exception as _e:
                self._log('[WARN] Could not write summary.json: %s\n' % _e)
            # ── Verify image ──
            if self._adv_skip_verify_var.get():
                self._log('[VERIFY] Skipped (disabled in Advanced settings)\n')
                self._verify_done_final(True, 'Build complete (verification skipped)',
                                        idx, indices, pos, out_path)
            else:
                self._set_status('Verifying image...', ACCENT)
                self._log('[VERIFY] Checking image integrity...\n')
                src_folder = self._queue[idx].game_folder
                def do_verify():
                    ok, msg = self._verify_image(out_path, src_folder)
                    self.after(0, self._verify_done, ok, msg, idx, indices, pos, out_path)
                threading.Thread(target=do_verify, daemon=True).start()
        else:
            self._update_queue_dot(idx, 'failed')
            self._set_progress(self._current_pct, 'Failed', '')
            self._set_status('Build failed (exit code ' + str(returncode) + ')', DANGER)
            self._save_history(self._queue[idx], out_path, False)
            # ── Auto-retry ──
            retry_max = self._retry_var.get()
            item = self._queue[idx]
            retry_count = getattr(item, '_retry_count', 0)
            if retry_max > 0 and retry_count < retry_max:
                item._retry_count = retry_count + 1
                item.status = 'waiting'
                self._log('\n[RETRY] Attempt %d/%d for %s\n' % (
                    retry_count + 1, retry_max,
                    item.game_title or os.path.basename(item.game_folder)))
                self._set_status('Retrying (%d/%d)...' % (retry_count + 1, retry_max), WARNING)
                self._render_queue()
                self.after(2000, self._process_next, indices, pos)
            else:
                # Step 43 (v2.5.8): include the last few [ERROR]/[WARN]
                # lines from the build's stdout in the dialog so the
                # user can see WHY the build failed without expanding
                # the OUTPUT LOG drawer.
                err_excerpt = self._extract_failure_lines()
                msg = 'Build failed for:\n' + out_path
                if err_excerpt:
                    msg += '\n\nReason (from PowerShell):\n' + err_excerpt
                msg += '\n\nContinue with remaining items?'
                # v3.0.0: OUTPUT LOG no longer auto-opens. The error
                # dialog above carries the gist; the user can click
                # the OUTPUT LOG toggle for the full text.
                if messagebox.askyesno('Item failed', msg):
                    self._check_pause_then_next(indices, pos + 1)
                else:
                    self._building = False
                    self._pause_btn.config(state='disabled')
                    self.build_btn.config(state='normal', text='Build All')

    def _extract_failure_lines(self):
        """Pull the most relevant error lines out of the per-build log
        tail buffer for display in a failure dialog. Priority order:
          1. Lines matching [ERROR] or PowerShell throw patterns
          2. Lines matching [WARN]
          3. Last 5 lines of any content
        Returns a short multi-line string, or empty if nothing useful.
        """
        try:
            tail = getattr(self, '_build_log_tail', None) or []
            if not tail:
                return ''

            err_lines = []
            warn_lines = []
            for ln in tail:
                low = ln.lower()
                if ('[error]' in low or 'throw' in low.split() or
                        'exception' in low or 'is not recognized' in low or
                        'access denied' in low or
                        'access is denied' in low or
                        'cannot find' in low):
                    err_lines.append(ln.strip())
                elif '[warn]' in low or 'warning' in low:
                    warn_lines.append(ln.strip())

            # Prefer error lines (up to 6). If none, fall back to warn
            # lines, then to the last 5 lines of any content.
            picked = []
            if err_lines:
                picked = err_lines[-6:]
            elif warn_lines:
                picked = warn_lines[-4:]
            else:
                picked = [l.strip() for l in tail[-5:] if l.strip()]

            # De-dupe while preserving order
            seen = set()
            out = []
            for l in picked:
                if l and l not in seen:
                    seen.add(l)
                    out.append(l)
            return '\n'.join(out)
        except Exception:
            return ''

    def _item_error(self, msg, idx, indices, pos):
        self._update_queue_dot(idx, 'failed')
        self._set_status('Error: ' + msg, DANGER)
        if messagebox.askyesno('Error',
                'Error running make_image.bat:\n' + msg + '\n\nContinue?'):
            self._process_next(indices, pos + 1)
        else:
            self._building = False
            self.build_btn.config(state='normal', text='Build All')

    def _load_cover_art(self, folder):
        folder = os.path.normpath(folder)
        for p in [
            os.path.join(folder, 'sce_sys', 'icon0.png'),
            os.path.join(folder, 'icon0.png'),
        ]:
            if os.path.isfile(p):
                return p
        # Walk up to 4 levels deep — handles triple-nested DLPSGAME structure
        try:
            for root, dirs, files in os.walk(folder):
                dirs[:] = [d for d in dirs
                           if d.lower() not in ('decrypted', 'fakelib')]
                rel = os.path.relpath(root, folder)
                depth = 0 if rel == '.' else rel.count(os.sep) + 1
                if depth > 4:
                    dirs[:] = []
                    continue
                if 'icon0.png' in files:
                    return os.path.join(root, 'icon0.png')
        except Exception:
            pass
        return None

    def _multi_add_confirm(self, folders, skipped, odir):
        if not folders:
            messagebox.showwarning('No games found',
                'No valid PS5 game folders found.\n\n'
                'Make sure the folder you selected contains '
                'game dump subfolders with eboot.bin inside.')
            self._set_status('No game folders found', WARNING)
            return

        msg = 'Found %d game folder(s) to add:\n\n' % len(folders)
        for f in folders[:10]:
            msg += '  \u2022 ' + os.path.basename(f) + '\n'
        if len(folders) > 10:
            msg += '  ... and %d more\n' % (len(folders) - 10)
        if skipped:
            msg += '\n%d folder(s) skipped (no game data or already queued)' % len(skipped)
        msg += '\n\nOutput directory: ' + odir
        msg += '\n\nAdd all to queue?'

        if not messagebox.askyesno('Add multiple games', msg):
            return

        added = 0
        for folder in folders:
            title, title_id, version = get_game_info(folder)
            if not title_id:
                m = re.search(r'((?:PPSA|CUSA|PPLH)\d{5})',
                              os.path.basename(folder), re.IGNORECASE)
                if m:
                    title_id = m.group(1).upper()
            name = build_exfat_name(title or None, title_id or None, version or None)
            item = QueueItem(folder, odir, name, title, title_id, version)
            self._queue.append(item)
            self._add_to_recent(folder)
            added += 1

        self._render_queue()
        self._set_status('Added %d game(s) to queue' % added, SUCCESS)
        messagebox.showinfo('Added to queue',
            '%d game(s) added to the build queue.\n\n'
            'Click Build All to start.' % added)

    def _on_bar_resize(self, event):
        self._bar_width = event.width
        self._update_bar_visual(self._current_pct)

    def _on_drop(self, data):
        # Strip braces that tkinterdnd2 adds around paths with spaces
        path = data.strip('{}').strip('"').strip()
        if os.path.isdir(path):
            # Step 42 (v2.5.8): descend into wrapper folders if needed.
            resolved = self._resolve_game_root(path)
            if os.path.normpath(resolved) != os.path.normpath(path):
                self._log('[INFO] Dropped folder had no eboot.bin; '
                          'descended to: %s\n' % resolved)
                path = resolved
            self.game_folder.set(path)
            self._detect_game_info(path)

    def _on_queue_drop(self, event):
        paths = event.data.strip()
        # tkinterdnd2 may wrap multiple paths in braces
        import re as _re
        items = _re.findall(r'\{([^}]+)\}|(\S+)', paths)
        folders = [a or b for a, b in items]
        if not folders:
            folders = [paths.strip('{}')]
        for folder in folders:
            folder = folder.strip()
            if os.path.isdir(folder):
                # Step 42 (v2.5.8): auto-descend wrapper folders.
                resolved = self._resolve_game_root(folder)
                if os.path.normpath(resolved) != os.path.normpath(folder):
                    self._log('[INFO] Dropped folder had no eboot.bin; '
                              'descended to: %s\n' % resolved)
                    folder = resolved
                self.game_folder.set(folder)
                self._detect_game_info(folder)
                self._add_to_queue()

    # ── Build history ──────────────────────────────────────────────────────────
    def _parse_line(self, line):
        m = re.search(r'\[(\d)/4\]', line)
        if m:
            key = m.group(1) + '/4'
            if key in STEPS:
                lo, hi, label = STEPS[key]
                self._activate_dot(int(m.group(1)) - 1)
                return lo, label, 'step'
        m = re.search(r'(\d{1,3})%', line)
        if m:
            robo_pct = int(m.group(1))
            lo, hi, _ = STEPS['3/4']
            mapped = lo + (hi - lo) * robo_pct / 100.0
            eta_m = re.search(r'(\d+):(\d{2}):(\d{2})', line)
            if eta_m:
                h, mn, sc = int(eta_m.group(1)), int(eta_m.group(2)), int(eta_m.group(3))
                total = h * 3600 + mn * 60 + sc
                eta = 'Almost done' if total < 5 else (
                    'ETA: %dh %02dm %02ds' % (h, mn, sc) if h
                    else 'ETA: %dm %02ds' % (mn, sc))
                return mapped, eta, 'robo_eta'
            return mapped, None, 'robo'
        return None, None, None

    # ── Build ─────────────────────────────────────────────────────────────────
    def _process_next(self, indices, pos):
        if pos >= len(indices):
            self._building = False
            self._pause_after_current = False
            self.build_btn.config(state='normal', text='Build All')
            self._pause_btn.config(state='disabled', text='⏸ Pause',
                                   bg=WARNING, fg='#000000')
            self._set_status(
                'All done!  \u2713  ' + str(len(indices)) + ' image(s) built', SUCCESS)
            self._refresh_temp_size()
            self._trigger_shutdown('exfat')  # launch countdown
            # Only show blocking messagebox if no shutdown is scheduled
            _sd_action = self._settings.get('shutdown_action', 'none')
            _sd_on_exfat = self._settings.get('shutdown_on_exfat', False)
            if _sd_action == 'none' or not _sd_on_exfat:
                messagebox.showinfo('Complete',
                    str(len(indices)) + ' image(s) built successfully!')
        idx  = indices[pos]
        item = self._queue[idx]
        self._update_queue_dot(idx, 'building')
        self.after(0, self._update_queue_total_eta, idx, indices)
        self._game_start_times[idx] = time.time()  # track per-game start time
        out_path = os.path.join(item.output_dir, item.output_name)
        # Pass custom OSFMount path so the PS1 script can find it
        osf_path     = self._find_osfmount() or ''
        cluster_arg  = self._get_cluster_size_arg()
        sector_arg   = self._get_sector_size_arg()
        threads_arg  = self._get_threads_arg()
        retries_arg  = self._adv_retries_var.get().strip() or '3'
        rwait_arg    = self._adv_retry_wait_var.get().strip() or '3'
        excl_hidden  = '1' if self._adv_excl_hidden_var.get() else '0'
        img_override = self._adv_img_size_var.get().strip()
        cmd = ('"' + self._bat_path + '" "' + out_path + '" "'
               + item.game_folder + '" "' + osf_path + '" "'
               + cluster_arg + '" "' + sector_arg + '" "' + threads_arg
               + '" "' + retries_arg + '" "' + rwait_arg + '" "' + excl_hidden
               + '" "' + img_override + '"')

        # Pre-flight: re-extract scripts if the temp dir was wiped.
        # Windows Storage Sense, antivirus quarantines, and long-running
        # sessions can all delete %TEMP%\exfat_builder_xxxxx between
        # app launch and Build click. Without this check, subprocess.Popen
        # fails with "WinError 267 - The directory name is invalid"
        # because cwd=bat_dir points at a folder that no longer exists.
        try:
            if not os.path.isfile(self._bat_path):
                self._log('[INFO] Script temp dir missing - re-extracting...\n')
                custom_temp = self._settings.get('temp_dir') or None
                self._bat_path, _ico_path = extract_scripts(custom_temp)
                self._log('[INFO] Scripts re-extracted to: %s\n'
                          % os.path.dirname(self._bat_path))
                # Rebuild the cmd string with the new path
                cmd = ('"' + self._bat_path + '" "' + out_path + '" "'
                       + item.game_folder + '" "' + osf_path + '" "'
                       + cluster_arg + '" "' + sector_arg + '" "' + threads_arg
                       + '" "' + retries_arg + '" "' + rwait_arg + '" "' + excl_hidden
                       + '" "' + img_override + '"')
        except Exception as _e:
            self._log('[ERROR] Could not re-extract scripts: %r\n' % _e)
            # Let the Popen below fail with its native error; we tried.

        bat_dir = os.path.dirname(self._bat_path)
        total   = len(indices)
        display = item.game_title or os.path.basename(item.game_folder)
        label   = 'Building %d/%d: %s' % (pos + 1, total, display)
        self._set_progress(0, label, '')
        self._activate_dot(-1)
        self._start_time = time.time()
        self._set_status(label, ACCENT)
        self._log_clear()
        self._log('[' + str(pos + 1) + '/' + str(total) + '] ' + cmd + '\n\n')
        os.makedirs(os.path.dirname(out_path), exist_ok=True)

        self._current_build_idx = idx
        self._source_file_count = 0
        # Step 44 (v2.5.8): also reset the live file counter. Without
        # this, the value lingers from the previous build's final
        # robocopy summary, producing nonsensical readouts like
        # "22,364 / 48 files copied" on the second game in a queue
        # (where 22,364 was the last game's total).
        self._robocopy_file_count = 0
        # Step 45 (v2.5.8): live destination-file count, updated
        # every ~5s by a background walk of the mounted drive while
        # robocopy runs. Gives users a real "X / Y files copied"
        # readout without /NFL having to spew thousands of lines.
        self._dest_file_count     = 0
        self._dest_walk_last_ts   = 0.0
        self._dest_walk_running   = False
        # Reset drive tracking for this build
        self._mounted_drive   = None   # e.g. 'E:'
        self._image_total_gb  = None   # total capacity of mounted image
        self._drive_poll_id   = None   # after() id for polling
        self._copy_start_free = None   # free space at copy start (to derive written)
        self._copy_start_time = None
        self._poll_window     = []
        # Step 43 (v2.5.8): ring buffer of recent stdout lines so we can
        # surface the actual error reason in the "Item failed" dialog
        # instead of just saying "Build failed for: <path>". Without
        # this, users had to expand the OUTPUT LOG drawer and dig
        # through it to find what went wrong.
        self._build_log_tail = []

        def worker():
            try:
                # ── Pre-flight scan ──
                # Walks the source ONCE in this worker thread before
                # invoking the BAT. Catches the common failure modes for
                # huge games (200k files / 120GB+) up front so the user
                # gets a clear error instead of a mysterious BAT failure
                # 10 minutes in:
                #   - source missing / no eboot.bin
                #   - output drive free space < image needs
                #   - extreme file counts (>500k)
                #   - extreme path length (>248 chars)
                # Also surfaces enumeration progress to the OUTPUT LOG
                # so users on slow disks can see something is happening.
                preflight = self._preflight_source(item.game_folder,
                                                    out_path)
                if not preflight.get('ok'):
                    err_msg = preflight.get('error',
                                            'pre-flight scan failed')
                    self.after(0, self._item_error, err_msg,
                               idx, indices, pos)
                    return

                # Build env with EXFAT_SCRIPT_DIR so the bat can find
                # its PS1 even when %~dp0 ends up empty (some elevated
                # contexts + non-Latin Windows installs do this).
                build_env = os.environ.copy()
                build_env['EXFAT_SCRIPT_DIR'] = bat_dir
                # IMGSIZEGB override is also injected via env so we don't
                # need a 12th positional arg to the bat
                if img_override:
                    build_env['EXFAT_IMGSIZEGB'] = img_override

                # Encoding: 'mbcs' decodes using the system's active
                # ANSI code page (CP1252 in the West, CP949 in Korea,
                # CP932 in Japan, etc.) which matches what cmd.exe
                # actually writes to its console. Forcing UTF-8 here
                # used to lose non-Latin path characters and produced
                # blank "PS1 not found at:" messages with the path
                # mangled away.
                _enc = 'mbcs' if sys.platform.startswith('win') else 'utf-8'
                try:
                    proc = subprocess.Popen(
                        cmd, shell=True, cwd=bat_dir,
                        stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                        text=True, encoding=_enc, errors='replace',
                        env=build_env,
                        creationflags=_NO_WIN_FLAGS)
                except OSError as _oe:
                    # Most common cases:
                    #   WinError 267: cwd doesn't exist (temp wiped)
                    #   WinError 2:   bat itself doesn't exist
                    #   WinError 5:   access denied (AV intervened)
                    # Re-raise with enough context for the user dialog.
                    raise RuntimeError(
                        '%s\n\n'
                        'Script path: %s\n'
                        'Working dir: %s\n\n'
                        'This usually means the temporary scripts folder '
                        'was deleted by Windows or antivirus. '
                        'Restarting the app will re-extract them.'
                        % (_oe, self._bat_path, bat_dir))
                for line in proc.stdout:
                    self.after(0, self._handle_line, line)
                proc.wait()

                # ── Post-process dismount safety net ──
                # The PS1 script dismounts internally, but in practice
                # Windows often keeps the drive letter alive briefly
                # (Defender / Windows Search scanning, our own drive
                # poll loop holding handles, etc.). The robust dismount
                # helper does:
                #   - stop our drive-poll loop FIRST (releases our handles)
                #   - osfmount -D (force) x3
                #   - osfmount -d x3
                #   - mountvol /D
                #   - FSCTL_LOCK_VOLUME + FSCTL_DISMOUNT_VOLUME
                # with up to ~30s total budget — long enough for
                # Defender's post-copy scan to settle.
                mounted = self._mounted_drive
                if mounted:
                    # CRITICAL: kill our drive-poll loop before attempting
                    # dismount. The poll holds a Win32 handle on the
                    # drive via shutil.disk_usage — that handle blocks
                    # FSCTL_LOCK_VOLUME and contributes to the spurious
                    # dismount failures users hit.
                    try:
                        self.after(0, self._stop_drive_poll)
                    except Exception:
                        pass
                    time.sleep(0.5)  # let the after() actually run

                    letter = mounted.rstrip(':\\').upper()[:1]
                    if letter:
                        ok = self._dismount_drive_robust(
                            letter, max_wait_seconds=30)
                        if ok:
                            self.after(0, self._log,
                                '[DISMOUNT] ' + mounted +
                                ' dismounted cleanly.\n')
                        else:
                            self.after(0, self._log,
                                '[WARN] Drive ' + mounted +
                                ' could not be dismounted after 30s. '
                                'You can use the Force Dismount '
                                'button to retry.\n')

                self.after(0, self._stop_drive_poll)
                self.after(0, self._item_done,
                           proc.returncode, idx, indices, pos, out_path)
            except Exception as ex:
                self.after(0, self._stop_drive_poll)
                self.after(0, self._item_error, str(ex), idx, indices, pos)

        threading.Thread(target=worker, daemon=True).start()

    def _refresh_temp_size(self):
        base = self._settings.get('temp_dir') or tempfile.gettempdir()
        total_size = 0
        count = 0
        try:
            for entry in os.scandir(base):
                if entry.name.startswith('exfat_builder_') and entry.is_dir():
                    count += 1
                    for root, dirs, files in os.walk(entry.path):
                        for fn in files:
                            try:
                                total_size += os.path.getsize(
                                    os.path.join(root, fn))
                            except Exception:
                                pass
        except Exception:
            pass
        location = self._settings.get('temp_dir') or 'System temp'
        if not hasattr(self, '_temp_size_var'):
            return
        if count > 0:
            mb = total_size / (1024 * 1024)
            self._temp_size_var.set(
                location + '  —  ' + str(count) +
                ' folder(s), %.1f MB used' % mb)
            if hasattr(self, '_temp_size_lbl'):
                self._temp_size_lbl.config(fg=WARNING if mb > 500 else MUTED)
            if hasattr(self, '_temp_usage_lbl'):
                self._temp_usage_lbl.config(
                    text='%.1f MB in %d temp folder(s)' % (mb, count),
                    fg=WARNING if mb > 500 else MUTED)
        else:
            self._temp_size_var.set(location + '  —  No temp files')
            if hasattr(self, '_temp_size_lbl'):
                self._temp_size_lbl.config(fg=MUTED)
            if hasattr(self, '_temp_usage_lbl'):
                self._temp_usage_lbl.config(text='No temp files', fg=MUTED)

    # ── Field helper ─────────────────────────────────────────────────────────
    def _remove_queue_item(self, index):
        if 0 <= index < len(self._queue):
            del self._queue[index]
            self._render_queue()

    def _move_queue_item(self, src_idx, dst_idx):
        """Swap two queue items by index — used by the right-click
        Move up / Move down menu items."""
        if 0 <= src_idx < len(self._queue) and 0 <= dst_idx < len(self._queue):
            self._queue[src_idx], self._queue[dst_idx] = (
                self._queue[dst_idx], self._queue[src_idx])
            self._render_queue()

    def _clip_set(self, text):
        """Put text on the clipboard with a brief status confirmation.
        Used by the queue context menu's Copy ... path entries so the
        user gets feedback instead of a silent no-op."""
        try:
            self.clipboard_clear()
            self.clipboard_append(text)
            # Force the X selection to flush so other apps see it
            self.update()
            try:
                self._set_status('Copied to clipboard: ' + text, ACCENT)
            except Exception:
                pass
        except Exception as _e:
            try:
                self._set_status('Could not copy to clipboard: %s' % _e, DANGER)
            except Exception:
                pass

    def _reveal_in_explorer(self, path):
        """Open the host file manager with the given file pre-selected.
        On Windows that's `explorer /select,<path>`. On other OSes we
        fall back to opening the containing folder."""
        try:
            if sys.platform.startswith('win'):
                subprocess.Popen(['explorer', '/select,', os.path.normpath(path)])
            elif sys.platform == 'darwin':
                subprocess.Popen(['open', '-R', path])
            else:
                # Linux file managers don't have a portable "reveal" — fall
                # back to opening the folder
                folder = os.path.dirname(path) or '.'
                subprocess.Popen(['xdg-open', folder])
        except Exception as _e:
            try:
                self._set_status('Could not reveal: %s' % _e, DANGER)
            except Exception:
                pass

    def _render_queue(self):
        for w in self._queue_frame.winfo_children():
            w.destroy()
        self._queue_count_var.set(str(len(self._queue)) + ' items')
        if not self._queue:
            tk.Label(self._queue_frame,
                     text='No items yet  \u2014  add a game above',
                     font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                     pady=14).pack()
            return
        for i, item in enumerate(self._queue):
            row_bg = QUEUE_ODD if i % 2 == 0 else QUEUE_EVEN
            row = tk.Frame(self._queue_frame, bg=row_bg)
            row.pack(fill='x')
            dot_color = {'waiting': MUTED, 'building': ACCENT,
                         'done': SUCCESS, 'failed': DANGER}.get(item.status, MUTED)
            dot = tk.Canvas(row, width=10, height=10, bg=row_bg,
                            highlightthickness=0)
            dot.pack(side='left', padx=(10, 6), pady=9)
            dot.create_oval(1, 1, 9, 9, fill=dot_color, outline='')
            display = item.game_title or os.path.basename(item.game_folder)
            if item.version:
                display += '  v' + item.version
            # Status badge for done/failed
            if item.status == 'done':
                tk.Label(row, text='\u2713', font=('Segoe UI', 9),
                         bg=row_bg, fg=SUCCESS).pack(side='left', padx=(0, 4))
            elif item.status == 'failed':
                tk.Label(row, text='\u2717', font=('Segoe UI', 9),
                         bg=row_bg, fg=DANGER).pack(side='left', padx=(0, 4))
            tk.Label(row, text=display, font=('Segoe UI', 9, 'bold'),
                     bg=row_bg, fg=TEXT, anchor='w').pack(side='left')
            tk.Label(row, text='  \u2192  ' + item.output_name,
                     font=('Consolas', 8), bg=row_bg, fg=INFO_FG,
                     anchor='w').pack(side='left')
            tk.Label(row, text=item.output_dir,
                     font=('Segoe UI', 8), bg=row_bg, fg=MUTED,
                     anchor='w').pack(side='left', padx=(6, 0), fill='x', expand=True)
            idx = i
            # Open output folder button (only when done)
            if item.status == 'done':
                out_path = os.path.join(item.output_dir, item.output_name)
                tk.Button(row, text='\U0001f4c2', font=('Segoe UI', 10),
                          bg=row_bg, fg=MUTED,
                          activebackground=row_bg, activeforeground=TEXT,
                          relief='flat', bd=0, padx=6, pady=4,
                          cursor='hand2',
                          command=lambda p=item.output_dir: self._open_folder(p)
                          ).pack(side='right', padx=(0, 2))
                # Upload to PS5 button
                tk.Button(row, text='\u2191 PS5', font=('Segoe UI', 8),
                          bg=row_bg, fg=ACCENT,
                          activebackground=row_bg, activeforeground=ACCENT,
                          relief='flat', bd=0, padx=6, pady=4,
                          cursor='hand2',
                          command=lambda p=out_path: self._ftp_upload_file(p)
                          ).pack(side='right', padx=(0, 2))
            tk.Button(row, text='\u00d7', font=('Segoe UI', 10),
                      bg=row_bg, fg=DANGER,
                      activebackground=row_bg, activeforeground=DANGER,
                      relief='flat', bd=0, padx=8, pady=4,
                      cursor='hand2',
                      command=lambda ix=idx: self._remove_queue_item(ix)
                      ).pack(side='right', padx=(0, 4))
            # Right-click context menu
            def _show_ctx(event, it=item, ix=idx):
                menu = tk.Menu(self, tearoff=0, bg=SURFACE2, fg=TEXT,
                               activebackground=ACCENT, activeforeground=TEXT,
                               font=('Segoe UI', 9))
                menu.add_command(label='\U0001f4c2  Open source folder',
                    command=lambda: self._open_folder(it.game_folder))
                menu.add_command(label='\U0001f4c2  Open output folder',
                    command=lambda: self._open_folder(it.output_dir))
                if it.status in ('waiting', 'failed'):
                    menu.add_separator()
                    menu.add_command(label='\u25b6  Build this item',
                        command=lambda: self._build_single(ix))
                if it.status == 'done':
                    out_path = os.path.join(it.output_dir, it.output_name)
                    menu.add_separator()
                    menu.add_command(label='\U0001f4be  Reveal .exfat in Explorer',
                        command=lambda: self._reveal_in_explorer(out_path))
                    menu.add_command(label='\u2191  Upload to PS5',
                        command=lambda: self._ftp_upload_file(out_path))
                # Move up / down — only show if more than one item
                if len(self._queue) > 1:
                    menu.add_separator()
                    if ix > 0:
                        menu.add_command(label='\u2191  Move up',
                            command=lambda: self._move_queue_item(ix, ix - 1))
                    if ix < len(self._queue) - 1:
                        menu.add_command(label='\u2193  Move down',
                            command=lambda: self._move_queue_item(ix, ix + 1))
                # Copy paths — convenience for sharing paths in bug reports
                menu.add_separator()
                menu.add_command(label='\U0001f4cb  Copy source path',
                    command=lambda: self._clip_set(it.game_folder))
                menu.add_command(label='\U0001f4cb  Copy output path',
                    command=lambda: self._clip_set(
                        os.path.join(it.output_dir, it.output_name)))
                menu.add_separator()
                menu.add_command(label='\u2717  Remove from queue',
                    command=lambda: self._remove_queue_item(ix))
                menu.tk_popup(event.x_root, event.y_root)
            row.bind('<Button-3>', _show_ctx)
            for child in row.winfo_children():
                child.bind('<Button-3>', _show_ctx)

    def _resume_queue(self):
        """Resume a paused queue."""
        self._building = True
        self._pause_after_current = False
        self._pause_btn.config(text='⏸ Pause', bg=WARNING, fg='#000000',
                               command=self._toggle_pause_queue)
        self._set_status('▶ Resumed', SUCCESS)
        self._process_next(self._paused_indices, self._paused_pos)

    def _run_extract(self):
        img_path = self._extract_file_var.get().strip()
        out_dir  = self._extract_outdir_var.get().strip()
        out_name = self._extract_name_var.get().strip()

        if not img_path:
            messagebox.showwarning('Missing', 'Please select an exFAT image file.')
            return
        if not os.path.isfile(img_path):
            messagebox.showerror('Not found', 'Image file not found:\n' + img_path)
            return
        if not out_dir:
            messagebox.showwarning('Missing', 'Please select an output directory.')
            return
        if not out_name:
            out_name = os.path.splitext(os.path.basename(img_path))[0]
            self._extract_name_var.set(out_name)

        dest_folder = os.path.join(out_dir, out_name)
        if os.path.exists(dest_folder):
            if not messagebox.askyesno('Folder exists',
                    'Output folder already exists:\n' + dest_folder +
                    '\n\nFiles will be merged/overwritten. Continue?'):
                return

        self._extract_btn.config(state='disabled', text='Extracting...')
        self._extract_status_var.set('Starting...')
        self._update_extract_bar(0)
        self._extract_eta_var.set('')
        self._elog_clear()
        self._elog('[EXTRACT] Image: ' + img_path + '\n')
        self._elog('[EXTRACT] Destination: ' + dest_folder + '\n\n')

        # Find OSFMount — defer to the canonical _find_osfmount() so
        # Extract honours the path saved in Settings, registry entries,
        # and OSFMount v3+ (which ships only OSFMount.exe). Step 48
        # (v2.6.1): the old hardcoded three-path scan rejected installs
        # outside Program Files and the modern .exe-only layout.
        osf = self._find_osfmount()
        if not osf:
            messagebox.showerror('OSFMount not found',
                'Could not find OSFMount.\n'
                'Please install OSFMount from:\n'
                'https://www.osforensics.com/tools/mount-disk-images.html\n\n'
                'Or set the path manually in Settings → OSFMount.')
            self._extract_btn.config(state='normal', text='\U0001f4e4  Extract Image')
            return

        start_time = [time.time()]
        mount_point = [None]

        def worker():
            try:
                os.makedirs(dest_folder, exist_ok=True)

                # Find free drive letter
                import ctypes as _ct
                drives_bitmask = _ct.windll.kernel32.GetLogicalDrives()
                free_letter = None
                for i in range(25, 3, -1):  # Z: down to D:
                    if not (drives_bitmask & (1 << i)):
                        free_letter = chr(65 + i) + ':'
                        break
                if not free_letter:
                    raise Exception('No free drive letters available')

                mount_point[0] = free_letter
                self.after(0, self._elog,
                    '[EXTRACT] Mounting image on ' + free_letter + '...\n')
                self.after(0, self._extract_status_var.set, 'Mounting image...')

                # Mount read-only
                result = subprocess.run(
                    [osf, '-a', '-t', 'file', '-f', img_path,
                     '-m', free_letter, '-o', 'ro,rem'],
                    capture_output=True, text=True,
                    creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())
                if result.returncode != 0:
                    raise Exception('Mount failed: ' + result.stderr + result.stdout)

                # Wait for drive to appear
                import time as _t
                for _ in range(20):
                    if os.path.exists(free_letter + '\\'):
                        break
                    _t.sleep(0.5)
                else:
                    raise Exception('Mounted drive did not appear in time')

                self.after(0, self._elog, '[EXTRACT] Mounted. Copying files...\n')
                self.after(0, self._extract_status_var.set, 'Copying files...')

                # Get total size for progress
                total_bytes = [0]
                for root, dirs, files in os.walk(free_letter + '\\'):
                    for fn in files:
                        try:
                            total_bytes[0] += os.path.getsize(os.path.join(root, fn))
                        except Exception:
                            pass

                self.after(0, self._elog,
                    '[EXTRACT] Total: %.2f GB to copy\n' % (total_bytes[0] / 1024**3))

                # Copy using robocopy for reliability
                robo_cmd = [
                    'robocopy.exe',
                    free_letter + '\\', dest_folder,
                    '/E', '/COPY:DAT', '/DCOPY:DAT',
                    '/R:1', '/W:1', '/NP', '/ETA'
                ]
                proc = subprocess.Popen(
                    robo_cmd,
                    stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                    text=True, encoding='utf-8', errors='replace',
                    creationflags=_NO_WIN_FLAGS)

                copied_bytes = [0]
                for line in proc.stdout:
                    self.after(0, self._elog, line)
                    # Parse robocopy progress
                    m = re.search(r'(\d{1,3})%', line)
                    if m:
                        pct = int(m.group(1))
                        elapsed = time.time() - start_time[0]
                        remaining = max(0, (elapsed / (pct/100.0)) - elapsed) if pct > 0 else 0
                        eta = ('ETA: %dm %02ds' % (int(remaining//60), int(remaining%60))
                               if remaining > 5 else 'Almost done')
                        elapsed_str = 'Elapsed: %dm %02ds' % (int(elapsed//60), int(elapsed%60))
                        self.after(0, self._update_extract_bar, pct)
                        self.after(0, self._extract_eta_var.set,
                                   elapsed_str + '  \u2014  ' + eta)
                proc.wait()

                # Dismount
                self.after(0, self._elog, '\n[EXTRACT] Dismounting...\n')
                subprocess.run([osf, '-d', '-m', free_letter],
                               capture_output=True,
                               creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())
                mount_point[0] = None

                elapsed = time.time() - start_time[0]
                m, s = int(elapsed//60), int(elapsed%60)
                self.after(0, self._extract_done, True, dest_folder, m, s)

            except Exception as e:
                # Try to dismount on error
                if mount_point[0]:
                    try:
                        subprocess.run([osf, '-d', '-m', mount_point[0]],
                                       capture_output=True,
                                       creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())
                    except Exception:
                        pass
                self.after(0, self._extract_done, False, str(e), 0, 0)

        threading.Thread(target=worker, daemon=True).start()

    def _run_queue(self):
        if self._building:
            return
        if not self._queue:
            messagebox.showwarning('Empty queue',
                'Add at least one game to the queue first.')
            return
        waiting = [i for i, q in enumerate(self._queue) if q.status == 'waiting']
        if not waiting:
            messagebox.showinfo('All done',
                'All queued items have already been built.')
            return

        # ── Pre-build checklist ──
        issues = []
        # 1. OSFMount installed?
        osf = self._find_osfmount()
        if not osf:
            issues.append('OSFMount is not installed — required for building images.')
        # 2. Per-item checks
        for i in waiting:
            item = self._queue[i]
            label = item.game_title or os.path.basename(item.game_folder)
            # eboot.bin present?
            eboot = os.path.join(item.game_folder, 'eboot.bin')
            if not os.path.isfile(eboot):
                issues.append(label + ': eboot.bin not found in source folder')
            # Output dir same as or inside game folder? Robocopy will try to
            # copy the growing image into itself causing out of space errors
            norm_out  = os.path.normpath(item.output_dir).lower()
            norm_game = os.path.normpath(item.game_folder).lower()
            if norm_out == norm_game or norm_out.startswith(norm_game + os.sep):
                issues.append(label + ': output directory is the same as (or inside) '
                    'the game source folder — the image will be copied into itself. '
                    'Choose a different output folder.')

            # Output dir is drive root? (C:\ etc — Windows blocks writes there)
            out_dir = item.output_dir.rstrip('\\/') 
            if len(out_dir) <= 3 and out_dir[1:2] == ':':
                issues.append(label + ': output directory is a drive root ('
                    + item.output_dir + '). Windows may block writing here. '
                    'Use a subfolder e.g. ' + out_dir + '\\PS5Images')
            # Can we write to the output directory?
            else:
                try:
                    test_file = os.path.join(item.output_dir, '.write_test')
                    with open(test_file, 'w') as tf:
                        tf.write('test')
                    os.remove(test_file)
                except Exception:
                    issues.append(label + ': cannot write to output directory — '
                        'check permissions: ' + item.output_dir)
            # output drive space?
            try:
                free = shutil.disk_usage(item.output_dir).free
                needed = self._get_folder_size(item.game_folder) * 1.05
                if needed > 0 and free < needed:
                    issues.append(label + ': output drive low on space '
                        '(need %.1f GB, have %.1f GB)' % (needed/1024**3, free/1024**3))
            except Exception:
                pass
            # image already exists?
            out_path = os.path.join(item.output_dir, item.output_name)
            if os.path.isfile(out_path):
                issues.append(label + ': output file already exists — will be overwritten')

        if issues:
            msg = 'Pre-build checklist found the following:\n\n'
            msg += '\n'.join('\u2022 ' + s for s in issues)
            msg += '\n\nContinue anyway?'
            if not messagebox.askyesno('Pre-build checklist', msg):
                return

        # ── Estimated total time ──
        total_gb = sum(
            self._get_folder_size(self._queue[i].game_folder) / 1024**3
            for i in waiting)
        # Rough estimate: ~300 MB/s copy speed average on most systems
        est_secs = int((total_gb * 1024) / 300) if total_gb > 0 else 0
        # Add ~30s overhead per game for mount/format/dismount
        est_secs += len(waiting) * 30
        if est_secs > 0:
            if est_secs < 60:
                est_str = '%ds' % est_secs
            elif est_secs < 3600:
                est_str = '%dm %02ds' % (est_secs // 60, est_secs % 60)
            else:
                est_str = '%dh %02dm' % (est_secs // 3600, (est_secs % 3600) // 60)
            msg = ('Build All — %d game(s)  •  %.1f GB total\n\n'
                   'Estimated time: ~%s\n\n'
                   'Start building?' % (len(waiting), total_gb, est_str))
            if not messagebox.askyesno('Ready to build', msg):
                return

        self._building = True
        self._pause_after_current = False
        self._game_start_times = {}
        self._pause_btn.config(state='normal', text='⏸ Pause',
                               bg=WARNING, fg='#000000')
        self.build_btn.config(state='disabled', text='Building...')
        self._process_next(waiting, 0)

    def _save_adv_params(self):
        self._settings['adv_cluster'] = self._adv_cluster_var.get()
        self._settings['adv_sector']  = self._adv_sector_var.get()
        self._settings['adv_threads'] = self._adv_threads_var.get()
        self._settings['adv_ffpkg_block']   = self._adv_ffpkg_block_var.get()
        self._settings['adv_ffpkg_frag']    = self._adv_ffpkg_frag_var.get()
        self._settings['adv_ffpkg_minfree'] = self._adv_ffpkg_minfree_var.get()
        self._settings['adv_ffpkg_inode']   = self._adv_ffpkg_inode_var.get()
        self._settings['adv_retries']       = self._adv_retries_var.get()
        self._settings['adv_retry_wait']    = self._adv_retry_wait_var.get()
        self._settings['adv_skip_verify']   = self._adv_skip_verify_var.get()
        self._settings['lowercase_names']   = self._lowercase_names_var.get()
        self._settings['adv_excl_hidden']   = self._adv_excl_hidden_var.get()
        save_settings(self._settings)

    def _save_history(self, item, out_path, success):
        try:
            try:
                with open(self._history_path(), 'r') as f:
                    history = json.load(f)
            except Exception:
                history = []
            history.insert(0, {
                'title':    item.game_title or os.path.basename(item.game_folder),
                'title_id': item.title_id or '',
                'version':  item.version or '',
                'folder':   item.game_folder or '',
                'output':   out_path,
                'success':  success,
                'time':     time.strftime('%Y-%m-%d %H:%M:%S'),
            })
            history = history[:50]  # keep last 50
            with open(self._history_path(), 'w') as f:
                json.dump(history, f, indent=2)
        except Exception:
            pass

    def _write_build_summary(self, out_path, idx, game_elapsed):
        """Write a summary.json sidecar next to the .exfat after each
        successful build. Records build provenance: source path, output
        size, settings used, duration, timestamp, app version, and a
        partial hash. Useful for verifying provenance, debugging drift
        between similar builds, and submitting bug reports.

        Hash strategy: sha256 of first 1 MiB + last 1 MiB of the .exfat,
        not the full file. Hashing an 80 GB image takes ~10 minutes on
        a fast SSD and gains little vs the partial hash for our purpose
        (detecting drift, not cryptographic integrity).
        """
        if not out_path or not os.path.isfile(out_path):
            return
        item = self._queue[idx]
        summary_path = os.path.splitext(out_path)[0] + '.summary.json'

        # Partial hash of first + last 1 MiB
        partial_sha256 = None
        try:
            import hashlib
            h = hashlib.sha256()
            chunk = 1024 * 1024
            size = os.path.getsize(out_path)
            with open(out_path, 'rb') as f:
                h.update(f.read(chunk))
                if size > chunk * 2:
                    f.seek(-chunk, 2)
                    h.update(f.read(chunk))
            partial_sha256 = h.hexdigest()
        except Exception:
            pass

        # Output size
        try:
            output_size = os.path.getsize(out_path)
        except Exception:
            output_size = None

        # Source size (cheap — already computed during build)
        source_size = getattr(self, '_last_source_size', None)

        summary = {
            'schema_version': 1,
            'app_version':    APP_VERSION,
            'build_timestamp': time.strftime('%Y-%m-%dT%H:%M:%S%z') or time.strftime('%Y-%m-%dT%H:%M:%S'),
            'duration_seconds': round(game_elapsed, 1),
            'game': {
                'title':    item.game_title or '',
                'title_id': item.title_id or '',
                'version':  item.version or '',
                'source_folder': item.game_folder or '',
                'source_size_bytes': source_size,
            },
            'output': {
                'path':       out_path,
                'filename':   os.path.basename(out_path),
                'size_bytes': output_size,
                'partial_sha256': partial_sha256,
                'partial_sha256_note': 'sha256 of first 1MB + last 1MB only',
            },
            'settings_used': {
                'cluster_size': self._adv_cluster_var.get() if hasattr(self, '_adv_cluster_var') else None,
                'sector_size':  self._adv_sector_var.get()  if hasattr(self, '_adv_sector_var')  else None,
                'threads':      self._adv_threads_var.get() if hasattr(self, '_adv_threads_var') else None,
                'retries':      self._adv_retries_var.get() if hasattr(self, '_adv_retries_var') else None,
                'retry_wait':   self._adv_retry_wait_var.get() if hasattr(self, '_adv_retry_wait_var') else None,
                'image_size_gb_override': (
                    self._adv_img_size_var.get()
                    if hasattr(self, '_adv_img_size_var') else None),
                'exclude_hidden': bool(
                    self._adv_excl_hidden_var.get()
                    if hasattr(self, '_adv_excl_hidden_var') else False),
                'skip_verify': bool(
                    self._adv_skip_verify_var.get()
                    if hasattr(self, '_adv_skip_verify_var') else False),
            },
        }
        with open(summary_path, 'w', encoding='utf-8') as f:
            json.dump(summary, f, indent=2)
        self._log('[INFO] Wrote summary: ' + summary_path + '\n')

