    def _y2jb_build_install(self, parent):
        """Install sub-tab: PKG file selectors and Install buttons + progress."""
        pkg_outer = tk.Frame(parent, bg=SURFACE2, highlightbackground=BORDER, highlightthickness=1)
        pkg_outer.pack(fill='x', padx=24, pady=(0, 12))
        pkg_body = tk.Frame(pkg_outer, bg=SURFACE2)
