    def _pl_save_conn(self):
        self._settings['pl_ip']   = self._pl_ip_var.get().strip()
        self._settings['pl_port'] = int(self._pl_port_var.get().strip() or '9090')
        save_settings(self._settings)
        self._pl_status_var.set('Connection settings saved')

    def _pl_save_payloads(self):
        self._settings['payloads'] = self._pl_payloads
        save_settings(self._settings)

    def _pl_render(self):
        # Step 14 (v2.1.6): rewritten to build payload cards in the new
        # design, with click-to-select that drives the detail aside.
        from tkinter_theme import COLORS as _TC, FONTS as _TF
        from ui.tab_payloads import _render_detail_for, _render_detail_empty

        for w in self._pl_list_frame.winfo_children():
            w.destroy()

        # Update count pill
        n = len(self._pl_payloads)
        if hasattr(self, '_pl_count_var'):
            self._pl_count_var.set('%d %s' % (n, 'saved'))

        # Apply search filter
        search = ''
        try:
            search = self._pl_search_var.get().strip().lower()
        except Exception:
            pass

        if not self._pl_payloads:
            empty = tk.Frame(self._pl_list_frame, bg=_TC['bg_2'])
            empty.pack(fill='both', expand=True, pady=40)
            tk.Label(empty, text='\U0001f4e5',
                     font=(_TF['body'][0], 32),
                     bg=_TC['bg_2'], fg=_TC['fg_6']
                     ).pack()
            tk.Label(empty,
                     text='No payloads saved.\nClick "+ Add payload" above '
                          'to add your first one.',
                     font=_TF['meta'],
                     bg=_TC['bg_2'], fg=_TC['fg_5'],
                     justify='center'
                     ).pack(pady=(8, 0))
            return

        active_idx = self._pl_selected_idx.get() if hasattr(
            self, '_pl_selected_idx') else -1

        rendered = 0
        for idx, pl in enumerate(self._pl_payloads):
            name = pl.get('name', '(unnamed)')
            notes = pl.get('notes', '')
            path = pl.get('path', '')
            fname = os.path.basename(path)

            if search:
                hay = (name + ' ' + notes + ' ' + fname).lower()
                if search not in hay:
                    continue

            is_active = (idx == active_idx)
            row_bg = _TC['accent_08'] if is_active else _TC['bg_2']
            border_bg = _TC['accent'] if is_active else _TC['bg_2']

            card = tk.Frame(self._pl_list_frame, bg=row_bg, cursor='hand2')
            card.pack(fill='x')

            # 2px left accent strip on active
            strip = tk.Frame(card, bg=border_bg, width=2)
            strip.pack(side='left', fill='y')
            strip.pack_propagate(False)

            inner = tk.Frame(card, bg=row_bg)
            inner.pack(side='left', fill='x', expand=True, padx=14, pady=10)

            # Type icon — color based on extension
            ext = os.path.splitext(path)[1].lower()
            icon_bg = (_TC['danger_bg'] if ext == '.bin'
                       else _TC['accent_08'] if ext == '.elf'
                       else _TC['bg_3'])
            icon_fg = (_TC['danger_hi'] if ext == '.bin'
                       else _TC['accent_hi'] if ext == '.elf'
                       else _TC['fg_4'])
            icon_label = tk.Label(inner, text='\u26a1',
                                   font=(_TF['body'][0], 14),
                                   bg=icon_bg, fg=icon_fg,
                                   width=3, height=1)
            icon_label.pack(side='left', padx=(0, 12))

            # Info column
            info = tk.Frame(inner, bg=row_bg)
            info.pack(side='left', fill='x', expand=True)
            tk.Label(info, text=name,
                     font=(_TF['body'][0], 11, 'bold'),
                     bg=row_bg, fg=_TC['fg_0'], anchor='w'
                     ).pack(fill='x')
            if notes:
                tk.Label(info, text=notes[:70] + ('\u2026' if len(notes) > 70 else ''),
                         font=_TF['meta'],
                         bg=row_bg, fg=_TC['fg_4'],
                         anchor='w', justify='left'
                         ).pack(fill='x', pady=(2, 0))
            # Tag row
            tag_row = tk.Frame(info, bg=row_bg)
            tag_row.pack(fill='x', pady=(4, 0))
            exists = path and os.path.isfile(path)
            tk.Label(tag_row, text=fname or '(no file)',
                     font=(_TF['mono_sm'][0], 9),
                     bg=row_bg,
                     fg=_TC['fg_5'] if exists else _TC['danger_hi']
                     ).pack(side='left')
            if pl.get('ip'):
                tk.Label(tag_row,
                         text='  \u00b7  ' + pl['ip']
                              + ':' + str(pl.get('port', '')),
                         font=(_TF['mono_sm'][0], 9),
                         bg=row_bg, fg=_TC['accent_hi']
                         ).pack(side='left')

            # Right action — Send button
            send_btn = tk.Button(inner,
                text='\u2197  ' + _('Send'),
                font=(_TF['button'][0], 9, 'bold'),
                bg=_TC['accent'], fg=_TC['fg_0'],
                activebackground=_TC['accent_hi'],
                activeforeground=_TC['fg_0'],
                relief='flat', bd=0,
                padx=10, pady=6,
                cursor='hand2',
                command=lambda p=pl: self._pl_send(p))
            send_btn.pack(side='right', padx=(8, 0))

            # Click-to-select on the whole card (excluding the send button)
            def _on_click(_e=None, i=idx):
                self._pl_selected_idx.set(i)
                _render_detail_for(self, i)
                self._pl_render()

            for w in [card, strip, inner, icon_label, info, tag_row]:
                w.bind('<Button-1>', _on_click)
            for child in info.winfo_children():
                try:
                    child.bind('<Button-1>', _on_click)
                except Exception:
                    pass
            for child in tag_row.winfo_children():
                try:
                    child.bind('<Button-1>', _on_click)
                except Exception:
                    pass

            # Hairline separator
            tk.Frame(self._pl_list_frame, bg=_TC['border_2'], height=1
                     ).pack(fill='x')
            rendered += 1

        if rendered == 0:
            tk.Label(self._pl_list_frame,
                     text='No matches for current filter.',
                     font=('Segoe UI', 9), bg=_TC['bg_2'], fg=_TC['fg_5'],
                     pady=40
                     ).pack(fill='x')

    def _pl_add(self):
        self._pl_edit(None)

    def _pl_edit(self, idx):
        """Open add/edit dialog for a payload."""
        is_new = idx is None
        pl = {} if is_new else dict(self._pl_payloads[idx])

        win = tk.Toplevel(self)
        win.title('Add Payload' if is_new else 'Edit Payload')
        win.geometry('520x280')
        win.configure(bg=BG)
        win.resizable(False, False)
        win.transient(self)
        win.grab_set()

        body = tk.Frame(win, bg=BG)
        body.pack(fill='both', expand=True, padx=24, pady=16)

        name_var  = tk.StringVar(value=pl.get('name', ''))
        path_var  = tk.StringVar(value=pl.get('path', ''))
        notes_var = tk.StringVar(value=pl.get('notes', ''))

        def row(label, var, browse=False):
            r = tk.Frame(body, bg=BG)
            r.pack(fill='x', pady=(0,8))
            tk.Label(r, text=label, font=('Segoe UI', 9),
                     bg=BG, fg=MUTED, width=10, anchor='w').pack(side='left')
            ef = tk.Frame(r, bg=FIELD_BG,
                          highlightbackground=BORDER, highlightthickness=1)
            ef.pack(side='left', fill='x', expand=True)
            e = tk.Entry(ef, textvariable=var, font=('Consolas', 9),
                         bg=FIELD_BG, fg=FIELD_FG, insertbackground=FIELD_FG,
                         selectbackground=FIELD_SEL_BG,
                         selectforeground=FIELD_SEL_FG, relief='flat', bd=4)
            e.pack(fill='x')
            if browse:
                tk.Button(r, text='Browse',
                          font=('Segoe UI', 9), bg=SURFACE2, fg=TEXT,
                          activebackground=BORDER, activeforeground=TEXT,
                          relief='flat', bd=0, padx=8, pady=3, cursor='hand2',
                          command=lambda v=var: self._pl_browse_file(v, name_var)
                          ).pack(side='left', padx=(6,0))
            return e

        name_entry = row('Name', name_var)
        name_entry.focus()
        row('File (.elf/.bin)', path_var, browse=True)
        row('Notes', notes_var)

        btn_row = tk.Frame(body, bg=BG)
        btn_row.pack(fill='x', pady=(8,0))

        def _save():
            name = name_var.get().strip()
            path = path_var.get().strip()
            if not name:
                messagebox.showwarning('Missing', 'Please enter a name.', parent=win)
                return
            if not path:
                messagebox.showwarning('Missing', 'Please select a payload file.', parent=win)
                return
            if not path.lower().endswith(('.elf', '.bin')):
                messagebox.showwarning('Invalid file',
                    'Only .elf and .bin files are supported.', parent=win)
                return
            entry = {'name': name, 'path': path, 'notes': notes_var.get().strip()}
            if is_new:
                self._pl_payloads.append(entry)
            else:
                self._pl_payloads[idx] = entry
            self._pl_save_payloads()
            self._pl_render()
            self._pl_status_var.set(('Added' if is_new else 'Updated') + ': ' + name)
            win.destroy()

        tk.Button(btn_row, text='Save',
                  font=('Segoe UI', 10, 'bold'), bg=SUCCESS, fg=TEXT,
                  activebackground='#3d9140', activeforeground=TEXT,
                  relief='flat', bd=0, padx=18, pady=6, cursor='hand2',
                  command=_save).pack(side='left')
        tk.Button(btn_row, text='Cancel',
                  font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                  activebackground=BORDER, activeforeground=TEXT,
                  relief='flat', bd=0, padx=12, pady=6, cursor='hand2',
                  command=win.destroy).pack(side='left', padx=(8,0))
        win.bind('<Return>', lambda e: _save())
        win.bind('<Escape>', lambda e: win.destroy())

        # Centre over parent
        win.update_idletasks()
        x = self.winfo_x() + (self.winfo_width()  - win.winfo_width())  // 2
        y = self.winfo_y() + (self.winfo_height() - win.winfo_height()) // 2
        win.geometry('+%d+%d' % (x, y))
        win.wait_window()

    def _pl_browse_file(self, var, name_var=None):
        p = filedialog.askopenfilename(
            title='Select payload file',
            filetypes=[('Payload files', '*.elf *.bin'),
                       ('ELF files', '*.elf'),
                       ('BIN files', '*.bin'),
                       ('All files', '*.*')])
        if p:
            p = p.replace('/', '\\')
            var.set(p)
            # Auto-fill name from filename if name is still empty
            if name_var is not None and not name_var.get().strip():
                name_var.set(os.path.splitext(os.path.basename(p))[0])

    def _pl_delete(self, idx):
        name = self._pl_payloads[idx].get('name', 'this payload')
        if not messagebox.askyesno('Delete payload',
                'Remove "%s" from the payload manager?\n\n'
                '(The file itself will not be deleted)' % name):
            return
        self._pl_payloads.pop(idx)
        self._pl_save_payloads()
        self._pl_render()
        self._pl_status_var.set('Removed: ' + name)

    def _pl_send(self, pl):
        """Send a payload to the PS5 via TCP socket."""
        path = pl.get('path', '')
        name = pl.get('name', os.path.basename(path))

        if not os.path.isfile(path):
            messagebox.showerror('File not found',
                'Payload file not found:\n' + path +
                '\n\nEdit the payload to update the file path.')
            return

        ip   = self._pl_ip_var.get().strip()
        port = self._pl_port_var.get().strip()
        if not ip:
            messagebox.showwarning('No IP',
                'Enter your PS5 IP address in the connection bar above.')
            return
        try:
            port = int(port)
        except ValueError:
            messagebox.showwarning('Invalid port', 'Port must be a number.')
            return

        self._pl_save_conn()
        self._pl_status_var.set('Sending %s to %s:%d...' % (name, ip, port))
        self._pl_sending = True

        def worker():
            try:
                import socket
                file_size = os.path.getsize(path)
                sent      = 0
                start     = time.time()

                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(10)
                    s.connect((ip, port))
                    s.settimeout(30)
                    with open(path, 'rb') as f:
                        while True:
                            chunk = f.read(65536)
                            if not chunk:
                                break
                            s.sendall(chunk)
                            sent += len(chunk)
                            pct  = int(sent / file_size * 100) if file_size else 0
                            elapsed = time.time() - start
                            speed = (sent / 1024 / 1024) / elapsed if elapsed > 0 else 0
                            self.after(0, self._pl_status_var.set,
                                'Sending %s — %d%%  %.1f MB/s' % (name, pct, speed))

                elapsed = time.time() - start
                self.after(0, self._pl_send_done, True, name, ip, port, elapsed)
            except Exception as e:
                self.after(0, self._pl_send_done, False, str(e), ip, port, 0)

        threading.Thread(target=worker, daemon=True).start()

    def _pl_send_done(self, ok, info, ip, port, elapsed):
        self._pl_sending = False
        if ok:
            self._pl_status_var.set(
                '\u2713 Sent "%s" to %s:%d in %.1fs' % (info, ip, port, elapsed))
            self._notify('Payload sent', info + ' \u2192 ' + ip)
        else:
            self._pl_status_var.set('\u2717 Send failed: ' + info)
            messagebox.showerror('Send failed',
                'Failed to send payload to PS5:\n\n' + info +
                '\n\nCheck:\n'
                '\u2022 PS5 is on and jailbroken\n'
                '\u2022 IP address is correct\n'
                '\u2022 Port matches your homebrew (9090 / 9021)\n'
                '\u2022 PS5 is ready to receive a payload')

    # ══════════════════════════════════════════════════════════════════════════
    # AUTOLOADER EDITOR HELPERS
    # ══════════════════════════════════════════════════════════════════════════
    def _al_browse_dir(self):
        """Browse for the ps5_autoloader folder."""
        p = filedialog.askdirectory(title='Select ps5_autoloader folder')
        if p:
            self._al_dir_var.set(p)
            self._settings['al_dir'] = p
            save_settings(self._settings)
            self._al_load()

    def _al_load(self):
        """Load autoload.txt into the editor and refresh the ELF file list."""
        folder = self._al_dir_var.get().strip()
        if not folder or not os.path.isdir(folder):
            messagebox.showwarning('Autoloader', 'Select a valid ps5_autoloader folder first.')
            return
        # Load autoload.txt
        txt_path = os.path.join(folder, 'autoload.txt')
        self._al_text.delete('1.0', 'end')
        if os.path.isfile(txt_path):
            with open(txt_path, 'r', encoding='utf-8', newline='') as f:
                raw = f.read()
            # Normalise line endings — strip all \r to prevent double-spacing
            raw = raw.replace('\r\n', '\n').replace('\r', '\n')
            # Collapse runs of blank lines (3+ newlines → 2) and strip trailing
            import re as _re
            raw = _re.sub(r'\n{3,}', '\n\n', raw)
            raw = raw.rstrip('\n') + '\n'
            self._al_text.insert('1.0', raw)
            self._al_status_var.set('\u2713 Loaded %s' % txt_path)
        else:
            # Create default header
            header = (
                '# ps5_autoloader\n'
                '# autoload config file\n'
                '# --------------------------------------------------------------------------------\n'
                '# The loader looks for ps5_autoloader/autoload.txt in this order (highest priority first):\n'
                '# 1) USB drives\n'
                '# 2) /data directory\n'
                '# 3) savedata directory\n'
                '# Only the first autoload.txt found will be used.\n'
                '#\n'
                '# Usage:\n'
                '# - Put one filename per line (e.g., payload.elf or script.js).\n'
                '# - Supported payload types: .elf, .bin, .js\n'
                '# - Lines starting with \'!\' are sleep commands (example: !1000 sleeps for 1000 ms).\n'
                '#\n'
                '# Notes:\n'
                '# - The kernel exploit will start automatically - do NOT include it here!\n'
                '# - You can use custom elf loader by putting it here and adding\n'
                '#   elfldr.elf (must be that filename!) line before other ELFs.\n'
                '# --------------------------------------------------------------------------------\n'
            )
            self._al_text.insert('1.0', header)
            self._al_status_var.set('autoload.txt not found — default header created')
        # Refresh ELF list
        self._al_refresh_files()

    def _al_refresh_files(self):
        """Rebuild the clickable ELF file buttons."""
        folder = self._al_dir_var.get().strip()
        # Clear existing buttons
        for w in self._al_files_frame.winfo_children():
            w.destroy()
        if not folder or not os.path.isdir(folder):
            return
        # Find .elf / .bin / .js files (not autoload.txt itself)
        try:
            files = sorted([
                f for f in os.listdir(folder)
                if f.lower().endswith(('.elf', '.bin', '.js'))
            ])
        except Exception:
            files = []
        if not files:
            tk.Label(self._al_files_frame, text='No ELF/BIN/JS files in folder',
                     font=('Segoe UI', 8), bg=SURFACE2, fg='#555555').pack(side='left')
            return
        for fname in files:
            # Card: [filename button] [🗑 delete]
            card = tk.Frame(self._al_files_frame, bg='#1a2a1a',
                            highlightbackground='#2a4a2a', highlightthickness=1)
            card.pack(side='left', padx=(0, 4))
            tk.Button(card, text=fname,
                      font=('Consolas', 8), bg='#1a2a1a', fg='#88dd88',
                      activebackground='#2a4a2a', activeforeground=TEXT,
                      relief='flat', bd=0, padx=8, pady=3, cursor='hand2',
                      command=lambda fn=fname: self._al_insert_filename(fn)
                      ).pack(side='left')
            tk.Button(card, text='🗑',
                      font=('Segoe UI', 8), bg='#1a2a1a', fg='#884444',
                      activebackground='#3a1a1a', activeforeground='#ff6666',
                      relief='flat', bd=0, padx=4, pady=3, cursor='hand2',
                      command=lambda fn=fname: self._al_delete_payload(fn)
                      ).pack(side='left')

    def _al_delete_payload(self, filename):
        """Delete a payload file from the autoloader folder after confirmation."""
        folder = self._al_dir_var.get().strip()
        if not folder:
            return
        fpath = os.path.join(folder, filename)
        if not messagebox.askyesno('Delete payload',
                'Permanently delete %s from the folder?\n\nThis cannot be undone.' % filename,
                icon='warning'):
            return
        try:
            os.remove(fpath)
            # Remove filename AND any !sleep lines immediately following it
            txt = self._al_text.get('1.0', 'end-1c')
            lines = txt.split('\n')
            filtered = []
            skip_sleeps = False
            for line in lines:
                stripped = line.strip()
                if stripped == filename:
                    skip_sleeps = True   # start skipping sleeps after this line
                    continue             # remove the filename line itself
                if skip_sleeps and stripped.startswith('!') and stripped[1:].isdigit():
                    continue             # remove the following !sleep line
                skip_sleeps = False      # stop skipping once we hit a non-sleep line
                filtered.append(line)
            self._al_text.delete('1.0', 'end')
            self._al_text.insert('1.0', '\n'.join(filtered))
            self._al_refresh_files()
            self._al_status_var.set('\u2713 Deleted: ' + filename)
        except Exception as e:
            messagebox.showerror('Delete failed', str(e))

    def _al_insert_filename(self, filename):
        """Insert a filename at the current cursor position in the editor."""
        try:
            idx = self._al_text.index('insert')
            # Go to end of current line and insert a newline + filename
            line_end = self._al_text.index('%s lineend' % idx)
            self._al_text.mark_set('insert', line_end)
            self._al_text.insert('insert', '\n' + filename)
            self._al_text.see('insert')
            self._al_status_var.set('Inserted: ' + filename)
        except Exception as e:
            self._al_status_var.set('Error: ' + str(e))

    def _al_insert_sleep(self):
        """Prompt user for sleep duration and insert !NNNN at cursor."""
        val = simpledialog.askinteger(
            'Insert Sleep',
            'Sleep duration in milliseconds:\n(e.g. 5000 = 5 seconds)',
            initialvalue=5000, minvalue=100, maxvalue=60000,
            parent=self)
        if val is None:
            return
        try:
            idx = self._al_text.index('insert')
            line_end = self._al_text.index('%s lineend' % idx)
            self._al_text.mark_set('insert', line_end)
            self._al_text.insert('insert', '\n!%d' % val)
            self._al_text.see('insert')
            self._al_status_var.set('Inserted sleep: !%d (%d ms)' % (val, val))
        except Exception as e:
            self._al_status_var.set('Error: ' + str(e))

    def _al_add_elf(self):
        """Browse for an ELF/BIN file, copy it into the autoloader folder,
        and append its name to the editor."""
        folder = self._al_dir_var.get().strip()
        if not folder or not os.path.isdir(folder):
            messagebox.showwarning('Autoloader', 'Load a ps5_autoloader folder first.')
            return
        src = filedialog.askopenfilename(
            title='Select payload to add',
            filetypes=[
                ('Payload files', '*.elf *.bin *.js'),
                ('ELF files', '*.elf'),
                ('All files', '*.*')
            ])
        if not src:
            return
        import shutil
        fname = os.path.basename(src)
        dst   = os.path.join(folder, fname)
        # Warn if file already exists
        if os.path.isfile(dst):
            if not messagebox.askyesno('Autoloader',
                    '%s already exists in the folder.\nOverwrite?' % fname):
                return
        try:
            shutil.copy2(src, dst)
            # Insert into text editor at cursor
            self._al_insert_filename(fname)
            # Refresh file list buttons
            self._al_refresh_files()
            self._al_status_var.set('\u2713 Added %s to folder and autoload.txt' % fname)
        except Exception as e:
            messagebox.showerror('Autoloader', 'Failed to copy file:\n' + str(e))

    def _al_save(self):
        """Save the text editor content back to autoload.txt with Unix line endings."""
        folder = self._al_dir_var.get().strip()
        if not folder or not os.path.isdir(folder):
            messagebox.showwarning('Autoloader', 'Load a ps5_autoloader folder first.')
            return
        content = self._al_text.get('1.0', 'end-1c')
        # Normalise to Unix LF and strip excessive blank lines
        content = content.replace('\r\n', '\n').replace('\r', '\n')
        import re as _re
        content = _re.sub(r'\n{3,}', '\n\n', content)
        content = content.rstrip('\n') + '\n'
        txt_path = os.path.join(folder, 'autoload.txt')
        try:
            with open(txt_path, 'w', encoding='utf-8', newline='\n') as f:
                f.write(content)
            self._al_status_var.set('\u2713 Saved to %s' % txt_path)
        except Exception as e:
            messagebox.showerror('Autoloader', 'Save failed:\n' + str(e))

    # ══════════════════════════════════════════════════════════════════════════
    # KLOG MONITOR TAB
    # ══════════════════════════════════════════════════════════════════════════
    def _build_klog_tab(self, parent):
        # Carved out in Step 1 — see ui/tab_klog.py
        from ui.tab_klog import build_klog_tab
        build_klog_tab(parent, self)

    # ── Klog helpers ──────────────────────────────────────────────────────────
    def _klog_save_settings(self):
        self._settings['klog_ip']   = self._klog_ip_var.get().strip()
        self._settings['klog_port'] = int(self._klog_port_var.get().strip() or '3232')
        save_settings(self._settings)

    def _klog_connect(self):
        ip   = self._klog_ip_var.get().strip()
        port = self._klog_port_var.get().strip()
        if not ip:
            messagebox.showwarning('No IP', 'Enter the PS5 IP address.')
            return
        try:
            port = int(port)
        except ValueError:
            messagebox.showwarning('Invalid port', 'Port must be a number.')
            return

        self._klog_save_settings()
        self._klog_running = True
        self._klog_connect_btn.config(state='disabled')
        self._klog_stop_btn.config(state='normal')
        self._klog_status_var.set('Connecting...')
        self._klog_status_lbl.config(fg=ACCENT)

        def worker():
            import socket
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.settimeout(10)
                s.connect((ip, port))
                s.settimeout(None)
                self._klog_socket[0] = s
                self.after(0, self._klog_status_var.set,
                           'Connected to ' + ip + ':' + str(port))
                self.after(0, self._klog_status_lbl.config, {'fg': SUCCESS})
                self.after(0, self._klog_pause_btn.config, {'state': 'normal'})
                buf = ''
                while self._klog_running:
                    try:
                        data = s.recv(4096)
                        if not data:
                            break
                        buf += data.decode('utf-8', errors='replace')
                        while '\n' in buf:
                            line, buf = buf.split('\n', 1)
                            line = line.rstrip('\r')
                            if line:
                                self.after(0, self._klog_add_line, line)
                    except Exception:
                        break
            except Exception as e:
                self.after(0, self._klog_status_var.set, 'Error: ' + str(e))
                self.after(0, self._klog_status_lbl.config, {'fg': DANGER})
            finally:
                try:
                    if self._klog_socket[0]:
                        self._klog_socket[0].close()
                        self._klog_socket[0] = None
                except Exception:
                    pass
                self.after(0, self._klog_on_disconnect)

        threading.Thread(target=worker, daemon=True).start()

    def _klog_disconnect(self):
        self._klog_running = False
        try:
            if self._klog_socket[0]:
                self._klog_socket[0].close()
        except Exception:
            pass

    def _klog_on_disconnect(self):
        self._klog_running = False
        self._klog_connect_btn.config(state='normal')
        self._klog_stop_btn.config(state='disabled')
        self._klog_pause_btn.config(state='disabled', text='\u23f8 Pause')
        self._klog_paused.set(False)
        self._klog_status_var.set('Disconnected')
        self._klog_status_lbl.config(fg=MUTED)

    def _klog_toggle_pause(self):
        if self._klog_paused.get():
            # Resume — flush buffered lines
            self._klog_paused.set(False)
            self._klog_pause_btn.config(text='\u23f8 Pause', bg=WARNING,
                                         fg='#000000')
            self._klog_status_var.set('Connected — live')
            self._klog_status_lbl.config(fg=SUCCESS)
        else:
            self._klog_paused.set(True)
            self._klog_pause_btn.config(text='\u25b6 Resume', bg=SUCCESS,
                                         fg=TEXT)
            self._klog_status_var.set('Paused — still receiving')
            self._klog_status_lbl.config(fg=WARNING)

    def _klog_get_tag(self, line):
        l = line.lower()
        if any(w in l for w in ['error', 'fatal', 'panic', 'assert', 'crash']):
            return 'error'
        if any(w in l for w in ['warn', 'caution']):
            return 'warning'
        if any(w in l for w in ['debug', 'trace', 'verbose']):
            return 'debug'
        return 'info'

    def _klog_add_line(self, line):
        # Prepend timestamp if enabled
        if self._klog_timestamps.get():
            ts = time.strftime('%H:%M:%S')
            line_display = '[' + ts + ']  ' + line
        else:
            line_display = line

        self._klog_lines.append(line_display)
        self._klog_count_var.set(str(len(self._klog_lines)) + ' lines')

        # Don't render if paused
        if self._klog_paused.get():
            return

        # Check filter
        filt = self._klog_filter_var.get().lower()
        if filt and filt not in line_display.lower():
            return

        tag  = self._klog_get_tag(line)
        self._klog_box.config(state='normal')
        self._klog_box.insert('end', line_display + '\n', tag)

        # Highlight filter term
        if filt:
            start = '1.0'
            while True:
                pos = self._klog_box.search(filt, start, stopindex='end',
                                             nocase=True)
                if not pos:
                    break
                end_pos = '%s+%dc' % (pos, len(filt))
                self._klog_box.tag_add('highlight', pos, end_pos)
                start = end_pos

        self._klog_box.config(state='disabled')
        if self._klog_autoscroll.get():
            self._klog_box.see('end')

    def _klog_apply_filter(self):
        """Re-render all lines with current filter."""
        filt = self._klog_filter_var.get().lower()
        self._klog_box.config(state='normal')
        self._klog_box.delete('1.0', 'end')
        for line in self._klog_lines:
            if filt and filt not in line.lower():
                continue
            tag = self._klog_get_tag(line)
            self._klog_box.insert('end', line + '\n', tag)
        if filt:
            start = '1.0'
            while True:
                pos = self._klog_box.search(filt, start, stopindex='end',
                                             nocase=True)
                if not pos:
                    break
                end_pos = '%s+%dc' % (pos, len(filt))
                self._klog_box.tag_add('highlight', pos, end_pos)
                start = end_pos
        self._klog_box.config(state='disabled')
        if self._klog_autoscroll.get():
            self._klog_box.see('end')

    def _klog_toggle_wrap(self):
        wrap = 'word' if self._klog_word_wrap.get() else 'none'
        self._klog_box.config(wrap=wrap)

    def _klog_clear(self):
        self._klog_lines = []
        self._klog_count_var.set('0 lines')
        self._klog_box.config(state='normal')
        self._klog_box.delete('1.0', 'end')
        self._klog_box.config(state='disabled')

    def _klog_export(self):
        if not self._klog_lines:
            messagebox.showwarning('Nothing to export', 'No log data to export.')
            return
        path = filedialog.asksaveasfilename(
            title='Export klog',
            defaultextension='.txt',
            filetypes=[('Text files', '*.txt'), ('Log files', '*.log'),
                       ('All files', '*.*')],
            initialfile='klog_' + time.strftime('%Y%m%d_%H%M%S') + '.txt')
        if not path:
            return
        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write('PS5 Klog Export\n')
                f.write('Date: ' + time.strftime('%Y-%m-%d %H:%M:%S') + '\n')
                f.write('=' * 60 + '\n\n')
                f.write('\n'.join(self._klog_lines))
            self._klog_status_var.set('Exported: ' + os.path.basename(path))
            self._klog_status_lbl.config(fg=SUCCESS)
        except Exception as e:
            messagebox.showerror('Export failed', str(e))

