        frag_opts = ['512', '1024', '2048', '4096', '8192', '16384', '32768', '65536']
        frag_disp = ['512', '1K', '2K', '4K', '8K', '16K', '32K', '64K (default)']
        self._adv_ffpkg_frag_display_var = tk.StringVar()
