    def _ls_mode_change(self):
        mode = self._ls_mode_var.get()
        self._ls_browse_btn.config(
            command=self._ls_browse if mode == 'single' else self._ls_browse_batch)
        self._ls_scan_btn.config(
            command=self._ls_scan if mode == 'single' else self._ls_scan_batch)

    def _ls_browse(self):
        p = filedialog.askdirectory(title='Select game folder')
        if p: self._ls_game_var.set(p)

    def _ls_browse_batch(self):
        p = filedialog.askdirectory(title='Select folder containing multiple games')
        if p: self._ls_game_var.set(p)

    def _ls_scan_batch(self):
        base = self._ls_game_var.get().strip()
        if not base or not os.path.isdir(base):
            messagebox.showwarning('No folder', 'Select a folder first.')
            return
        self._ls_status_var.set('Scanning for games...')
        for w in self._ls_check_frame.winfo_children():
            w.destroy()
        self._ls_check_vars.clear()

        def worker():
            game_folders = []
            for entry in os.scandir(base):
                if not entry.is_dir(): continue
                eboot = os.path.join(entry.path, 'eboot.bin')
                if not os.path.isfile(eboot):
                    for sub in os.scandir(entry.path) if entry.is_dir() else []:
                        if os.path.isfile(os.path.join(sub.path, 'eboot.bin')):
                            game_folders.append(sub.path)
                            break
                else:
                    game_folders.append(entry.path)
            all_results = {}
            for gf in game_folders:
                found = {}
                self._ls_walk_for_langs(gf, found)
                if found:
                    all_results[gf] = found
            self.after(0, self._ls_render_results_batch, all_results)

        import threading as _t
        _t.Thread(target=worker, daemon=True).start()

    def _ls_walk_for_langs(self, game, found):
        """Walk game folder and find all language-specific files and folders."""
        import re as _re

        # All known 2-letter language codes
        valid_2letter = {
            'en','ja','fr','de','es','it','pt','ru','ko','zh',
            'ar','pl','nl','sv','tr','da','fi','no','cs','hu',
            'ro','sk','uk','vi','th','id','el','he','hr','bg',
            'af','ca','cy','et','eu','gl','lt','lv','ms',
            'nb','sl','sq','sr',
        }

        # BCP-47 locale folder pattern (en-US, zh-Hant, pt-BR etc.)
        locale_re = _re.compile(
            r'^(?:[a-z]{2}-[A-Z]{2}|[a-z]{2}-[A-Z][a-z]+-[A-Z]{2}|'
            r'[a-z]{2}-[A-Z][a-z]+|[a-z]{2}-\d{3}|[a-z]{2})$')

        lang_container_dirs = {
            'localization','locale','locales','lang','language','languages',
            'audio','speech','voices','vo','subtitles','text','strings',
            'l10n','i18n','translation','translations','movie','movies',
            'video','videos','cutscenes','cinema','fmv',
        }

        lang_codes = '|'.join(sorted(valid_2letter, key=len, reverse=True))

        # Unreal PAK language patterns
        pak_lang_re = _re.compile(
            r'(?:_lang_(' + lang_codes + r')|'
            r'_(' + lang_codes + r')_[Pp]\.pak|'
            r'[_\-](' + lang_codes + r')(?=\.pak)|'
            r'pakchunk\d+.*?[_\-](' + lang_codes + r')[_\-\.])',
            _re.IGNORECASE)

        # PSARC language patterns
        psarc_lang_re = _re.compile(
            r'(?:audio|speech|voice|vo|sub|subtitle|text|string|loc|lang|movie|video)'
            r'[_\-](' + lang_codes + r')(?:_\w+)?\.psarc$',
            _re.IGNORECASE)

        # Video/movie language patterns (cutscenes)
        video_lang_re = _re.compile(
            r'[_\-](' + lang_codes + r')[_\-]?(?:sub|dub|audio|voice)?'
            r'\.(?:mp4|m4v|webm|mkv|avi|mov|mxf|m2ts|ts)$',
            _re.IGNORECASE)

        # Audio bank language patterns (WWise, FMOD, PS5 AT9)
        audio_lang_re = _re.compile(
            r'[_\-](' + lang_codes + r')[_\-]?\.'
            r'(?:bnk|wem|pck|at9|snd|fsb|bank)$',
            _re.IGNORECASE)

        def _get_lang_code(path):
            """Extract language code from path for display."""
            name = os.path.basename(path).lower()
            # Direct match
            if name in valid_2letter:
                return name
            # BCP-47
            m = _re.match(r'^([a-z]{2})(?:-|$)', name)
            if m:
                return m.group(1)
            return None

        def _walk(root, depth=0, in_container=False):
            if depth > 7:
                return
            try:
                entries = sorted(os.scandir(root), key=lambda e: e.name.lower())
            except PermissionError:
                return

            for entry in entries:
                name     = entry.name
                name_low = name.lower()
                path     = entry.path

                if name_low in {'sce_sys','sce_module','decrypted','fakelib',
                                'at9tool','scelocale'}:
                    continue

                if entry.is_dir():
                    # Direct locale folder (en-US, ja, de, zh-Hant etc.)
                    if locale_re.match(name):
                        code = name_low.split('-')[0]
                        if len(name) >= 2 and (code in valid_2letter or '-' in name):
                            lang = self._LANG_NAMES.get(name_low,
                                   self._LANG_NAMES.get(code, name))
                            found[path] = ('folder', lang, code)
                            continue

                    # Language container — scan inside for locale subfolders
                    if name_low in lang_container_dirs:
                        _walk(path, depth+1, in_container=True)
                        continue

                    # Inside a container, any 2-letter subfolder is a language
                    if in_container and name_low in valid_2letter:
                        lang = self._LANG_NAMES.get(name_low, name)
                        found[path] = ('folder', lang, name_low)
                        continue

                    if depth < 6:
                        _walk(path, depth+1, in_container)

                else:
                    ext = os.path.splitext(name)[1].lower()

                    if ext == '.pak':
                        m = pak_lang_re.search(name)
                        if m:
                            code = next(g for g in m.groups() if g)
                            lang = self._LANG_NAMES.get(code.lower(), code.upper())
                            found[path] = ('file', lang, code.lower())

                    elif ext == '.psarc':
                        m = psarc_lang_re.search(name)
                        if m:
                            code = m.group(1).lower()
                            lang = self._LANG_NAMES.get(code, code.upper())
                            found[path] = ('file', lang, code)

                    elif ext in ('.mp4','.m4v','.webm','.mkv','.avi',
                                 '.mov','.m2ts','.ts'):
                        m = video_lang_re.search(name)
                        if m:
                            code = m.group(1).lower()
                            lang = self._LANG_NAMES.get(code, code.upper())
                            found[path] = ('file', lang + ' (video)', code)

                    elif ext in ('.bnk','.wem','.pck','.at9','.fsb','.bank'):
                        m = audio_lang_re.search(name)
                        if m:
                            code = m.group(1).lower()
                            lang = self._LANG_NAMES.get(code, code.upper())
                            found[path] = ('file', lang + ' (audio)', code)

                    # .sig files that accompany language .pak files
                    elif ext == '.sig':
                        pak = path[:-4] + '.pak'
                        if pak in found:
                            found[path] = found[pak]

        _walk(game)

    def _ls_scan(self):
        game = self._ls_game_var.get().strip()
        if not game or not os.path.isdir(game):
            messagebox.showwarning('No folder', 'Select a game folder first.')
            return
        self._ls_status_var.set('Scanning...')
        self.update_idletasks()
        for w in self._ls_check_frame.winfo_children():
            w.destroy()
        self._ls_check_vars.clear()

        def worker():
            found = {}
            self._ls_walk_for_langs(game, found)
            if not found:
                self.after(0, self._ls_status_var.set,
                    'No language files found.\n'
                    'This game may store all languages in its main data files.')
                return
            # Calculate sizes
            results = []
            for p, info in sorted(found.items()):
                kind, lang, code = info
                sz = 0
                try:
                    if os.path.isfile(p):
                        sz = os.path.getsize(p)
                    else:
                        for r, _, fs in os.walk(p):
                            for f in fs:
                                try: sz += os.path.getsize(os.path.join(r,f))
                                except Exception: pass
                except Exception: pass
                results.append((p, kind, lang, code, sz))
            self.after(0, self._ls_render_results, results, game)

        import threading as _t
        _t.Thread(target=worker, daemon=True).start()

    def _ls_render_results(self, results, game=''):
        """Render results grouped by language with size and type."""
        for w in self._ls_check_frame.winfo_children():
            w.destroy()
        self._ls_check_vars.clear()

        total_size = sum(sz for _, _, _, _, sz in results)

        # Group by language code
        from collections import defaultdict as _dd
        by_lang = _dd(list)
        for item in results:
            p, kind, lang, code, sz = item
            by_lang[code].append(item)

        self._ls_status_var.set(
            'Found %d language file(s) in %d language(s) — %.0f MB total  '
            '(check languages to KEEP, uncheck to DELETE)' % (
            len(results), len(by_lang), total_size/1024/1024))

        # Header
        hdr = tk.Frame(self._ls_check_frame, bg=BG)
        hdr.pack(fill='x', pady=(2, 0))
        for txt, w, anchor in [('Keep?', 5, 'w'), ('Language', 22, 'w'),
                                ('Files/Folders', 8, 'center'), ('Size', 10, 'e')]:
            tk.Label(hdr, text=txt, font=('Segoe UI', 8, 'bold'),
                     bg=BG, fg=MUTED, width=w, anchor=anchor,
                     padx=4, pady=3).pack(side='left')
        tk.Frame(self._ls_check_frame, bg=BORDER, height=1).pack(fill='x')

        # One row per language
        for i, (code, items) in enumerate(sorted(by_lang.items())):
            row_bg = SURFACE2 if i % 2 == 0 else BG
            row = tk.Frame(self._ls_check_frame, bg=row_bg)
            row.pack(fill='x')

            lang_name = self._LANG_NAMES.get(code, code.upper())
            total_lang_sz = sum(sz for _,_,_,_,sz in items)

            # Group checkbox (toggling this toggles all items for this language)
            chk_var = tk.BooleanVar(value=True)
            def _on_group_toggle(v=chk_var, its=items):
                state = v.get()
                for item in its:
                    p = item[0]
                    if p in self._ls_check_vars:
                        self._ls_check_vars[p].set(state)
                self._ls_update_savings()

            chk = tk.Checkbutton(row, variable=chk_var,
                                  bg=row_bg, activebackground=row_bg,
                                  selectcolor='#1a3a1a', cursor='hand2',
                                  command=_on_group_toggle)
            chk.pack(side='left', padx=(6, 0))

            # Flag emoji if available
            flag = {'en':'🇬🇧','ja':'🇯🇵','fr':'🇫🇷','de':'🇩🇪',
                    'es':'🇪🇸','it':'🇮🇹','pt':'🇧🇷','ru':'🇷🇺',
                    'ko':'🇰🇷','zh':'🇨🇳','ar':'🇸🇦','pl':'🇵🇱',
                    'nl':'🇳🇱','tr':'🇹🇷','sv':'🇸🇪','da':'🇩🇰',
                    'fi':'🇫🇮','no':'🇳🇴','cs':'🇨🇿','hu':'🇭🇺',
                    'uk':'🇺🇦','el':'🇬🇷','he':'🇮🇱','th':'🇹🇭',
                    'id':'🇮🇩','vi':'🇻🇳','ro':'🇷🇴','hr':'🇭🇷',
                    'bg':'🇧🇬','sk':'🇸🇰'}.get(code, '🌐')

            tk.Label(row, text='%s  %s' % (flag, lang_name),
                     font=('Segoe UI', 9, 'bold'), bg=row_bg, fg=TEXT,
                     anchor='w', width=24).pack(side='left', padx=(2, 0))

            tk.Label(row, text=str(len(items)),
                     font=('Segoe UI', 8), bg=row_bg, fg=MUTED,
                     width=8, anchor='center').pack(side='left')

            sz_str = ('%.1f GB' % (total_lang_sz/1024**3)
                      if total_lang_sz >= 1024**3
                      else '%.0f MB' % (total_lang_sz/1024**2)
                      if total_lang_sz >= 1024**2
                      else '%d KB' % (total_lang_sz/1024))
            tk.Label(row, text=sz_str,
                     font=('Segoe UI', 9, 'bold'), bg=row_bg,
                     fg=DANGER if total_lang_sz > 500*1024*1024 else MUTED,
                     width=10, anchor='e').pack(side='left')

            # Expand to show individual files
            detail_frame = tk.Frame(self._ls_check_frame, bg=row_bg)
            def _toggle_detail(df=detail_frame, items=items, rb=row_bg, code=code):
                if df.winfo_children():
                    for w in df.winfo_children(): w.destroy()
                else:
                    for p, kind, lang, c, sz in items:
                        irow = tk.Frame(df, bg=rb)
                        irow.pack(fill='x')
                        ivar = self._ls_check_vars.get(p, tk.BooleanVar(value=True))
                        self._ls_check_vars[p] = ivar
                        tk.Label(irow, text='   ', bg=rb, width=4).pack(side='left')
                        ck = tk.Checkbutton(irow, variable=ivar, bg=rb,
                                            activebackground=rb, selectcolor='#1a3a1a',
                                            cursor='hand2',
                                            command=self._ls_update_savings)
                        ck.pack(side='left')
                        rel = os.path.relpath(p, game) if game else p
                        type_icon = '📁' if kind == 'folder' else '🎬' if 'video' in lang.lower() else '🔊' if 'audio' in lang.lower() else '📄'
                        tk.Label(irow, text=type_icon + ' ' + (rel[:72] if len(rel) > 72 else rel),
                                 font=('Consolas', 7), bg=rb, fg='#555555', anchor='w'
                                 ).pack(side='left', fill='x', expand=True)
                        s = ('%.0fMB' % (sz/1024**2) if sz >= 1024**2 else '%dKB' % (sz/1024))
                        tk.Label(irow, text=s, font=('Segoe UI', 7), bg=rb, fg=MUTED
                                 ).pack(side='right', padx=(0,8))

            expand_btn = tk.Label(row, text='▶', font=('Segoe UI', 7),
                                   bg=row_bg, fg=MUTED, cursor='hand2')
            expand_btn.pack(side='right', padx=(0, 8))
            expand_btn.bind('<Button-1>', lambda e, df=detail_frame,
                            btn=expand_btn, it=items, rb=row_bg: (
                _toggle_detail(df, it, rb),
                btn.config(text='▼' if detail_frame.winfo_children() else '▶')))
            detail_frame.pack(fill='x')

            # Register group var so individual file vars get linked
            for p, kind, lang, c, sz in items:
                if p not in self._ls_check_vars:
                    self._ls_check_vars[p] = chk_var  # default to group var

        self._ls_update_savings()

    def _ls_render_results_batch(self, all_results):
        """Render batch results grouped by game."""
        for w in self._ls_check_frame.winfo_children():
            w.destroy()
        self._ls_check_vars.clear()

        if not all_results:
            self._ls_status_var.set('No language files found in any game.')
            return

        total_files = sum(len(v) for v in all_results.values())
        self._ls_status_var.set(
            'Found %d language file(s) across %d game(s)' % (
            total_files, len(all_results)))

        import threading as _t

        for gf, found in all_results.items():
            game_name = os.path.basename(gf)
            hdr = tk.Frame(self._ls_check_frame, bg=ACCENT)
            hdr.pack(fill='x', pady=(6, 0))
            tk.Label(hdr, text='🎮 ' + game_name,
                     font=('Segoe UI', 9, 'bold'), bg=ACCENT, fg=TEXT,
                     padx=8, pady=3).pack(side='left')

            # Calc sizes
            results = []
            for p, info in sorted(found.items()):
                kind, lang, code = info
                sz = 0
                if os.path.isfile(p):
                    try: sz = os.path.getsize(p)
                    except Exception: pass
                results.append((p, kind, lang, code, sz))

            sub_frame = tk.Frame(self._ls_check_frame, bg=SURFACE2)
            sub_frame.pack(fill='x', padx=12)
            self._ls_render_results(results, gf)

    def _ls_update_savings(self):
        """Recalculate and show how much space will be freed."""
        to_delete = [p for p, v in self._ls_check_vars.items() if not v.get()]
        total_sz = 0
        for p in to_delete:
            try:
                if os.path.isfile(p):
                    total_sz += os.path.getsize(p)
                else:
                    for r, _, fs in os.walk(p):
                        for f in fs:
                            try: total_sz += os.path.getsize(os.path.join(r,f))
                            except Exception: pass
            except Exception:
                pass
        if total_sz > 0:
            if total_sz >= 1024**3:
                s = '%.1f GB' % (total_sz/1024**3)
            else:
                s = '%.0f MB' % (total_sz/1024**2)
            self._ls_savings_var.set('💾 %s will be freed' % s)
        else:
            self._ls_savings_var.set('')

    def _ls_select_all(self, state):
        for var in self._ls_check_vars.values():
            var.set(state)
        self._ls_update_savings()

    def _ls_keep_only(self, keep_codes):
        """Uncheck all except specified locale codes."""
        keep_lower = {c.lower() for c in keep_codes}
        for path, var in self._ls_check_vars.items():
            name = os.path.basename(path).lower()
            code = name.split('-')[0]
            keep = (name in keep_lower or code in keep_lower or
                    any(name.startswith(k) for k in keep_lower))
            var.set(keep)
        self._ls_update_savings()

    def _ls_strip(self):
        """Backup then delete unchecked items."""
        if not self._ls_check_vars:
            messagebox.showwarning('Nothing scanned', 'Scan a game folder first.')
            return
        to_delete = [p for p, v in self._ls_check_vars.items() if not v.get()]
        to_keep   = [p for p, v in self._ls_check_vars.items() if v.get()]

        if not to_delete:
            messagebox.showinfo('Nothing to delete', 'All languages are checked to keep.')
            return
        if not to_keep:
            if not messagebox.askyesno('Delete ALL?',
                    'You are deleting ALL detected language files.\nThis may break the game.\n\nAre you sure?'):
                return

        # Calculate savings
        total_sz = 0
        for p in to_delete:
            try:
                if os.path.isfile(p): total_sz += os.path.getsize(p)
                else:
                    for r,_,fs in os.walk(p):
                        for f in fs:
                            try: total_sz += os.path.getsize(os.path.join(r,f))
                            except Exception: pass
            except Exception: pass

        del_preview = '\n'.join('  • ' + os.path.basename(p) for p in to_delete[:8])
        if len(to_delete) > 8:
            del_preview += '\n  ... and %d more' % (len(to_delete)-8)
        savings = ('%.1f GB' % (total_sz/1024**3) if total_sz >= 1024**3
                   else '%.0f MB' % (total_sz/1024**2))

        backup_dest = filedialog.askdirectory(
            title='Select backup folder (required — files backed up before deletion)')
        if not backup_dest:
            return

        if not messagebox.askyesno('Confirm Strip',
                '⚠ This will permanently delete %d file(s)/folder(s) '
                '(saving ~%s):\n\n%s\n\n'
                'A backup zip will be saved to:\n%s\n\n'
                'Continue?' % (len(to_delete), savings, del_preview, backup_dest)):
            return

        import shutil as _sh, zipfile as _zf
        ts = time.strftime('%Y-%m-%d_%H.%M.%S')
        backed_up = deleted = 0
        failed = []

        for path in to_delete:
            try:
                # Find game root for naming
                check = os.path.dirname(path)
                game_root = check
                for _ in range(6):
                    if os.path.isfile(os.path.join(check, 'eboot.bin')):
                        game_root = check
                        break
                    check = os.path.dirname(check)
                game_name = os.path.basename(game_root.rstrip('\\/'))
                folder_name = os.path.basename(path)
                zip_path = os.path.join(backup_dest,
                    '%s_%s_%s.zip' % (game_name, folder_name, ts))

                with _zf.ZipFile(zip_path, 'w', _zf.ZIP_DEFLATED) as zf:
                    if os.path.isfile(path):
                        zf.write(path, os.path.relpath(path, os.path.dirname(path)))
                    else:
                        for r, dirs, files in os.walk(path):
                            for fn in files:
                                fp = os.path.join(r, fn)
                                zf.write(fp, os.path.relpath(fp, os.path.dirname(path)))
                backed_up += 1
                self._log('[LANG] Backed up: %s\n' % path)

                if os.path.isfile(path):
                    os.remove(path)
                else:
                    _sh.rmtree(path)
                deleted += 1
                self._log('[LANG] Deleted: %s\n' % path)
            except Exception as e:
                failed.append('%s: %s' % (os.path.basename(path), e))
                self._log('[LANG] FAILED: %s — %s\n' % (path, e))

        msg = 'Stripped %d item(s), backed up %d.' % (deleted, backed_up)
        if failed:
            msg += '\n\nFailed:\n' + '\n'.join(failed[:5])
        messagebox.showinfo('Strip complete', msg)
        self._ls_status_var.set('Done — %d deleted, %d failed' % (deleted, len(failed)))


