    def _adv_save_post_build(self):
        self._settings['adv_delete_source']       = self._adv_delete_source_var.get()
        self._settings['adv_delete_source_ffpkg'] = self._adv_delete_source_ffpkg_var.get()
        self._settings['adv_auto_upload']         = self._adv_auto_upload_var.get()
        self._settings['adv_robo_log']            = self._adv_robo_log_var.get()
        self._settings['adv_robo_log_dir']        = self._adv_robo_log_dir_var.get()
        self._settings['adv_checksum_verify']     = self._adv_checksum_var.get()
        self._settings['adv_img_size_override']   = self._adv_img_size_var.get()
        save_settings(self._settings)

    def _adv_browse_robo_log(self):
        p = filedialog.askdirectory(title='Select folder for robocopy logs')
        if p:
            self._adv_robo_log_dir_var.set(p.replace('/', '\\'))
            self._adv_save_post_build()

    def _adv_refresh_summary(self):
        cluster = self._adv_cluster_var.get()
        cluster_label = ('Auto  (64K — PS5 default)' if cluster == 'Auto'
                         else cluster + ' bytes')
        sector  = self._adv_sector_var.get() or '512'
        threads = self._adv_threads_var.get() or '1'
        lines = [
            'Cluster Size   :  %s' % cluster_label,
            'Sector Size    :  %s bytes' % sector,
            'Copy Threads   :  %s' % threads,
        ]
        if hasattr(self, '_adv_summary_var'):
            self._adv_summary_var.set('\n'.join(lines))

    def _adv_save_all(self):
        self._adv_clamp_threads()
        self._save_adv_params()
        self._adv_refresh_summary()
        if hasattr(self, '_adv_save_status'):
            self._adv_save_status.set('Saved \u2713')
            self.after(2500, lambda: self._adv_save_status.set(''))

    def _adv_reset_defaults(self):
        self._adv_cluster_var.set('Auto')
        if hasattr(self, '_adv_cluster_display_var'):
            self._adv_cluster_display_var.set('Auto')
        self._adv_sector_var.set('512')
        self._adv_threads_var.set('1')
        self._save_adv_params()
        self._adv_refresh_summary()

    def _adv_clamp_threads(self):
        try:
            n = int(self._adv_threads_var.get().strip())
            self._adv_threads_var.set(str(max(1, min(128, n))))
        except Exception:
            self._adv_threads_var.set('1')

    def _adv_ffpkg_refresh_summary(self):
        block  = self._adv_ffpkg_block_var.get()  or '65536'
        frag   = self._adv_ffpkg_frag_var.get()   or '65536'
        minfr  = self._adv_ffpkg_minfree_var.get() or '0'
        inode  = self._adv_ffpkg_inode_var.get()  or '262144'
        def _kb(v):
            try:
                n = int(v)
                return ('%dK' % (n//1024)) if n >= 1024 else str(n)
            except Exception:
                return v
        lines = [
            'Block Size     :  %s bytes  (%s)' % (block, _kb(block)),
            'Fragment Size  :  %s bytes  (%s)' % (frag,  _kb(frag)),
            'Min Free %%     :  %s%%' % minfr,
            'Bytes/Inode    :  %s bytes  (%s)' % (inode, _kb(inode)),
            'Sector Size    :  512 bytes  (locked)',
        ]
        if hasattr(self, '_adv_ffpkg_summary_var'):
            self._adv_ffpkg_summary_var.set('\n'.join(lines))

    def _adv_ffpkg_save_all(self):
        self._save_adv_params()
        self._adv_ffpkg_refresh_summary()
        if hasattr(self, '_adv_ffpkg_save_status'):
            self._adv_ffpkg_save_status.set('Saved \u2713')
            self.after(2500, lambda: self._adv_ffpkg_save_status.set(''))

    def _adv_ffpkg_reset_defaults(self):
        self._adv_ffpkg_block_var.set('65536')
        self._adv_ffpkg_frag_var.set('65536')
        self._adv_ffpkg_minfree_var.set('0')
        self._adv_ffpkg_inode_var.set('262144')
        # Sync display vars
        for attr in ('_adv_ffpkg_block_display_var', '_adv_ffpkg_frag_display_var',
                     '_adv_ffpkg_inode_display_var'):
            if hasattr(self, attr):
                getattr(self, attr).set('')
        self._save_adv_params()
        self._adv_ffpkg_refresh_summary()

