    def _build_shutdown_section(self, body):
        """Shutdown / Sleep after task section in Settings tab."""
        tk.Frame(body, bg=BORDER, height=1).pack(fill='x', padx=24, pady=(0, 12))

        hdr_row = tk.Frame(body, bg=BG)
        hdr_row.pack(fill='x', padx=24, pady=(0, 6))
        tk.Label(hdr_row, text='Shutdown / Sleep after task',
                 font=('Segoe UI', 11, 'bold'), bg=BG, fg=TEXT).pack(side='left')

        tk.Label(body,
                 text='Automatically shut down, restart or sleep the PC when a task completes.',
                 font=('Segoe UI', 8), bg=BG, fg=MUTED,
                 anchor='w').pack(fill='x', padx=24, pady=(0, 8))

        card = tk.Frame(body, bg=SURFACE2,
                        highlightbackground=BORDER, highlightthickness=1)
        card.pack(fill='x', padx=24, pady=(0, 16))
        inner = tk.Frame(card, bg=SURFACE2)
        inner.pack(fill='x', padx=14, pady=10)

        # Action selector
        self._shutdown_action_var = tk.StringVar(
            value=self._settings.get('shutdown_action', 'none'))
        action_row = tk.Frame(inner, bg=SURFACE2)
        action_row.pack(fill='x', pady=(0, 8))
        tk.Label(action_row, text='Action:',
                 font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                 width=10, anchor='w').pack(side='left')
        for val, lbl in [('none',     'None — do nothing'),
                         ('shutdown', '⏻ Shut down'),
                         ('restart',  '🔄 Restart'),
                         ('sleep',    '💤 Sleep')]:
            tk.Radiobutton(action_row, text=lbl,
                           variable=self._shutdown_action_var, value=val,
                           font=('Segoe UI', 9), bg=SURFACE2, fg=TEXT,
                           activebackground=SURFACE2, selectcolor=BG,
                           cursor='hand2',
                           command=self._save_shutdown_settings
                           ).pack(side='left', padx=(0, 16))

        # Delay
        delay_row = tk.Frame(inner, bg=SURFACE2)
        delay_row.pack(fill='x', pady=(0, 8))
        tk.Label(delay_row, text='Delay:',
                 font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                 width=10, anchor='w').pack(side='left')
        self._shutdown_delay_var = tk.StringVar(
            value=str(self._settings.get('shutdown_delay', 60)))
        import tkinter.ttk as _ttsd
        delay_cb = _ttsd.Combobox(delay_row,
                                   textvariable=self._shutdown_delay_var,
                                   values=['0', '30', '60', '120', '300', '600'],
                                   state='readonly',
                                   font=('Segoe UI', 9), width=6)
        delay_cb.pack(side='left')
        tk.Label(delay_row,
                 text='seconds after task completes  (0 = immediate, no cancel window)',
                 font=('Segoe UI', 8), bg=SURFACE2, fg='#444444'
                 ).pack(side='left', padx=(8, 0))
        self._shutdown_delay_var.trace('w',
            lambda *a: self._save_shutdown_settings())

        # Trigger checkboxes
        tk.Label(inner, text='Trigger after:',
                 font=('Segoe UI', 9), bg=SURFACE2, fg=MUTED,
                 anchor='w').pack(anchor='w', pady=(4, 4))

        self._shutdown_on_exfat_var    = tk.BooleanVar(
            value=self._settings.get('shutdown_on_exfat', True))
        self._shutdown_on_ffpkg_var    = tk.BooleanVar(
            value=self._settings.get('shutdown_on_ffpkg', True))
        self._shutdown_on_backport_var = tk.BooleanVar(
            value=self._settings.get('shutdown_on_backport', False))
        self._shutdown_on_ftp_var      = tk.BooleanVar(
            value=self._settings.get('shutdown_on_ftp', False))

        triggers_row = tk.Frame(inner, bg=SURFACE2)
        triggers_row.pack(fill='x')
        for var, lbl in [
            (self._shutdown_on_exfat_var,    'exFAT queue finished'),
            (self._shutdown_on_ffpkg_var,    'ffpkg queue finished'),
            (self._shutdown_on_backport_var, 'Backport finished'),
            (self._shutdown_on_ftp_var,      'FTP upload finished'),
        ]:
            tk.Checkbutton(triggers_row, text=lbl, variable=var,
                           font=('Segoe UI', 9), bg=SURFACE2, fg=TEXT,
                           activebackground=SURFACE2, selectcolor=BG,
                           cursor='hand2',
                           command=self._save_shutdown_settings
                           ).pack(side='left', padx=(0, 16))

        self._shutdown_status_var = tk.StringVar(value='')
        tk.Label(inner, textvariable=self._shutdown_status_var,
                 font=('Segoe UI', 8), bg=SURFACE2, fg=WARNING,
                 anchor='w').pack(fill='x', pady=(6, 0))

    def _save_shutdown_settings(self):
        self._settings['shutdown_action']       = self._shutdown_action_var.get()
        self._settings['shutdown_delay']        = int(self._shutdown_delay_var.get() or 60)
        self._settings['shutdown_on_exfat']     = self._shutdown_on_exfat_var.get()
        self._settings['shutdown_on_ffpkg']     = self._shutdown_on_ffpkg_var.get()
        self._settings['shutdown_on_backport']  = self._shutdown_on_backport_var.get()
        self._settings['shutdown_on_ftp']       = self._shutdown_on_ftp_var.get()
        save_settings(self._settings)

    def _trigger_shutdown(self, trigger):
        """Call after task completes. trigger = 'exfat'|'ffpkg'|'backport'|'ftp'"""
        action = self._settings.get('shutdown_action', 'none')
        if action == 'none':
            return
        if not self._settings.get('shutdown_on_' + trigger, False):
            return
        delay  = int(self._settings.get('shutdown_delay', 60))
        labels = {'shutdown': 'Shut down', 'restart': 'Restart', 'sleep': 'Sleep'}
        if delay == 0:
            self.after(0, self._execute_shutdown, action)
        else:
            self.after(0, self._shutdown_countdown, action, labels.get(action, action), delay)

    def _shutdown_countdown(self, action, label, seconds_left):
        dlg = tk.Toplevel(self)
        dlg.title('PC ' + label + ' scheduled')
        dlg.configure(bg=BG)
        dlg.resizable(False, False)
        dlg.attributes('-topmost', True)

        tk.Label(dlg, text='\u23fb  ' + label + ' scheduled',
                 font=('Segoe UI', 13, 'bold'), bg=BG, fg=WARNING,
                 padx=24, pady=16).pack()
        countdown_var = tk.StringVar()
        tk.Label(dlg, textvariable=countdown_var,
                 font=('Segoe UI', 10), bg=BG, fg=MUTED, padx=24).pack()

        cancelled = [False]
        def _cancel():
            cancelled[0] = True
            dlg.destroy()
            self._log('[SHUTDOWN] %s cancelled by user.\n' % label)

        tk.Button(dlg, text='\u2717  Cancel ' + label,
                  font=('Segoe UI', 10, 'bold'),
                  bg=DANGER, fg=TEXT, activebackground='#c0392b',
                  relief='flat', bd=0, padx=20, pady=10,
                  cursor='hand2', command=_cancel).pack(pady=(8, 20))

        def _tick(n):
            if cancelled[0] or not dlg.winfo_exists():
                return
            if n <= 0:
                dlg.destroy()
                self._execute_shutdown(action)
                return
            m, s = divmod(n, 60)
            countdown_var.set(
                '%s in %dm %02ds  —  click Cancel to abort' % (label, m, s))
            dlg.after(1000, _tick, n - 1)

        _tick(seconds_left)
        # Don't grab_set — let other dialogs (like the Complete messagebox) coexist

    def _execute_shutdown(self, action):
        import subprocess as _sp
        try:
            if action == 'shutdown':
                _sp.run(['shutdown', '/s', '/t', '5',
                         '/c', 'exFAT Image Builder task complete'],
                        creationflags=_sp.CREATE_NO_WINDOW)
            elif action == 'restart':
                _sp.run(['shutdown', '/r', '/t', '5'],
                        creationflags=_sp.CREATE_NO_WINDOW)
            elif action == 'sleep':
                _sp.run(['rundll32.exe', 'powrprof.dll,SetSuspendState', '0', '1', '0'],
                        creationflags=_sp.CREATE_NO_WINDOW)
            self._log('[SHUTDOWN] %s command sent.\n' % action.capitalize())
        except Exception as e:
            self._log('[SHUTDOWN] Error: %s\n' % str(e))

    def _browse_osfmount(self):
        p = filedialog.askopenfilename(
            title='Locate OSFMount.exe or osfmount.com',
            filetypes=[('OSFMount binary',  'OSFMount.exe osfmount.com'),
                       ('OSFMount executable', '*.exe'),
                       ('OSFMount CLI wrapper', '*.com'),
                       ('All files', '*.*')])
        if p:
            p = p.replace('/', '\\')
            self._osfmount_path_var.set(p)
            self._settings['osfmount_path'] = p
            save_settings(self._settings)
            self._refresh_osf_status()

    def _detect_osfmount(self):
        found = self._find_osfmount()
        if found:
            self._osfmount_path_var.set(found)
            self._settings['osfmount_path'] = found
            save_settings(self._settings)
            self._refresh_osf_status()
        else:
            self._osf_found_var.set('\u2717 Not found — use Browse to locate it manually')

    def _refresh_osf_status(self):
        found = self._find_osfmount()
        # Auto-heal: if detection found a real binary, but the saved
        # path either doesn't match it or doesn't exist on disk, update
        # the settings entry so the build path (which validates) and
        # the Settings panel (which just displays) stay in sync.
        if found:
            try:
                saved = (self._settings.get('osfmount_path') or '').strip()
                if (not saved) or (not os.path.isfile(saved)) or \
                        (os.path.normcase(saved) !=
                         os.path.normcase(found)):
                    self._settings['osfmount_path'] = found
                    save_settings(self._settings)
                    try:
                        self._osfmount_path_var.set(found)
                    except Exception:
                        pass
            except Exception:
                pass

            self._osf_found_var.set('\u2713 Found: ' + found)
            if hasattr(self, '_osf_found_var'):
                try:
                    # Hide the banner if it was shown
                    for w in self.winfo_children():
                        if isinstance(w, tk.Frame) and w.cget('bg') == '#3a1500':
                            w.pack_forget()
                except Exception:
                    pass
        else:
            self._osf_found_var.set('\u2717 Not detected — click Browse to locate OSFMount.exe or osfmount.com')


    def _build_history_tab(self, parent):
        # Carved out in Step 1 — see ui/tab_history.py
        from ui.tab_history import build_history_tab
        build_history_tab(parent, self)

    def _history_refresh(self, list_frame):
        """Reload and display history entries, applying filters if set.

        Step 10 (v2.1.2): rewritten to render rows in the new design with
        proper grid columns matching the table header (Game / Type / Output
        / Size / Duration / When / Status / Actions). UI-only change.
        """
        from ui.tab_history import _humanize_when, _detect_kind, _COLS, _icon_btn

        # Theme constants — pulled here so the row builder uses tokens
        from tkinter_theme import COLORS as _TC, FONTS as _TF

        for w in list_frame.winfo_children():
            w.destroy()
        try:
            with open(self._history_path(), 'r') as f:
                history = json.load(f)
        except Exception:
            history = []

        # Apply filters
        search   = ''
        show_ok  = True
        show_bad = True
        try:
            search   = self._hist_search_var.get().strip().lower()
            show_ok  = self._hist_show_success.get()
            show_bad = self._hist_show_failed.get()
        except Exception:
            pass

        filtered = []
        for h in history:
            ok = h.get('success', True)
            if ok and not show_ok:
                continue
            if not ok and not show_bad:
                continue
            if search:
                hay = (h.get('title', '') + ' ' + h.get('title_id', '') + ' '
                       + h.get('output', '') + ' ' + h.get('folder', '')).lower()
                if search not in hay:
                    continue
            filtered.append(h)

        if not filtered:
            msg = ('No build history yet — finish a build to populate this list.'
                   if not history
                   else 'No matches for current filter.')
            tk.Label(list_frame, text=msg,
                     font=('Segoe UI', 10), bg=_TC['bg_2'], fg=_TC['fg_5'],
                     pady=40).pack(fill='x')
            return

        for entry in filtered:
            row = tk.Frame(list_frame, bg=_TC['bg_2'])
            row.pack(fill='x')

            # Configure same column grid as the header
            for i, (key, _label, width) in enumerate(_COLS):
                if width is None:
                    row.grid_columnconfigure(i, weight=1, uniform='col')
                else:
                    row.grid_columnconfigure(i, weight=0, minsize=width)

            inner = tk.Frame(row, bg=_TC['bg_2'])
            inner.grid(row=0, column=0, columnspan=len(_COLS),
                       sticky='ew')
            for i, (key, _label, width) in enumerate(_COLS):
                if width is None:
                    inner.grid_columnconfigure(i, weight=1, uniform='col2')
                else:
                    inner.grid_columnconfigure(i, weight=0, minsize=width)

            ok = entry.get('success', True)
            kind = _detect_kind(entry)

            # Folder/output for action callbacks
            folder = entry.get('folder', '')
            out_path = entry.get('output', '')
            output_dir = (os.path.dirname(out_path)
                          if out_path else folder)

            # Hover effect — subtle bg lift
            def _hover_in(_e=None, w=inner):
                w.configure(bg=_TC['bg_3'])
                for ch in w.winfo_children():
                    try:
                        ch.configure(bg=_TC['bg_3'])
                        # Also recolor any sub-frames
                        for sub in ch.winfo_children():
                            try:
                                if not hasattr(sub, '_pill_protected'):
                                    sub.configure(bg=_TC['bg_3'])
                            except Exception:
                                pass
                    except Exception:
                        pass
            def _hover_out(_e=None, w=inner):
                w.configure(bg=_TC['bg_2'])
                for ch in w.winfo_children():
                    try:
                        ch.configure(bg=_TC['bg_2'])
                        for sub in ch.winfo_children():
                            try:
                                if not hasattr(sub, '_pill_protected'):
                                    sub.configure(bg=_TC['bg_2'])
                            except Exception:
                                pass
                    except Exception:
                        pass
            inner.bind('<Enter>', _hover_in)
            inner.bind('<Leave>', _hover_out)

            # ── Col 0: Game (title + meta line) ──
            game_cell = tk.Frame(inner, bg=_TC['bg_2'])
            game_cell.grid(row=0, column=0, sticky='ew',
                            padx=(14, 8), pady=10)
            tk.Label(game_cell, text=entry.get('title', '(no title)'),
                     font=(_TF['body'][0], 10, 'bold'),
                     bg=_TC['bg_2'], fg=_TC['fg_0'],
                     anchor='w'
                     ).pack(fill='x')
            sub = ' \u00b7 '.join(filter(None, [
                entry.get('title_id', ''),
                ('v' + entry['version']) if entry.get('version') else '',
            ]))
            if sub:
                tk.Label(game_cell, text=sub,
                         font=_TF['mono_sm'],
                         bg=_TC['bg_2'], fg=_TC['accent_hi'],
                         anchor='w'
                         ).pack(fill='x')

            # ── Col 1: Type pill ──
            type_cell = tk.Frame(inner, bg=_TC['bg_2'])
            type_cell.grid(row=0, column=1, sticky='w', padx=(0, 8))
            type_schemes = {
                'exfat':    (_TC['accent_08'],  _TC['accent_hi'], 'EXFAT'),
                'ffpkg':    (_TC['teal_bg'],    _TC['teal_hi'],   'FFPKG'),
                'backport': (None,              _TC['purple'],    'BACKPORT'),
                'unknown':  (_TC['bg_3'],       _TC['fg_4'],      '?'),
            }
            tbg, tfg, tlabel = type_schemes.get(kind, type_schemes['unknown'])
            if tbg is None:
                tbg = '#1f1228'  # purple-tinted
            type_pill = tk.Label(type_cell, text=' ' + tlabel + ' ',
                                 font=(_TF['mono_sm'][0], 9, 'bold'),
                                 bg=tbg, fg=tfg, padx=4, pady=2)
            type_pill._pill_protected = True
            type_pill.pack(anchor='w')

            # ── Col 2: Output path ──
            out_lbl_text = out_path if out_path else '— no output —'
            # Truncate from the left if too long
            if len(out_lbl_text) > 60:
                out_lbl_text = '\u2026' + out_lbl_text[-58:]
            out_lbl = tk.Label(inner, text=out_lbl_text,
                               font=_TF['mono_sm'],
                               bg=_TC['bg_2'], fg=_TC['fg_4'],
                               anchor='w',
                               cursor='hand2' if (out_path and
                                                  os.path.isdir(output_dir or '')) else '')
            out_lbl.grid(row=0, column=2, sticky='ew', padx=(0, 8))
            if out_path and output_dir and os.path.isdir(output_dir):
                out_lbl.bind('<Button-1>',
                    lambda e, p=output_dir: os.startfile(p))

            # ── Col 3: Size (right-aligned) ──
            if out_path and os.path.isfile(out_path):
                try:
                    sz = os.path.getsize(out_path)
                    if sz >= 1024**3:
                        size_text = '%.1f GB' % (sz / 1024**3)
                    else:
                        size_text = '%d MB' % (sz // 1024**2)
                except Exception:
                    size_text = '—'
            else:
                size_text = '—'
            tk.Label(inner, text=size_text,
                     font=_TF['mono_sm'],
                     bg=_TC['bg_2'], fg=_TC['fg_4'],
                     anchor='e'
                     ).grid(row=0, column=3, sticky='e', padx=(0, 8))

            # ── Col 4: Duration (right-aligned, currently always — not stored) ──
            tk.Label(inner, text='—',
                     font=_TF['mono_sm'],
                     bg=_TC['bg_2'], fg=_TC['fg_5'],
                     anchor='e'
                     ).grid(row=0, column=4, sticky='e', padx=(0, 8))

            # ── Col 5: When ──
            tk.Label(inner, text=_humanize_when(entry.get('time', '')),
                     font=_TF['mono_sm'],
                     bg=_TC['bg_2'], fg=_TC['fg_4'],
                     anchor='w'
                     ).grid(row=0, column=5, sticky='w', padx=(0, 8))

            # ── Col 6: Status pill ──
            status_cell = tk.Frame(inner, bg=_TC['bg_2'])
            status_cell.grid(row=0, column=6, sticky='w', padx=(0, 8))
            if ok:
                spill_bg, spill_fg, spill_text = (
                    _TC['success_bg'], _TC['success_hi'], '\u2713 SUCCESS')
            else:
                spill_bg, spill_fg, spill_text = (
                    _TC['danger_bg'],  _TC['danger_hi'],  '\u2717 FAILED')
            spill = tk.Label(status_cell, text=' ' + spill_text + ' ',
                             font=(_TF['mono_sm'][0], 9, 'bold'),
                             bg=spill_bg, fg=spill_fg, padx=4, pady=2)
            spill._pill_protected = True
            spill.pack(anchor='w')

            # ── Col 7: Actions (icon buttons) ──
            actions = tk.Frame(inner, bg=_TC['bg_2'])
            actions.grid(row=0, column=7, sticky='e', padx=(0, 14))

            # 📂 Open output folder
            if output_dir and os.path.isdir(output_dir):
                _icon_btn(actions, '\U0001f4c2',
                          tooltip='Open folder',
                          command=lambda p=output_dir: os.startfile(p)
                          ).pack(side='left', padx=1)
            # ↻ Re-queue
            if folder and os.path.isdir(folder):
                _icon_btn(actions, '\u21bb',
                          tooltip='Re-queue',
                          command=lambda f=folder: self._add_to_queue_from_path(f),
                          accent=True
                          ).pack(side='left', padx=1)
            # ✕ Remove from history (decorative — no per-entry remove
            #    callback exists; would need backend work)
            #    For now, do nothing on click; tooltip says removal isn't
            #    yet supported per-entry. The Clear-history button does
            #    bulk wipe.

            # Hairline divider below the row
            tk.Frame(list_frame, bg=_TC['border_2'], height=1
                     ).pack(fill='x')

    def _history_clear(self):
        if messagebox.askyesno('Clear history',
                'Delete all build history? This cannot be undone.'):
            try:
                import os as _os
                _os.remove(self._history_path())
            except Exception:
                pass
            # Refresh the tab
            for frame, builder in [(self._tab_hist_frame, self._build_history_tab)]:
                for w in frame.winfo_children():
                    w.destroy()
                builder(frame)

