    def _y2jb_log_write(self, text):
        self._y2jb_log.config(state='normal')
        self._y2jb_log.insert('end', text)
        self._y2jb_log.see('end')
        self._y2jb_log.config(state='disabled')

    def _y2jb_clear_log(self):
        self._y2jb_log.config(state='normal')
        self._y2jb_log.delete('1.0', 'end')
        self._y2jb_log.config(state='disabled')

    def _y2jb_check_pkg(self, region):
        path = self._y2jb_pkg_paths[region].get()
        if not path or not os.path.isfile(path):
            self._y2jb_pkg_status[region].set('\u2717 File not found')
            return
        size_gb = os.path.getsize(path) / 1024**3
        self._y2jb_pkg_status[region].set(
            '\u2713 Ready  —  %.2f GB' % size_gb)

    def _y2jb_save_connection(self):
        self._settings['y2jb_ftp_port'] = self._y2jb_ftp_port.get()
        self._settings['y2jb_dpi_port'] = self._y2jb_dpi_port.get()
        self._settings['ftp_ip'] = self._y2jb_ps5_ip.get()
        save_settings(self._settings)
        self._y2jb_log_write('[Y2JB] Connection settings saved.\n')

    def _y2jb_test_ftp(self):
        import ftplib
        ip   = self._y2jb_ps5_ip.get().strip()
        port = int(self._y2jb_ftp_port.get().strip() or '2121')
        if not ip:
            messagebox.showwarning('Y2JB', 'Enter a PS5 IP address first.')
            return
        def worker():
            try:
                ftp = ftplib.FTP()
                ftp.connect(ip, port, timeout=5)
                ftp.login()
                ftp.quit()
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] FTP connection to %s:%d OK \u2713\n' % (ip, port))
            except Exception as e:
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] FTP connection failed: %s\n' % str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _y2jb_test_dpi(self):
        """Test the etaHEN Direct Package Installer V2 endpoint."""
        import socket
        ip   = self._y2jb_ps5_ip.get().strip()
        port = int(self._y2jb_dpi_port.get().strip() or '12800')
        if not ip:
            messagebox.showwarning('Y2JB', 'Enter a PS5 IP address first.')
            return
        def worker():
            self.after(0, self._y2jb_log_write,
                       '[Y2JB] Testing DPI at %s:%d ...\n' % (ip, port))
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.settimeout(5)
                s.connect((ip, port))
                s.close()
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] DPI port %d is open \u2713\n' % port +
                           '[Y2JB] PKG install should work.\n')
            except socket.timeout:
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] DPI test failed: timeout (port %d not responding)\n' % port +
                           '[Y2JB] Make sure etaHEN is running and DPI V2 is enabled in Services.\n')
            except ConnectionRefusedError:
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] DPI test failed: connection refused on port %d\n' % port +
                           '[Y2JB] DPI V2 is not running. Enable it in etaHEN Services.\n')
            except Exception as e:
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] DPI test failed: %s\n' % str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _y2jb_update_bar(self, pct):
        try:
            w = self._y2jb_inst_bar.winfo_width()
            fill_w = int(w * pct / 100)
            self._y2jb_inst_bar.coords(
                self._y2jb_inst_bar_rect, 0, 0, fill_w, 10)
            self._y2jb_inst_bar.itemconfig(
                self._y2jb_inst_bar_rect,
                fill=SUCCESS if pct >= 100 else ACCENT)
        except Exception:
            pass

    def _y2jb_set_progress(self, pct, step='', eta=''):
        self._y2jb_inst_pct_val = pct
        self._y2jb_update_bar(pct)
        self._y2jb_inst_step.set(step)
        self._y2jb_inst_pct.set(eta)

    def _y2jb_install_pkg(self, region):
        pkg_path = self._y2jb_pkg_paths[region].get().strip()
        if not pkg_path or not os.path.isfile(pkg_path):
            messagebox.showwarning('Y2JB',
                'No %s PKG file selected.\nBrowse for the PKG file first.' % region)
            return
        ip       = self._y2jb_ps5_ip.get().strip()
        dpi_port = self._y2jb_dpi_port.get().strip() or '12800'
        if not ip:
            messagebox.showwarning('Y2JB', 'Enter a PS5 IP address first.')
            return

        self._y2jb_clear_log()
        self._y2jb_set_progress(0, 'Preparing to send %s PKG...' % region, '')
        self._y2jb_log_write('[Y2JB] Installing %s YouTube PKG\n' % region)
        self._y2jb_log_write('[Y2JB] File: %s\n' % os.path.basename(pkg_path))
        self._y2jb_log_write('[Y2JB] Target: http://%s:%s/upload\n' % (ip, dpi_port))
        self._y2jb_log_write('[Y2JB] Size: %.2f GB\n\n' % (
            os.path.getsize(pkg_path) / 1024**3))

        def worker():
            import http.client, ssl
            boundary = 'X-INSOMNIA-BOUNDARY'
            try:
                file_size = os.path.getsize(pkg_path)
                filename  = os.path.basename(pkg_path)

                # Build multipart headers
                header = (
                    '--%s\r\n'
                    'Content-Disposition: form-data; name="file"; filename="%s"\r\n'
                    'Content-Type: application/octet-stream\r\n\r\n'
                ) % (boundary, filename)
                footer = '\r\n--%s--\r\n' % boundary

                header_b = header.encode('utf-8')
                footer_b = footer.encode('utf-8')
                total_size = len(header_b) + file_size + len(footer_b)

                conn = http.client.HTTPConnection(ip, int(dpi_port), timeout=30)
                conn.putrequest('POST', '/upload')
                conn.putheader('Content-Type',
                               'multipart/form-data; boundary=%s' % boundary)
                conn.putheader('Content-Length', str(total_size))
                conn.endheaders()

                # Send header
                conn.send(header_b)

                # Stream file in chunks with progress
                sent = 0
                chunk_size = 512 * 1024  # 512KB chunks
                start_t = time.time()
                with open(pkg_path, 'rb') as f:
                    while True:
                        chunk = f.read(chunk_size)
                        if not chunk:
                            break
                        conn.send(chunk)
                        sent += len(chunk)
                        pct   = (sent / file_size) * 90  # 0-90%, last 10% for response
                        elapsed = time.time() - start_t
                        speed = (sent / 1024 / 1024) / elapsed if elapsed > 0 else 0
                        rem   = (file_size - sent) / 1024 / 1024 / speed if speed > 0 else 0
                        eta_s = 'ETA: %dm %02ds' % (int(rem//60), int(rem%60)) if rem > 0 else ''
                        step  = '[%s] Sending... %.2f / %.2f GB  (%.1f MB/s)' % (
                            region,
                            sent / 1024**3,
                            file_size / 1024**3,
                            speed)
                        self.after(0, self._y2jb_set_progress, pct, step, eta_s)

                # Send footer
                conn.send(footer_b)

                self.after(0, self._y2jb_set_progress, 95,
                           'Waiting for PS5 to confirm...', '')
                self.after(0, self._y2jb_log_write,
                           '\n[Y2JB] PKG sent. Waiting for PS5 response...\n')

                # Read response
                resp = conn.getresponse()
                body = resp.read().decode('utf-8', errors='replace')
                conn.close()

                if resp.status == 200 or 'success' in body.lower() or 'install' in body.lower():
                    self.after(0, self._y2jb_set_progress, 100,
                               '\u2713 %s PKG is now installing on PS5!' % region,
                               'Check your PS5 — installation will appear in the queue')
                    self.after(0, self._y2jb_log_write,
                               '[Y2JB] \u2713 Success! YouTube %s PKG is installing.\n' % region)
                    self.after(0, self._y2jb_log_write,
                               '[Y2JB] Response: %s\n' % body[:200])
                else:
                    raise Exception('HTTP %d: %s' % (resp.status, body[:200]))

            except Exception as e:
                self.after(0, self._y2jb_set_progress, 0, 'Failed', '')
                self.after(0, self._y2jb_log_write,
                           '\n[Y2JB] \u2717 Error: %s\n' % str(e))
                self.after(0, messagebox.showerror, 'Y2JB Install Failed',
                           'Failed to send %s PKG:\n\n%s\n\n'
                           'Make sure etaHEN is running with Direct Package\n'
                           'Installer V2 enabled in Services.' % (region, str(e)))

        threading.Thread(target=worker, daemon=True).start()

