    def _y2jb_browse_dat(self):
        p = filedialog.askopenfilename(
            title='Select download0.dat file',
            filetypes=[('DAT files', '*.dat'), ('All files', '*.*')])
        if p:
            self._y2jb_dat_path.set(p.replace('/', '\\'))

    def _y2jb_place_dat(self):
        """Upload download0.dat to the correct PS5 path via FTP."""
        import ftplib
        dat_file = self._y2jb_dat_path.get().strip()
        if not dat_file or not os.path.isfile(dat_file):
            messagebox.showwarning('Y2JB', 'Select a download0.dat file first.')
            return
        region = getattr(self, '_y2jb_dat_region', tk.StringVar(value='USA')).get()
        DAT_PATHS = {
            'USA': '/user/download/PPSA01650',
            'EU':  '/user/download/PPSA01651',
            'JP':  '/user/download/PPSA01652',
        }
        remote_dir  = DAT_PATHS.get(region, '/user/download/PPSA01650')
        remote_path = remote_dir + '/download0.dat'
        ip   = self._y2jb_ps5_ip.get().strip()
        port = int(self._y2jb_ftp_port.get().strip() or '2121')
        if not ip:
            messagebox.showwarning('Y2JB', 'Enter a PS5 IP address first.')
            return
        self._y2jb_dat_status.set('Connecting...')
        self._y2jb_log_write('[Y2JB] Placing download0.dat for %s region\n' % region)
        self._y2jb_log_write('[Y2JB] Remote path: %s\n' % remote_path)

        def worker():
            try:
                ftp = ftplib.FTP()
                ftp.connect(ip, port, timeout=15)
                ftp.login()
                # Ensure directory exists
                try:
                    ftp.mkd(remote_dir)
                except Exception:
                    pass  # already exists
                with open(dat_file, 'rb') as f:
                    ftp.storbinary('STOR ' + remote_path, f)
                ftp.quit()
                msg = '\u2713 download0.dat placed at %s' % remote_path
                self.after(0, self._y2jb_dat_status.set, msg)
                self.after(0, self._y2jb_log_write, '[Y2JB] ' + msg + '\n')
                self.after(0, messagebox.showinfo, 'Y2JB',
                           'download0.dat placed successfully!\n\nPath: ' + remote_path)
            except Exception as e:
                self.after(0, self._y2jb_dat_status.set, '\u2717 Failed: ' + str(e))
                self.after(0, self._y2jb_log_write, '[Y2JB] Error: %s\n' % str(e))
                self.after(0, messagebox.showerror, 'Y2JB Error', str(e))

        threading.Thread(target=worker, daemon=True).start()

    def _y2jb_browse_icon(self):
        p = filedialog.askopenfilename(
            title='Select 512x512 icon0.png',
            filetypes=[('PNG files', '*.png'), ('All files', '*.*')])
        if p:
            self._y2jb_icon_path.set(p.replace('/', '\\'))

    def _y2jb_upload_icon(self):
        """Upload a custom 512x512 PNG as icon0.png for selected region(s) via FTP."""
        import ftplib
        icon_file = self._y2jb_icon_path.get().strip()
        if not icon_file or not os.path.isfile(icon_file):
            messagebox.showwarning('Y2JB', 'Select an icon0.png file first.')
            return

        # Validate it is a PNG and 512x512
        try:
            import struct, zlib
            with open(icon_file, 'rb') as _f:
                sig = _f.read(8)
            if sig != b'\x89PNG\r\n\x1a\n':
                messagebox.showwarning('Y2JB', 'Selected file is not a valid PNG.')
                return
            with open(icon_file, 'rb') as _f:
                _f.read(8)           # skip signature
                _f.read(4)           # IHDR length
                chunk_type = _f.read(4)
                if chunk_type != b'IHDR':
                    raise ValueError('Missing IHDR')
                w = struct.unpack('>I', _f.read(4))[0]
                h = struct.unpack('>I', _f.read(4))[0]
            if w != 512 or h != 512:
                messagebox.showwarning('Y2JB',
                    'Icon must be exactly 512x512 pixels.\n'
                    'Your image is %dx%d.' % (w, h))
                return
        except Exception as e:
            messagebox.showwarning('Y2JB', 'Could not read PNG info: %s' % e)
            return

        selected = [r for r, v in self._y2jb_icon_regions.items() if v.get()]
        if not selected:
            messagebox.showwarning('Y2JB', 'Select at least one region.')
            return

        ip   = self._y2jb_ps5_ip.get().strip()
        port = int(self._y2jb_ftp_port.get().strip() or '2121')
        if not ip:
            messagebox.showwarning('Y2JB', 'Enter a PS5 IP address first.')
            return

        ICON_PATHS = {
            'USA': '/user/appmeta/PPSA01650/icon0.png',
            'EU':  '/user/appmeta/PPSA01651/icon0.png',
            'JP':  '/user/appmeta/PPSA01652/icon0.png',
        }

        self._y2jb_icon_status.set('Connecting...')
        self._y2jb_log_write('[Y2JB] Uploading icon0.png to region(s): %s\n' % ', '.join(selected))

        def worker():
            try:
                ftp = ftplib.FTP()
                ftp.connect(ip, port, timeout=15)
                ftp.login()
                ok = []
                for reg in selected:
                    remote_path = ICON_PATHS[reg]
                    remote_dir  = remote_path.rsplit('/', 1)[0]
                    # Ensure directory exists
                    try:
                        ftp.mkd(remote_dir)
                    except Exception:
                        pass  # already exists
                    with open(icon_file, 'rb') as f:
                        ftp.storbinary('STOR ' + remote_path, f)
                    self.after(0, self._y2jb_log_write,
                               '[Y2JB] \u2713 Uploaded to %s\n' % remote_path)
                    ok.append(reg)
                ftp.quit()
                msg = '\u2713 Icon uploaded for: %s' % ', '.join(ok)
                self.after(0, self._y2jb_icon_status.set, msg)
                self.after(0, messagebox.showinfo, 'Y2JB',
                           'icon0.png uploaded successfully!\n\n'
                           + '\n'.join(ICON_PATHS[r] for r in ok)
                           + '\n\nRestart the PS5 or re-launch YouTube for the icon to refresh.')
            except Exception as e:
                self.after(0, self._y2jb_icon_status.set, '\u2717 Failed: ' + str(e))
                self.after(0, self._y2jb_log_write, '[Y2JB] Icon upload error: %s\n' % str(e))
                self.after(0, messagebox.showerror, 'Y2JB Error', str(e))

        threading.Thread(target=worker, daemon=True).start()

    def _y2jb_patch_local(self):
        folder = self._y2jb_patch_dir.get().strip()
        if not folder or not os.path.isdir(folder):
            messagebox.showwarning('Y2JB', 'Select a folder first.')
            return
        # Get selected region and title ID
        region = getattr(self, '_y2jb_patch_region', tk.StringVar(value='USA')).get()
        REGION_IDS = {'USA': 'PPSA01650', 'EU': 'PPSA01165', 'JP': 'PPSA01380'}
        title_id = REGION_IDS.get(region, 'PPSA01650')

        self._y2jb_clear_log()
        self._y2jb_patch_status.set('')
        self._y2jb_log_write('[Y2JB] Patching local files for %s (%s)\n' % (region, title_id))

        results = []

        # ── patch param.json ──
        pj = os.path.join(folder, 'param.json')
        if os.path.isfile(pj):
            try:
                import json, shutil
                shutil.copy2(pj, pj + '.bak')
                with open(pj, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                # Set contentVersion to max to prevent update prompt
                if 'contentVersion' in data:
                    data['contentVersion'] = '99.999.999'
                # Block update check URL
                if 'versionFileUri' in data:
                    data['versionFileUri'] = 'http://127.0.0.2'
                # Legacy fields
                if 'localVersion' in data and 'masterVersion' in data:
                    data['localVersion'] = data['masterVersion']
                with open(pj, 'w', encoding='utf-8') as f:
                    json.dump(data, f, indent=2)
                results.append('\u2713 param.json patched (backup created)')
                self._y2jb_log_write('[Y2JB] param.json patched.\n')
            except Exception as e:
                results.append('\u2717 param.json failed: ' + str(e))
                self._y2jb_log_write('[Y2JB] param.json error: %s\n' % str(e))
        else:
            results.append('\u25cb param.json not found')

        # ── patch appinfo.db (tbl_appinfo) ──
        # Sets VERSION_FILE_URI to 127.0.0.2 and CONTENT_VERSION to 99.999.999
        appinfo_path = os.path.join(folder, 'appinfo.db')
        if os.path.isfile(appinfo_path):
            try:
                import sqlite3 as _sql, shutil
                shutil.copy2(appinfo_path, appinfo_path + '.bak')
                conn = _sql.connect(appinfo_path)
                cur  = conn.cursor()
                # Patch VERSION_FILE_URI — blocks update check URL
                cur.execute(
                    "UPDATE tbl_appinfo SET val = 'http://127.0.0.2' "
                    "WHERE titleId = ? AND key = 'VERSION_FILE_URI'",
                    (title_id,))
                rows1 = cur.rowcount
                # Patch CONTENT_VERSION — sets to max so no update appears
                cur.execute(
                    "UPDATE tbl_appinfo SET val = '99.999.999' "
                    "WHERE titleId = ? AND key = 'CONTENT_VERSION'",
                    (title_id,))
                rows2 = cur.rowcount
                conn.commit()
                conn.close()
                if rows1 > 0 or rows2 > 0:
                    results.append('\u2713 appinfo.db patched (VERSION_FILE_URI + CONTENT_VERSION)')
                    self._y2jb_log_write('[Y2JB] appinfo.db: VERSION_FILE_URI=%d rows, CONTENT_VERSION=%d rows\n' % (rows1, rows2))
                else:
                    results.append('\u25cb appinfo.db — no rows found for %s (YouTube not installed?)' % title_id)
                    self._y2jb_log_write('[Y2JB] appinfo.db: no rows for %s\n' % title_id)
            except Exception as e:
                results.append('\u2717 appinfo.db failed: ' + str(e))
                self._y2jb_log_write('[Y2JB] appinfo.db error: %s\n' % str(e))
        else:
            results.append('\u25cb appinfo.db not found — skipped')

        # ── patch app.db (tbl_contentinfo) ──
        # Sets $.CONTENT_VERSION and $.VERSION_FILE_URI in AppInfoJson
        appdb_path = os.path.join(folder, 'app.db')
        if os.path.isfile(appdb_path):
            try:
                import sqlite3 as _sql2, shutil
                shutil.copy2(appdb_path, appdb_path + '.bak')
                conn = _sql2.connect(appdb_path)
                cur  = conn.cursor()
                cur.execute(
                    "UPDATE tbl_contentinfo "
                    "SET AppInfoJson = json_set(AppInfoJson, "
                    "'$.CONTENT_VERSION', '99.999.999', "
                    "'$.VERSION_FILE_URI', 'http://127.0.0.2') "
                    "WHERE titleId = ?",
                    (title_id,))
                rows = cur.rowcount
                conn.commit()
                conn.close()
                if rows > 0:
                    results.append('\u2713 app.db patched (tbl_contentinfo AppInfoJson)')
                    self._y2jb_log_write('[Y2JB] app.db: tbl_contentinfo updated %d rows\n' % rows)
                else:
                    results.append('\u25cb app.db — no rows for %s' % title_id)
                    self._y2jb_log_write('[Y2JB] app.db: no rows for %s\n' % title_id)
            except Exception as e:
                results.append('\u2717 app.db failed: ' + str(e))
                self._y2jb_log_write('[Y2JB] app.db error: %s\n' % str(e))
        else:
            results.append('\u25cb app.db not found — skipped')

        summary = '\n'.join(results)
        self._y2jb_patch_status.set(summary)
        self._y2jb_log_write('\n[Y2JB] Done:\n' + summary + '\n')
        messagebox.showinfo('Y2JB Patch Complete',
            '%s (%s) patch results:\n\n%s\n\nBackups created with .bak extension.' % (
                region, title_id, summary))

    def _y2jb_auto_block_ftp(self):
        """Patch param.json, appinfo.db and app.db directly on PS5 via FTP."""
        import ftplib, json, io, tempfile, os as _os, sqlite3 as _sql
        region = getattr(self, '_y2jb_patch_region', tk.StringVar(value='USA')).get()
        REGION_IDS = {'USA': 'PPSA01650', 'EU': 'PPSA01651', 'JP': 'PPSA01652'}
        title_id = REGION_IDS.get(region, 'PPSA01650')
        ip   = self._y2jb_ps5_ip.get().strip()
        port = int(self._y2jb_ftp_port.get().strip() or '2121')
        if not ip:
            messagebox.showwarning('Y2JB', 'Enter a PS5 IP address first.')
            return
        if not messagebox.askyesno('Y2JB Auto-Block',
                'This will patch ALL 3 files for %s (%s) directly on your PS5:\n\n'
                '  • param.json  — contentVersion + versionFileUri\n'
                '  • appinfo.db  — VERSION_FILE_URI + CONTENT_VERSION\n'
                '  • app.db      — AppInfoJson in tbl_contentinfo\n\n'
                '\u26a0  Make sure you are in the PS5 Settings menu before proceeding!\n\n'
                'Continue?' % (region, title_id)):
            return

        self._y2jb_clear_log()
        self._y2jb_patch_status.set('Connecting...')

        # param.json locations
        PARAM_PATHS = [
            '/user/appmeta/%s/param.json' % title_id,
            '/system_data/priv/appmeta/%s/param.json' % title_id,
        ]
        # DB locations
        APPINFO_PATHS = [
            '/system_data/priv/mms/appinfo.db',
        ]
        APP_PATHS = [
            '/system_data/priv/mms/app.db',
        ]

        def _patch_db_ftp(ftp, remote_path, patch_fn, label):
            """Download DB via FTP, patch in a temp file, upload back."""
            try:
                buf = io.BytesIO()
                ftp.retrbinary('RETR ' + remote_path, buf.write)
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] Downloaded %s (%d bytes)\n' % (label, buf.tell()))
                # Write to temp file, patch, read back
                with tempfile.NamedTemporaryFile(suffix='.db', delete=False) as tmp:
                    tmp.write(buf.getvalue())
                    tmp_path = tmp.name
                try:
                    # Backup on PS5
                    backup_path = remote_path + '.bak'
                    buf.seek(0)
                    try:
                        ftp.storbinary('STOR ' + backup_path, buf)
                    except Exception:
                        pass
                    # Apply patch
                    patch_fn(tmp_path, title_id)
                    # Upload patched DB back
                    with open(tmp_path, 'rb') as pf:
                        ftp.storbinary('STOR ' + remote_path, pf)
                    self.after(0, self._y2jb_log_write,
                               '[Y2JB] \u2713 Patched and uploaded: %s\n' % label)
                    return True
                finally:
                    try:
                        _os.remove(tmp_path)
                    except Exception:
                        pass
            except ftplib.error_perm:
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] Not found on PS5: %s\n' % label)
            except Exception as e2:
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] Error patching %s: %s\n' % (label, e2))
            return False

        def _patch_appinfo(db_path, tid):
            conn = _sql.connect(db_path)
            cur  = conn.cursor()
            cur.execute(
                "UPDATE tbl_appinfo SET val = 'http://127.0.0.2' "
                "WHERE titleId = ? AND key = 'VERSION_FILE_URI'", (tid,))
            cur.execute(
                "UPDATE tbl_appinfo SET val = '99.999.999' "
                "WHERE titleId = ? AND key = 'CONTENT_VERSION'", (tid,))
            conn.commit()
            conn.close()

        def _patch_appdb(db_path, tid):
            conn = _sql.connect(db_path)
            cur  = conn.cursor()
            cur.execute(
                "UPDATE tbl_contentinfo "
                "SET AppInfoJson = json_set(AppInfoJson, "
                "'$.CONTENT_VERSION', '99.999.999', "
                "'$.VERSION_FILE_URI', 'http://127.0.0.2') "
                "WHERE titleId = ?", (tid,))
            conn.commit()
            conn.close()

        def worker():
            try:
                ftp = ftplib.FTP()
                ftp.connect(ip, port, timeout=10)
                ftp.login()
                self.after(0, self._y2jb_log_write,
                           '[Y2JB] Connected — patching %s (%s)\n' % (region, title_id))

                results = []

                # ── param.json ──
                param_patched = 0
                for remote_path in PARAM_PATHS:
                    try:
                        buf = io.BytesIO()
                        ftp.retrbinary('RETR ' + remote_path, buf.write)
                        buf.seek(0)
                        data = json.loads(buf.read().decode('utf-8'))
                        backup_path = remote_path.replace('param.json', 'param_backup.json')
                        buf.seek(0)
                        try:
                            ftp.storbinary('STOR ' + backup_path, buf)
                        except Exception:
                            pass
                        if 'contentVersion' in data:
                            data['contentVersion'] = '99.999.999'
                        if 'versionFileUri' in data:
                            data['versionFileUri'] = 'http://127.0.0.2'
                        if 'localVersion' in data and 'masterVersion' in data:
                            data['localVersion'] = data['masterVersion']
                        patched_bytes = json.dumps(data, indent=2).encode('utf-8')
                        ftp.storbinary('STOR ' + remote_path, io.BytesIO(patched_bytes))
                        self.after(0, self._y2jb_log_write,
                                   '[Y2JB] \u2713 param.json patched: %s\n' % remote_path)
                        param_patched += 1
                    except ftplib.error_perm:
                        self.after(0, self._y2jb_log_write,
                                   '[Y2JB] Not found: %s\n' % remote_path)
                    except Exception as e2:
                        self.after(0, self._y2jb_log_write,
                                   '[Y2JB] param.json error: %s\n' % str(e2))
                results.append('param.json: %d/%d patched' % (param_patched, len(PARAM_PATHS)))

                # ── appinfo.db ──
                ai_ok = False
                for p in APPINFO_PATHS:
                    if _patch_db_ftp(ftp, p, _patch_appinfo, 'appinfo.db'):
                        ai_ok = True
                        break
                results.append('appinfo.db: ' + ('\u2713 patched' if ai_ok else '\u25cb not found'))

                # ── app.db ──
                ap_ok = False
                for p in APP_PATHS:
                    if _patch_db_ftp(ftp, p, _patch_appdb, 'app.db'):
                        ap_ok = True
                        break
                results.append('app.db: ' + ('\u2713 patched' if ap_ok else '\u25cb not found'))

                ftp.quit()

                summary = '\n'.join(results)
                msg = '\u2713 Auto-Block complete for %s (%s):\n\n%s' % (region, title_id, summary)
                self.after(0, self._y2jb_patch_status.set,
                           '\u2713 Done — param:%d appinfo:%s app:%s' % (
                           param_patched, '\u2713' if ai_ok else '\u25cb',
                           '\u2713' if ap_ok else '\u25cb'))
                self.after(0, self._y2jb_log_write, '\n[Y2JB] ' + msg + '\n')
                if param_patched == 0 and not ai_ok and not ap_ok:
                    self.after(0, messagebox.showwarning, 'Y2JB',
                               'Nothing patched for %s.\nMake sure YouTube is installed.' % title_id)
                else:
                    self.after(0, messagebox.showinfo, 'Y2JB Auto-Block', msg)
            except Exception as e:
                self.after(0, self._y2jb_patch_status.set, '\u2717 Failed: ' + str(e))
                self.after(0, self._y2jb_log_write, '[Y2JB] Error: %s\n' % str(e))
                self.after(0, messagebox.showerror, 'Y2JB FTP Error', str(e))

        threading.Thread(target=worker, daemon=True).start()

