    def _help_text_fallback(self, parent):
        """Simple text fallback when tkinterweb isn't installed."""
        canvas = tk.Canvas(parent, bg=BG, highlightthickness=0)
        sb = tk.Scrollbar(parent, command=canvas.yview,
                          bg=SURFACE2, troughcolor=BG)
        canvas.configure(yscrollcommand=sb.set)
        sb.pack(side='right', fill='y')
        canvas.pack(side='left', fill='both', expand=True)
        body = tk.Frame(canvas, bg=BG)
        canvas.create_window((0,0), window=body, anchor='nw', tags='hb')
        body.bind('<Configure>', lambda e:
            canvas.configure(scrollregion=canvas.bbox('all')))
        canvas.bind('<Configure>', lambda e:
            canvas.itemconfig('hb', width=e.width))
        canvas.bind('<MouseWheel>',
            lambda e: canvas.yview_scroll(int(-1*(e.delta/120)), 'units'))

        def section(title):
            tk.Label(body, text=title, font=('Segoe UI', 11, 'bold'),
                     bg=BG, fg=ACCENT, anchor='w').pack(
                         fill='x', padx=32, pady=(20,4))
            tk.Frame(body, bg=BORDER, height=1).pack(fill='x', padx=32)

        def qa(question, answer):
            tk.Label(body, text=question, font=('Segoe UI', 9, 'bold'),
                     bg=BG, fg=TEXT, anchor='w',
                     wraplength=680, justify='left').pack(
                         fill='x', padx=40, pady=(10,2))
            tk.Label(body, text=answer, font=('Segoe UI', 9),
                     bg=BG, fg=MUTED, anchor='w',
                     wraplength=680, justify='left').pack(
                         fill='x', padx=40, pady=(0,4))

        tk.Label(body, text='Help & Tutorial',
                 font=('Segoe UI', 16, 'bold'), bg=BG, fg=TEXT).pack(
                     anchor='w', padx=32, pady=(20,2))
        tk.Label(body,
                 text='exFAT Image Builder v' + APP_VERSION + '  —  by DecKerr97\n'
                      'Click "Open in browser" above for the full tutorial.',
                 font=('Segoe UI', 9), bg=BG, fg='#3a3a3a').pack(anchor='w', padx=32)

        section('Getting Started')
        qa('Do I need Python installed?',
           'No. The .exe includes everything. The only requirement is OSFMount (free). '
           'Go to Settings → OSFMount → Browse if it is not detected automatically.')
        qa('What is OSFMount?',
           'A free tool by PassMark that mounts disk image files as Windows drive letters. '
           'Required for building images. Download from osforensics.com.')
        qa('The app says OSFMount not detected',
           'Go to the Settings tab → OSFMount section → click Browse and navigate to '
           'osfmount.com wherever you installed it. It saves automatically.')

        section('Building')
        qa('What does the temp folder do?',
           'During a build the app creates a blank disk image, mounts it, formats it '
           'as exFAT, copies all game files in, then saves it to your output directory. '
           'The temp folder is where this staging happens — it needs free space equal '
           'to the game size.')
        qa('Build failed — what do I check?',
           '1. OSFMount is installed and detected in Settings.\n'
           '2. eboot.bin exists in the game folder root.\n'
           '3. The output drive has enough free space.\n'
           '4. The temp folder drive also has enough free space.\n'
           '5. The app is running as Administrator.')
        qa('Image not dismounting after build?',
           'Click the ⏏ Force Dismount button in the bottom right of the Build tab. '
           'It uses the same method as Windows Explorer Eject, which works even when '
           'OSFMount\'s own command fails.')

        section('FTP & PS5')
        qa('How do I find my PS5 IP address?',
           'On the PS5: Settings → Network → View Connection Status. '
           'Or use Auto-detect PS5 IP in Settings.')
        qa('FTP won\'t connect',
           'Make sure the PS5 FTP server is running in your homebrew settings. '
           'Check the IP address and port number.')

        tk.Frame(body, bg=BG, height=32).pack()

    def _help_load_bundled(self):
        """Load the bundled tutorial HTML (base64 embedded in the exe)."""
        try:
            import base64 as _b64
            html_bytes = _b64.b64decode(_TUTORIAL_HTML_B64)
            self._help_html_data[0] = html_bytes
            self._help_render(html_bytes)
            self._help_status_var.set('Showing bundled tutorial v' + APP_VERSION)
        except Exception as e:
            self._help_status_var.set('Could not load tutorial: ' + str(e))

    def _help_fetch_latest(self):
        """Try to fetch the latest tutorial from GitHub raw content."""
        self._help_status_var.set('Checking for updated tutorial...')
        url = ('https://raw.githubusercontent.com/'
               'kerrdec97/ps5-exfat-builder/main/tutorial.html')
        def worker():
            try:
                import urllib.request
                req = urllib.request.Request(url,
                    headers={'User-Agent': 'ps5-exfat-builder/' + APP_VERSION})
                with urllib.request.urlopen(req, timeout=8) as r:
                    html_bytes = r.read()
                # Only update if it's actually HTML
                if b'<!DOCTYPE' in html_bytes[:20] or b'<html' in html_bytes[:20]:
                    self._help_html_data[0] = html_bytes
                    self.after(0, self._help_render, html_bytes)
                    self.after(0, self._help_status_var.set,
                               'Tutorial loaded from GitHub \u2713')
                else:
                    self.after(0, self._help_status_var.set,
                               'Showing bundled tutorial (GitHub version not available)')
            except Exception:
                self.after(0, self._help_status_var.set,
                           'Showing bundled tutorial (offline)')
        threading.Thread(target=worker, daemon=True).start()

    def _help_render(self, html_bytes):
        """Render HTML in the viewer if tkinterweb is available."""
        hv = self._help_viewer[0]
        if hv is None:
            return  # text fallback already shown
        try:
            html_str = html_bytes.decode('utf-8', errors='replace')
            hv.load_html(html_str)
        except Exception:
            pass

    def _help_open_browser(self):
        """Save tutorial to temp file and open in default browser."""
        import webbrowser, tempfile as _tf
        html_bytes = self._help_html_data[0]
        if not html_bytes:
            # Try bundled
            try:
                import base64 as _b64
                html_bytes = _b64.b64decode(_TUTORIAL_HTML_B64)
            except Exception:
                messagebox.showwarning('Tutorial not available',
                    'Could not load the tutorial file.')
                return
        try:
            tmp = _tf.NamedTemporaryFile(
                suffix='.html', prefix='exfat_tutorial_',
                delete=False, mode='wb')
            tmp.write(html_bytes)
            tmp.close()
            webbrowser.open('file:///' + tmp.name.replace('\\', '/'))
        except Exception as e:
            messagebox.showerror('Error', str(e))

    def _build_library_tab(self, parent):
        # Step 40 (v2.5.4): Library tab now hosts two sub-tabs —
        # Source Dumps (the original Library scan view) and Built
        # Images (the previous standalone Images tab). Both views
        # are about your game collection, just at different stages
        # of the build pipeline.
        from ui.tab_library import build_library_tab
        from ui.tab_images  import build_images_tab
        from ui.shared.cards import build_subtabs

        self._library_subtab_activate = build_subtabs(parent, [
            ('dumps',  '\U0001f4da Source Dumps',
                lambda f: build_library_tab(f, self)),
            ('images', '\U0001f4be Built Images',
                lambda f: build_images_tab(f, self)),
        ])

    # ── Library helpers ───────────────────────────────────────────────────────
    def _lib_render_folders(self):
        # Step 5 (v2.0.7): rewritten to use the FolderChip shared widget,
        # rendering chips in a horizontal flex-style layout to match the
        # design system mock. Logic-wise (paths shown, remove behavior)
        # nothing changed.
        from ui.shared.cards import FolderChip
        for w in self._lib_folder_frame.winfo_children():
            w.destroy()
        if not self._lib_folders:
            tk.Label(self._lib_folder_frame,
                     text=_('No scan folders added yet — click "+ Add folder"'),
                     font=('Segoe UI', 8), bg=BG, fg=MUTED,
                     pady=4).pack(anchor='w')
            return
        # Pack chips left-to-right; tk Frames don't wrap automatically, but
        # the typical case is 1–4 folders which fit comfortably. For more,
        # the parent's overflow is hidden by the pack manager — acceptable
        # since the mock uses overflow-x:auto and we have far less than the
        # 18-tab bar's wider strip in real life.
        for i, folder in enumerate(self._lib_folders):
            idx = i  # capture
            # Optional meta — count of games found in this folder
            meta = None
            if self._lib_games:
                count = sum(1 for g in self._lib_games
                            if g.get('folder', '').startswith(folder))
                if count:
                    meta = '%d game%s' % (count, '' if count == 1 else 's')
            chip = FolderChip(self._lib_folder_frame, path=folder,
                              meta=meta,
                              on_remove=lambda ix=idx:
                                  self._lib_remove_folder(ix))
            chip.pack(side='left', padx=(0, 8))

    def _lib_add_folder(self):
        p = filedialog.askdirectory(title='Select folder containing PS5 game dumps')
        if not p:
            return
        p = os.path.normpath(p)
        if p not in self._lib_folders:
            self._lib_folders.append(p)
            self._settings['lib_folders'] = self._lib_folders
            save_settings(self._settings)
        self._lib_render_folders()

    def _lib_remove_folder(self, idx):
        if not (0 <= idx < len(self._lib_folders)):
            return
        folder = self._lib_folders[idx]
        # Step 37 (v2.5.1): confirm before removing — prevents accidental
        # taps on the small ✕ button. Show how many games will be
        # removed from the listing as part of the confirmation.
        affected = sum(1 for g in self._lib_games or []
                       if g.get('folder', '').startswith(folder))
        msg = ('Stop scanning this folder?\n\n'
               '%s\n\n'
               'This removes the folder from the Library scan list.\n'
               'Files on disk are NOT touched.' % folder)
        if affected:
            msg += '\n\n%d game%s currently shown from this folder will be hidden.' % (
                affected, '' if affected == 1 else 's')
        if not messagebox.askyesno('Remove scan folder', msg):
            return
        self._lib_folders.pop(idx)
        self._settings['lib_folders'] = self._lib_folders
        save_settings(self._settings)
        # Drop games whose folder lives under the removed root, so the
        # grid/list updates immediately without requiring a full re-scan.
        if self._lib_games:
            self._lib_games = [g for g in self._lib_games
                               if not g.get('folder', '').startswith(folder)]
        self._lib_render_folders()
        self._lib_apply_filter()

    def _lib_scan(self):
        if not self._lib_folders:
            messagebox.showwarning('No folders',
                'Add at least one scan folder first.')
            return
        self._lib_status_var.set('Counting folders...')
        self._lib_games = []
        for w in self._lib_grid_frame.winfo_children():
            w.destroy()

        # Show progress bar
        self._lib_progress_frame.pack(fill='x', padx=24, pady=(0, 4),
                                       before=self._lib_canvas.master)
        self._lib_set_scan_progress(0, 0, 0)

        def worker():
            # First pass — count total subfolders so we can show progress
            total_entries = 0
            for base in self._lib_folders:
                if not os.path.isdir(base):
                    continue
                try:
                    total_entries += sum(1 for e in os.scandir(base) if e.is_dir())
                except Exception:
                    pass

            games       = []
            scanned     = 0

            for base in self._lib_folders:
                if not os.path.isdir(base):
                    continue
                try:
                    for entry in os.scandir(base):
                        if not entry.is_dir():
                            continue
                        if (entry.name.lower() in {
                                '$recycle.bin', 'system volume information',
                                '$sysreset', '$windows.~bt', '$windows.~ws',
                                'recovery', 'recycler', 'found.000', 'lost+found'}
                                or entry.name.startswith('.')):
                            continue
                        folder = entry.path
                        scanned += 1

                        # Update progress every folder
                        pct = int(scanned / total_entries * 100) if total_entries else 0
                        self.after(0, self._lib_set_scan_progress,
                                   pct, scanned, len(games))

                        # Check for eboot.bin up to 3 levels deep
                        has_eboot = os.path.isfile(
                            os.path.join(folder, 'eboot.bin'))
                        eboot_root = folder

                        if not has_eboot:
                            try:
                                for sub in os.scandir(folder):
                                    if sub.is_dir():
                                        if os.path.isfile(
                                                os.path.join(sub.path, 'eboot.bin')):
                                            has_eboot = True
                                            eboot_root = sub.path
                                            break
                            except Exception:
                                pass

                        if not has_eboot:
                            try:
                                for sub in os.scandir(folder):
                                    if sub.is_dir():
                                        for subsub in os.scandir(sub.path):
                                            if subsub.is_dir():
                                                if os.path.isfile(
                                                        os.path.join(subsub.path, 'eboot.bin')):
                                                    has_eboot = True
                                                    eboot_root = subsub.path
                                                    break
                                    if has_eboot:
                                        break
                            except Exception:
                                pass

                        if not has_eboot:
                            # Step 21 (v2.2.2): dropped the PPSA-name
                            # fallback. A folder that just *looks* like
                            # a game folder (PPSA-shaped name) but has
                            # no eboot.bin within 3 levels is a partial
                            # dump, not a playable game — and clutters
                            # the library with cards that can never
                            # display cover art or be built. Skip it.
                            continue

                        title, title_id, version = get_game_info(eboot_root)
                        if not title_id:
                            for part in [os.path.basename(eboot_root),
                                         os.path.basename(folder)]:
                                m = re.search(
                                    r'((?:PPSA|CUSA|PPLH)\d{5})',
                                    part, re.IGNORECASE)
                                if m:
                                    title_id = m.group(1).upper()
                                    break
                        cover   = self._load_cover_art(eboot_root)
                        size    = self._get_folder_size(folder)
                        sfo_inf = self._read_sfo_info(eboot_root)
                        sdk_v   = sfo_inf.get('SYSTEM_VER', 0) if sfo_inf else 0
                        # Deep fallback: if shallow SFO/JSON didn't yield a
                        # version, walk the folder for any param.json/sfo —
                        # catches DLPSGAME-style nested dumps where the
                        # meta files live a few levels under eboot.
                        if not sdk_v:
                            try:
                                deep = ExFATBuilder._read_sdk_from_folder(folder)
                                if deep:
                                    sdk_v = deep
                            except Exception as _e:
                                try:
                                    self._log(
                                        '[SCAN] Deep SDK probe failed for %s: %r\n'
                                        % (folder, _e))
                                except Exception:
                                    pass
                            if not sdk_v:
                                try:
                                    deep = ExFATBuilder._read_sdk_from_folder(eboot_root)
                                    if deep:
                                        sdk_v = deep
                                except Exception as _e:
                                    try:
                                        self._log(
                                            '[SCAN] Deep SDK probe failed for %s: %r\n'
                                            % (eboot_root, _e))
                                    except Exception:
                                        pass
                        games.append({
                            'folder':     eboot_root,
                            'title':      title or title_id or os.path.basename(folder),
                            'title_id':   title_id or '',
                            'version':    version or '',
                            'cover':      cover,
                            'size':       size,
                            'system_ver': sdk_v,
                        })
                except Exception:
                    pass

            games.sort(key=lambda g: g['title'].lower())
            self.after(0, self._lib_scan_done, games)

        threading.Thread(target=worker, daemon=True).start()

    def _lib_set_scan_progress(self, pct, scanned, found):
        """Update the scan progress bar and status text."""
        try:
            w = self._lib_prog_canvas.winfo_width() or 400
            fill_w = int(w * pct / 100)
            self._lib_prog_canvas.coords(self._lib_prog_fill, 0, 0, fill_w, 6)
            self._lib_prog_canvas.itemconfig(
                self._lib_prog_fill,
                fill=SUCCESS if pct >= 100 else ACCENT)
            if pct < 100:
                self._lib_status_var.set(
                    'Scanning...  %d%% — %d folder(s) checked, %d game(s) found'
                    % (pct, scanned, found))
        except Exception:
            pass

    def _lib_scan_done(self, games):
        # Step 29 (v2.2.10): dedupe by title_id, keeping the LARGEST
        # entry. Backport residue, partial decrypts, and other
        # non-playable subfolders that share a PPSA with a real dump
        # show as duplicate cards with much smaller sizes. Users want
        # only the playable copy.
        if games:
            best_by_id = {}
            no_id = []
            for g in games:
                tid = (g.get('title_id') or '').upper().replace('-', '')
                if not tid:
                    no_id.append(g)
                    continue
                cur = best_by_id.get(tid)
                if cur is None or g.get('size', 0) > cur.get('size', 0):
                    best_by_id[tid] = g
            games = list(best_by_id.values()) + no_id
            # Preserve original sort order roughly by re-sorting on title
            games.sort(key=lambda g: (g.get('title') or
                                       g.get('title_id') or '').lower())

        self._lib_games = games
        # Fill bar to 100% and hide after a moment
        self._lib_set_scan_progress(100, 0, len(games))
        self.after(1500, self._lib_progress_frame.pack_forget)
        self._lib_status_var.set(
            str(len(games)) + ' game(s) found across ' +
            str(len(self._lib_folders)) + ' folder(s)')
        # Step 5 (v2.0.7): also feed the new count pill in the page-head.
        # `_lib_count_var` is a new UI element introduced by ui/tab_library.py;
        # this is the only place we feed it, so the trace is one line and
        # doesn't change scan/render behavior.
        if hasattr(self, '_lib_count_var'):
            n_games = len(games)
            n_folders = len(self._lib_folders)
            self._lib_count_var.set(
                '%d game%s \u00b7 %d folder%s' %
                (n_games, '' if n_games == 1 else 's',
                 n_folders, '' if n_folders == 1 else 's'))
        self._lib_apply_filter()

    def _lib_apply_filter(self):
        query = self._lib_search_var.get().lower().strip() \
            if hasattr(self, '_lib_search_var') else ''
        if query:
            filtered = [g for g in self._lib_games
                        if query in g['title'].lower()
                        or query in g['title_id'].lower()]
        else:
            filtered = self._lib_games
        if hasattr(self, '_lib_view_mode') and self._lib_view_mode.get() == 'list':
            self._lib_render_list(filtered)
        else:
            self._lib_render_grid(filtered)

    def _lib_render_list(self, games=None):
        if games is None:
            games = self._lib_games
        for w in self._lib_grid_frame.winfo_children():
            w.destroy()
        if not games:
            tk.Label(self._lib_grid_frame, text='No games found',
                     font=('Segoe UI', 11), bg=BG, fg=MUTED,
                     pady=40).pack()
            return
        for i, game in enumerate(games):
            row_bg = QUEUE_ODD if i % 2 == 0 else QUEUE_EVEN
            row = tk.Frame(self._lib_grid_frame, bg=row_bg, cursor='hand2')
            row.pack(fill='x')

            # Cover thumbnail (small)
            thumb_lbl = tk.Label(row, bg=row_bg, text='\U0001f3ae',
                                  font=('Segoe UI', 14), fg='#333333',
                                  width=4, height=2)
            thumb_lbl.pack(side='left', padx=(8, 6), pady=4)
            if game.get('cover'):
                def load_thumb(path=game['cover'], lbl=thumb_lbl, bg=row_bg):
                    try:
                        img = _load_cover_image(path, target=40)
                        if img is None:
                            return
                        from PIL import ImageTk
                        photo = ImageTk.PhotoImage(img)
                        lbl.config(image=photo, text='', width=40, height=40)
                        lbl.image = photo
                    except Exception:
                        pass
                threading.Thread(target=load_thumb, daemon=True).start()

            # Title + meta
            info_col = tk.Frame(row, bg=row_bg)
            info_col.pack(side='left', fill='x', expand=True, pady=6)
            tk.Label(info_col, text=game['title'],
                     font=('Segoe UI', 9, 'bold'), bg=row_bg, fg=TEXT,
                     anchor='w').pack(anchor='w')
            meta = game['title_id']
            if game['version']:
                meta += '  v' + game['version']
            tk.Label(info_col, text=meta,
                     font=('Segoe UI', 8), bg=row_bg, fg=INFO_FG,
                     anchor='w').pack(anchor='w')

            # Size
            if game['size'] > 0:
                sz = ('%.1f GB' % (game['size'] / 1024**3)
                      if game['size'] >= 1024**3
                      else '%d MB' % (game['size'] // 1024**2))
                tk.Label(row, text=sz,
                         font=('Segoe UI', 8), bg=row_bg, fg='#444444',
                         anchor='e').pack(side='right', padx=12)

            # Bind click / right-click to context menu
            def _bind_ctx(widgets, g=game):
                for w in widgets:
                    w.bind('<Button-1>',   lambda e, gg=g: self._lib_context_menu(e, gg))
                    w.bind('<Double-Button-1>', lambda e, gg=g: self._add_to_queue_from_path(gg['folder']))
                    w.bind('<Button-3>',   lambda e, gg=g: self._lib_context_menu(e, gg))
            _bind_ctx([row, thumb_lbl, info_col] + list(info_col.winfo_children()))

    def _lib_render_grid(self, games=None):
        if games is None:
            games = self._lib_games
        for w in self._lib_grid_frame.winfo_children():
            w.destroy()
        if not games:
            tk.Label(self._lib_grid_frame,
                     text='No games found',
                     font=('Segoe UI', 11), bg=BG, fg=MUTED,
                     pady=40).pack()
            return
        try:
            canvas_w = self._lib_canvas.winfo_width()
        except Exception:
            canvas_w = 700
        # Step 34 (v2.2.15): card width matches the GameCard cover
        # frame (180px) plus inter-card gutter. Was 160 — that
        # underestimated cards and packed too many columns.
        card_w = 192
        cols   = max(1, canvas_w // (card_w + 12))
        for i, game in enumerate(games):
            row = i // cols
            col = i % cols
            self._lib_make_card(self._lib_grid_frame, game, row, col)

    def _lib_make_card(self, parent, game, row, col):
        # Step 5 (v2.0.7): rewritten to use the GameCard shared widget.
        # The cover image loads async into card.cover_label, the badges +
        # CUSA-id chip + hover effects are built into GameCard. Click and
        # right-click bindings match the legacy behavior.
        from ui.shared.cards import GameCard

        # Compute the card's status badge.
        # SDK threshold: HEN coverage reaches roughly FW 7.61 = SDK 16
        # in early 2026; games at SDK 18+ need a backport. (The legacy
        # threshold was >=8, set when PS5 firmware was around 4.x —
        # that's now stale and incorrectly flags every modern game.)
        status = None
        status_text = None
        if game.get('built'):
            status = 'built'
        else:
            sdk_val = game.get('system_ver', 0)
            if sdk_val and sdk_val >= 18:
                status = 'warn'
                status_text = 'SDK %d.xx+' % sdk_val
            elif sdk_val and sdk_val >= 16:
                # Edge of HEN coverage — show as backport-required
                status = 'backport'
                status_text = 'SDK %d' % sdk_val
            elif sdk_val and sdk_val >= 1:
                # Any detected SDK gets a badge — older games at SDK 2–4
                # don't strictly *need* a backport on jailbroken FW, but
                # users want to see what SDK each game has anyway.
                status = 'backport'
                status_text = 'SDK %d' % sdk_val

        # Format version + size for the meta row.
        # Compact the SFO version 'XX.YYY.ZZZ' to PS5-style 'vX.YY' so it
        # doesn't overflow the narrow card meta row. The patch (ZZZ) is
        # almost always 000 and is not shown to match PS5's own UI.
        version = None
        v_raw = game.get('version', '')
        if v_raw:
            try:
                parts = v_raw.split('.')
                major = int(parts[0])
                minor = int(parts[1]) if len(parts) > 1 else 0
                # PS5 shows "1.00", "1.18", "4.01" — major stripped of
                # leading zeros, minor as 2-digit padded.
                version = 'v%d.%02d' % (major, minor)
            except (ValueError, IndexError):
                # Non-numeric version string; truncate raw to 8 chars
                version = 'v' + v_raw[:8]
        size_text = None
        if game.get('size', 0) > 0:
            sz = game['size']
            size_text = ('%.1f GB' % (sz / 1024**3)
                         if sz >= 1024**3
                         else '%d MB' % (sz // 1024**2))

        card = GameCard(
            parent,
            title=game['title'],
            game_id=game.get('title_id', ''),
            version=version,
            size_text=size_text,
            status=status,
            status_text=status_text,
            on_click=lambda e, g=game: self._lib_context_menu(e, g),
            on_double=lambda e, g=game:
                self._add_to_queue_from_path(g['folder']),
            on_right=lambda e, g=game: self._lib_context_menu(e, g),
        )
        card.grid(row=row, column=col, padx=6, pady=6, sticky='nsew')
        parent.grid_columnconfigure(col, weight=1)

        # Async cover-art load — same threading pattern as the legacy code,
        # writes to card.cover_label which is the inner emoji/image label.
        if game.get('cover'):
            def load_art(path=game['cover'], lbl=card.cover_label):
                try:
                    img = _load_cover_image(path, target=180)
                    if img is None:
                        return
                    from PIL import ImageTk
                    photo = ImageTk.PhotoImage(img)
                    lbl.config(image=photo, text='')
                    lbl.image = photo  # keep reference (GC otherwise frees it)
                except Exception:
                    pass
            threading.Thread(target=load_art, daemon=True).start()

        # If SDK isn't already known, kick off the async detect — matches
        # the legacy behavior. The badge can't be added retroactively to
        # GameCard (the widget bakes its badge at construction time), so
        # for the SDK-warn case we just log it; the badge will appear on
        # the next render. This is acceptable because the typical path is
        # _lib_scan → games dict gets system_ver populated → render.
        if not game.get('system_ver'):
            def _maybe_log_sdk(folder=game['folder']):
                sdk = ExFATBuilder._read_sdk_from_folder(folder)
                if sdk:
                    game['system_ver'] = sdk
            threading.Thread(target=_maybe_log_sdk, daemon=True).start()

    def _lib_context_menu(self, event, game):
        menu = tk.Menu(self, tearoff=0, bg=SURFACE2, fg=TEXT,
                       activebackground=ACCENT, activeforeground=TEXT,
                       font=('Segoe UI', 9))
        menu.add_command(label='\U0001f3ae  ' + game['title'],
                         state='disabled', font=('Segoe UI', 9, 'bold'))
        menu.add_separator()
        menu.add_command(label='\u2795  Add to exFAT Queue',
                         command=lambda: self._lib_quick_add(game))
        menu.add_command(label='\u2795  Add to ffpkg Queue',
                         command=lambda: self._lib_quick_add_ffpkg(game))
        menu.add_command(label='\U0001f4cb  View details',
                         command=lambda: self._lib_show_detail(game))
        menu.add_separator()
        menu.add_command(label='\u26a1  Auto Backport',
                         command=lambda: self._lib_auto_backport(game))
        menu.add_separator()
        menu.add_command(label='\U0001f4c2  Open folder',
                         command=lambda: self._open_folder(game['folder']))
        menu.add_command(label='\U0001f5d1  Remove from library',
                         command=lambda: self._lib_remove_game(game))
        menu.tk_popup(event.x_root, event.y_root)

    def _lib_backport_all(self):
        """Queue all library games for auto backport in sequence."""
        games = [g for g in getattr(self, '_lib_games', [])
                 if os.path.isdir(g.get('folder', ''))]
        if not games:
            messagebox.showwarning('No games',
                'No games found in library. Add a folder and scan first.')
            return

        # Step 52 (v2.6.1): the saved zip destinations (set via the
        # Auto Backport form's "Originals zip" / "Backported zip"
        # fields) are the source of truth for where backups land. If
        # the user has those configured already, don't pop a redundant
        # "Select backup folder for ALL backports" picker — the queue
        # runner downstream already honors the same per-flow Tk vars
        # and settings keys (see _live_dest in run_all). The standalone
        # `out` variable was only ever used as a display string in the
        # confirmation messagebox; resolve it from the saved settings
        # instead. Only fall back to a picker if NOTHING is configured.
        def _resolved(setting_key, attr_name):
            v = getattr(self, attr_name, None)
            d = ''
            if v is not None:
                try:
                    d = (v.get() or '').strip()
                except Exception:
                    d = ''
            if not d:
                d = self._settings.get(setting_key, '').strip()
            if d:
                d = d.replace('/', '\\')
            return d if (d and os.path.isdir(d)) else ''

        orig_zip_dest = _resolved('abp_zip_orig_dest', '_abp_zip_orig_var')
        pat_zip_dest  = _resolved('abp_zip_pat_dest',  '_abp_zip_pat_var')

        if orig_zip_dest or pat_zip_dest:
            # Build a human-readable summary for the confirm dialog.
            if orig_zip_dest and pat_zip_dest:
                out_display = ('Originals zips: %s\nBackport zips:  %s'
                               % (orig_zip_dest, pat_zip_dest))
            elif orig_zip_dest:
                out_display = ('Originals zips: %s\n(backport zip dest not '
                               'configured — those zips will be skipped)'
                               % orig_zip_dest)
            else:
                out_display = ('Backport zips: %s\n(originals zip dest not '
                               'configured — those zips will be skipped)'
                               % pat_zip_dest)
        else:
            # Nothing configured — fall back to the original picker so
            # the user has at least one destination on file.
            picked = filedialog.askdirectory(
                title='Select backup folder for ALL backports '
                      '(used for both originals and backport zips)')
            if not picked:
                return
            picked = picked.replace('/', '\\')
            # Save to both keys so future runs don't re-prompt.
            self._settings['abp_zip_orig_dest'] = picked
            self._settings['abp_zip_pat_dest']  = picked
            try:
                save_settings(self._settings)
            except Exception:
                pass
            # Also push to the form Tk vars if they exist, so the
            # next visit to the Auto Backport tab shows the choice.
            for attr in ('_abp_zip_orig_var', '_abp_zip_pat_var'):
                v = getattr(self, attr, None)
                if v is not None:
                    try:
                        self.after(0, v.set, picked)
                    except Exception:
                        pass
            orig_zip_dest = pat_zip_dest = picked
            out_display = picked

        sdk = self._settings.get('abp_last_sdk', '4')
        sdk_win = tk.Toplevel(self)
        sdk_win.title('Target SDK')
        sdk_win.configure(bg=BG)
        sdk_win.resizable(False, False)
        sdk_var = tk.StringVar(value=sdk)
        tk.Label(sdk_win, text='Target SDK for all games:',
                 font=('Segoe UI', 10), bg=BG, fg=TEXT,
                 padx=20, pady=10).pack()
        import tkinter.ttk as _ttk
        ttk_cb = _ttk.Combobox(sdk_win, textvariable=sdk_var,
                                values=['4','5','6','7','8','9','10','11'],
                                state='readonly', font=('Segoe UI', 10), width=6)
        ttk_cb.pack(pady=(0,10))
        confirmed = [False]
        def _confirm():
            confirmed[0] = True
            sdk_win.destroy()
        tk.Button(sdk_win, text='Start Backport All',
                  font=('Segoe UI', 10, 'bold'),
                  bg='#9b59b6', fg=TEXT, relief='flat', bd=0,
                  padx=16, pady=8, cursor='hand2',
                  command=_confirm).pack(pady=(0,16))
        sdk_win.grab_set()
        self.wait_window(sdk_win)
        if not confirmed[0]:
            return

        try:
            sdk_int = int(sdk_var.get())
        except (ValueError, TypeError):
            messagebox.showwarning('Invalid Target SDK',
                'Target SDK must be a number between 1 and 10.\n'
                'Got: %r\n\nUsing default (4).' % sdk_var.get())
            sdk_int = 4
        # Clamp to SDKVersionPatcher's supported range [1,10]
        if sdk_int < 1 or sdk_int > 10:
            messagebox.showwarning('Target SDK out of range',
                'Target SDK %d is outside the supported range [1, 10].\n'
                'Clamping to %d.' % (sdk_int, max(1, min(10, sdk_int))))
            sdk_int = max(1, min(10, sdk_int))
        self._settings['abp_last_sdk'] = sdk_var.get()
        save_settings(self._settings)

        fakelib_src = self._settings.get('abp_fakelib', '').strip() or None

        if not messagebox.askyesno('Backport All',
                'Backport %d game(s) with SDK %d?\n\n%s\n\n'
                '%s\n\n'
                'This will run sequentially — may take a long time.'
                % (len(games), sdk_int,
                   '\n'.join('  • ' + g.get('title', g['folder'])
                             for g in games[:5]) +
                   ('\n  ... and %d more' % (len(games)-5) if len(games)>5 else ''),
                   out_display)):
            return

        self._switch_tab('backports')
        self._bp_mode_var.set('auto')
        self._bp_switch_mode()

        def _glog(text):
            self.after(0, self._log, '[BACKPORT ALL] ' + text + '\n')

        def run_all():
            ok_count   = 0
            fail_count = 0
            total      = len(games)
            self.after(0, self._log,
                       '[BACKPORT ALL] Starting — %d game(s) — SDK %d\n'
                       % (total, sdk_int))
            for i, game in enumerate(games):
                folder = game['folder']
                title  = game.get('title', os.path.basename(folder))
                self.after(0, self._abp_status_var.set,
                           'Backporting %d/%d: %s' % (i+1, total, title))
                self.after(0, self._abp_game_var.set, folder)
                self.after(0, self._abp_sdk_var.set, str(sdk_int))
                _glog('\n── %d/%d: %s ──' % (i+1, total, title))

                game_base = os.path.basename(folder.rstrip('\\/'))
                if ' - Auto Backport Backup' in game_base:
                    game_base = game_base[:game_base.index(' - Auto Backport Backup')]
                ts = time.strftime('%Y-%m-%d %H.%M.%S')
                backup_dir    = tempfile.mkdtemp(prefix='exfat_builder_abp_')
                originals_dir = os.path.join(backup_dir, 'originals')
                patched_dir   = os.path.join(backup_dir, 'patched')

                try:
                    import shutil as _sh

                    # Snapshot originals before fakelib
                    original_game_files = set()
                    for og_root, og_dirs, og_files in os.walk(folder):
                        og_dirs[:] = [d for d in og_dirs
                                      if d.lower() != 'decrypted']
                        for og_fn in og_files:
                            og_rel = os.path.relpath(
                                os.path.join(og_root, og_fn), folder)
                            original_game_files.add(og_rel.lower())

                    os.makedirs(originals_dir, exist_ok=True)
                    os.makedirs(patched_dir,   exist_ok=True)

                    # Apply fakelib
                    if fakelib_src and os.path.isdir(fakelib_src):
                        fakelib_dest = os.path.join(folder, 'fakelib')
                        os.makedirs(fakelib_dest, exist_ok=True)
                        for fl_root, _, fl_files in os.walk(fakelib_src):
                            for fl_fn in fl_files:
                                fl_src = os.path.join(fl_root, fl_fn)
                                fl_rel = os.path.relpath(fl_src, fakelib_src)
                                fl_dst = os.path.join(fakelib_dest, fl_rel)
                                os.makedirs(os.path.dirname(fl_dst), exist_ok=True)
                                _sh.copy2(fl_src, fl_dst)

                    # Run pipeline or fallback
                    bp_ok = False
                    try:
                        bp_path, bp_tmp = extract_backport(
                            self._settings.get('temp_dir') or None)
                        for p in [bp_tmp, os.path.join(bp_tmp, 'src')]:
                            if p not in sys.path:
                                sys.path.insert(0, p)
                        for mod in ['Backport', 'src.Archive', 'src.make_fself',
                                    'src.decrypt_fself', 'src.ps5_sdk_version_patcher']:
                            if mod in sys.modules:
                                del sys.modules[mod]
                        from Backport import PS5ELFProcessor
                        import io as _io, re as _re
                        processor = PS5ELFProcessor(use_colors=False)
                        old_stdout = sys.stdout
                        sys.stdout = _io.StringIO()
                        try:
                            results = processor.decrypt_and_sign_pipeline(
                                input_dir=folder, output_dir=patched_dir,
                                sdk_pair=sdk_int, paid=0x3100000000000002,
                                ptype=1, fakelib_source=fakelib_src,
                                create_backup=True, overwrite=True,
                                apply_libc_patch=True,
                                auto_revert_for_high_sdk=True,
                                verbose=False, save_to_config=False)
                        finally:
                            sys.stdout = old_stdout
                        # Copy patched back
                        for p_root, p_dirs, p_files in os.walk(patched_dir):
                            p_dirs[:] = [d for d in p_dirs
                                         if d.lower() != 'decrypted']
                            for p_fn in p_files:
                                p_src  = os.path.join(p_root, p_fn)
                                p_rel  = os.path.relpath(p_src, patched_dir)
                                parts  = p_rel.replace('/', '\\').split('\\')
                                gbase  = os.path.basename(folder.rstrip('\\/'))
                                if parts[0] == gbase:
                                    p_rel = os.path.join(*parts[1:])
                                p_dest = os.path.join(folder, p_rel)
                                os.makedirs(os.path.dirname(p_dest), exist_ok=True)
                                if (os.path.isfile(p_dest) and
                                        p_rel.lower() in original_game_files):
                                    orig_p = os.path.join(originals_dir, p_rel)
                                    if not os.path.isfile(orig_p):
                                        os.makedirs(os.path.dirname(orig_p),
                                                    exist_ok=True)
                                        _sh.copy2(p_dest, orig_p)
                                _sh.copy2(p_src, p_dest)
                        bp_ok = True
                    except Exception as bp_e:
                        _glog('⚠ Pipeline failed, using basic patch: ' + str(bp_e))

                    if bp_ok:
                        ok_count += 1
                        _glog('✓ Done: ' + title + ' — zipping...')
                        try:
                            import zipfile as _bpzf
                            prefix = self._sfo_zip_prefix(
                                folder, os.path.basename(folder.rstrip('\\/')))
                            _glog('📦 Prefix: ' + prefix)

                            def _zf_dir(src_dir, zip_path, extra_files=None, excl=None):
                                _ed = {d.lower() for d in (excl or [])} | {'decrypted'}
                                with _bpzf.ZipFile(zip_path, 'w', _bpzf.ZIP_DEFLATED) as zf:
                                    for zr, zd, zf2 in os.walk(src_dir):
                                        zd[:] = [d for d in zd if d.lower() not in _ed]
                                        for fn in zf2:
                                            fp = os.path.join(zr, fn)
                                            zf.write(fp, os.path.relpath(fp, src_dir))
                                    if extra_files:
                                        for abs_path, arcname in extra_files:
                                            if os.path.isfile(abs_path):
                                                zf.write(abs_path, arcname)

                            def _find_pj(gf):
                                if not gf or not os.path.isdir(gf):
                                    return None
                                for sub in [os.path.join('sce_sys','param.json'), 'param.json']:
                                    p = os.path.join(gf, sub)
                                    if os.path.isfile(p):
                                        return p
                                for root, dirs, files in os.walk(gf):
                                    dirs[:] = [d for d in dirs if d.lower() != 'decrypted']
                                    rel = os.path.relpath(root, gf)
                                    if (0 if rel == '.' else rel.count(os.sep)+1) > 3:
                                        dirs[:] = []
                                        continue
                                    if 'param.json' in files:
                                        return os.path.join(root, 'param.json')
                                return None

                            # Step 47 (v2.6.1): consult live Tk vars
                            # before settings, same fix as _get_dest in
                            # the single-game flow. Without this, the
                            # queue runner silently skipped the zip
                            # write when the form had a path but the
                            # settings key was empty/stale.
                            def _live_dest(setting_key, attr_name):
                                _v = getattr(self, attr_name, None)
                                _d = ''
                                if _v is not None:
                                    try:
                                        _d = (_v.get() or '').strip()
                                    except Exception:
                                        _d = ''
                                if not _d:
                                    _d = self._settings.get(setting_key, '').strip()
                                if _d:
                                    _d = _d.replace('/', '\\')
                                return _d

                            orig_dest   = _live_dest('abp_zip_orig_dest', '_abp_zip_orig_var')
                            pat_dest    = _live_dest('abp_zip_pat_dest',  '_abp_zip_pat_var')
                            saved_orig  = ''
                            saved_pat   = ''

                            # Find param.json to include in originals zip
                            _pj = _find_pj(game.get('folder', ''))
                            _pj_extra = [(_pj, 'sce_sys/param.json')] if _pj else []
                            if _pj:
                                _glog('📄 Adding param.json to originals zip')
                            else:
                                _glog('⚠ param.json not found for: ' + title)

                            # Step 51 (v2.6.1): also pull in the dump's
                            # `decrypted` folder if it exists. Same
                            # behaviour as the single-game flow — see
                            # _collect_decrypted_files in
                            # _abp_zip_backups for the full rationale.
                            def _find_dec(gf):
                                out = []
                                if not gf or not os.path.isdir(gf):
                                    return out
                                try:
                                    for root, dirs, _ in os.walk(gf):
                                        rel = os.path.relpath(root, gf)
                                        depth = 0 if rel == '.' else rel.count(os.sep) + 1
                                        if depth > 4:
                                            dirs[:] = []
                                            continue
                                        for d in list(dirs):
                                            if d.lower() == 'decrypted':
                                                dec_root = os.path.join(root, d)
                                                for dr, _dd, df in os.walk(dec_root):
                                                    for fn in df:
                                                        fp = os.path.join(dr, fn)
                                                        try:
                                                            if os.path.getsize(fp) == 0:
                                                                continue
                                                        except Exception:
                                                            pass
                                                        try:
                                                            arc = os.path.relpath(fp, gf).replace('\\', '/')
                                                        except Exception:
                                                            continue
                                                        out.append((fp, arc))
                                                dirs.remove(d)
                                except Exception:
                                    pass
                                return out

                            _dec_extra = _find_dec(game.get('folder', ''))
                            if _dec_extra:
                                try:
                                    _dec_mb = sum(
                                        os.path.getsize(p) for p, _ in _dec_extra
                                    ) / (1024.0 * 1024.0)
                                except Exception:
                                    _dec_mb = 0.0
                                _glog('🔓 Adding decrypted folder: %d file(s), '
                                      '%.1f MB' % (len(_dec_extra), _dec_mb))

                            _orig_extras = _pj_extra + _dec_extra

                            if orig_dest and os.path.isdir(orig_dest):
                                saved_orig = os.path.join(
                                    orig_dest, self._apply_name_case(prefix) + ' original files.zip')
                                _zf_dir(originals_dir, saved_orig,
                                        extra_files=_orig_extras, excl=['fakelib'])
                                _glog('📦 Originals zip saved')
                            if pat_dest and os.path.isdir(pat_dest):
                                saved_pat = os.path.join(
                                    pat_dest, self._apply_name_case(prefix) + ' backport files.zip')
                                _zf_dir(patched_dir, saved_pat)
                                _glog('📦 Backport zip saved')

                            # Log to BP Results tab
                            self.after(0, self._bpr_log_entry,
                                       prefix, saved_orig, saved_pat)
                        except Exception as ze:
                            _glog('⚠ Zip error: ' + str(ze))
                        # Clean up temp dir
                        try:
                            import shutil as _sh2
                            _sh2.rmtree(backup_dir, ignore_errors=True)
                        except Exception:
                            pass
                    else:
                        fail_count += 1
                        _glog('✗ Failed: ' + title)

                except Exception as e:
                    fail_count += 1
                    _glog('✗ Error on %s: %s' % (title, str(e)))

            def finish():
                self._abp_status_var.set(
                    '✓ Backport All complete — %d done, %d failed'
                    % (ok_count, fail_count))
                self._log('[BACKPORT ALL] Complete — %d done, %d failed\n'
                          % (ok_count, fail_count))
                messagebox.showinfo('Backport All complete',
                    '%d game(s) backported ✓\n%d failed'
                    % (ok_count, fail_count))
            self.after(0, finish)

        threading.Thread(target=run_all, daemon=True).start()

        # v3.0.0: OUTPUT LOG no longer auto-opens. User can click
        # the toggle if they want to follow progress in the log.

    def _lib_auto_backport(self, game):
        """Switch to Backports tab and pre-fill Auto Backport with this game."""
        self._switch_tab('backports')
        self._bp_mode_var.set('auto')
        self._bp_switch_mode()
        self._abp_game_var.set(game['folder'])
        self.after(300, self._abp_detect_sdk)
    def _lib_quick_add(self, game):
        odir = self.output_dir.get().strip()
        if not odir:
            odir = filedialog.askdirectory(title='Select output directory for ' + game['title'])
            if not odir:
                return
            odir = odir.replace('/', '\\')
            self.output_dir.set(odir)
            self._settings['output_dir'] = odir
            save_settings(self._settings)
        title, title_id, version = game['title'], game['title_id'], game['version']
        name = build_exfat_name(title or None, title_id or None, version or None)
        item = QueueItem(game['folder'], odir, name, title, title_id, version)
        self._queue.append(item)
        self._render_queue()
        self._switch_tab('build')
        self._set_status('Added to exFAT queue: ' + (title or title_id), SUCCESS)

    def _lib_quick_add_ffpkg(self, game):
        odir = self._ffpkg_output_dir.get().strip()
        if not odir:
            odir = filedialog.askdirectory(
                title='Select ffpkg output directory for ' + game['title'])
            if not odir:
                return
            odir = odir.replace('/', '\\')
            self._ffpkg_output_dir.set(odir)
            self._settings['ffpkg_output_dir'] = odir
            save_settings(self._settings)
        title, title_id, version = game['title'], game['title_id'], game['version']
        name = build_exfat_name(title or None, title_id or None, version or None)
        name = name.replace('.exfat', '.ffpkg')
        self._ffpkg_queue.append({
            'folder': game['folder'],
            'odir':   odir,
            'name':   name,
            'status': 'waiting',
        })
        self._ffpkg_render_queue()
        self._switch_tab('ffpkg')
        self._set_status('Added to ffpkg queue: ' + (title or title_id), SUCCESS)

    def _lib_remove_game(self, game):
        self._lib_games = [g for g in self._lib_games if g['folder'] != game['folder']]
        self._lib_apply_filter()
        self._lib_status_var.set(str(len(self._lib_games)) + ' game(s)')

    def _lib_show_detail(self, game):
        win = tk.Toplevel(self)
        win.title(game['title'])
        win.geometry('500x380')
        win.configure(bg=BG)
        win.resizable(False, False)
        win.transient(self)

        body = tk.Frame(win, bg=BG)
        body.pack(fill='both', expand=True, padx=24, pady=20)

        # Cover + info side by side
        top = tk.Frame(body, bg=BG)
        top.pack(fill='x', pady=(0, 16))

        # Cover
        cover_frame = tk.Frame(top, bg='#0a0a0a',
                               width=120, height=120)
        cover_frame.pack(side='left', padx=(0, 20))
        cover_frame.pack_propagate(False)
        cover_lbl = tk.Label(cover_frame, bg='#0a0a0a',
                             text='\U0001f3ae', font=('Segoe UI', 30),
                             fg='#2a2a2a')
        cover_lbl.pack(expand=True)

        if game.get('cover'):
            def load(path=game['cover'], lbl=cover_lbl):
                try:
                    from PIL import Image, ImageTk
                    img = Image.open(path).resize((120, 120), Image.LANCZOS)
                    photo = ImageTk.PhotoImage(img)
                    lbl.config(image=photo, text='')
                    lbl.image = photo
                except Exception:
                    pass
            threading.Thread(target=load, daemon=True).start()

        # Info
        info = tk.Frame(top, bg=BG)
        info.pack(side='left', fill='both', expand=True)

        tk.Label(info, text=game['title'],
                 font=('Segoe UI', 12, 'bold'), bg=BG, fg=TEXT,
                 wraplength=300, justify='left', anchor='w').pack(anchor='w')
        tk.Label(info, text=game['title_id'],
                 font=('Consolas', 9), bg=BG, fg=INFO_FG,
                 anchor='w').pack(anchor='w', pady=(4, 0))
        if game['version']:
            tk.Label(info, text='Version ' + game['version'],
                     font=('Segoe UI', 9), bg=BG, fg=MUTED,
                     anchor='w').pack(anchor='w')
        if game['size'] > 0:
            sz = ('%.2f GB' % (game['size'] / 1024**3)
                  if game['size'] >= 1024**3
                  else '%d MB' % (game['size'] // 1024**2))
            tk.Label(info, text=sz + ' estimated image size',
                     font=('Segoe UI', 8), bg=BG, fg='#555555',
                     anchor='w').pack(anchor='w', pady=(4, 0))

        # SDK version — read in background
        sdk_var = tk.StringVar(value='Detecting SDK...')
        sdk_lbl = tk.Label(info, textvariable=sdk_var,
                           font=('Segoe UI', 8, 'bold'),
                           bg=BG, fg='#ffaa00', anchor='w')
        sdk_lbl.pack(anchor='w', pady=(4, 0))

        def _detect_sdk_bg():
            sdk = ExFATBuilder._read_sdk_from_folder(game['folder'])
            if sdk is not None:
                suggest = max(4, sdk - 1)
                self.after(0, sdk_var.set,
                           'Game SDK: %d.xx  —  Backport target: SDK %d' % (sdk, suggest))
            else:
                self.after(0, sdk_var.set, 'SDK: not detected')
        threading.Thread(target=_detect_sdk_bg, daemon=True).start()

        # Folder path
        tk.Label(body, text=game['folder'],
                 font=('Consolas', 8), bg=BG, fg='#3a3a3a',
                 wraplength=440, justify='left', anchor='w').pack(anchor='w')

        

    def _rebuild_all_tabs(self):
        """Destroy and rebuild every tab frame with the current language."""
        active = self._active_tab.get()
        self._ffpkg_stop_poll()
        rebuilds = [
            (self._tab_build_frame,   self._build_build_tab),
            (self._tab_ffpkg_frame,   self._build_ffpkg_tab),
            (self._tab_library_frame, self._build_library_tab),
            # Step 40 (v2.5.4): Images is now a sub-tab of Library.
            # (self._tab_images_frame,  self._build_images_tab),
            (self._tab_ps5_frame,     self._build_ps5_tab),
            # Step 38 (v2.5.2): Extract is now a sub-tab of Build, not
            # a top-level frame. Removed from rebuild list.
            # (self._tab_extract_frame, self._build_extract_tab),
            (self._tab_dumps_frame,   self._build_dumps_tab),
            # Step 39 (v2.5.3): Files is a sub-tab of Build now.
            # (self._tab_files_frame,   self._build_files_tab),
            # Step 40 (v2.5.4): FTP/Klog/Payloads/Y2JB are sub-tabs of PS5
            # (rebuilt as part of _build_ps5_tab).
            # (self._tab_ftp_frame,     self._build_ftp_tab),
            (self._tab_bp_frame,      self._build_backports_tab),
            # (self._tab_pl_frame,      self._build_payload_tab),
            # (self._tab_klog_frame,    self._build_klog_tab),
            (self._tab_adv_frame,     self._build_advanced_tab),
            (self._tab_cfg_frame,     self._build_settings_tab),
            # Step 40 (v2.5.4): Language and Help are sub-tabs of Settings.
            # (self._tab_lang_frame,    self._build_language_tab),
            (self._tab_y2jb_frame,    self._build_y2jb_tab),
            # Step 40 — keep y2jb in the list as a no-op rebuild target
            # for back-compat (no longer visible as top-level).
            # (self._tab_help_frame,    self._build_help_tab),
        ]
        for frame, builder in rebuilds:
            for w in frame.winfo_children():
                w.destroy()
            try:
                builder(frame)
            except Exception:
                import traceback; traceback.print_exc()
        self._switch_tab(active)


