    def _build_dumps_tab(self, parent):
        # Carved out in Step 1 — see ui/tab_dump_rename.py
        from ui.tab_dump_rename import build_dump_rename_tab
        build_dump_rename_tab(parent, self)

    def _dumps_browse_src(self):
        p = filedialog.askdirectory(title='Select folder containing PS5 game dumps')
        if p:
            self._dumps_src_var.set(p)

    def _dumps_browse_dst(self):
        p = filedialog.askdirectory(title='Select destination folder')
        if p:
            self._dumps_dst_var.set(p)

    def _dumps_scan(self):
        src = self._dumps_src_var.get().strip()
        if src and os.path.isdir(src):
            self._settings['dumps_last_src'] = src
            save_settings(self._settings)
        if not src or not os.path.isdir(src):
            messagebox.showwarning('No folder', 'Select a dumps folder first.')
            return
        if self._dumps_scanning:
            return

        # Clear
        for w in self._dumps_list_frame.winfo_children():
            w.destroy()
        self._dumps_items = []
        # Step 18 (v2.1.9): also clear the inspector view's parallel
        # model + tree rows. The four group nodes are kept in place;
        # only their children are removed.
        try:
            self._dumps_model = []
            self._dumps_iid_to_idx = {}
            if hasattr(self, '_dumps_tree'):
                for grp_key in ('ready', 'review', 'dup', 'failed'):
                    grp_iid = 'grp_' + grp_key
                    for kid in self._dumps_tree.get_children(grp_iid):
                        self._dumps_tree.delete(kid)
        except Exception:
            pass
        self._dumps_scanning = True
        self._dumps_pbar.start(10)
        self._dumps_status_var.set('Scanning...')

        def do_scan():
            found = 0
            # System / junk folders to skip
            SKIP_FOLDERS = {
                '$recycle.bin', 'system volume information', '$sysreset',
                '$windows.~bt', '$windows.~ws', 'recovery', 'recycler',
                'found.000', 'found.001', '.spotlight-v100', '.trashes',
                '.fseventsd', 'lost+found'
            }

            def _find_eboot_within(folder, max_depth=2):
                """Return (eboot_path, eboot_root) or (None, None).
                Searches up to max_depth subdirs deep."""
                try:
                    for root, dirs, files in os.walk(folder):
                        dirs[:] = [d for d in dirs
                                   if d.lower() not in ('decrypted', 'fakelib')]
                        rel = os.path.relpath(root, folder)
                        depth = 0 if rel == '.' else rel.count(os.sep) + 1
                        if depth > max_depth:
                            dirs[:] = []
                            continue
                        if 'eboot.bin' in files:
                            return (os.path.join(root, 'eboot.bin'), root)
                except Exception:
                    pass
                return (None, None)

            def _looks_like_container(folder):
                """Heuristic: does this folder contain 2+ subfolders
                that each look like their own dump?"""
                game_subs = 0
                try:
                    for entry in os.scandir(folder):
                        if not entry.is_dir():
                            continue
                        if entry.name.lower() in SKIP_FOLDERS:
                            continue
                        eb_path, _ = _find_eboot_within(entry.path,
                                                       max_depth=2)
                        if eb_path:
                            game_subs += 1
                            if game_subs >= 2:
                                return True
                except Exception:
                    pass
                return False

            # ── Build the candidate list. Step 24 (v2.2.5): if a
            # top-level child folder is itself a container of multiple
            # game folders (e.g. user picked `D:\` but `D:\Keep\`
            # holds 30 dumps), recurse into it instead of registering
            # the container as a single dump. One level of container-
            # unwrapping; we don't recurse deeper than that to avoid
            # accidentally exploring an entire user drive.
            candidates = []
            try:
                top_entries = sorted(os.listdir(src))
            except Exception:
                top_entries = []

            # Step 26 (v2.2.7): a folder is treated as a DUMP if its
            # name looks like a PS5 game folder (PPSA/CUSA/PPLH id, or
            # a version pattern). Otherwise it's treated as a CONTAINER
            # and we recurse one level. This prevents user-organization
            # folders like "Keep", "Backups", "MyGames" from being
            # renamed when they're actually just holding game folders.
            import re as _re_scan
            _DUMP_NAME_PAT = _re_scan.compile(
                r'(?:PPSA|CUSA|PPLH|PPSB)\d{5,}'
                r'|\(\d{2}\.\d{3}\.\d{3}\)'
                r'|\[\d{2}\.\d{3}\.\d{3}\]',
                _re_scan.IGNORECASE)

            def _looks_like_dump_name(name):
                """True if folder name has a game-id or version pattern."""
                return bool(_DUMP_NAME_PAT.search(name))

            for name in top_entries:
                full = os.path.join(src, name)
                if not os.path.isdir(full):
                    continue
                if name.lower() in SKIP_FOLDERS or name.startswith('.'):
                    continue

                # Quick eboot check at the immediate level — if eboot.bin
                # is RIGHT IN this folder, it's definitely a dump.
                direct_eb = os.path.isfile(os.path.join(full, 'eboot.bin'))
                if direct_eb:
                    candidates.append(full)
                    continue

                # If folder name LOOKS like a dump name (has PPSA/CUSA
                # id or version pattern), treat as a dump regardless of
                # nesting depth. Eboot may be 1-2 levels in (wrappers).
                if _looks_like_dump_name(name):
                    candidates.append(full)
                    continue

                # Folder name doesn't look like a dump (e.g. "Keep",
                # "Backups", "MyGames") — recurse one level looking for
                # actual dump folders inside. Eboot is typically 0-2
                # levels deep within each child.
                try:
                    for sub in sorted(os.listdir(full)):
                        sub_full = os.path.join(full, sub)
                        if (not os.path.isdir(sub_full) or
                                sub.lower() in SKIP_FOLDERS or
                                sub.startswith('.')):
                            continue
                        # The recursed-into subfolder must itself look
                        # like a dump OR have eboot.bin within 2 levels.
                        # This prevents recursing into deep junk
                        # hierarchies like "Music/Albums/Beatles/...".
                        sub_direct_eb = os.path.isfile(
                            os.path.join(sub_full, 'eboot.bin'))
                        if (sub_direct_eb or
                                _looks_like_dump_name(sub) or
                                _find_eboot_within(sub_full, 2)[0]):
                            candidates.append(sub_full)
                except Exception:
                    pass

            for full in candidates:
                name = os.path.basename(full)
                # Look for eboot.bin within 2 levels of THIS candidate
                eboot_path, eboot_root = _find_eboot_within(full,
                                                            max_depth=2)
                if not eboot_path:
                    continue

                # game_root is where eboot.bin lives
                game_root = eboot_root or full

                # Get new name from SFO/JSON
                try:
                    import re as _re
                    info    = self._read_sfo_info(game_root)
                    ppsa    = info.get('TITLE_ID', '').upper()
                    title   = info.get('TITLE', '').strip()
                    # Strip trademark symbols from title
                    title = _re.sub(r'[™®©]', '', title).strip()
                    # Fix ALL CAPS titles (e.g. VARLET → Varlet)
                    if title and title == title.upper() and len(title) > 2:
                        title = title.title()
                    version = info.get('APP_VER', '').strip()

                    # Extract PPSA from folder name if param.json didn't have it
                    if not ppsa:
                        m = _re.search(r'((?:PPSA|CUSA|PPSB)\d{5,})', name, _re.IGNORECASE)
                        if m:
                            ppsa = m.group(1).upper()

                    if ppsa and not title:
                        # Title is blank — parse folder name
                        # Try the outer folder first (e.g. "Alone in the Dark 2 (01.000.003)")
                        # then the inner app folder name
                        candidates = []
                        outer = os.path.basename(os.path.dirname(game_root))
                        if outer and outer != name and outer != os.path.basename(full):
                            candidates.append(outer)
                        candidates.append(name)

                        best = ''
                        for cand in candidates:
                            t = cand
                            # Strip bracketed content: [DLPSGAME.COM], [04.001.000]
                            t = _re.sub(r'\[[^\]]*\]', '', t)
                            t = _re.sub(r'\([^)]*\)', '', t)
                            # Strip PPSA/CUSA IDs (with or without surrounding brackets)
                            t = _re.sub(r'\[?(?:PPSA|CUSA|PPSB)\d+\]?', '', t, flags=_re.IGNORECASE)
                            # Strip version patterns: 4xx, 04.001.000
                            # Strip bracket contents first (e.g. [PPSA05344], [04.001.000])
                            t = _re.sub(r'\[[^\]]*\]', ' ', t)
                            t = _re.sub(r'\([^)]*\)', ' ', t)
                            t = _re.sub(r'\{[^}]*\}', ' ', t)
                            t = _re.sub(r'\b\d+xx\b', '', t, flags=_re.IGNORECASE)
                            t = _re.sub(r'\b\d{2}\.\d{3}\.\d{3}\b', '', t)
                            # Strip -app/-app0/.part01 suffixes
                            t = _re.sub(r'[-_ ]app0*$', '', t, flags=_re.IGNORECASE)
                            t = _re.sub(r'\.part\d+$', '', t, flags=_re.IGNORECASE)
                            # Strip trailing duplicate numbers e.g. " 2"
                            t = _re.sub(r'\s+\d+$', '', t)
                            # Replace separators
                            t = _re.sub(r'[-_]+', ' ', t)
                            t = _re.sub(r'[\[\]{}()]', '', t)
                            t = ' '.join(t.split()).strip('. -')
                            if len(t) > len(best):
                                best = t
                        title = best

                    # Reject generic/short folder names used as titles
                    _GENERIC = {'downloads', 'games', 'keep', 'ps5', 'backup',
                                'compressed', 'backport files', 'backport',
                                'original', 'originals', 'temp', 'tmp', 'video'}
                    if title and (title.lower() in _GENERIC or len(title) < 2):
                        title = ''

                    # Build the new name — never duplicate version
                    if ppsa and title and version:
                        new_name = '%s %s (%s)' % (ppsa, title, version)
                        confidence = 'green'
                    elif ppsa and title:
                        new_name = '%s %s' % (ppsa, title)
                        confidence = 'yellow'
                    elif ppsa and version:
                        new_name = '%s (%s)' % (ppsa, version)
                        confidence = 'yellow'
                    elif ppsa:
                        new_name = ppsa
                        confidence = 'yellow'
                    else:
                        new_name = name
                        confidence = 'red'

                    # Final cleanup
                    new_name = new_name.replace('_', ' ')
                    new_name = _re.sub(r'\[[^\]]*\]', ' ', new_name)
                    new_name = _re.sub(r'\b\d+xx\b', ' ', new_name, flags=_re.IGNORECASE)
                    new_name = _re.sub(r'\s+', ' ', new_name).strip()

                except Exception as e:
                    self._log('[DUMPS] Name error for %s: %s\n' % (name, e))
                    new_name = name
                    confidence = 'red'

                found += 1
                self.after(0, self._dumps_add_card, full, name, new_name, found,
                           confidence, game_root, ppsa, title, version)

            self.after(0, self._dumps_scan_done, found)

        import threading as _t
        _t.Thread(target=do_scan, daemon=True).start()

    def _dumps_add_card(self, full, orig_name, new_name, idx,
                        confidence='yellow', game_root=None,
                        ppsa='', title='', version=''):
        """Step 18 (v2.1.9): rewritten for the inspector view in
        ui/dump_rename.py.

        Same signature as before — the scanner thread calls this for
        each dump it finds. Instead of building card widgets, this now:
          1. Appends the legacy 5-tuple to `_dumps_items` (so
             `_dumps_apply` keeps working unchanged)
          2. Appends a parallel dict to `_dumps_model` with inspector-
             view state (group, iid, confidence)
          3. Inserts a Treeview row under the appropriate group node
          4. Maps the row's iid to the list index for selection lookup
          5. Calculates folder size asynchronously (same threading
             pattern as before; updates the size_var AND tree row)

        Step 21 (v2.2.2): also accepts ppsa/title/version components
        so the bulk-rail naming preset can regenerate names without
        re-scanning. Older callers passing only the positional args still
        work (the components default to empty strings).
        """
        from ui.dump_rename import _CONF_TO_GROUP

        # ── Legacy 5-tuple (preserves _dumps_apply contract) ──
        name_var   = tk.StringVar(value=new_name)
        chk_var    = tk.BooleanVar(value=(orig_name != new_name))
        size_var   = tk.StringVar(value='\u2026')
        status_var = tk.StringVar(value='')
        self._dumps_items.append((full, name_var, chk_var,
                                   size_var, status_var))

        # ── Inspector-view dict ──
        group_key = _CONF_TO_GROUP.get(confidence, 'review')
        model_dict = {
            'full':       full,
            'orig_name':  orig_name,
            'proposed':   new_name,
            'confidence': confidence,
            'game_root':  game_root or full,
            'group':      group_key,
            'iid':        None,   # filled in just below
            # Step 21: store the parsed components so the bulk-rail
            # naming preset can regenerate names without re-scanning.
            'ppsa':       ppsa,
            'title':      title,
            'version':    version,
        }
        self._dumps_model.append(model_dict)
        list_idx = len(self._dumps_items) - 1

        # ── Insert Treeview row ──
        tag = {'ready': 'ok', 'review': 'warn',
               'dup': 'skip', 'failed': 'err'}.get(group_key, 'warn')
        try:
            # Step 21 (v2.2.3): tree row shows the ORIGINAL folder name,
            # not the proposed-rename. The proposed name lives in the
            # inspector pane's TO field (which IS reactive to the
            # NAMING/CASE/OPTIONS toggles). The list rail should be a
            # stable reference so users don't see all 50+ rows flip
            # between formats every time they tap a radio.
            iid = self._dumps_tree.insert('grp_' + group_key, 'end',
                text=orig_name,
                values=('\u2026',),
                tags=(tag,))
            model_dict['iid'] = iid
            self._dumps_iid_to_idx[iid] = list_idx
        except Exception as e:
            self._log('[DUMPS] Tree insert failed for %s: %s\n'
                      % (orig_name, e))

        # ── Calculate folder size in a background thread ──
        # Same pattern as before: update size_var (legacy) AND the new
        # tree row's size column.
        import threading as _t

        def _calc_size():
            try:
                sb = sum(os.path.getsize(os.path.join(r, f))
                         for r, _, fs in os.walk(full) for f in fs)
                s = ('%.1f GB' % (sb / 1024**3) if sb > 1024**3
                     else '%.0f MB' % (sb / 1024**2))
            except Exception:
                s = '?'
            # Update on the main thread
            def _apply_size():
                size_var.set(s)
                _iid = model_dict.get('iid')
                if _iid:
                    try:
                        self._dumps_tree.item(_iid, values=(s,))
                    except Exception:
                        pass
            self.after(0, _apply_size)

        _t.Thread(target=_calc_size, daemon=True).start()

        self._dumps_status_var.set('Found %d dump(s)...' % idx)

        # Refresh KPI on every add — cheap, gives a live count
        try:
            if hasattr(self, '_dumps_tab') and self._dumps_tab is not None:
                self._dumps_tab._refresh_kpi()
        except Exception:
            pass


    def _dumps_regenerate_names(self):
        """Step 21 (v2.2.2): rebuild each dump's name_var (and the
        Treeview row text) from its stored ppsa/title/version components
        plus the bulk-rail preset / case / sanitize options. Called
        whenever any of those options change."""
        import re as _re

        try:
            preset = self._dumps_naming_preset_var.get()
        except Exception:
            preset = 'ppsa_title_v'
        try:
            case = self._dumps_case_var.get()
        except Exception:
            case = 'keep'
        try:
            sanitize = self._dumps_sanitize_var.get()
        except Exception:
            sanitize = True
        try:
            replace_spaces = self._dumps_replace_spaces_var.get()
        except Exception:
            replace_spaces = False

        for i, m in enumerate(self._dumps_model):
            ppsa = m.get('ppsa', '') or ''
            title = m.get('title', '') or ''
            version = m.get('version', '') or ''

            # Build base name from preset
            if preset == 'ppsa':
                base = ppsa or m.get('orig_name', '')
            elif preset == 'ppsa_title':
                if ppsa and title:
                    base = '%s %s' % (ppsa, title)
                elif ppsa:
                    base = ppsa
                else:
                    base = m.get('orig_name', '')
            else:  # ppsa_title_v
                if ppsa and title and version:
                    base = '%s %s (%s)' % (ppsa, title, version)
                elif ppsa and title:
                    base = '%s %s' % (ppsa, title)
                elif ppsa and version:
                    base = '%s (%s)' % (ppsa, version)
                elif ppsa:
                    base = ppsa
                else:
                    base = m.get('orig_name', '')

            # Sanitize special chars
            if sanitize:
                base = _re.sub(r'[\\/:*?"<>|\u2122\u00ae\u00a9]', '', base)
                base = _re.sub(r'\s+', ' ', base).strip()

            # Replace spaces with hyphens
            if replace_spaces:
                base = base.replace(' ', '-')

            # Case
            if case == 'upper':
                base = base.upper()
            elif case == 'lower':
                base = base.lower()
            # 'keep' = no-op

            # Update model + name_var (which feeds _dumps_apply).
            # Step 22 (v2.2.3): NO LONGER updating the tree row's
            # `text` — the list rail keeps showing the original folder
            # name. The user sees naming-option changes in the
            # inspector's TO field instead.
            m['proposed'] = base
            try:
                full, name_var, chk, sv, st = self._dumps_items[i]
                name_var.set(base)
            except (IndexError, ValueError):
                pass

        # Re-render the inspector pane for the currently selected dump
        # so the TO field reflects the new computed name immediately.
        try:
            if hasattr(self, '_dumps_tab') and self._dumps_tab is not None:
                tab = self._dumps_tab
                sel_iid = getattr(tab, 'app', self)._dumps_selected_iid \
                    if hasattr(tab, 'app') else None
                if not sel_iid:
                    sel_iid = self._dumps_selected_iid
                if sel_iid:
                    idx = self._dumps_iid_to_idx.get(sel_iid)
                    if idx is not None:
                        tab._show_detail(idx)
        except Exception:
            pass


        self._dumps_scanning = False
        self._dumps_pbar.stop()
        # Step 18 (v2.1.9): no longer rendering "no dumps found" into
        # the (now hidden) _dumps_list_frame — the new inspector view
        # shows that message via its empty-state on the detail pane and
        # the KPI counts. Status var still gets updated for the
        # legacy status label in the topbar.
        self._dumps_status_var.set(
            '%d dump(s) found. Sizes calculating in background...' % found
            if found else 'No dumps found.')
        # Refresh inspector KPI now that all dumps are added
        try:
            if hasattr(self, '_dumps_tab') and self._dumps_tab is not None:
                self._dumps_tab._refresh_kpi()
        except Exception:
            pass

    def _dumps_select_all(self):
        for _, _, chk, _, _ in self._dumps_items:
            chk.set(True)
        try:
            if hasattr(self, '_dumps_tab') and self._dumps_tab is not None:
                self._dumps_tab._refresh_kpi()
        except Exception:
            pass

    def _dumps_select_none(self):
        for _, _, chk, _, _ in self._dumps_items:
            chk.set(False)
        try:
            if hasattr(self, '_dumps_tab') and self._dumps_tab is not None:
                self._dumps_tab._refresh_kpi()
        except Exception:
            pass

    def _dumps_apply(self):
        dst_base = self._dumps_dst_var.get().strip()
        # Build the (full, new_name, status_var) list from selected
        # checkboxes. Skip entries whose new_name is empty.
        selected = [(full, nv.get().strip(), sv)
                    for full, nv, chk, _, sv in self._dumps_items
                    if chk.get() and nv.get().strip()]
        if not selected:
            messagebox.showwarning('Nothing selected',
                'Tick at least one dump to rename/move.')
            return
        if dst_base and not os.path.isdir(dst_base):
            messagebox.showerror('Destination not found',
                'The destination folder does not exist.')
            return

        # Step 24 (v2.2.5): drop entries whose path is strictly inside
        # another selected entry's path. e.g. if the user selected both
        # `D:\Keep` (top-level scan source) and `D:\Keep\PPSA30490 ...`
        # (child), renaming/moving the parent would relocate the child
        # and the child rename would then fail with "path not found".
        # We keep only the OUTERMOST entries.
        norm_pairs = [(os.path.normcase(os.path.normpath(p) +
                                        os.sep), p, n, s)
                      for p, n, s in selected]
        # Sort shortest-path-first so a parent always comes before
        # its children in the iteration order.
        norm_pairs.sort(key=lambda t: len(t[0]))
        dedup = []
        seen_prefixes = []
        skipped_children = 0
        for norm_p, full, new_name, status_var in norm_pairs:
            inside = any(norm_p.startswith(pref) and norm_p != pref
                         for pref in seen_prefixes)
            if inside:
                # Mark the row so the user sees why it was skipped
                self.after(0, status_var.set, '— inside other')
                skipped_children += 1
                continue
            seen_prefixes.append(norm_p)
            dedup.append((full, new_name, status_var))

        if not dedup:
            self._dumps_status_var.set('Nothing to do.')
            return

        total_count = len(dedup)

        import threading as _t, shutil as _sh, time as _time

        start_t = _time.time()
        # Use a list for the running byte count so the inner closures
        # can mutate it (Python 2-style nonlocal workaround).
        progress_bytes = [0]
        # Filled inside the worker AFTER the size pre-scan, since
        # walking dozens of multi-GB folders on the UI thread freezes
        # the app for tens of seconds. Step 25 (v2.2.6).
        total_bytes_holder = [1]
        per_entry_bytes_holder = [None]

        def _fmt_size(b):
            for u in ('B', 'KB', 'MB', 'GB', 'TB'):
                if b < 1024:
                    return '%.1f %s' % (b, u)
                b /= 1024.0
            return '%.1f PB' % b

        def _fmt_eta(secs):
            if secs < 0 or secs == float('inf'):
                return '—'
            secs = int(secs)
            if secs < 60:
                return '%ds' % secs
            if secs < 3600:
                return '%dm %02ds' % (secs // 60, secs % 60)
            return '%dh %02dm' % (secs // 3600, (secs % 3600) // 60)

        def _bump_progress(extra_bytes, current_label=None):
            progress_bytes[0] += extra_bytes
            elapsed = _time.time() - start_t
            mbps = (progress_bytes[0] / elapsed / (1024 * 1024)
                    if elapsed > 0.5 else 0)
            tot = total_bytes_holder[0]
            remaining = tot - progress_bytes[0]
            eta = remaining / (progress_bytes[0] / elapsed) \
                if progress_bytes[0] > 0 and elapsed > 0.5 else -1
            try:
                self._dumps_pbar.configure(value=progress_bytes[0])
            except Exception:
                pass
            parts = []
            if current_label:
                parts.append(current_label)
            parts.append('%s / %s' % (_fmt_size(progress_bytes[0]),
                                       _fmt_size(tot)))
            if mbps > 0.1:
                parts.append('%.1f MB/s' % mbps)
            if eta >= 0:
                parts.append('ETA %s' % _fmt_eta(eta))
            self._dumps_status_var.set(' \u00b7 '.join(parts))

        # Manual chunked copy so we can update progress mid-file. Used
        # only for the cross-folder copytree case.
        def _copytree_with_progress(src, dst, current_label):
            os.makedirs(dst, exist_ok=False)
            for root, dirs, files in os.walk(src):
                rel = os.path.relpath(root, src)
                target_dir = dst if rel == '.' else os.path.join(dst, rel)
                os.makedirs(target_dir, exist_ok=True)
                for fn in files:
                    sp = os.path.join(root, fn)
                    dp = os.path.join(target_dir, fn)
                    try:
                        with open(sp, 'rb') as fsrc, open(dp, 'wb') as fdst:
                            while True:
                                chunk = fsrc.read(4 * 1024 * 1024)  # 4 MB
                                if not chunk:
                                    break
                                fdst.write(chunk)
                                self.after(0, _bump_progress,
                                           len(chunk), current_label)
                        # Preserve mtime/atime
                        try:
                            _sh.copystat(sp, dp)
                        except Exception:
                            pass
                    except Exception:
                        # Re-raise so the outer worker marks the row failed
                        raise

        def worker():
            done = failed = 0
            errors = []  # collect short error strings for summary

            # Step 25 (v2.2.6): byte pre-scan happens here on the worker
            # thread, NOT on the UI thread. Walking 27 multi-GB folders
            # on the UI thread freezes the app for tens of seconds.
            #
            # Optimisation: if every entry is an in-place rename (no
            # `dst_base`, OR dst_base resolves to each entry's source
            # parent), the byte counts are irrelevant — every rename
            # is an instant filesystem operation. Skip the walk.
            all_renames = True
            if dst_base:
                for full, _n, _s in dedup:
                    sp = os.path.dirname(os.path.normpath(full))
                    try:
                        if not os.path.samefile(
                                os.path.normpath(dst_base), sp):
                            all_renames = False
                            break
                    except OSError:
                        if (os.path.normcase(os.path.normpath(dst_base)) !=
                                os.path.normcase(sp)):
                            all_renames = False
                            break

            if all_renames:
                # Equal weight per entry; total = count, each entry
                # ticks 1. Avoids minutes of disk-walking on huge
                # folders that aren't going to be touched anyway.
                per_entry_bytes = [1] * len(dedup)
                total_bytes = max(len(dedup), 1)
            else:
                self.after(0, self._dumps_status_var.set,
                           'Calculating sizes...')
                total_bytes = 0
                per_entry_bytes = []
                for full, _name, _sv in dedup:
                    sz = 0
                    try:
                        for r, _, fs in os.walk(full):
                            for fn in fs:
                                try:
                                    sz += os.path.getsize(
                                        os.path.join(r, fn))
                                except Exception:
                                    pass
                    except Exception:
                        pass
                    per_entry_bytes.append(sz)
                    total_bytes += sz
                total_bytes = max(total_bytes, 1)

            total_bytes_holder[0] = total_bytes
            per_entry_bytes_holder[0] = per_entry_bytes

            # Switch progress bar to determinate mode now that we
            # have a real total. Marshal to UI thread.
            def _setup_bar():
                try:
                    self._dumps_pbar.stop()
                    self._dumps_pbar.configure(mode='determinate',
                                                maximum=total_bytes,
                                                value=0)
                except Exception:
                    pass
            self.after(0, _setup_bar)

            for i, (full, new_name, status_var) in enumerate(dedup):
                entry_label = '[%d/%d] %s' % (i + 1, total_count,
                                                os.path.basename(full)
                                                or full)
                try:
                    full_norm   = os.path.normpath(full)
                    src_parent  = os.path.dirname(full_norm)
                    dest_parent = (os.path.normpath(dst_base)
                                   if dst_base else src_parent)

                    import re as _re
                    safe_name = _re.sub(r'[\\/:*?"<>|]', '', new_name).strip()
                    if not safe_name:
                        self.after(0, status_var.set, '✗ empty name')
                        failed += 1
                        errors.append('%s: name became empty after sanitisation'
                                      % os.path.basename(full))
                        # Still tick progress so the bar advances
                        self.after(0, _bump_progress, per_entry_bytes[i],
                                   entry_label)
                        continue
                    dest_path = os.path.join(dest_parent, safe_name)

                    if os.path.normpath(dest_path) == full_norm:
                        # Exact same path — nothing to do
                        self.after(0, status_var.set, '— same')
                        self.after(0, _bump_progress, per_entry_bytes[i],
                                   entry_label)
                        continue

                    # Step 27 (v2.2.8): on case-insensitive filesystems
                    # (Windows, macOS default), os.path.exists() returns
                    # True for the destination path even when the only
                    # difference is letter case — because the OS resolves
                    # both paths to the same file. Use os.path.samefile
                    # to detect this and let os.rename handle it (which
                    # DOES properly perform case-only renames on Windows).
                    is_case_only = False
                    if os.path.exists(dest_path):
                        try:
                            is_case_only = os.path.samefile(dest_path,
                                                             full_norm)
                        except OSError:
                            is_case_only = False
                        if not is_case_only:
                            self.after(0, status_var.set, '⚠ exists')
                            failed += 1
                            errors.append('%s: destination already exists'
                                          % safe_name)
                            self.after(0, _bump_progress,
                                       per_entry_bytes[i], entry_label)
                            continue

                    same_parent = False
                    try:
                        same_parent = os.path.samefile(dest_parent,
                                                       src_parent)
                    except OSError:
                        same_parent = (os.path.normcase(dest_parent) ==
                                       os.path.normcase(src_parent))

                    # Helper: rename with retries to handle transient
                    # Windows locks (Explorer preview, AV scan, indexer).
                    # WinError 5 / 32 are the typical transient failures.
                    def _rename_with_retry(src, dst, attempts=4):
                        last_err = None
                        for attempt in range(attempts):
                            try:
                                os.rename(src, dst)
                                return
                            except OSError as oe:
                                last_err = oe
                                # Re-raise immediately on hard failures
                                # (file not found, dest exists & isn't
                                # case-collision, etc.)
                                if getattr(oe, 'winerror', None) not in (
                                        5, 32, 1224):
                                    raise
                                # Backoff: 0.5s, 1s, 2s
                                _time.sleep(0.5 * (2 ** attempt))
                        raise last_err

                    if dst_base and not same_parent and not is_case_only:
                        # Real cross-folder move — chunked copy with
                        # mid-file progress, then remove source.
                        _copytree_with_progress(full_norm, dest_path,
                                                 entry_label)
                        try:
                            _sh.rmtree(full_norm)
                        except Exception as rmerr:
                            # Copy succeeded but source removal failed —
                            # treat as soft warning, not failure.
                            errors.append(
                                '%s: copied OK, source removal failed: %s'
                                % (safe_name, rmerr))
                    elif is_case_only:
                        # Windows can sometimes refuse a direct rename
                        # when the only difference is case (depends on
                        # the underlying filesystem's case-sensitivity
                        # mode). Use a two-step rename via a temporary
                        # name to force it through.
                        try:
                            _rename_with_retry(full_norm, dest_path)
                        except OSError:
                            tmp_path = full_norm + '.__case_rename_tmp__'
                            _rename_with_retry(full_norm, tmp_path)
                            try:
                                _rename_with_retry(tmp_path, dest_path)
                            except Exception:
                                # Try to revert if the second step fails
                                try:
                                    os.rename(tmp_path, full_norm)
                                except Exception:
                                    pass
                                raise
                        self.after(0, _bump_progress, per_entry_bytes[i],
                                   entry_label)
                    else:
                        # In-place rename. Retries handle transient
                        # locks from Windows Explorer / AV / indexer.
                        _rename_with_retry(full_norm, dest_path)
                        self.after(0, _bump_progress, per_entry_bytes[i],
                                   entry_label)

                    self.after(0, status_var.set, '✓ done')
                    done += 1
                except Exception as e:
                    self.after(0, status_var.set, '✗ error')
                    # Step 28 (v2.2.9): translate Windows access-denied
                    # to actionable advice. WinError 5 means another
                    # process has the folder open — most often Windows
                    # Explorer (folder navigated into / preview pane),
                    # antivirus, or the search indexer.
                    err_text = str(e)
                    winerr = getattr(e, 'winerror', None)
                    if winerr == 5:
                        err_text = ('Access denied — close any window '
                                    'showing this folder (Explorer, '
                                    'preview pane), pause antivirus, '
                                    'and retry. Original: %s' % e)
                    elif winerr == 32:
                        err_text = ('File in use — another process has '
                                    'the folder open. Close it and '
                                    'retry. Original: %s' % e)
                    self._log('[DUMPS] %s: %s\n'
                              % (os.path.basename(full), err_text))
                    errors.append('%s: %s'
                                  % (os.path.basename(full), err_text))
                    failed += 1
                    # Tick progress so bar reaches 100% even on errors
                    self.after(0, _bump_progress, per_entry_bytes[i],
                               entry_label)

            elapsed = _time.time() - start_t
            msg_parts = ['%d renamed/moved' % done]
            if failed:
                msg_parts.append('%d failed' % failed)
            if skipped_children:
                msg_parts.append('%d skipped (inside other)'
                                 % skipped_children)
            msg_parts.append('in %s' % _fmt_eta(elapsed))
            self.after(0, self._dumps_status_var.set,
                       ' \u00b7 '.join(msg_parts))

            # Restore the bar to indeterminate mode for the next scan.
            def _restore_bar():
                try:
                    self._dumps_pbar.configure(value=0,
                                                mode='indeterminate')
                except Exception:
                    pass
            self.after(100, _restore_bar)

            # If anything failed, surface the first few errors via a
            # dialog so the user actually knows what went wrong.
            if errors:
                snippet = '\n'.join(errors[:6])
                if len(errors) > 6:
                    snippet += '\n... and %d more' % (len(errors) - 6)
                self.after(0, lambda s=snippet:
                    messagebox.showwarning(
                        'Some dumps could not be processed',
                        s + '\n\nFull details in OUTPUT LOG.'))

        _t.Thread(target=worker, daemon=True).start()
        self._dumps_status_var.set('Starting...')



    def _run_benchmark(self):
        """Write 256MB of zeros to the output directory and measure MB/s."""
        import tkinter.filedialog as _fd
        out_dir = ''
        try:
            out_dir = self._outdir_var.get().strip()
        except Exception:
            pass
        if not out_dir or not os.path.isdir(out_dir):
            out_dir = _fd.askdirectory(title='Select output directory to benchmark')
            if not out_dir:
                return
        self._bench_result_var.set('Running...')
        import threading as _t

        def worker():
            test_path = os.path.join(out_dir, '_bench_tmp.bin')
            chunk = b'\x00' * (4 * 1024 * 1024)
            total = 256 * 1024 * 1024
            written = 0
            try:
                start = time.time()
                with open(test_path, 'wb') as f:
                    while written < total:
                        f.write(chunk)
                        written += len(chunk)
                    f.flush()
                    os.fsync(f.fileno())
                elapsed = time.time() - start
                mb_s = (written / 1024**2) / max(elapsed, 0.01)
                self._bench_mb_s = mb_s
                self.after(0, self._bench_result_var.set, '%.0f MB/s' % mb_s)
                self._log('[BENCH] Write speed: %.0f MB/s (256MB test)\n' % mb_s)
            except Exception as e:
                self.after(0, self._bench_result_var.set, 'Error: ' + str(e))
            finally:
                try:
                    os.remove(test_path)
                except Exception:
                    pass

        _t.Thread(target=worker, daemon=True).start()


    def _dumps_delete_folder(self, folder):
        """Delete a dump folder after confirmation."""
        name = os.path.basename(folder)
        if not messagebox.askyesno('Delete dump?',
                'Permanently delete:\n%s\n\nThis cannot be undone.' % name,
                icon='warning'):
            return
        try:
            import shutil as _sh
            _sh.rmtree(folder, ignore_errors=False)
            self._dumps_status_var.set('Deleted: ' + name)
            self._dumps_scan()  # Rescan
        except Exception as e:
            messagebox.showerror('Delete failed', str(e))

    def _add_to_queue_from_path(self, folder):
        """Add a game folder to the exFAT build queue."""
        try:
            self._switch_tab('build')
            self._game_var.set(folder)
            self._on_game_browse_done(folder)
            self._add_to_queue()
            self._log('[DUMPS] Added to exFAT queue: %s\n' % os.path.basename(folder))
        except Exception as e:
            messagebox.showerror('Queue error', str(e))


    def _apply_name_case(self, name):
        """Apply lowercase setting to a filename (without extension)."""
        if getattr(self, '_lowercase_names_var', None) and self._lowercase_names_var.get():
            return name.lower()
        return name


    def _update_queue_total_eta(self, current_idx, indices):
        """Calculate and display total remaining time for the whole queue."""
        try:
            bench = getattr(self, '_bench_mb_s', 0)
            if bench <= 0:
                self._queue_eta_var.set('')
                return
            # Sum sizes of remaining items
            remaining_gb = 0.0
            for idx in indices:
                if idx <= current_idx:
                    continue
                item = self._queue[idx]
                try:
                    folder = item.game_folder
                    sz = sum(os.path.getsize(os.path.join(r, f))
                             for r, _, fs in os.walk(folder)
                             for f in fs
                             if not r.endswith('decrypted'))
                    remaining_gb += sz / 1024**3
                except Exception:
                    pass
            if remaining_gb < 0.01:
                self._queue_eta_var.set('')
                return
            secs = (remaining_gb * 1024) / bench
            if secs < 60:
                eta_str = 'Queue ~%ds remaining' % int(secs)
            elif secs < 3600:
                eta_str = 'Queue ~%dm %ds remaining' % (int(secs)//60, int(secs)%60)
            else:
                eta_str = 'Queue ~%dh %dm remaining' % (int(secs)//3600, (int(secs)%3600)//60)
            self._queue_eta_var.set(eta_str)
        except Exception:
            self._queue_eta_var.set('')

    def _verify_image(self, out_path, src_folder):
        osf = self._find_osfmount()
        if not osf:
            return True, 'OSFMount not found — skipping verify'
        if not os.path.isfile(out_path):
            # Step 41 (v2.5.7): give the user a clue what went wrong.
            # The build process said it succeeded but the file we
            # expected isn't there. Dump the output directory contents
            # to the log so the user can see if it was written under
            # a different name (sanitization mismatch, etc).
            try:
                out_dir = os.path.dirname(out_path)
                self._log('[VERIFY] Expected file NOT FOUND: %s\n' % out_path)
                self._log('[VERIFY] Listing %s for similar files:\n' % out_dir)
                if os.path.isdir(out_dir):
                    found_similar = []
                    for fn in os.listdir(out_dir):
                        if fn.lower().endswith('.exfat'):
                            full = os.path.join(out_dir, fn)
                            try:
                                sz = os.path.getsize(full)
                                self._log('[VERIFY]   %s (%.1f MB)\n' %
                                          (fn, sz / 1024.0 / 1024.0))
                                found_similar.append(fn)
                            except Exception:
                                pass
                    if not found_similar:
                        self._log('[VERIFY]   (no .exfat files in output '
                                  'directory — build produced no output)\n')
                else:
                    self._log('[VERIFY]   (output directory does not '
                              'exist!)\n')
            except Exception as e:
                self._log('[VERIFY] Could not list output dir: %s\n' % str(e))
            return False, 'Output file not found at: ' + out_path

        # Step 41 (v2.5.7): also catch zero-byte files as a build failure.
        # OSFMount can leave a zero-byte file behind when it fails to
        # create the volume.
        try:
            sz = os.path.getsize(out_path)
            if sz == 0:
                self._log('[VERIFY] Output file exists but is 0 bytes — '
                          'build did not write any data.\n')
                return False, 'Output file is 0 bytes (build failed silently)'
            if sz < 1024 * 1024:  # less than 1 MB
                self._log('[VERIFY] Warning: output file is only %d bytes '
                          '(less than 1 MB)\n' % sz)
        except Exception:
            pass

        # Count source files — exclude 'decrypted' folder
        src_count = 0
        for _vroot, _vdirs, _vfiles in os.walk(src_folder):
            _vdirs[:] = [d for d in _vdirs if d.lower() != 'decrypted']
            src_count += len(_vfiles)

        # Find free drive letter
        try:
            import ctypes as _ct
            bitmask = _ct.windll.kernel32.GetLogicalDrives()
            free_letter = None
            for i in range(25, 3, -1):
                if not (bitmask & (1 << i)):
                    free_letter = chr(65 + i) + ':'
                    break
            if not free_letter:
                return True, 'No free drive letter — skipping verify'
        except Exception as e:
            return True, 'Could not find drive letter: ' + str(e)

        try:
            import time as _t

            # Wait for file to be fully released by the build process
            # (Windows can keep the file handle open briefly after robocopy exits)
            for _wait in range(10):
                if os.path.isfile(out_path) and os.path.getsize(out_path) > 0:
                    break
                _t.sleep(0.5)

            # Step 49 (v2.6.1): sweep any leaked OSFMount drives from
            # earlier builds. Without this, a previous verify that
            # timed out (leaving its Y: / Z: mount dangling) snipes
            # the free-letter pick and the new verify mount races into
            # the wedged kernel driver state, producing another
            # 30-second timeout. Excluding the active build drive
            # keeps the current build safe.
            try:
                excl = (self._mounted_drive or '').rstrip(':\\').upper()[:1]
                self._sweep_stale_osf_mounts(
                    exclude_letter=excl, log_prefix='[VERIFY]')
            except Exception:
                pass

            # Re-pick a free letter AFTER the sweep — letters we just
            # freed are now eligible, and we avoid colliding with any
            # drive that survived the sweep.
            try:
                import ctypes as _ct2
                bitmask2 = _ct2.windll.kernel32.GetLogicalDrives()
                for i in range(25, 3, -1):
                    if not (bitmask2 & (1 << i)):
                        free_letter = chr(65 + i) + ':'
                        break
            except Exception:
                pass

            # Try to mount read-only — retry up to 4 times with backoff
            # as the file handle may still be releasing. Step 49: the
            # per-call timeout was 30s, which is too tight when the
            # OSFMount driver is briefly slow (large image, AV scan
            # on the image file, recent kernel state thrash). Bump to
            # 90s and on TimeoutExpired specifically, immediately try
            # to dismount the letter we asked for — OSFMount may have
            # completed the mount even though our subprocess got
            # killed, and leaving it dangling causes the next build's
            # verify to fail the same way.
            result = None
            for _attempt in range(4):
                try:
                    result = subprocess.run(
                        [osf, '-a', '-t', 'file', '-f', out_path,
                         '-m', free_letter, '-o', 'ro,rem'],
                        capture_output=True, text=True, timeout=90,
                        creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())
                except subprocess.TimeoutExpired:
                    self._log('[VERIFY] Mount attempt %d timed out — '
                              'cleaning up possibly-orphaned mount on %s\n'
                              % (_attempt + 1, free_letter))
                    try:
                        self._dismount_drive_robust(
                            free_letter.rstrip(':\\'), max_wait_seconds=15)
                    except Exception:
                        pass
                    _t.sleep(2)
                    continue
                if result.returncode == 0:
                    break
                self._log('[VERIFY] Mount attempt %d failed (rc=%d) — retrying...\n'
                          % (_attempt + 1, result.returncode))
                _t.sleep(2)

            if result is None or result.returncode != 0:
                # Mount failed after retries — skip verify rather than false-failing
                # the build (image is likely fine, OSFMount just couldn't get a handle)
                self._log('[VERIFY] Could not mount for verification — skipping\n')
                return True, 'Verification skipped (could not mount — image likely OK)'

            # Wait for drive
            import time as _t
            for _ in range(20):
                if os.path.exists(free_letter + '\\'):
                    break
                _t.sleep(0.3)
            else:
                # Drive didn't appear — clean up via the robust helper
                # so we don't leave the OSFMount slot dangling.
                self._dismount_drive_robust(
                    free_letter.rstrip(':\\'), max_wait_seconds=10)
                return False, 'Mounted drive did not appear'

            # Check eboot.bin
            eboot_found = False
            img_count   = 0
            for root, dirs, files in os.walk(free_letter + '\\'):
                img_count += len(files)
                for fn in files:
                    if fn.lower() == 'eboot.bin':
                        eboot_found = True

            # Dismount via the robust helper (handles Defender locks etc.)
            self._dismount_drive_robust(
                free_letter.rstrip(':\\'), max_wait_seconds=15)

            if not eboot_found:
                return False, 'eboot.bin not found in built image!'
            # Allow tolerance of up to 2 files — robocopy can skip the root
            # directory entry or a single locked file without failing the build
            if src_count > 0 and img_count < src_count - 2:
                return False, ('File count mismatch: source has %d files, '
                               'image has %d' % (src_count, img_count))
            return True, ('Verified \u2713  eboot.bin present, '
                          '%d/%d files confirmed' % (img_count, src_count))

        except Exception as e:
            try:
                self._dismount_drive_robust(
                    free_letter.rstrip(':\\'), max_wait_seconds=10)
            except Exception:
                pass
            return False, 'Verification error: ' + str(e)

    def _verify_done(self, ok, msg, idx, indices, pos, out_path):
        self._log('[VERIFY] ' + msg + '\n')

        # ── Corrupt image detection ──
        if ok and os.path.isfile(out_path):
            size = os.path.getsize(out_path)
            src_size = self._get_folder_size(self._queue[idx].game_folder)
            if src_size > 10 * 1024**2 and size < src_size * 0.05:
                ok = False
                msg = ('Image is suspiciously small (%.1f MB) for a game that '
                       'should be %.1f GB. It may be corrupt.' % (
                           size/1024**2, src_size/1024**3))
                self._log('[WARN] ' + msg + '\n')

        # ── If verification failed, retry once with a fresh mount ──
        if not ok and 'file count' in msg.lower():
            self._log('[VERIFY] File count mismatch — retrying with fresh mount...\n')
            self._set_status('Verifying (retry)...', WARNING)

            def _retry_verify():
                # Mount image fresh and recount
                osf = self._find_osfmount()
                if osf:
                    try:
                        # Find free drive letter
                        import ctypes as _ct
                        used = _ct.windll.kernel32.GetLogicalDrives()
                        mount_letter = None
                        for i in range(3, 26):
                            if not (used & (1 << i)):
                                mount_letter = chr(65 + i) + ':'
                                break
                        if mount_letter:
                            import subprocess as _sp
                            try:
                                r = _sp.run([osf, '-a', '-t', 'file', '-f', out_path,
                                             '-o', 'ro,rem', '-m', mount_letter],
                                            capture_output=True, timeout=90,
                                            creationflags=_NO_WIN_FLAGS, startupinfo=_silent_startupinfo())
                            except _sp.TimeoutExpired:
                                # Step 49 (v2.6.1): same orphan-mount
                                # cleanup as the main verify path.
                                self._log('[VERIFY] Retry mount timed '
                                          'out — cleaning up %s\n'
                                          % mount_letter)
                                try:
                                    self._dismount_drive_robust(
                                        mount_letter.rstrip(':\\'),
                                        max_wait_seconds=15)
                                except Exception:
                                    pass
                                self.after(0, self._verify_done_final,
                                           ok, msg, idx, indices, pos, out_path)
                                return
                            if r.returncode == 0:
                                import time as _t
                                for _ in range(10):
                                    if os.path.exists(mount_letter + '\\'):
                                        break
                                    _t.sleep(0.5)
                                # Recount
                                img_count  = sum(len(fs) for _, _, fs
                                                 in os.walk(mount_letter + '\\'))
                                src_folder = self._queue[idx].game_folder
                                src_count  = sum(len(fs) for _, _, fs
                                                 in os.walk(src_folder))
                                # Robust dismount — much more reliable
                                # than the old retry-osfmount-d loop.
                                self._dismount_drive_robust(
                                    mount_letter.rstrip(':\\'),
                                    max_wait_seconds=15)
                                retry_ok = img_count >= src_count - 2
                                retry_msg = ('Retry verify: %d/%d files'
                                             % (img_count, src_count))
                                self.after(0, self._verify_done_final,
                                           retry_ok, retry_msg,
                                           idx, indices, pos, out_path)
                                return
                    except Exception as e:
                        self._log('[VERIFY] Retry mount failed: %s\n' % str(e))

                # Can't retry — proceed with original result
                self.after(0, self._verify_done_final, ok, msg,
                           idx, indices, pos, out_path)

            threading.Thread(target=_retry_verify, daemon=True).start()
            return

        self._verify_done_final(ok, msg, idx, indices, pos, out_path)

    def _verify_done_final(self, ok, msg, idx, indices, pos, out_path):
        """Final verification result — handle success/failure and continue queue."""
        if ok:
            self._set_status(msg, SUCCESS)
            self._export_log(out_path)
            if self._adv_delete_source_var.get():
                src = self._queue[idx].game_folder
                try:
                    import shutil as _sh
                    self._log('[POST] Deleting source folder: %s\n' % src)
                    _sh.rmtree(src)
                    self._log('[POST] Source folder deleted \u2713\n')
                except Exception as de:
                    self._log('[POST] Failed to delete source: %s\n' % str(de))
        else:
            # Step 41 (v2.5.7): don't block the queue with a modal dialog.
            # When a queue of 4+ games runs overnight and one fails verify,
            # the old behaviour was a blocking messagebox that froze the
            # remaining builds until the user clicked OK. Now: mark the
            # queue item with a warn dot, log the failure, and let the
            # queue continue. The user can review failures from the
            # OUTPUT LOG when they come back.
            self._set_status('Verify failed: ' + msg, DANGER)
            self._log('\n[VERIFY] FAILED for %s\n' % out_path)
            self._log('[VERIFY] Reason: %s\n' % msg)
            self._log('[VERIFY] The image may be incomplete \u2014 check it '
                      'manually before using.\n\n')
            self._update_queue_dot(idx, 'warn')
            self._export_log(out_path, failed=True)

            # Only show a blocking dialog if this is a single-item build
            # (i.e. the user is sat watching it) AND there's no queue
            # left to process. For multi-item runs we trust the log.
            is_last = (pos >= len(indices) - 1)
            single_item = (len(indices) == 1)
            if single_item and is_last:
                messagebox.showwarning('Verification failed',
                    'Build completed but verification found an issue:\n\n'
                    + msg +
                    '\n\nThe image may be incomplete.')

        self._notify('Build complete', (self._queue[idx].game_title or '') + '\n' + out_path)

        # ── Checksum verification ──
        if ok and self._adv_checksum_var.get():
            self._set_status('Running checksum verification...', ACCENT)
            def _chk():
                import hashlib as _hl
                try:
                    h = _hl.sha256()
                    with open(out_path, 'rb') as f:
                        while True:
                            chunk = f.read(8 * 1024 * 1024)
                            if not chunk:
                                break
                            h.update(chunk)
                    digest = h.hexdigest()
                    self._log('[CHECKSUM] SHA-256: %s\n' % digest)
                    self.after(0, self._set_status,
                               'SHA-256: ' + digest[:16] + '...', SUCCESS)
                except Exception as e:
                    self._log('[CHECKSUM] Error: %s\n' % str(e))
            threading.Thread(target=_chk, daemon=True).start()

        # ── Auto FTP upload ──
        if ok and self._adv_auto_upload_var.get() and self._ftp_ip_var.get().strip():
            self._log('[AUTO-UPLOAD] Uploading to PS5...\n')
            self._ftp_upload_file(out_path,
                on_done=lambda: self._process_next(indices, pos + 1))
            return

        if self._ftp_auto_var.get() and self._ftp_ip_var.get().strip():
            if messagebox.askyesno('FTP Upload',
                    'Build complete!\n\nUpload to PS5 now?\n' + out_path):
                self._ftp_upload_file(out_path,
                    on_done=lambda: self._process_next(indices, pos + 1))
            else:
                self._process_next(indices, pos + 1)
        else:
            self._process_next(indices, pos + 1)

    def _get_logs_dir(self):
        custom = self._settings.get('logs_dir', '').strip()
        if custom:
            logs_dir = custom
        else:
            logs_dir = os.path.join(os.path.expanduser('~'), 'exfat_builder_logs')
        os.makedirs(logs_dir, exist_ok=True)
        return logs_dir

    def _browse_logs_dir(self):
        p = filedialog.askdirectory(title='Select folder for build logs')
        if p:
            p = os.path.normpath(p)
            self._logs_dir_var.set(p)
            self._settings['logs_dir'] = p
            save_settings(self._settings)
            self._refresh_logs_count()

    def _open_logs_dir(self):
        d = self._get_logs_dir()
        self._open_folder(d)

    def _refresh_logs_count(self):
        try:
            d = self._get_logs_dir()
            logs = [f for f in os.listdir(d) if f.endswith('.log')]
            failed = sum(1 for f in logs if '_FAILED' in f)
            total  = len(logs)
            self._logs_count_var.set(
                '%d log(s) saved  (%d failed)' % (total, failed)
                if failed else '%d log(s) saved' % total)
        except Exception:
            self._logs_count_var.set('')

    def _clear_logs(self):
        d = self._get_logs_dir()
        try:
            logs = [f for f in os.listdir(d) if f.endswith('.log')]
            if not logs:
                messagebox.showinfo('No logs', 'No log files found.')
                return
            if not messagebox.askyesno('Clear logs',
                    'Delete %d log file(s) from:\n%s\n\nThis cannot be undone.' % (
                        len(logs), d)):
                return
            for f in logs:
                os.remove(os.path.join(d, f))
            self._refresh_logs_count()
            self._set_status('Cleared %d log(s)' % len(logs), SUCCESS)
        except Exception as e:
            messagebox.showerror('Error', str(e))

    def _export_log(self, out_path, failed=False):
        """Save build log to dedicated logs folder."""
        try:
            log_text = self.log_box.get('1.0', 'end')
            ts        = time.strftime('%Y%m%d_%H%M%S')
            game_name = os.path.splitext(os.path.basename(out_path))[0]
            suffix    = '_FAILED' if failed else ''
            filename  = '%s_%s%s.log' % (ts, game_name, suffix)
            log_path  = os.path.join(self._get_logs_dir(), filename)
            with open(log_path, 'w', encoding='utf-8') as f:
                f.write('exFAT Image Builder v' + APP_VERSION + '\n')
                f.write('Build log: ' + os.path.basename(out_path) + '\n')
                f.write('Date: ' + time.strftime('%Y-%m-%d %H:%M:%S') + '\n')
                f.write('Status: ' + ('FAILED' if failed else 'SUCCESS') + '\n')
                f.write('=' * 60 + '\n\n')
                f.write(log_text)
        except Exception:
            pass

    # ── Installed games list + PS5 storage ────────────────────────────────────
    def _show_installed_games(self):
        ip = self._ftp_ip_var.get().strip()
        if not ip:
            messagebox.showwarning('No IP', 'Enter your PS5 IP address in Settings first.')
            return
        remote_dir = self._ftp_path_var.get().strip() or '/data/etaHEN/games/'

        win = tk.Toplevel(self)
        win.title('Installed Games on PS5 — ' + ip)
        win.geometry('640x480')
        win.configure(bg=BG)
        win.transient(self)

        hdr = tk.Frame(win, bg=BG)
        hdr.pack(fill='x', padx=16, pady=(12, 4))
        tk.Label(hdr, text='Installed Games',
                 font=('Segoe UI', 13, 'bold'), bg=BG, fg=TEXT).pack(side='left')
        self._ps5_storage_var = tk.StringVar(value='')
        tk.Label(hdr, textvariable=self._ps5_storage_var,
                 font=('Segoe UI', 9), bg=BG, fg=INFO_FG).pack(side='right')

        status_var = tk.StringVar(value='Connecting...')
        tk.Label(win, textvariable=status_var,
                 font=('Segoe UI', 8), bg=BG, fg=MUTED).pack(anchor='w', padx=16)

        list_frame = tk.Frame(win, bg=SURFACE2,
                              highlightbackground=BORDER, highlightthickness=1)
        list_frame.pack(fill='both', expand=True, padx=16, pady=(6, 8))
        listbox = tk.Listbox(list_frame, font=('Consolas', 9),
                             bg=SURFACE2, fg=TEXT,
                             selectbackground=ACCENT, selectforeground='#ffffff',
                             relief='flat', activestyle='none', bd=6)
        sb = tk.Scrollbar(list_frame, command=listbox.yview,
                          bg=SURFACE2, troughcolor=BG)
        listbox.configure(yscrollcommand=sb.set)
        sb.pack(side='right', fill='y')
        listbox.pack(fill='both', expand=True)

        btn_row = tk.Frame(win, bg=BG)
        btn_row.pack(fill='x', padx=16, pady=(0, 12))
        tk.Button(btn_row, text='Refresh', font=('Segoe UI', 9),
                  bg=SURFACE2, fg=TEXT, relief='flat', bd=0,
                  padx=10, pady=5, cursor='hand2',
                  command=lambda: _load()).pack(side='left')
        tk.Button(btn_row, text='Close', font=('Segoe UI', 9),
                  bg=SURFACE2, fg=MUTED, relief='flat', bd=0,
                  padx=10, pady=5, cursor='hand2',
                  command=win.destroy).pack(side='right')

        def _load():
            status_var.set('Loading...')
            listbox.delete(0, 'end')
            def worker():
                try:
                    import ftplib
                    ftp = self._ftp_connect()
                    # Get storage free space
                    try:
                        lines = []
                        ftp.retrlines('LIST ' + remote_dir, lines.append)
                        # Parse .exfat files
                        games = []
                        for line in lines:
                            parts = line.split()
                            if len(parts) < 9:
                                continue
                            name = ' '.join(parts[8:])
                            if not name.lower().endswith('.exfat'):
                                continue
                            try:
                                sz = int(parts[4])
                            except Exception:
                                sz = 0
                            games.append((name, sz))
                        games.sort(key=lambda x: x[0].lower())
                        ftp.quit()
                        win.after(0, _show, games)
                    except Exception as e:
                        ftp.quit()
                        win.after(0, status_var.set, 'Error: ' + str(e))
                except Exception as e:
                    win.after(0, status_var.set, 'Connection failed: ' + str(e))
            threading.Thread(target=worker, daemon=True).start()

        def _show(games):
            listbox.delete(0, 'end')
            if not games:
                listbox.insert('end', '  No .exfat files found in ' + remote_dir)
                status_var.set('0 games found')
                return
            total_size = sum(sz for _, sz in games)
            status_var.set('%d game(s)  —  %.1f GB total' % (
                len(games), total_size / 1024**3))
            for name, sz in games:
                if sz >= 1024**3:
                    sz_str = '%.2f GB' % (sz / 1024**3)
                else:
                    sz_str = '%.0f MB' % (sz / 1024**2)
                listbox.insert('end', '\U0001f4be  %-50s %s' % (name, sz_str))

        _load()



        if pct is not None:
            if kind == 'step':
                self._set_progress(pct, extra,
                    self._format_eta(elapsed, pct) if pct > 0 else '')
            elif kind == 'robo_eta':
                es = 'Elapsed: %dm %02ds' % (int(elapsed // 60), int(elapsed % 60))
                self._set_progress(pct, None,
                    es + '  \u2014  ' + extra if extra
                    else self._format_eta(elapsed, pct))
            else:
                self._set_progress(pct, None, self._format_eta(elapsed, pct))
        elif self._current_pct > 0 and self._start_time:
            self._eta_var.set(self._format_eta(elapsed, self._current_pct))

    # ── Real-time drive polling ────────────────────────────────────────────────
    def _maybe_kick_dest_walk(self):
        """Kick off a one-shot background walk of the mounted destination
        drive to count files, but only if (a) we have a mounted drive,
        (b) at least 5 seconds have passed since the last walk, and
        (c) no walk is currently in flight. Cheap (metadata only) and
        the drive is already hot from the copy. Result is stored in
        self._dest_file_count for the poll display to pick up.
        """
        try:
            drive = self._mounted_drive
            if not drive or not self._building:
                return
            now = time.time()
            if self._dest_walk_running:
                return
            if now - (self._dest_walk_last_ts or 0) < 5.0:
                return
            self._dest_walk_running = True

            def _walk(drive_root=drive + '\\'):
                count = 0
                try:
                    for _r, _d, files in os.walk(drive_root):
                        count += len(files)
                except Exception:
                    pass
                # Marshal back to the UI thread for the assignment
                def _assign(c=count):
                    self._dest_file_count   = c
                    self._dest_walk_last_ts = time.time()
                    self._dest_walk_running = False
                try:
                    self.after(0, _assign)
                except Exception:
                    self._dest_walk_running = False
            threading.Thread(target=_walk, daemon=True).start()
        except Exception:
            self._dest_walk_running = False

    def _start_drive_poll(self):
        self._poll_drive()

    def _stop_drive_poll(self):
        if self._drive_poll_id is not None:
            try:
                self.after_cancel(self._drive_poll_id)
            except Exception:
                pass
            self._drive_poll_id = None

    def _poll_drive(self):
        if not self._building or not self._mounted_drive:
            self._drive_poll_id = self.after(1000, self._poll_drive)
            return
        try:
            usage = shutil.disk_usage(self._mounted_drive + '\\')
            free_gb  = usage.free  / (1024 ** 3)
            total_gb = usage.total / (1024 ** 3)

            if self._copy_start_free is None:
                self._copy_start_free = usage.free
                self._copy_start_time = time.time()

            written_gb    = max(0, (self._copy_start_free - usage.free) / (1024 ** 3))
            # Remaining is what's still to be copied (total image - written)
            remaining_gb  = max(0, total_gb - written_gb)

            elapsed_copy  = max(1, time.time() - self._copy_start_time) \
                            if self._copy_start_time else 1
            elapsed_total = time.time() - self._start_time \
                            if self._start_time else 0

            # ── Rolling speed window — 30s for large file accuracy ──
            now = time.time()
            if not hasattr(self, '_poll_window'):
                self._poll_window = []
            self._poll_window.append((now, usage.free))
            cutoff = now - 30.0  # 30s window handles large single files
            self._poll_window = [(t, f) for t, f in self._poll_window if t >= cutoff]

            speed_mbs = 0.0
            if len(self._poll_window) >= 2:
                dt = self._poll_window[-1][0] - self._poll_window[0][0]
                df = self._poll_window[0][1]  - self._poll_window[-1][1]
                if dt > 2.0 and df > 0:
                    speed_mbs = (df / 1024 / 1024) / dt
            # Fallback: average speed over entire copy so far
            if speed_mbs == 0 and written_gb > 0.01:
                speed_mbs = (written_gb * 1024) / elapsed_copy

            # ── ETA ──
            eta_str = ''
            if speed_mbs > 0 and remaining_gb > 0.01:
                eta_secs = (remaining_gb * 1024) / speed_mbs
                if eta_secs < 10:
                    eta_str = 'Almost done'
                elif eta_secs < 60:
                    eta_str = 'ETA: %ds' % int(eta_secs)
                else:
                    eta_str = 'ETA: %dm %02ds' % (
                        int(eta_secs // 60), int(eta_secs % 60))

            # ── File count ──
            # Step 45 (v2.5.8): give users an actual live "X / Y files"
            # readout. Robocopy /NFL doesn't emit per-file lines, so the
            # old _robocopy_file_count only updated once per build (at
            # the very end). Now we walk the mounted destination drive
            # every ~5 seconds on a background thread (cheap because
            # it's metadata-only and the drive's already hot) and use
            # that count as the truth.
            self._maybe_kick_dest_walk()
            dest_count = getattr(self, '_dest_file_count', 0)
            src_total  = self._source_file_count
            rc         = getattr(self, '_robocopy_file_count', 0)
            # Prefer the live destination count if we have it. Fall
            # back to robocopy's final summary if dest count is 0
            # (very start of copy, or walk hasn't finished its first
            # pass yet).
            live_copied = dest_count if dest_count > 0 else rc

            file_count_str = ''
            if live_copied > 0 and src_total > 0 and live_copied <= src_total:
                pct_files = int(100 * live_copied / src_total)
                file_count_str = '%s / %s files (%d%%)' % (
                    '{:,}'.format(live_copied),
                    '{:,}'.format(src_total),
                    pct_files)
            elif live_copied > 0:
                file_count_str = '%s files copied' % '{:,}'.format(live_copied)
            elif src_total > 0:
                file_count_str = '%s files to copy' % '{:,}'.format(src_total)

            # ── Pct progress ──
            if total_gb > 0:
                lo, hi, _ = STEPS.get('3/4', (30, 90, 'Copying...'))
                pct = lo + (hi - lo) * min(1.0, written_gb / total_gb)
                self._update_bar_visual(pct)
                self._pct_var.set(str(int(pct)) + '%')

            # ── Status line ──
            elapsed_str = 'Elapsed: %dm %02ds' % (
                int(elapsed_total // 60), int(elapsed_total % 60))
            parts = [elapsed_str]
            if file_count_str:
                parts.append(file_count_str)
            if written_gb > 0.01:
                parts.append('%.2f GB written' % written_gb)
            if remaining_gb > 0.01:
                parts.append('%.2f GB remaining' % remaining_gb)
            if speed_mbs > 0:
                parts.append('%.1f MB/s' % speed_mbs)
            if eta_str:
                parts.append(eta_str)
            self._eta_var.set('  \u2022  '.join(parts))

        except Exception:
            pass

        self._drive_poll_id = self.after(2000, self._poll_drive)  # poll every 2s

    # ── FTP ───────────────────────────────────────────────────────────────────
    def _save_ftp_settings(self):
        self._settings['ftp_ip']   = self._ftp_ip_var.get().strip()
        self._settings['ftp_port'] = int(self._ftp_port_var.get().strip() or '2121')
        self._settings['ftp_path'] = self._ftp_path_var.get().strip() or '/data/etaHEN/games/'
        self._settings['ftp_auto'] = self._ftp_auto_var.get()
        save_settings(self._settings)

    def _ftp_connect(self):
        import ftplib
        ip   = self._ftp_ip_var.get().strip()
        port = int(self._ftp_port_var.get().strip() or '2121')
        if not ip:
            raise ValueError('No PS5 IP address set. Enter it in Settings.')
        ftp = ftplib.FTP()
        ftp.connect(ip, port, timeout=10)
        ftp.login()
        return ftp

    def _ftp_test(self):
        self._save_ftp_settings()
        self._ftp_status_var.set('Connecting...')
        self._ftp_status_lbl.config(fg=ACCENT)
        def worker():
            try:
                import ftplib
                ftp = self._ftp_connect()
                # List root to confirm connection
                items = ftp.nlst()
                ftp.quit()
                self.after(0, self._ftp_test_result, True,
                           'Connected \u2713  (' + str(len(items)) + ' items at root)')
            except Exception as e:
                self.after(0, self._ftp_test_result, False, str(e))
        threading.Thread(target=worker, daemon=True).start()

    def _ftp_test_result(self, ok, msg):
        self._ftp_status_var.set(msg)
        self._ftp_status_lbl.config(fg=SUCCESS if ok else DANGER)

    def _cancel_ftp_upload(self):
        if self._ftp_uploading:
            self._ftp_cancel = True
            self._ftp_status_var.set('Cancelling...')
            self._ftp_status_lbl.config(fg=WARNING)

    def _ftp_upload_file(self, local_path, on_done=None):
        # Auto-switch to FTP tab so user can see progress
        self._switch_tab('ftp')
        if hasattr(self, '_ftp_switch_sub'):
            self._ftp_switch_sub('upload')
        remote_dir  = self._ftp_path_var.get().strip() or '/data/etaHEN/games/'
        filename    = os.path.basename(local_path)
        remote_path = remote_dir.rstrip('/') + '/' + filename
        file_size   = os.path.getsize(local_path)
        file_size_gb = file_size / (1024 ** 3)

        self._ftp_cancel    = False
        self._ftp_uploading = True
        self._cancel_btn.pack(side='left', padx=(6, 0))  # show cancel button

        self._ftp_status_var.set('Connecting...')
        self._ftp_status_lbl.config(fg=ACCENT)
        self._set_status('Uploading to PS5: ' + filename, ACCENT)
        self._set_progress(0, 'Uploading to PS5: ' + filename, '')
        self._log('\n[FTP] Uploading ' + filename + ' -> ' + remote_path + '\n')
        self._log('[FTP] File size: %.2f GB\n' % file_size_gb)

        uploaded  = [0]
        start     = [time.time()]
        window    = []
        cancelled = [False]

        def progress(block):
            if self._ftp_cancel:
                cancelled[0] = True
                raise Exception('Upload cancelled by user')
            uploaded[0] += len(block)
            now     = time.time()
            elapsed = now - start[0]
            window.append((now, uploaded[0]))
            cutoff = now - 5.0
            while len(window) > 1 and window[0][0] < cutoff:
                window.pop(0)
            if len(window) >= 2:
                dt = window[-1][0] - window[0][0]
                db = window[-1][1] - window[0][1]
                speed_mbs = (db / (1024 * 1024)) / dt if dt > 0 else 0
            else:
                speed_mbs = uploaded[0] / (1024 * 1024) / elapsed if elapsed > 0 else 0
            sent_gb      = uploaded[0] / (1024 ** 3)
            remaining_gb = max(0, file_size_gb - sent_gb)
            pct          = min(100, int(uploaded[0] / file_size * 100)) if file_size else 0
            if speed_mbs > 0 and remaining_gb > 0:
                eta_secs = (remaining_gb * 1024) / speed_mbs
                if eta_secs < 5:
                    eta_str = 'Almost done'
                elif eta_secs < 60:
                    eta_str = 'ETA: %ds' % int(eta_secs)
                else:
                    eta_str = 'ETA: %dm %02ds' % (int(eta_secs // 60), int(eta_secs % 60))
            else:
                eta_str = ''
            elapsed_str = 'Elapsed: %dm %02ds' % (int(elapsed // 60), int(elapsed % 60))
            self.after(0, self._ftp_upload_progress,
                       pct, speed_mbs, sent_gb, remaining_gb,
                       elapsed_str, eta_str, filename)

        def worker():
            try:
                import ftplib
                ftp = self._ftp_connect()
                self.after(0, self._ftp_status_var.set, 'Uploading...')
                parts = remote_dir.strip('/').split('/')
                path = ''
                for part in parts:
                    path += '/' + part
                    try:
                        ftp.mkd(path)
                    except Exception:
                        pass
                with open(local_path, 'rb') as f:
                    ftp.storbinary('STOR ' + remote_path, f,
                                   blocksize=65536, callback=progress)
                ftp.quit()
                self.after(0, self._ftp_upload_done, True, remote_path, on_done)
            except Exception as e:
                if cancelled[0]:
                    self.after(0, self._ftp_upload_done, False, 'cancelled', on_done)
                else:
                    self.after(0, self._ftp_upload_done, False, str(e), on_done)

        threading.Thread(target=worker, daemon=True).start()

    def _ftp_upload_progress(self, pct, speed_mbs, sent_gb, remaining_gb,
                              elapsed_str, eta_str, filename):
        # Update progress bar
        self._set_progress(pct, 'Uploading to PS5: ' + filename, '')

        # Build detailed ETA string
        info_parts = [elapsed_str]
        if sent_gb > 0.001:
            info_parts.append('%.2f GB sent' % sent_gb)
        if remaining_gb > 0.001:
            info_parts.append('%.2f GB remaining' % remaining_gb)
        if speed_mbs > 0:
            info_parts.append('%.1f MB/s' % speed_mbs)
        if eta_str:
            info_parts.append(eta_str)

        eta_line = '  \u2022  '.join(info_parts)
        self._eta_var.set(eta_line)

        # Update FTP status bar with compact summary
        self._ftp_status_var.set(
            '%d%%  \u2022  %.1f MB/s  \u2022  %.2f GB remaining  \u2022  %s'
            % (pct, speed_mbs, remaining_gb, eta_str))

    def _ftp_upload_done(self, ok, info, on_done):
        self._ftp_uploading = False
        self._ftp_cancel    = False
        self._cancel_btn.pack_forget()

        if info == 'cancelled':
            self._ftp_status_var.set('Upload cancelled')
            self._ftp_status_lbl.config(fg=WARNING)
            self._set_status('FTP upload cancelled', WARNING)
            self._set_progress(0, '', '')
            self._eta_var.set('')
            self._log('[FTP] Upload cancelled by user\n')
        elif ok:
            self._ftp_status_var.set('Upload complete \u2713  ' + info)
            self._ftp_status_lbl.config(fg=SUCCESS)
            self._set_progress(100, 'Upload complete!', '')
            self._set_status('Upload complete: ' + info, SUCCESS)
            self._log('[FTP] Upload complete: ' + info + '\n')
            self._notify('Upload complete', info)
            self._trigger_shutdown('ftp')
        else:
            self._ftp_status_var.set('Upload failed: ' + info)
            self._ftp_status_lbl.config(fg=DANGER)
            self._set_status('FTP upload failed', DANGER)
            self._log('[FTP] Error: ' + info + '\n')
            messagebox.showerror('FTP Upload Failed',
                'Failed to upload to PS5:\n\n' + info +
                '\n\nCheck your IP, port, and that the PS5 FTP server is running.')
        if on_done:
            on_done()

    # ── Extra settings ────────────────────────────────────────────────────────
    def _save_extra_settings(self):
        self._settings['notify_sound']    = self._sound_var.get()
        self._settings['retry_count']     = self._retry_var.get()
