    # ── Notification sound ────────────────────────────────────────────────────
    def _notify(self, title, detail=''):
        if self._sound_var.get():
            try:
                import winsound
                winsound.MessageBeep(winsound.MB_ICONASTERISK)
            except Exception:
                pass
        # Windows toast notification via PowerShell (no pip needed)
        try:
            import subprocess as _sp, os as _os
            icon_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)),
                                      'controller.ico')
            ps_script = (
                'Add-Type -AssemblyName System.Windows.Forms;'
                '$n = New-Object System.Windows.Forms.NotifyIcon;'
                '$n.Icon = [System.Drawing.Icon]::ExtractAssociatedIcon('
                '(Get-Process -Id $pid).Path);'
                '$n.Visible = $true;'
                '$n.ShowBalloonTip(4000, "%s", "%s",'
                '[System.Windows.Forms.ToolTipIcon]::Info);'
                'Start-Sleep -Milliseconds 4500;'
                '$n.Dispose()' % (
                    title.replace('"', "'"),
                    detail.replace('"', "'").replace('\n', ' ')[:120])
            )
            _sp.Popen(
                ['powershell', '-WindowStyle', 'Hidden',
                 '-NonInteractive', '-Command', ps_script],
                creationflags=_sp.CREATE_NO_WINDOW)
        except Exception:
            pass
        self._discord_notify(title, detail)

    # ── Discord webhook ───────────────────────────────────────────────────────
    def _discord_notify(self, title, detail=''):
        url = self._discord_var.get().strip()
        if not url:
            return
        def worker():
            try:
                import urllib.request, urllib.parse
                colour = 0x4caf50  # green
                payload = json.dumps({
                    'embeds': [{
                        'title': '\U0001f3ae ' + title,
                        'description': detail,
                        'color': colour,
                        'footer': {'text': 'PS5 exFAT Image Builder by DecKerr97'},
                        'timestamp': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
                    }]
                }).encode('utf-8')
                req = urllib.request.Request(url, data=payload,
                    headers={'Content-Type': 'application/json'})
                urllib.request.urlopen(req, timeout=5)
            except Exception:
                pass
        threading.Thread(target=worker, daemon=True).start()

    # ── Auto-detect PS5 IP ────────────────────────────────────────────────────
    def _auto_detect_ip(self):
        self._autoip_status.config(text='Scanning network...', fg=ACCENT)
        def worker():
            import socket, concurrent.futures
            found = []
            # Get local subnet from default gateway
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                s.connect(('8.8.8.8', 80))
                local_ip = s.getsockname()[0]
                s.close()
                subnet = '.'.join(local_ip.split('.')[:3])
            except Exception:
                self.after(0, self._autoip_status.config,
                           {'text': 'Could not determine subnet', 'fg': DANGER})
                return

            ports = [2121, 2122]

            def check(ip):
                for port in ports:
                    try:
                        s = socket.create_connection((ip, port), timeout=0.3)
                        s.close()
                        return ip, port
                    except Exception:
                        pass
                return None

            ips = [subnet + '.' + str(i) for i in range(1, 255)]
            with concurrent.futures.ThreadPoolExecutor(max_workers=50) as ex:
                results = list(ex.map(check, ips))

            found = [r for r in results if r]
            self.after(0, self._autoip_result, found)

        threading.Thread(target=worker, daemon=True).start()

    def _autoip_result(self, found):
        if not found:
            self._autoip_status.config(
                text='No PS5 found on network', fg=DANGER)
            return
        ip, port = found[0]
        self._ftp_ip_var.set(ip)
        self._ftp_port_var.set(str(port))
        self._save_ftp_settings()
        self._autoip_status.config(
            text='Found PS5 at ' + ip + ':' + str(port) + '  \u2713', fg=SUCCESS)

    # ── Update checker ────────────────────────────────────────────────────────
    @staticmethod
    def _parse_version_tuple(s):
        """Parse a version string like 'v2.7.0', 'V2.7', or '2.7.0-rc1'
        into a comparable tuple of integers. Non-numeric suffixes are
        stripped. Pads to at least 3 components so '2.7' and '2.7.0'
        compare equal. Returns (0, 0, 0) if parsing fails.
        """
        if not s:
            return (0, 0, 0)
        # Strip leading v/V and surrounding whitespace
        s = str(s).strip().lstrip('vV').strip()
        # Capture only the numeric.dotted.prefix
        # (e.g. '2.7.0-rc1' -> '2.7.0', '2.7.0+build5' -> '2.7.0')
        import re as _re
        m = _re.match(r'^(\d+(?:\.\d+)*)', s)
        if not m:
            return (0, 0, 0)
        try:
            parts = [int(p) for p in m.group(1).split('.')]
        except (ValueError, TypeError):
            return (0, 0, 0)
        # Pad to length 3 so 2.7 == 2.7.0
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts)

    def _check_for_updates(self):
        def worker():
            try:
                import urllib.request
                url = 'https://api.github.com/repos/kerrdec97/ps5-exfat-builder/releases/latest'
                req = urllib.request.Request(url,
                    headers={'User-Agent': 'ps5-exfat-builder'})
                with urllib.request.urlopen(req, timeout=5) as r:
                    data = json.loads(r.read().decode())
                latest_raw = data.get('tag_name', '')
                # Compare as numeric tuples so 'V2.7.0', 'v2.7.0',
                # and '2.7.0' all match correctly. Also handles
                # '2.7' vs '2.7.0' equivalence.
                latest_tuple  = ExFATBuilder._parse_version_tuple(latest_raw)
                current_tuple = ExFATBuilder._parse_version_tuple(APP_VERSION)
                if latest_tuple > current_tuple:
                    # Normalize display: always show with lowercase v prefix
                    latest_display = latest_raw.strip().lstrip('vV').strip()
                    self.after(0, self._show_update_notice, latest_display,
                               data.get('html_url', ''))
            except Exception:
                pass
        threading.Thread(target=worker, daemon=True).start()

    def _show_update_notice(self, version, dl_url):
        # Belt-and-braces: strip any v/V prefix that snuck through so we
        # never produce 'vV2.7.0' style display strings.
        clean = str(version).strip().lstrip('vV').strip()
        ans = messagebox.askyesnocancel(
            'Update available',
            'v' + clean + ' is available!\n\n'
            'Current version: v' + APP_VERSION + '\n\n'
            'Yes  = Download and install automatically\n'
            'No   = Open GitHub releases page\n'
            'Cancel = Remind me later')
        if ans is True:
            self._auto_update(clean, dl_url)
        elif ans is False:
            import webbrowser
            webbrowser.open('https://github.com/kerrdec97/ps5-exfat-builder/releases')

    def _auto_update(self, version, dl_url):
        """Download the new exe and replace the current one on next launch."""
        win = tk.Toplevel(self)
        win.title('Updating to v' + version)
        win.geometry('420x160')
        win.configure(bg=BG)
        win.resizable(False, False)
        win.transient(self)

        body = tk.Frame(win, bg=BG)
        body.pack(fill='both', expand=True, padx=24, pady=16)
        tk.Label(body, text='Downloading v' + version + '...',
                 font=('Segoe UI', 11, 'bold'), bg=BG, fg=TEXT).pack(anchor='w')
        status_var = tk.StringVar(value='Connecting to GitHub...')
        tk.Label(body, textvariable=status_var,
                 font=('Segoe UI', 9), bg=BG, fg=MUTED).pack(anchor='w', pady=(4,8))
        bar_frame = tk.Frame(body, bg=TRACK, height=16)
        bar_frame.pack(fill='x')
        bar_frame.pack_propagate(False)
        bar_cv = tk.Canvas(bar_frame, height=16, bg=TRACK,
                           highlightthickness=0, bd=0)
        bar_cv.pack(fill='both', expand=True)
        bar_rect = bar_cv.create_rectangle(0, 0, 0, 16, fill=ACCENT, outline='')

        def set_bar(pct):
            try:
                w = bar_cv.winfo_width()
                bar_cv.coords(bar_rect, 0, 0, int(w * pct / 100), 16)
                bar_cv.itemconfig(bar_rect, fill=SUCCESS if pct >= 100 else ACCENT)
            except Exception:
                pass

        def worker():
            try:
                import urllib.request
                # Get the download URL for the exe asset
                api_url = 'https://api.github.com/repos/kerrdec97/ps5-exfat-builder/releases/latest'
                req = urllib.request.Request(api_url,
                    headers={'User-Agent': 'ps5-exfat-builder'})
                with urllib.request.urlopen(req, timeout=10) as r:
                    data = json.loads(r.read().decode())

                # Find the .exe asset
                exe_url = None
                for asset in data.get('assets', []):
                    name = asset.get('name', '')
                    if name.endswith('.exe') and 'Lite' not in name:
                        exe_url = asset.get('browser_download_url')
                        break

                if not exe_url:
                    win.after(0, status_var.set, 'No exe found in release assets.')
                    return

                win.after(0, status_var.set, 'Downloading...')

                # Download to temp file
                tmp_path = sys.executable + '.new'
                total    = [0]
                received = [0]

                def reporthook(count, block_size, total_size):
                    received[0] = count * block_size
                    total[0]    = total_size
                    pct = min(100, int(received[0] / total_size * 100)) if total_size > 0 else 0
                    mb  = received[0] / 1024 / 1024
                    win.after(0, set_bar, pct)
                    win.after(0, status_var.set,
                              'Downloading... %.1f MB (%d%%)' % (mb, pct))

                urllib.request.urlretrieve(exe_url, tmp_path, reporthook)

                # Write a batch file that replaces the exe after exit
                bat_path = sys.executable + '_update.bat'
                exe_dir  = os.path.dirname(sys.executable)
                with open(bat_path, 'w') as f:
                    f.write('@echo off\n')
                    f.write('REM Wait for the old process to fully exit\n')
                    f.write('timeout /t 4 /nobreak >nul\n')
                    f.write('REM Replace the exe (retry up to 5 times)\n')
                    f.write('set ATTEMPTS=0\n')
                    f.write(':retry\n')
                    f.write('move /y "%s" "%s"\n' % (tmp_path, sys.executable))
                    f.write('if errorlevel 1 (\n')
                    f.write('  set /a ATTEMPTS+=1\n')
                    f.write('  if %ATTEMPTS% lss 5 (\n')
                    f.write('    timeout /t 2 /nobreak >nul\n')
                    f.write('    goto retry\n')
                    f.write('  )\n')
                    f.write('  echo Failed to replace exe after 5 attempts.\n')
                    f.write('  echo Please download manually from GitHub.\n')
                    f.write('  pause\n')
                    f.write('  goto :eof\n')
                    f.write(')\n')
                    f.write('REM Wait for file system to flush\n')
                    f.write('timeout /t 3 /nobreak >nul\n')
                    f.write('REM Launch from its own directory so PyInstaller finds its files\n')
                    f.write('cd /d "%s"\n' % exe_dir)
                    f.write('start "" "%s"\n' % sys.executable)
                    f.write('REM Clean up\n')
                    f.write('(goto) 2>nul & del "%s"\n' % bat_path)

                win.after(0, set_bar, 100)
                win.after(0, status_var.set, 'Download complete! Restarting...')
                win.after(1500, lambda: (
                    subprocess.Popen(['cmd', '/c', bat_path],
                                     creationflags=subprocess.CREATE_NO_WINDOW),
                    self.destroy()))

            except Exception as e:
                win.after(0, status_var.set, 'Update failed: ' + str(e))
                win.after(0, messagebox.showerror, 'Update failed',
                          str(e) + '\n\nVisit GitHub to download manually.')

        threading.Thread(target=worker, daemon=True).start()

    def _set_status(self, text, color=MUTED):
        self.status_text.set(text)
        self.status_lbl.config(fg=color)

    def _parse_ver_from_name(self, filename):
        """Extract version like 01.007.000 from a filename like 'Game (01.007.000).exfat'"""
        m = re.search(r'\((\d{2}\.\d{3}\.\d{3})\)', filename or '')
        return m.group(1) if m else None

